        [MenuItem("Bellerophon/Player/Apply Lightsaber Off Idle Locomotion")]
        internal static void ApplyLightsaberOffIdleLocomotion()
        {
            RequireEditMode();
            int consoleErrorsBefore = ConsoleErrorCount();
            Scene scene = RequireScene();
            if (scene.isDirty)
                throw new InvalidOperationException(
                    "Lightsaber_Off_Idle locomotion requires a clean CargoRunMvp scene.");

            GameObject target = FindUnique(scene, "Lightsaber_Off_Idle");
            Animator animator = target.GetComponent<Animator>() ??
                throw new InvalidOperationException("Lightsaber_Off_Idle Animator is missing.");
            if (animator.avatar == null)
                throw new InvalidOperationException("Lightsaber_Off_Idle Avatar is missing.");
            Transform hand = RequireRightHand(target);
            Transform prop = RequireLightsaberProp(hand, target.name);
            RequireAuthoredPropTransform(prop, target.name);

            var targetSnapshot = new TransformSnapshot(target.transform);
            var propSnapshot = new TransformSnapshot(prop);
            string rendererBefore = RendererSignature(target.transform);
            string avatarBefore = ObjectIdentity(animator.avatar);
            LightsaberLocomotionSources sources = RequireLightsaberLocomotionSources(scene);
            string sourceSignatureBefore = LightsaberLocomotionSourceSignature(sources);
            List<LightsaberOffIdleBoneRotation> authoredPose =
                CaptureLightsaberCarryPose(target.transform);
            List<LightsaberOffIdleBoneRotation> sourceIdlePose =
                CaptureLightsaberCarryPose(FindUnique(scene, "Player_Idle").transform);

            EnsureFolder(LocomotionAssetFolder);
            AnimationClip idle = CopyLightsaberLocomotionClip(
                sources.Idle, LocomotionIdleClipPath, "LightsaberOffIdle_Idle");
            AnimationClip forward = CopyLightsaberLocomotionClip(
                sources.Forward, LocomotionForwardClipPath,
                "LightsaberOffIdle_WalkForward");
            AnimationClip backward = CopyLightsaberLocomotionClip(
                sources.Backward, LocomotionBackwardClipPath,
                "LightsaberOffIdle_WalkBackward");
            AnimationClip sidestep = CopyLightsaberLocomotionClip(
                sources.Sidestep, LocomotionSidestepClipPath,
                "LightsaberOffIdle_Sidestep");
            AnimationClip run = CopyLightsaberLocomotionClip(
                sources.Run, LocomotionRunClipPath, "LightsaberOffIdle_RunForward");
            AnimatorController controller = CreateLightsaberLocomotionController(
                sources.Diagonal, idle, forward, backward, sidestep, run);

            LightsaberOffIdleCarryPoseBehaviour carry =
                target.GetComponent<LightsaberOffIdleCarryPoseBehaviour>();
            if (carry == null)
                carry = Undo.AddComponent<LightsaberOffIdleCarryPoseBehaviour>(target);
            Undo.RecordObject(carry, "Configure Lightsaber_Off_Idle carry pose");
            carry.Configure(authoredPose, sourceIdlePose);
            PrefabUtility.RecordPrefabInstancePropertyModifications(carry);
            EditorUtility.SetDirty(carry);

            Undo.RecordObject(animator, "Configure Lightsaber_Off_Idle locomotion");
            animator.runtimeAnimatorController = controller;
            animator.applyRootMotion = false;
            animator.enabled = true;
            animator.cullingMode = AnimatorCullingMode.AlwaysAnimate;
            PrefabUtility.RecordPrefabInstancePropertyModifications(animator);
            EditorUtility.SetDirty(animator);
            AssetDatabase.SaveAssets();

            targetSnapshot.RequireUnchanged();
            propSnapshot.RequireUnchanged();
            RequireEqual(rendererBefore, RendererSignature(target.transform),
                "Lightsaber_Off_Idle renderer hierarchy");
            RequireEqual(avatarBefore, ObjectIdentity(animator.avatar),
                "Lightsaber_Off_Idle Avatar");
            RequireEqual(sourceSignatureBefore,
                LightsaberLocomotionSourceSignature(
                    RequireLightsaberLocomotionSources(scene)),
                "source locomotion objects");

            if (!EditorSceneManager.SaveScene(scene))
                throw new InvalidOperationException(
                    "CargoRunMvp could not save Lightsaber_Off_Idle locomotion.");
            InspectLightsaberOffIdleLocomotionInternal(scene, false);
            RequireNoNewUnityConsoleErrors(consoleErrorsBefore);
            Debug.Log(
                "[Lightsaber] Lightsaber_Off_Idle exact six-motion 2D Blend Tree applied; " +
                "one second per motion, six-second loop, authored grip retained with sway.");
        }

        [MenuItem("Bellerophon/Player/Inspect Lightsaber Off Idle Locomotion")]
        internal static void InspectLightsaberOffIdleLocomotion()
        {
            RequireEditMode();
            int consoleErrorsBefore = ConsoleErrorCount();
            InspectLightsaberOffIdleLocomotionInternal(RequireScene(), false);
            RequireNoNewUnityConsoleErrors(consoleErrorsBefore);
            Debug.Log(
                "[Lightsaber] Lightsaber_Off_Idle locomotion inspected read-only: " +
                "six exact source motions, one second each, looping after RunForward.");
        }

        private static void InspectLightsaberOffIdleLocomotionInternal(
            Scene scene,
            bool requireCleanScene)
        {
            if (requireCleanScene && scene.isDirty)
                throw new InvalidOperationException(
                    "Read-only Lightsaber_Off_Idle locomotion inspection requires a clean scene.");
            GameObject target = FindUnique(scene, "Lightsaber_Off_Idle");
            Animator animator = target.GetComponent<Animator>() ??
                throw new InvalidOperationException("Lightsaber_Off_Idle Animator is missing.");
            AnimatorController controller = animator.runtimeAnimatorController as AnimatorController;
            if (controller == null ||
                AssetDatabase.GetAssetPath(controller) != LocomotionControllerPath)
                throw new InvalidOperationException(
                    "Lightsaber_Off_Idle locomotion controller connection differs.");
            if (animator.applyRootMotion || !animator.enabled ||
                animator.cullingMode != AnimatorCullingMode.AlwaysAnimate)
                throw new InvalidOperationException(
                    "Lightsaber_Off_Idle Animator settings differ.");

            RequireLightsaberLocomotionFloatParameter(
                controller, LightsaberOffIdleLocomotionCycleBehaviour.MoveXParameter, 0f);
            RequireLightsaberLocomotionFloatParameter(
                controller, LightsaberOffIdleLocomotionCycleBehaviour.MoveYParameter, 0f);
            RequireLightsaberLocomotionFloatParameter(
                controller,
                LightsaberOffIdleLocomotionCycleBehaviour.DiagonalBlendParameter,
                0.5f);
            if (controller.layers.Length != 1)
                throw new InvalidOperationException(
                    "Lightsaber_Off_Idle controller must have one layer.");
            AnimatorControllerLayer layer = controller.layers[0];
            if (layer.avatarMask != null ||
                layer.blendingMode != AnimatorLayerBlendingMode.Override ||
                !Mathf.Approximately(layer.defaultWeight, 1f))
                throw new InvalidOperationException(
                    "Lightsaber_Off_Idle source locomotion layer differs.");
            AnimatorState state = layer.stateMachine.defaultState ??
                throw new InvalidOperationException(
                    "Lightsaber_Off_Idle default state is missing.");
            if (state.name != LocomotionStateName || state.writeDefaultValues ||
                state.mirror || !Mathf.Approximately(state.speed, 1f))
                throw new InvalidOperationException(
                    "Lightsaber_Off_Idle locomotion state settings differ.");
            StateMachineBehaviour[] stateBehaviours = state.behaviours;
            if (stateBehaviours.Any(item => item == null))
                throw new InvalidOperationException(
                    "Lightsaber_Off_Idle controller contains a missing Behaviour script.");
            if (stateBehaviours
                    .OfType<LightsaberOffIdleLocomotionCycleBehaviour>().Count() != 1)
                throw new InvalidOperationException(
                    "Lightsaber_Off_Idle one-second loop behaviour differs.");
            BlendTree root = state.motion as BlendTree ??
                throw new InvalidOperationException(
                    "Lightsaber_Off_Idle root 2D Blend Tree is missing.");
            RequireLightsaberLocomotionRootTree(root);

            LightsaberLocomotionSources sources = RequireLightsaberLocomotionSources(scene);
            AnimationClip idle = RequireLightsaberLocomotionClip(LocomotionIdleClipPath);
            AnimationClip forward = RequireLightsaberLocomotionClip(LocomotionForwardClipPath);
            AnimationClip backward = RequireLightsaberLocomotionClip(LocomotionBackwardClipPath);
            AnimationClip sidestep = RequireLightsaberLocomotionClip(LocomotionSidestepClipPath);
            AnimationClip run = RequireLightsaberLocomotionClip(LocomotionRunClipPath);
            RequireEqual(LightsaberClipSignature(sources.Idle),
                LightsaberClipSignature(idle), "Idle copy");
            RequireEqual(LightsaberClipSignature(sources.Forward),
                LightsaberClipSignature(forward), "WalkForward copy");
            RequireEqual(LightsaberClipSignature(sources.Backward),
                LightsaberClipSignature(backward), "WalkBackward copy");
            RequireEqual(LightsaberClipSignature(sources.Sidestep),
                LightsaberClipSignature(sidestep), "Sidestep copy");
            RequireEqual(LightsaberClipSignature(sources.Run),
                LightsaberClipSignature(run), "RunForward copy");
            RequireLightsaberDiagonalEquivalent(
                sources.Diagonal,
                root.children[4].motion as BlendTree,
                new Dictionary<AnimationClip, AnimationClip>
                {
                    [sources.Forward] = forward,
                    [sources.Sidestep] = sidestep
                });

            LightsaberOffIdleCarryPoseBehaviour carry =
                target.GetComponent<LightsaberOffIdleCarryPoseBehaviour>() ??
                throw new InvalidOperationException(
                    "Lightsaber_Off_Idle carry-pose behaviour is missing.");
            RequireLightsaberCarryPoseList(
                carry.AuthoredPose,
                CaptureLightsaberCarryPose(target.transform),
                "authored carry pose");
            RequireLightsaberCarryPoseList(
                carry.SourceIdlePose,
                CaptureLightsaberCarryPose(FindUnique(scene, "Player_Idle").transform),
                "source idle pose");
            Transform hand = RequireRightHand(target);
            Transform prop = RequireLightsaberProp(hand, target.name);
            if (prop.parent != hand)
                throw new InvalidOperationException(
                    "Lightsaber_Off_Idle prop no longer follows RightHand.");
            RequireAuthoredPropTransform(prop, target.name);
        }

        private static LightsaberLocomotionSources RequireLightsaberLocomotionSources(
            Scene scene)
        {
            Motion[] motions = LocomotionSourceNames.Select(name =>
            {
                GameObject source = FindUnique(scene, name);
                Animator animator = source.GetComponent<Animator>() ??
                    throw new InvalidOperationException(name + " Animator is missing.");
                AnimatorController controller =
                    animator.runtimeAnimatorController as AnimatorController ??
                    throw new InvalidOperationException(
                        name + " AnimatorController is missing.");
                return controller.layers[0].stateMachine.defaultState?.motion ??
                    throw new InvalidOperationException(name + " default motion is missing.");
            }).ToArray();
            if (!(motions[0] is AnimationClip idle) ||
                !(motions[1] is AnimationClip forward) ||
                !(motions[2] is AnimationClip backward) ||
                !(motions[3] is AnimationClip sidestep) ||
                !(motions[4] is BlendTree diagonal) ||
                !(motions[5] is AnimationClip run))
                throw new InvalidOperationException(
                    "Lightsaber locomotion source motion types differ.");
            if (diagonal.blendType != BlendTreeType.Simple1D ||
                diagonal.children.Length != 2)
                throw new InvalidOperationException(
                    "Player_Walk_Diagonal source tree differs.");
            return new LightsaberLocomotionSources(
                idle, forward, backward, sidestep, diagonal, run);
        }

        private static AnimationClip CopyLightsaberLocomotionClip(
            AnimationClip source,
            string path,
            string name)
        {
            AnimationClip copy = AssetDatabase.LoadAssetAtPath<AnimationClip>(path);
            if (copy == null)
            {
                copy = new AnimationClip();
                EditorUtility.CopySerialized(source, copy);
                copy.name = name;
                AssetDatabase.CreateAsset(copy, path);
            }
            else
            {
                EditorUtility.CopySerialized(source, copy);
                copy.name = name;
                EditorUtility.SetDirty(copy);
            }
            RequireEqual(LightsaberClipSignature(source),
                LightsaberClipSignature(copy), name + " serialized copy");
            return copy;
        }

        private static AnimatorController CreateLightsaberLocomotionController(
            BlendTree sourceDiagonal,
            AnimationClip idle,
            AnimationClip forward,
            AnimationClip backward,
            AnimationClip sidestep,
            AnimationClip run)
        {
            AnimatorController controller =
                AssetDatabase.LoadAssetAtPath<AnimatorController>(LocomotionControllerPath);
            if (controller == null)
                controller = AnimatorController.CreateAnimatorControllerAtPath(
                    LocomotionControllerPath);
            AnimatorControllerLayer layer = controller.layers[0];
            AnimatorStateMachine stateMachine = layer.stateMachine;
            foreach (AnimatorState existing in stateMachine.states
                .Select(item => item.state).ToArray())
                stateMachine.RemoveState(existing);
            foreach (AnimatorStateMachine existing in stateMachine.stateMachines
                .Select(item => item.stateMachine).ToArray())
                stateMachine.RemoveStateMachine(existing);
            foreach (BlendTree existing in AssetDatabase
                .LoadAllAssetsAtPath(LocomotionControllerPath)
                .OfType<BlendTree>().ToArray())
                UnityEngine.Object.DestroyImmediate(existing, true);

            controller.parameters = Array.Empty<AnimatorControllerParameter>();
            controller.AddParameter(
                LightsaberOffIdleLocomotionCycleBehaviour.MoveXParameter,
                AnimatorControllerParameterType.Float);
            controller.AddParameter(
                LightsaberOffIdleLocomotionCycleBehaviour.MoveYParameter,
                AnimatorControllerParameterType.Float);
            controller.AddParameter(new AnimatorControllerParameter
            {
                name = LightsaberOffIdleLocomotionCycleBehaviour.DiagonalBlendParameter,
                type = AnimatorControllerParameterType.Float,
                defaultFloat = 0.5f
            });
            layer.name = "Source Locomotion";
            layer.defaultWeight = 1f;
            layer.blendingMode = AnimatorLayerBlendingMode.Override;
            layer.avatarMask = null;

            ChildMotion[] diagonalChildren = sourceDiagonal.children;
            var clipMap = new Dictionary<AnimationClip, AnimationClip>
            {
                [(AnimationClip)diagonalChildren[0].motion] = forward,
                [(AnimationClip)diagonalChildren[1].motion] = sidestep
            };
            BlendTree diagonal = CloneLightsaberDiagonalTree(
                sourceDiagonal,
                LocomotionDiagonalTreeName,
                controller,
                clipMap);
            var root = new BlendTree
            {
                name = LocomotionRootTreeName,
                blendType = BlendTreeType.FreeformCartesian2D,
                blendParameter = LightsaberOffIdleLocomotionCycleBehaviour.MoveXParameter,
                blendParameterY = LightsaberOffIdleLocomotionCycleBehaviour.MoveYParameter,
                useAutomaticThresholds = false
            };
            AssetDatabase.AddObjectToAsset(root, controller);
            root.children = new[]
            {
                LightsaberLocomotionChild(idle, LocomotionPositions[0]),
                LightsaberLocomotionChild(forward, LocomotionPositions[1]),
                LightsaberLocomotionChild(backward, LocomotionPositions[2]),
                LightsaberLocomotionChild(sidestep, LocomotionPositions[3]),
                LightsaberLocomotionChild(diagonal, LocomotionPositions[4]),
                LightsaberLocomotionChild(run, LocomotionPositions[5])
            };
            AnimatorState state = stateMachine.AddState(LocomotionStateName);
            state.motion = root;
            state.speed = 1f;
            state.cycleOffset = 0f;
            state.mirror = false;
            state.writeDefaultValues = false;
            state.AddStateMachineBehaviour<LightsaberOffIdleLocomotionCycleBehaviour>();
            stateMachine.defaultState = state;
            controller.layers = new[] { layer };
            EditorUtility.SetDirty(controller);
            EditorUtility.SetDirty(stateMachine);
            EditorUtility.SetDirty(root);
            EditorUtility.SetDirty(diagonal);
            return controller;
        }

        private static BlendTree CloneLightsaberDiagonalTree(
            BlendTree source,
            string name,
            AnimatorController owner,
            IReadOnlyDictionary<AnimationClip, AnimationClip> clipMap)
        {
            var copy = new BlendTree
            {
                name = name,
                blendType = source.blendType,
                blendParameter = source.blendParameter,
                blendParameterY = source.blendParameterY,
                useAutomaticThresholds = source.useAutomaticThresholds,
                minThreshold = source.minThreshold,
                maxThreshold = source.maxThreshold
            };
            AssetDatabase.AddObjectToAsset(copy, owner);
            ChildMotion[] sourceChildren = source.children;
            var children = new ChildMotion[sourceChildren.Length];
            for (int index = 0; index < sourceChildren.Length; index++)
            {
                ChildMotion sourceChild = sourceChildren[index];
                Motion motion;
                if (sourceChild.motion is AnimationClip sourceClip)
                {
                    if (!clipMap.TryGetValue(sourceClip, out AnimationClip mapped))
                        throw new InvalidOperationException(
                            "Player_Walk_Diagonal clip mapping is missing.");
                    motion = mapped;
                }
                else if (sourceChild.motion is BlendTree nested)
                    motion = CloneLightsaberDiagonalTree(
                        nested, name + "_" + index, owner, clipMap);
                else
                    throw new InvalidOperationException(
                        "Player_Walk_Diagonal contains an unsupported motion.");
                children[index] = new ChildMotion
                {
                    motion = motion,
                    threshold = sourceChild.threshold,
                    position = sourceChild.position,
                    timeScale = sourceChild.timeScale,
                    cycleOffset = sourceChild.cycleOffset,
                    mirror = sourceChild.mirror,
                    directBlendParameter = sourceChild.directBlendParameter
                };
            }
            copy.children = children;
            return copy;
        }

        private static ChildMotion LightsaberLocomotionChild(
            Motion motion,
            Vector2 position)
        {
            return new ChildMotion
            {
                motion = motion,
                position = position,
                timeScale = 1f,
                cycleOffset = 0f,
                mirror = false,
                threshold = 0f,
                directBlendParameter = string.Empty
            };
        }

        private static void RequireLightsaberLocomotionRootTree(BlendTree root)
        {
            if (root.name != LocomotionRootTreeName ||
                root.blendType != BlendTreeType.FreeformCartesian2D ||
                root.blendParameter !=
                    LightsaberOffIdleLocomotionCycleBehaviour.MoveXParameter ||
                root.blendParameterY !=
                    LightsaberOffIdleLocomotionCycleBehaviour.MoveYParameter ||
                root.children.Length != LocomotionPositions.Length)
                throw new InvalidOperationException(
                    "Lightsaber_Off_Idle root 2D Blend Tree differs.");
            string[] paths =
            {
                LocomotionIdleClipPath,
                LocomotionForwardClipPath,
                LocomotionBackwardClipPath,
                LocomotionSidestepClipPath,
                LocomotionControllerPath,
                LocomotionRunClipPath
            };
            ChildMotion[] children = root.children;
            for (int index = 0; index < children.Length; index++)
            {
                if ((children[index].position - LocomotionPositions[index]).sqrMagnitude >
                        0.00000001f ||
                    !Mathf.Approximately(children[index].timeScale, 1f) ||
                    !Mathf.Approximately(children[index].cycleOffset, 0f) ||
                    children[index].mirror ||
                    AssetDatabase.GetAssetPath(children[index].motion) != paths[index])
                    throw new InvalidOperationException(
                        "Lightsaber_Off_Idle root motion differs at " + index + ".");
            }
        }

        private static void RequireLightsaberDiagonalEquivalent(
            BlendTree source,
            BlendTree copy,
            IReadOnlyDictionary<AnimationClip, AnimationClip> clipMap)
        {
            if (copy == null || source.blendType != copy.blendType ||
                source.blendParameter != copy.blendParameter ||
                source.blendParameterY != copy.blendParameterY ||
                source.useAutomaticThresholds != copy.useAutomaticThresholds ||
                !Mathf.Approximately(source.minThreshold, copy.minThreshold) ||
                !Mathf.Approximately(source.maxThreshold, copy.maxThreshold) ||
                source.children.Length != copy.children.Length)
                throw new InvalidOperationException(
                    "Lightsaber_Off_Idle diagonal source tree differs.");
            ChildMotion[] sourceChildren = source.children;
            ChildMotion[] copyChildren = copy.children;
            for (int index = 0; index < sourceChildren.Length; index++)
            {
                ChildMotion a = sourceChildren[index];
                ChildMotion b = copyChildren[index];
                if (!Mathf.Approximately(a.threshold, b.threshold) ||
                    (a.position - b.position).sqrMagnitude > 0.00000001f ||
                    !Mathf.Approximately(a.timeScale, b.timeScale) ||
                    !Mathf.Approximately(a.cycleOffset, b.cycleOffset) ||
                    a.mirror != b.mirror ||
                    a.directBlendParameter != b.directBlendParameter)
                    throw new InvalidOperationException(
                        "Lightsaber_Off_Idle diagonal child differs at " + index + ".");
                if (a.motion is AnimationClip sourceClip)
                {
                    if (!(b.motion is AnimationClip copiedClip) ||
                        !clipMap.TryGetValue(sourceClip, out AnimationClip expected) ||
                        copiedClip != expected)
                        throw new InvalidOperationException(
                            "Lightsaber_Off_Idle diagonal clip differs at " + index + ".");
                    RequireEqual(LightsaberClipSignature(sourceClip),
                        LightsaberClipSignature(copiedClip),
                        "diagonal clip " + index);
                }
                else if (a.motion is BlendTree sourceNested)
                    RequireLightsaberDiagonalEquivalent(
                        sourceNested, b.motion as BlendTree, clipMap);
                else
                    throw new InvalidOperationException(
                        "Lightsaber_Off_Idle diagonal motion type differs.");
            }
        }

        private static void RequireLightsaberLocomotionFloatParameter(
            AnimatorController controller,
            string name,
            float expectedDefault)
        {
            AnimatorControllerParameter parameter = controller.parameters
                .SingleOrDefault(item => item.name == name);
            if (parameter == null ||
                parameter.type != AnimatorControllerParameterType.Float ||
                !Mathf.Approximately(parameter.defaultFloat, expectedDefault))
                throw new InvalidOperationException(
                    "Lightsaber_Off_Idle parameter differs: " + name + ".");
        }

        private static AnimationClip RequireLightsaberLocomotionClip(string path)
        {
            return AssetDatabase.LoadAssetAtPath<AnimationClip>(path) ??
                throw new InvalidOperationException(
                    "Lightsaber_Off_Idle copied clip is missing: " + path);
        }

        private static List<LightsaberOffIdleBoneRotation> CaptureLightsaberCarryPose(
            Transform target)
        {
            return LocomotionCarryPosePaths.Select(path =>
            {
                Transform bone = target.Find(path) ??
                    throw new InvalidOperationException(
                        target.name + " carry pose path is missing: " + path);
                return new LightsaberOffIdleBoneRotation(path, bone.localRotation);
            }).ToList();
        }

        private static void RequireLightsaberCarryPoseList(
            IReadOnlyList<LightsaberOffIdleBoneRotation> actual,
            IReadOnlyList<LightsaberOffIdleBoneRotation> expected,
            string label)
        {
            if (actual.Count != expected.Count)
                throw new InvalidOperationException(label + " count differs.");
            for (int index = 0; index < actual.Count; index++)
                if (actual[index].Path != expected[index].Path ||
                    Quaternion.Angle(
                        actual[index].LocalRotation,
                        expected[index].LocalRotation) > 0.0001f)
                    throw new InvalidOperationException(
                        label + " differs at " + index + ".");
        }

        private static string LightsaberLocomotionSourceSignature(
            LightsaberLocomotionSources sources)
        {
            return string.Join("|", new[]
            {
                LightsaberClipSignature(sources.Idle),
                LightsaberClipSignature(sources.Forward),
                LightsaberClipSignature(sources.Backward),
                LightsaberClipSignature(sources.Sidestep),
                LightsaberMotionSignature(sources.Diagonal),
                LightsaberClipSignature(sources.Run)
            });
        }

        private static string LightsaberMotionSignature(Motion motion)
        {
            if (motion is AnimationClip clip) return LightsaberClipSignature(clip);
            if (!(motion is BlendTree tree))
                throw new InvalidOperationException("Unsupported locomotion motion type.");
            var text = new StringBuilder()
                .Append(tree.name).Append('|')
                .Append(tree.blendType).Append('|')
                .Append(tree.blendParameter).Append('|')
                .Append(tree.blendParameterY).Append('|')
                .Append(tree.useAutomaticThresholds).Append('|')
                .Append(Num(tree.minThreshold)).Append('|')
                .AppendLine(Num(tree.maxThreshold));
            foreach (ChildMotion child in tree.children)
                text.Append(Num(child.threshold)).Append('|')
                    .Append(Num(child.position.x)).Append('|')
                    .Append(Num(child.position.y)).Append('|')
                    .Append(Num(child.timeScale)).Append('|')
                    .Append(Num(child.cycleOffset)).Append('|')
                    .Append(child.mirror).Append('|')
                    .Append(child.directBlendParameter).Append('|')
                    .AppendLine(LightsaberMotionSignature(child.motion));
            return LightsaberSha256(text.ToString());
        }

        private static string LightsaberClipSignature(AnimationClip clip)
        {
            var result = new StringBuilder()
                .AppendLine("length=" + Num(clip.length))
                .AppendLine("frameRate=" + Num(clip.frameRate))
                .AppendLine("legacy=" + clip.legacy)
                .AppendLine("wrapMode=" + clip.wrapMode)
                .AppendLine("settings=" + EditorJsonUtility.ToJson(
                    AnimationUtility.GetAnimationClipSettings(clip)));
            foreach (EditorCurveBinding binding in AnimationUtility.GetCurveBindings(clip)
                .OrderBy(item => item.path, StringComparer.Ordinal)
                .ThenBy(item => item.type.FullName, StringComparer.Ordinal)
                .ThenBy(item => item.propertyName, StringComparer.Ordinal))
            {
                result.Append("curve|").Append(binding.path).Append('|')
                    .Append(binding.type.FullName).Append('|')
                    .AppendLine(binding.propertyName);
                AnimationCurve curve = AnimationUtility.GetEditorCurve(clip, binding);
                result.AppendLine("wrap=" + curve.preWrapMode + "," + curve.postWrapMode);
                foreach (Keyframe key in curve.keys)
                    result.AppendLine(string.Join(",", new[]
                    {
                        Num(key.time), Num(key.value), Num(key.inTangent), Num(key.outTangent),
                        Num(key.inWeight), Num(key.outWeight), key.weightedMode.ToString()
                    }));
            }
            foreach (EditorCurveBinding binding in AnimationUtility
                .GetObjectReferenceCurveBindings(clip)
                .OrderBy(item => item.path, StringComparer.Ordinal)
                .ThenBy(item => item.type.FullName, StringComparer.Ordinal)
                .ThenBy(item => item.propertyName, StringComparer.Ordinal))
            {
                result.Append("objectCurve|").Append(binding.path).Append('|')
                    .Append(binding.type.FullName).Append('|')
                    .AppendLine(binding.propertyName);
                foreach (ObjectReferenceKeyframe key in AnimationUtility
                    .GetObjectReferenceCurve(clip, binding))
                    result.AppendLine(Num(key.time) + "|" + ObjectIdentity(key.value));
            }
            foreach (AnimationEvent item in AnimationUtility.GetAnimationEvents(clip))
                result.AppendLine("event|" + Num(item.time) + "|" + item.functionName + "|" +
                    item.stringParameter + "|" + item.intParameter + "|" +
                    Num(item.floatParameter) + "|" + ObjectIdentity(
                        item.objectReferenceParameter) + "|" + item.messageOptions);
            return LightsaberSha256(result.ToString());
        }

        private static string LightsaberSha256(string value)
        {
            using (SHA256 sha = SHA256.Create())
                return BitConverter.ToString(
                    sha.ComputeHash(Encoding.UTF8.GetBytes(value)))
                    .Replace("-", string.Empty);
        }

        [MenuItem("Bellerophon/Player/Inspect Lightsaber Diagonal Slash Sources")]
        internal static void InspectLightsaberDiagonalSlashSources()
        {
            RequireEditMode();
            int consoleErrorsBefore = ConsoleErrorCount();
            string slashAbsolute = Absolute(DiagonalSlashSourceRelativePath);
            string mirrorAbsolute = Absolute(DiagonalSlashMirrorSourceRelativePath);
            if (!File.Exists(slashAbsolute) || !File.Exists(mirrorAbsolute))
                throw new InvalidOperationException(
                    "Both supplied lightsaber slash FBX files must exist.");

            Scene scene = RequireScene();
            GameObject target = FindUnique(scene, DiagonalSlashTargetName);
            Animator animator = target.GetComponent<Animator>() ??
                throw new InvalidOperationException(
                    DiagonalSlashTargetName + " Animator is missing.");
            if (animator.avatar == null)
                throw new InvalidOperationException(
                    DiagonalSlashTargetName + " Avatar is missing.");
            Transform hand = RequireRightHand(target);
            Transform prop = RequireLightsaberProp(hand, target.name);
            if (prop.parent != hand)
                throw new InvalidOperationException(
                    "Lightsaber_Prop must remain a direct RightHand child.");
            RequireAuthoredPropTransform(prop, target.name);

            RequireNoNewUnityConsoleErrors(consoleErrorsBefore);
            Debug.Log(
                "[LightsaberDiagonalSlash] Sources inspected read-only." +
                " slashBytes=" + new FileInfo(slashAbsolute).Length +
                "|slashSha256=" + Sha256File(slashAbsolute) +
                "|mirrorBytes=" + new FileInfo(mirrorAbsolute).Length +
                "|mirrorSha256=" + Sha256File(mirrorAbsolute) +
                "|targetAvatar=" + ObjectIdentity(animator.avatar) +
                "|targetRoot=" + Precise(target.transform.position) +
                "|propParent=" + prop.parent.name +
                "|verificationTargetTransformManipulated=False");
        }

        [MenuItem("Bellerophon/Player/Apply Lightsaber Diagonal Slash Sequence")]
        internal static void ApplyLightsaberDiagonalSlashSequence()
        {
            RequireEditMode();
            int consoleErrorsBefore = ConsoleErrorCount();
            Scene scene = RequireScene();
            if (scene.isDirty)
                throw new InvalidOperationException(
                    "Lightsaber_DiagonalSlash setup requires a clean CargoRunMvp scene.");

            GameObject target = FindUnique(scene, DiagonalSlashTargetName);
            Animator animator = target.GetComponent<Animator>() ??
                throw new InvalidOperationException(
                    DiagonalSlashTargetName + " Animator is missing.");
            if (animator.avatar == null)
                throw new InvalidOperationException(
                    DiagonalSlashTargetName + " Avatar is missing.");
            Transform hand = RequireRightHand(target);
            Transform prop = RequireLightsaberProp(hand, target.name);
            if (prop.parent != hand)
                throw new InvalidOperationException(
                    "Lightsaber_Prop must remain a direct RightHand child.");
            RequireAuthoredPropTransform(prop, target.name);

            var targetRootBefore = new TransformSnapshot(target.transform);
            var propBefore = new TransformSnapshot(prop);
            Dictionary<string, DiagonalSlashLocalPose> currentPose =
                CaptureDiagonalSlashPose(target.transform, prop);
            string rendererBefore = RendererSignature(target.transform);
            string avatarBefore = ObjectIdentity(animator.avatar);

            EnsureFolder(DiagonalSlashAssetFolder);
            EnsureFolder(DiagonalSlashSourceFolder);
            EnsureDiagonalSlashSourceCopy(
                DiagonalSlashSourceRelativePath,
                DiagonalSlashSourcePath,
                "slash");
            EnsureDiagonalSlashSourceCopy(
                DiagonalSlashMirrorSourceRelativePath,
                DiagonalSlashMirrorSourcePath,
                "mirror slash");
            ConfigureDiagonalSlashSourceImporter(
                DiagonalSlashSourcePath, "slash");
            ConfigureDiagonalSlashSourceImporter(
                DiagonalSlashMirrorSourcePath, "mirror slash");

            AnimationClip slashSource = RequireSingleDiagonalSlashClip(
                DiagonalSlashSourcePath, "slash");
            AnimationClip mirrorSource = RequireSingleDiagonalSlashClip(
                DiagonalSlashMirrorSourcePath, "mirror slash");
            RequireDiagonalSlashBindingCompatibility(target.transform, slashSource, "slash");
            RequireDiagonalSlashBindingCompatibility(target.transform, mirrorSource, "mirror slash");

            Dictionary<string, DiagonalSlashLocalPose> slashFirst =
                SampleDiagonalSlashPose(target, prop, slashSource, 0f, currentPose);
            Dictionary<string, DiagonalSlashLocalPose> slashLast =
                SampleDiagonalSlashPose(
                    target, prop, slashSource, slashSource.length, currentPose);
            Dictionary<string, DiagonalSlashLocalPose> mirrorFirst =
                SampleDiagonalSlashPose(target, prop, mirrorSource, 0f, currentPose);

            AnimationClip startTransition = CreateOrUpdateDiagonalSlashTransitionClip(
                DiagonalSlashStartTransitionClipPath,
                "LightsaberDiagonalSlash_StartToSlash",
                currentPose,
                slashFirst);
            AnimationClip slash = CopyExactDiagonalSlashClip(
                slashSource,
                DiagonalSlashClipPath,
                "LightsaberDiagonalSlash_SourceExact");
            AnimationClip mirrorTransition = CreateOrUpdateDiagonalSlashTransitionClip(
                DiagonalSlashMirrorTransitionClipPath,
                "LightsaberDiagonalSlash_SlashToMirror",
                slashLast,
                mirrorFirst);
            AnimationClip mirror = CopyExactDiagonalSlashClip(
                mirrorSource,
                DiagonalSlashMirrorClipPath,
                "LightsaberDiagonalSlash_MirrorSourceExact");
            AnimatorController controller = CreateOrUpdateDiagonalSlashController(
                startTransition, slash, mirrorTransition, mirror);

            Undo.RecordObject(animator, "Configure Lightsaber_DiagonalSlash sequence");
            animator.runtimeAnimatorController = controller;
            animator.applyRootMotion = false;
            animator.enabled = true;
            animator.cullingMode = AnimatorCullingMode.AlwaysAnimate;
            PrefabUtility.RecordPrefabInstancePropertyModifications(animator);
            EditorUtility.SetDirty(animator);
            AssetDatabase.SaveAssets();

            targetRootBefore.RequireUnchanged();
            propBefore.RequireUnchanged();
            RequireDiagonalSlashPoseEqual(
                currentPose,
                CaptureDiagonalSlashPose(target.transform, prop),
                "scene pose after setup");
            RequireEqual(rendererBefore, RendererSignature(target.transform),
                "Lightsaber_DiagonalSlash renderer hierarchy");
            RequireEqual(avatarBefore, ObjectIdentity(animator.avatar),
                "Lightsaber_DiagonalSlash Avatar");

            if (!EditorSceneManager.SaveScene(scene))
                throw new InvalidOperationException(
                    "CargoRunMvp could not save Lightsaber_DiagonalSlash sequence.");
            InspectLightsaberDiagonalSlashSequenceInternal(scene, false);
            RequireNoNewUnityConsoleErrors(consoleErrorsBefore);
            Debug.Log(
                "[LightsaberDiagonalSlash] Sequence applied: current pose -> 0.4s " +
                "generated bridge -> exact slash -> 0.4s generated bridge -> exact " +
                "mirror slash -> immediate start-pose return -> repeat. Root locked; " +
                "Lightsaber_Prop remained a direct RightHand child.");
        }

        [MenuItem("Bellerophon/Player/Inspect Lightsaber Diagonal Slash Sequence")]
        internal static void InspectLightsaberDiagonalSlashSequence()
        {
            RequireEditMode();
