        [MenuItem("Bellerophon/Player/Apply Lightsaber Diagonal Slash Blade Trajectory")]
        internal static void ApplyLightsaberDiagonalSlashBladeTrajectory()
        {
            RequireEditMode();
            int consoleErrorsBefore = ConsoleErrorCount();
            Scene scene = RequireScene();
            if (scene.isDirty)
                throw new InvalidOperationException(
                    "Lightsaber blade trajectory setup requires a clean CargoRunMvp scene.");
            InspectLightsaberDiagonalSlashSequenceInternal(scene, false);

            GameObject target = FindUnique(scene, DiagonalSlashTargetName);
            Animator animator = target.GetComponent<Animator>() ??
                throw new InvalidOperationException(
                    DiagonalSlashTargetName + " Animator is missing.");
            Transform hand = RequireRightHand(target);
            Transform prop = RequireLightsaberProp(hand, target.name);
            RequireAuthoredPropTransform(prop, target.name);
            var targetRootBefore = new TransformSnapshot(target.transform);
            var propBefore = new TransformSnapshot(prop);
            string rendererBefore = RendererSignature(target.transform);
            string avatarBefore = ObjectIdentity(animator.avatar);

            AnimationClip baseStart = RequireDiagonalSlashAsset<AnimationClip>(
                DiagonalSlashStartTransitionClipPath);
            AnimationClip baseSlash = RequireDiagonalSlashAsset<AnimationClip>(
                DiagonalSlashClipPath);
            AnimationClip baseBridge = RequireDiagonalSlashAsset<AnimationClip>(
                DiagonalSlashMirrorTransitionClipPath);
            AnimationClip baseMirror = RequireDiagonalSlashAsset<AnimationClip>(
                DiagonalSlashMirrorClipPath);
            string baseStartSignature = LightsaberClipSignature(baseStart);
            string baseSlashSignature = LightsaberClipSignature(baseSlash);
            string baseBridgeSignature = LightsaberClipSignature(baseBridge);
            string baseMirrorSignature = LightsaberClipSignature(baseMirror);
            Dictionary<string, DiagonalSlashLocalPose> currentPose =
                CaptureDiagonalSlashPose(target.transform, prop);
            Vector3 bladeAxis = DiagonalSlashBladeAxisLocal();

            DiagonalSlashTrajectoryClipResult slashResult =
                CreateOrUpdateDiagonalSlashTrajectoryClip(
                    target,
                    prop,
                    baseSlash,
                    DiagonalSlashTrajectoryClipPath,
                    "LightsaberDiagonalSlash_Source_BladeTrajectory",
                    currentPose,
                    bladeAxis,
                    false);
            DiagonalSlashTrajectoryClipResult mirrorResult =
                CreateOrUpdateDiagonalSlashTrajectoryClip(
                    target,
                    prop,
                    baseMirror,
                    DiagonalSlashTrajectoryMirrorClipPath,
                    "LightsaberDiagonalSlash_MirrorSource_BladeTrajectory",
                    currentPose,
                    bladeAxis,
                    true);
            AnimationClip start = CreateOrUpdateDiagonalSlashPropBridgeClip(
                baseStart,
                DiagonalSlashTrajectoryStartTransitionClipPath,
                "LightsaberDiagonalSlash_StartToSlash_BladeTrajectory",
                AuthoredPropLocalRotation,
                slashResult.Rotations[0]);
            AnimationClip bridge = CreateOrUpdateDiagonalSlashPropBridgeClip(
                baseBridge,
                DiagonalSlashTrajectoryMirrorTransitionClipPath,
                "LightsaberDiagonalSlash_SlashToMirror_BladeTrajectory",
                slashResult.Rotations[slashResult.Rotations.Count - 1],
                mirrorResult.Rotations[0]);
            AnimatorController controller = CreateOrUpdateDiagonalSlashController(
                start, slashResult.Clip, bridge, mirrorResult.Clip);

            Undo.RecordObject(animator,
                "Configure Lightsaber_DiagonalSlash blade trajectory");
            animator.runtimeAnimatorController = controller;
            animator.applyRootMotion = false;
            animator.enabled = true;
            animator.cullingMode = AnimatorCullingMode.AlwaysAnimate;
            PrefabUtility.RecordPrefabInstancePropertyModifications(animator);
            EditorUtility.SetDirty(animator);
            AssetDatabase.SaveAssets();

            RequireEqual(baseStartSignature, LightsaberClipSignature(baseStart),
                "protected start transition clip");
            RequireEqual(baseSlashSignature, LightsaberClipSignature(baseSlash),
                "protected exact slash character clip");
            RequireEqual(baseBridgeSignature, LightsaberClipSignature(baseBridge),
                "protected mirror transition clip");
            RequireEqual(baseMirrorSignature, LightsaberClipSignature(baseMirror),
                "protected exact mirror character clip");
            targetRootBefore.RequireUnchanged();
            propBefore.RequireUnchanged();
            RequireEqual(rendererBefore, RendererSignature(target.transform),
                "Lightsaber_DiagonalSlash renderer hierarchy");
            RequireEqual(avatarBefore, ObjectIdentity(animator.avatar),
                "Lightsaber_DiagonalSlash Avatar");
            if (!EditorSceneManager.SaveScene(scene))
                throw new InvalidOperationException(
                    "CargoRunMvp could not save the lightsaber blade trajectory.");
            InspectLightsaberDiagonalSlashBladeTrajectoryInternal(scene, false);
            RequireNoNewUnityConsoleErrors(consoleErrorsBefore);
            Debug.Log(
                "[LightsaberBladeTrajectory] Applied GIF-normalized slash blade " +
                "rotation and its left-right mirrored counterpart. Character curves, " +
                "clip durations, prop position/scale, root and renderer data were preserved.");
        }

