        [MenuItem("Bellerophon/Player/Apply Lightsaber Grip One Hand Transition")]
        internal static void ApplyLightsaberGripOneHandTransition()
        {
            RequireEditMode();
            int consoleErrorsBefore = ConsoleErrorCount();
            Scene scene = RequireScene();
            if (scene.isDirty)
                throw new InvalidOperationException(
                    "Lightsaber_Grip_OneHand setup requires a clean CargoRunMvp scene.");
            GameObject target = FindUnique(scene, GripOneHandTargetName);
            Animator animator = target.GetComponent<Animator>() ??
                throw new InvalidOperationException(
                    GripOneHandTargetName + " Animator is missing.");
            Transform hand = RequireRightHand(target);
            Transform prop = RequireLightsaberProp(hand, target.name);
            RequireAuthoredPropTransform(prop, target.name);
            var rootBefore = new TransformSnapshot(target.transform);
            var propBefore = new TransformSnapshot(prop);
            Dictionary<string, DiagonalSlashLocalPose> scenePoseBefore =
                CaptureDiagonalSlashPose(target.transform, prop);
            string rendererBefore = RendererSignature(target.transform);
            string avatarBefore = ObjectIdentity(animator.avatar);

            InspectLightsaberGripOneHandTransitionSourcesInternal(
                scene,
                out Dictionary<string, DiagonalSlashLocalPose> slashFirst,
                out Dictionary<string, DiagonalSlashLocalPose> offIdlePose,
                out AnimationClip slashSource);
            string slashSourceSignature = LightsaberClipSignature(slashSource);
            EnsureFolder(GripOneHandAssetFolder);
            AnimationClip cycle = CreateOrUpdateGripOneHandCycleClip(
                slashFirst, offIdlePose);
            if (AssetDatabase.LoadMainAssetAtPath(GripOneHandTransitionClipPath) != null)
                AssetDatabase.DeleteAsset(GripOneHandTransitionClipPath);
            if (AssetDatabase.LoadMainAssetAtPath(GripOneHandHoldClipPath) != null)
                AssetDatabase.DeleteAsset(GripOneHandHoldClipPath);
            AnimatorController controller = CreateOrUpdateGripOneHandController(cycle);

            Undo.RecordObject(animator, "Configure Lightsaber_Grip_OneHand sequence");
            animator.runtimeAnimatorController = controller;
            animator.applyRootMotion = false;
            animator.enabled = true;
            animator.cullingMode = AnimatorCullingMode.AlwaysAnimate;
            PrefabUtility.RecordPrefabInstancePropertyModifications(animator);
            EditorUtility.SetDirty(animator);
            AssetDatabase.SaveAssets();

            RequireEqual(
                slashSourceSignature,
                LightsaberClipSignature(slashSource),
                "protected exact slash source");
            rootBefore.RequireUnchanged();
            propBefore.RequireUnchanged();
            RequireDiagonalSlashPoseEqual(
                scenePoseBefore,
                CaptureDiagonalSlashPose(target.transform, prop),
                "Lightsaber_Grip_OneHand scene pose after setup");
            RequireEqual(rendererBefore, RendererSignature(target.transform),
                "Lightsaber_Grip_OneHand renderer hierarchy");
