                "Lightsaber_Grip_OneHand Avatar");
            if (!EditorSceneManager.SaveScene(scene))
                throw new InvalidOperationException(
                    "CargoRunMvp could not save Lightsaber_Grip_OneHand sequence.");
            InspectLightsaberGripOneHandTransitionInternal(scene, false);
            RequireNoNewUnityConsoleErrors(consoleErrorsBefore);
            Debug.Log(
                "[LightsaberGripOneHand] Applied exact slash-first -> 0.4-second " +
                "Off_Idle transition -> 0.5-second hold -> immediate reset loop. " +
                "Root, renderers and Lightsaber_Prop grip transform were preserved.");
