        private static void InspectLightsaberGripOneHandTransitionSourcesInternal(
            Scene scene,
            out Dictionary<string, DiagonalSlashLocalPose> slashFirst,
            out Dictionary<string, DiagonalSlashLocalPose> offIdlePose,
            out AnimationClip slashSource)
        {
            GameObject target = FindUnique(scene, GripOneHandTargetName);
            GameObject offIdle = FindUnique(scene, TransformReplicationSourceName);
            Animator targetAnimator = target.GetComponent<Animator>() ??
                throw new InvalidOperationException(
                    GripOneHandTargetName + " Animator is missing.");
            Animator offIdleAnimator = offIdle.GetComponent<Animator>() ??
                throw new InvalidOperationException(
                    TransformReplicationSourceName + " Animator is missing.");
            if (targetAnimator.avatar == null || offIdleAnimator.avatar == null ||
                targetAnimator.avatar != offIdleAnimator.avatar)
                throw new InvalidOperationException(
                    "Lightsaber_Grip_OneHand and Lightsaber_Off_Idle Avatars differ.");
            Transform targetProp = RequireLightsaberProp(
                RequireRightHand(target), target.name);
            Transform offIdleProp = RequireLightsaberProp(
                RequireRightHand(offIdle), offIdle.name);
            RequireAuthoredPropTransform(targetProp, target.name);
            RequireAuthoredPropTransform(offIdleProp, offIdle.name);
            Dictionary<string, DiagonalSlashLocalPose> targetRestorePose =
                CaptureDiagonalSlashPose(target.transform, targetProp);
            offIdlePose = CaptureDiagonalSlashPose(offIdle.transform, offIdleProp);
            slashSource = RequireDiagonalSlashAsset<AnimationClip>(
                DiagonalSlashClipPath);
            RequireNoPropCurves(slashSource, "protected exact slash source");
            slashFirst = SampleDiagonalSlashPose(
                target, targetProp, slashSource, 0f, targetRestorePose);
            RequireGripOneHandPosePathSets(slashFirst, offIdlePose);
        }

        private static AnimationClip CreateOrUpdateGripOneHandPoseClip(
            string assetPath,
            string clipName,
            IReadOnlyDictionary<string, DiagonalSlashLocalPose> from,
            IReadOnlyDictionary<string, DiagonalSlashLocalPose> to,
            float duration)
        {
            RequireGripOneHandPosePathSets(from, to);
            var generated = new AnimationClip
            {
                name = clipName,
                frameRate = 60f,
                legacy = false,
                wrapMode = WrapMode.ClampForever
            };
            foreach (string posePath in from.Keys.OrderBy(
                item => item, StringComparer.Ordinal))
            {
                DiagonalSlashLocalPose a = from[posePath];
                DiagonalSlashLocalPose b = to[posePath];
                Quaternion endRotation = b.Rotation;
                if (Quaternion.Dot(a.Rotation, endRotation) < 0f)
                    endRotation = NegateQuaternion(endRotation);
                SetGripOneHandCurve(generated, posePath, "m_LocalPosition.x",
                    a.Position.x, b.Position.x, duration);
                SetGripOneHandCurve(generated, posePath, "m_LocalPosition.y",
                    a.Position.y, b.Position.y, duration);
                SetGripOneHandCurve(generated, posePath, "m_LocalPosition.z",
                    a.Position.z, b.Position.z, duration);
                SetGripOneHandCurve(generated, posePath, "m_LocalRotation.x",
                    a.Rotation.x, endRotation.x, duration);
                SetGripOneHandCurve(generated, posePath, "m_LocalRotation.y",
                    a.Rotation.y, endRotation.y, duration);
                SetGripOneHandCurve(generated, posePath, "m_LocalRotation.z",
                    a.Rotation.z, endRotation.z, duration);
                SetGripOneHandCurve(generated, posePath, "m_LocalRotation.w",
                    a.Rotation.w, endRotation.w, duration);
                SetGripOneHandCurve(generated, posePath, "m_LocalScale.x",
                    a.Scale.x, b.Scale.x, duration);
                SetGripOneHandCurve(generated, posePath, "m_LocalScale.y",
                    a.Scale.y, b.Scale.y, duration);
                SetGripOneHandCurve(generated, posePath, "m_LocalScale.z",
                    a.Scale.z, b.Scale.z, duration);
            }
            generated.EnsureQuaternionContinuity();
            FlattenThrustModeEnterHoldTangents(generated);
            AnimationClipSettings settings =
                AnimationUtility.GetAnimationClipSettings(generated);
            settings.loopTime = false;
            settings.loopBlend = false;
            AnimationUtility.SetAnimationClipSettings(generated, settings);
            AnimationClip clip = AssetDatabase.LoadAssetAtPath<AnimationClip>(assetPath);
            if (clip == null)
            {
                AssetDatabase.CreateAsset(generated, assetPath);
                clip = generated;
            }
            else
            {
                EditorUtility.CopySerialized(generated, clip);
                clip.name = clipName;
                EditorUtility.SetDirty(clip);
                UnityEngine.Object.DestroyImmediate(generated);
            }
            RequireGripOneHandClipDuration(clip, duration, clipName);
            RequireNoPropCurves(clip, clipName);
            return clip;
        }

        private static AnimationClip CreateOrUpdateGripOneHandCycleClip(
            IReadOnlyDictionary<string, DiagonalSlashLocalPose> slashFirst,
            IReadOnlyDictionary<string, DiagonalSlashLocalPose> offIdlePose)
        {
            RequireGripOneHandPosePathSets(slashFirst, offIdlePose);
            float cycleSeconds =
                GripOneHandTransitionSeconds + GripOneHandHoldSeconds;
            var generated = new AnimationClip
            {
                name = "LightsaberGripOneHand_SlashFirst_To_OffIdle_Hold_0_9s",
                frameRate = 60f,
                legacy = false,
                wrapMode = WrapMode.Loop
            };
            foreach (string posePath in slashFirst.Keys.OrderBy(
                item => item, StringComparer.Ordinal))
            {
                DiagonalSlashLocalPose a = slashFirst[posePath];
                DiagonalSlashLocalPose b = offIdlePose[posePath];
                Quaternion endRotation = b.Rotation;
                if (Quaternion.Dot(a.Rotation, endRotation) < 0f)
                    endRotation = NegateQuaternion(endRotation);
                SetGripOneHandCycleCurve(generated, posePath, "m_LocalPosition.x",
                    a.Position.x, b.Position.x, cycleSeconds);
                SetGripOneHandCycleCurve(generated, posePath, "m_LocalPosition.y",
                    a.Position.y, b.Position.y, cycleSeconds);
                SetGripOneHandCycleCurve(generated, posePath, "m_LocalPosition.z",
                    a.Position.z, b.Position.z, cycleSeconds);
                SetGripOneHandCycleCurve(generated, posePath, "m_LocalRotation.x",
                    a.Rotation.x, endRotation.x, cycleSeconds);
                SetGripOneHandCycleCurve(generated, posePath, "m_LocalRotation.y",
                    a.Rotation.y, endRotation.y, cycleSeconds);
                SetGripOneHandCycleCurve(generated, posePath, "m_LocalRotation.z",
                    a.Rotation.z, endRotation.z, cycleSeconds);
                SetGripOneHandCycleCurve(generated, posePath, "m_LocalRotation.w",
                    a.Rotation.w, endRotation.w, cycleSeconds);
                SetGripOneHandCycleCurve(generated, posePath, "m_LocalScale.x",
                    a.Scale.x, b.Scale.x, cycleSeconds);
                SetGripOneHandCycleCurve(generated, posePath, "m_LocalScale.y",
                    a.Scale.y, b.Scale.y, cycleSeconds);
                SetGripOneHandCycleCurve(generated, posePath, "m_LocalScale.z",
                    a.Scale.z, b.Scale.z, cycleSeconds);
            }
            generated.EnsureQuaternionContinuity();
            AnimationClipSettings settings =
                AnimationUtility.GetAnimationClipSettings(generated);
            settings.loopTime = true;
            settings.loopBlend = false;
            AnimationUtility.SetAnimationClipSettings(generated, settings);
            AnimationClip clip = AssetDatabase.LoadAssetAtPath<AnimationClip>(
                GripOneHandCycleClipPath);
            if (clip == null)
            {
                AssetDatabase.CreateAsset(generated, GripOneHandCycleClipPath);
                clip = generated;
            }
            else
            {
                EditorUtility.CopySerialized(generated, clip);
                clip.name = generated.name;
                EditorUtility.SetDirty(clip);
                UnityEngine.Object.DestroyImmediate(generated);
            }
            RequireGripOneHandCycleClip(clip);
            RequireNoPropCurves(clip, "GripOneHand cycle");
            return clip;
        }

        private static void SetGripOneHandCycleCurve(
            AnimationClip clip,
            string posePath,
            string property,
            float from,
            float to,
            float cycleSeconds)
        {
            var curve = new AnimationCurve(
                new Keyframe(0f, from, 0f, 0f),
                new Keyframe(GripOneHandTransitionSeconds, to, 0f, 0f),
                new Keyframe(cycleSeconds, to, 0f, 0f))
            {
                preWrapMode = WrapMode.ClampForever,
                postWrapMode = WrapMode.ClampForever
            };
            AnimationUtility.SetEditorCurve(
                clip,
                EditorCurveBinding.FloatCurve(
                    posePath, typeof(Transform), property),
                curve);
        }

        private static void SetGripOneHandCurve(
            AnimationClip clip,
            string posePath,
            string property,
            float from,
            float to,
            float duration)
        {
            var curve = new AnimationCurve(
                new Keyframe(0f, from, 0f, 0f),
                new Keyframe(duration, to, 0f, 0f))
            {
                preWrapMode = WrapMode.ClampForever,
                postWrapMode = WrapMode.ClampForever
            };
            AnimationUtility.SetEditorCurve(
                clip,
                EditorCurveBinding.FloatCurve(
                    posePath, typeof(Transform), property),
                curve);
        }

        private static AnimatorController CreateOrUpdateGripOneHandController(
            AnimationClip cycle)
        {
            AnimatorController controller =
                AssetDatabase.LoadAssetAtPath<AnimatorController>(
                    GripOneHandControllerPath);
            if (controller == null)
                controller = AnimatorController.CreateAnimatorControllerAtPath(
                    GripOneHandControllerPath);
            while (controller.layers.Length > 1)
                controller.RemoveLayer(controller.layers.Length - 1);
            if (controller.layers.Length != 1)
                throw new InvalidOperationException(
                    "Lightsaber_Grip_OneHand controller must contain one layer.");
            AnimatorControllerLayer layer = controller.layers[0];
            AnimatorStateMachine stateMachine = layer.stateMachine;
            foreach (AnimatorState existingState in stateMachine.states
                .Select(item => item.state).ToArray())
                stateMachine.RemoveState(existingState);
            foreach (AnimatorStateMachine nested in stateMachine.stateMachines
                .Select(item => item.stateMachine).ToArray())
                stateMachine.RemoveStateMachine(nested);
            controller.parameters = Array.Empty<AnimatorControllerParameter>();
            layer.name = "Lightsaber Grip One Hand Sequence";
            layer.defaultWeight = 1f;
            layer.blendingMode = AnimatorLayerBlendingMode.Override;
            layer.avatarMask = null;
            AnimatorState cycleState = AddGripOneHandState(
                stateMachine, GripOneHandCycleStateName, cycle);
            stateMachine.defaultState = cycleState;
            controller.layers = new[] { layer };
            EditorUtility.SetDirty(stateMachine);
            EditorUtility.SetDirty(controller);
            return controller;
        }

        private static AnimatorState AddGripOneHandState(
            AnimatorStateMachine stateMachine,
            string stateName,
            Motion motion)
        {
            AnimatorState state = stateMachine.AddState(stateName);
            state.motion = motion;
            state.speed = 1f;
            state.cycleOffset = 0f;
            state.mirror = false;
            state.writeDefaultValues = false;
            return state;
        }

        private static void AddImmediateGripOneHandTransition(
            AnimatorState source,
            AnimatorState destination)
        {
            AnimatorStateTransition transition = source.AddTransition(destination);
            transition.hasExitTime = true;
            transition.exitTime = 1f;
            transition.hasFixedDuration = true;
            transition.duration = 0f;
            transition.offset = 0f;
            transition.interruptionSource = TransitionInterruptionSource.None;
            transition.orderedInterruption = true;
            transition.canTransitionToSelf = false;
        }

        private static void InspectLightsaberGripOneHandTransitionInternal(
            Scene scene,
            bool requireCleanScene)
        {
            if (requireCleanScene && scene.isDirty)
                throw new InvalidOperationException(
                    "Lightsaber_Grip_OneHand inspection requires a clean scene.");
            InspectLightsaberGripOneHandTransitionSourcesInternal(
                scene,
                out Dictionary<string, DiagonalSlashLocalPose> slashFirst,
                out Dictionary<string, DiagonalSlashLocalPose> offIdlePose,
                out _);
            AnimationClip cycle = RequireDiagonalSlashAsset<AnimationClip>(
                GripOneHandCycleClipPath);
            RequireGripOneHandCycleClip(cycle);
            RequireNoPropCurves(cycle, "GripOneHand cycle");
            if (AssetDatabase.LoadMainAssetAtPath(GripOneHandTransitionClipPath) != null ||
                AssetDatabase.LoadMainAssetAtPath(GripOneHandHoldClipPath) != null)
                throw new InvalidOperationException(
                    "Obsolete two-state Grip One Hand assets remain.");

            GameObject target = FindUnique(scene, GripOneHandTargetName);
            Transform hand = RequireRightHand(target);
            Transform prop = RequireLightsaberProp(hand, target.name);
            RequireAuthoredPropTransform(prop, target.name);
            Dictionary<string, DiagonalSlashLocalPose> restorePose =
                CaptureDiagonalSlashPose(target.transform, prop);
            RequireDiagonalSlashPoseEqual(
                slashFirst,
                SampleDiagonalSlashPose(
                    target, prop, cycle, 0f, restorePose),
                "GripOneHand transition start");
            RequireDiagonalSlashPoseEqual(
                offIdlePose,
                SampleDiagonalSlashPose(
                    target, prop, cycle,
                    GripOneHandTransitionSeconds, restorePose),
                "GripOneHand transition end");
            RequireDiagonalSlashPoseEqual(
                offIdlePose,
                SampleDiagonalSlashPose(
                    target, prop, cycle,
                    GripOneHandTransitionSeconds + GripOneHandHoldSeconds * 0.5f,
                    restorePose),
                "GripOneHand hold midpoint");

            Animator animator = target.GetComponent<Animator>() ??
                throw new InvalidOperationException(
                    GripOneHandTargetName + " Animator is missing.");
            AnimatorController controller = animator.runtimeAnimatorController as
                AnimatorController ?? throw new InvalidOperationException(
                    "Lightsaber_Grip_OneHand controller is missing.");
            if (AssetDatabase.GetAssetPath(controller) != GripOneHandControllerPath ||
                animator.applyRootMotion || !animator.enabled ||
                animator.cullingMode != AnimatorCullingMode.AlwaysAnimate)
                throw new InvalidOperationException(
                    "Lightsaber_Grip_OneHand Animator settings differ.");
            if (controller.layers.Length != 1)
                throw new InvalidOperationException(
                    "Lightsaber_Grip_OneHand controller layer count differs.");
            AnimatorStateMachine stateMachine = controller.layers[0].stateMachine;
            AnimatorState[] states = stateMachine.states
                .Select(item => item.state).ToArray();
            if (states.Length != 1 || stateMachine.stateMachines.Length != 0 ||
                controller.parameters.Length != 0)
                throw new InvalidOperationException(
                    "Lightsaber_Grip_OneHand controller structure differs.");
            AnimatorState cycleState = RequireGripOneHandState(
                states, GripOneHandCycleStateName, cycle);
            if (stateMachine.defaultState != cycleState ||
                cycleState.transitions.Length != 0)
                throw new InvalidOperationException(
                    "Lightsaber_Grip_OneHand default state differs.");
        }

        private static AnimatorState RequireGripOneHandState(
            IEnumerable<AnimatorState> states,
            string stateName,
            Motion expectedMotion)
        {
            AnimatorState state = states.SingleOrDefault(item => item.name == stateName) ??
                throw new InvalidOperationException(
                    "Lightsaber_Grip_OneHand state is missing: " + stateName);
            if (state.motion != expectedMotion || Mathf.Abs(state.speed - 1f) > 0.0001f ||
                state.mirror || state.writeDefaultValues || state.behaviours.Length != 0)
                throw new InvalidOperationException(
                    "Lightsaber_Grip_OneHand state settings differ: " + stateName);
            return state;
        }

        private static void RequireImmediateGripOneHandTransition(
            AnimatorState source,
            AnimatorState destination,
            string label)
        {
            if (source.transitions.Length != 1)
                throw new InvalidOperationException(label + " transition count differs.");
            AnimatorStateTransition transition = source.transitions[0];
            if (transition.destinationState != destination || !transition.hasExitTime ||
                Mathf.Abs(transition.exitTime - 1f) > 0.0001f ||
                !transition.hasFixedDuration || Mathf.Abs(transition.duration) > 0.0001f ||
                Mathf.Abs(transition.offset) > 0.0001f ||
                transition.conditions.Length != 0 || transition.canTransitionToSelf)
                throw new InvalidOperationException(label + " transition settings differ.");
        }

        private static void RequireGripOneHandClipDuration(
            AnimationClip clip,
            float expectedDuration,
            string label)
        {
            if (Mathf.Abs(clip.length - expectedDuration) > 0.0001f ||
                Mathf.Abs(clip.frameRate - 60f) > 0.0001f || clip.isLooping)
                throw new InvalidOperationException(
                    "Lightsaber_Grip_OneHand " + label + " duration differs.");
        }

        private static void RequireGripOneHandCycleClip(AnimationClip clip)
        {
            float expected = GripOneHandTransitionSeconds + GripOneHandHoldSeconds;
            if (Mathf.Abs(clip.length - expected) > 0.0001f ||
                Mathf.Abs(clip.frameRate - 60f) > 0.0001f || !clip.isLooping)
                throw new InvalidOperationException(
                    "Lightsaber_Grip_OneHand cycle must be an exact looping " +
                    "0.4-second transition plus 0.5-second hold.");
            foreach (EditorCurveBinding binding in
                AnimationUtility.GetCurveBindings(clip))
            {
                AnimationCurve curve = AnimationUtility.GetEditorCurve(clip, binding);
                if (curve == null || curve.keys.Length != 3 ||
                    Mathf.Abs(curve.keys[0].time) > 0.0001f ||
                    Mathf.Abs(curve.keys[1].time - GripOneHandTransitionSeconds) > 0.0001f ||
                    Mathf.Abs(curve.keys[2].time - expected) > 0.0001f ||
                    Mathf.Abs(curve.keys[1].value - curve.keys[2].value) > 0.0001f)
                    throw new InvalidOperationException(
                        "Lightsaber_Grip_OneHand cycle key timing or hold value differs at " +
                        binding.path + "/" + binding.propertyName + ".");
            }
        }

        private static void RequireGripOneHandPosePathSets(
            IReadOnlyDictionary<string, DiagonalSlashLocalPose> first,
            IReadOnlyDictionary<string, DiagonalSlashLocalPose> second)
        {
            if (first.Count != second.Count ||
                first.Keys.Any(key => !second.ContainsKey(key)))
                throw new InvalidOperationException(
                    "Lightsaber_Grip_OneHand source pose path sets differ.");
        }

        private static string GripOneHandPoseSignature(
            IReadOnlyDictionary<string, DiagonalSlashLocalPose> pose)
        {
            var builder = new StringBuilder();
            foreach (KeyValuePair<string, DiagonalSlashLocalPose> item in pose
                .OrderBy(entry => entry.Key, StringComparer.Ordinal))
                builder.Append(item.Key).Append('|')
                    .Append(Precise(item.Value.Position)).Append('|')
                    .Append(Precise(item.Value.Rotation)).Append('|')
                    .AppendLine(Precise(item.Value.Scale));
            return LightsaberSha256(builder.ToString());
        }

        private static string GripOneHandPoseDifferenceSummary(
            IReadOnlyDictionary<string, DiagonalSlashLocalPose> first,
            IReadOnlyDictionary<string, DiagonalSlashLocalPose> second)
        {
            RequireGripOneHandPosePathSets(first, second);
            return string.Join(
                ";",
                first.Keys.Select(path =>
                    {
                        DiagonalSlashLocalPose a = first[path];
                        DiagonalSlashLocalPose b = second[path];
                        return new
                        {
                            Path = path,
                            Position = Vector3.Distance(a.Position, b.Position),
                            Rotation = Quaternion.Angle(a.Rotation, b.Rotation),
                            Scale = Vector3.Distance(a.Scale, b.Scale),
                            A = a,
                            B = b
                        };
                    })
                    .OrderByDescending(item => item.Position)
                    .ThenByDescending(item => item.Scale)
                    .ThenByDescending(item => item.Rotation)
                    .Take(12)
                    .Select(item => item.Path + "[p=" + Num(item.Position) +
                        ",r=" + Num(item.Rotation) + ",s=" + Num(item.Scale) +
                        ",fromPos=" + Precise(item.A.Position) +
                        ",toPos=" + Precise(item.B.Position) +
                        ",fromScale=" + Precise(item.A.Scale) +
                        ",toScale=" + Precise(item.B.Scale) + "]"));
        }

