                "|currentPose=" + GripOneHandPoseSignature(currentPose) +
                "|posePathCount=" + currentPose.Count +
                "|targetAvatar=" + ObjectIdentity(animator.avatar) +
                "|targetRoot=" + Precise(target.transform.position) +
                "|propParent=" + prop.parent.name +
                "|transitionSeconds=" + Num(ThrustModeEnterTransitionSeconds) +
                "|holdSeconds=" + Num(ThrustModeEnterHoldSeconds) +
                "|verificationTargetTransformManipulated=False");
