        [MenuItem("Bellerophon/Player/Apply Lightsaber Thrust Mode Enter Transition")]
        internal static void ApplyLightsaberThrustModeEnterTransition()
        {
            RequireEditMode();
            int consoleErrorsBefore = ConsoleErrorCount();
            Scene scene = RequireScene();
            if (scene.isDirty)
                throw new InvalidOperationException(
                    "Lightsaber_ThrustMode_Enter setup requires a clean CargoRunMvp scene.");
            GameObject target = FindUnique(scene, ThrustModeEnterTargetName);
            Animator animator = target.GetComponent<Animator>() ??
                throw new InvalidOperationException(
                    ThrustModeEnterTargetName + " Animator is missing.");
            if (animator.avatar == null)
                throw new InvalidOperationException(
                    ThrustModeEnterTargetName + " Avatar is missing.");
            Transform hand = RequireRightHand(target);
            Transform prop = RequireLightsaberProp(hand, target.name);
            RequireAuthoredPropTransform(prop, target.name);
            var rootBefore = new TransformSnapshot(target.transform);
            var propBefore = new TransformSnapshot(prop);
            Dictionary<string, DiagonalSlashLocalPose> currentPose =
                CaptureDiagonalSlashPose(target.transform, prop);
            string rendererBefore = RendererSignature(target.transform);
            string avatarBefore = ObjectIdentity(animator.avatar);
            string supplied = Absolute(ThrustModeEnterSourceRelativePath);
            string suppliedHash = Sha256File(supplied);

            EnsureFolder(ThrustModeEnterAssetFolder);
            EnsureFolder(ThrustModeEnterSourceFolder);
            EnsureDiagonalSlashSourceCopy(
                ThrustModeEnterSourceRelativePath,
                ThrustModeEnterSourcePath,
                "thrust-mode-enter");
            ConfigureThrustModeEnterSourceImporter();
            AnimationClip source = RequireSingleThrustModeEnterClip();
            RequireThrustModeEnterBindingCompatibility(target.transform, source);
            Dictionary<string, DiagonalSlashLocalPose> sourceFirst =
                SampleDiagonalSlashPose(target, prop, source, 0f, currentPose);
            RequireGripOneHandPosePathSets(currentPose, sourceFirst);
            Dictionary<string, DiagonalSlashLocalPose> correctedDestination =
                CreateCorrectedThrustModeEnterDestination(currentPose, sourceFirst);
            RequireCorrectedThrustModeEnterDestination(
                currentPose, sourceFirst, correctedDestination);
            AnimationClip cycle = CreateOrUpdateThrustModeEnterCycleClip(
                currentPose, correctedDestination);
            AnimatorController controller =
                CreateOrUpdateThrustModeEnterController(cycle);

            Undo.RecordObject(animator,
                "Configure Lightsaber_ThrustMode_Enter transition");
            animator.runtimeAnimatorController = controller;
            animator.applyRootMotion = false;
            animator.enabled = true;
            animator.cullingMode = AnimatorCullingMode.AlwaysAnimate;
            PrefabUtility.RecordPrefabInstancePropertyModifications(animator);
            EditorUtility.SetDirty(animator);
            AssetDatabase.SaveAssets();

            RequireEqual(suppliedHash, Sha256File(supplied),
                "protected supplied thrust-mode-enter FBX");
            RequireEqual(suppliedHash, Sha256File(Absolute(ThrustModeEnterSourcePath)),
                "thrust-mode-enter FBX binary copy");
            rootBefore.RequireUnchanged();
            propBefore.RequireUnchanged();
            RequireDiagonalSlashPoseEqual(
                currentPose,
                CaptureDiagonalSlashPose(target.transform, prop),
                "Lightsaber_ThrustMode_Enter scene pose after setup");
            RequireEqual(rendererBefore, RendererSignature(target.transform),
                "Lightsaber_ThrustMode_Enter renderer hierarchy");
            RequireEqual(avatarBefore, ObjectIdentity(animator.avatar),
                "Lightsaber_ThrustMode_Enter Avatar");
            if (!EditorSceneManager.SaveScene(scene))
                throw new InvalidOperationException(
                    "CargoRunMvp could not save Lightsaber_ThrustMode_Enter transition.");
            InspectLightsaberThrustModeEnterTransitionInternal(scene, false);
            RequireNoNewUnityConsoleErrors(consoleErrorsBefore);
            Debug.Log(
                "[LightsaberThrustModeEnter] Applied current pose -> 0.5-second " +
                "two-hand forward-thrust correction -> 0.5-second hold -> immediate " +
                "reset loop. The supplied FBX, root, renderers and Lightsaber_Prop " +
                "local position and scale were preserved; both hands meet in the upper " +
                "red-box area, both knees finish near ten degrees, both feet remain " +
                "planted, and the blade finishes ten degrees down and carrier-left.");
        }

