                throw new InvalidOperationException(
                    "The passed Lightsaber_ThrustMode_Enter direct review is missing.");
            string report = File.ReadAllText(reportPath, Encoding.UTF8);
            if (!report.Contains("passedNumericChecks=True") ||
                !report.Contains("naturalPlayback=True") ||
                !report.Contains("twoHandGripConfirmed=True") ||
                !report.Contains("rightShoulderOutsideGripConfirmed=True") ||
                !report.Contains("redBoxHeightConfirmed=True") ||
                !report.Contains("bladeHeadTorsoClearanceConfirmed=True") ||
                !report.Contains("bladeTiltConfirmed=True") ||
                !report.Contains("kneeBendTenDegreesConfirmed=True") ||
                !report.Contains("bothFeetPlantedConfirmed=True") ||
                !report.Contains("leftArmOutwardPopAbsent=True") ||
                !report.Contains("holdPoseConfirmed=True") ||
                !report.Contains("immediateRepeatConfirmed=True") ||
                !report.Contains("propRotationAnimated=True"))
                throw new InvalidOperationException(
                    "The Lightsaber_ThrustMode_Enter review report has not passed.");
            EnsureFolder(ThrustModeEnterReviewFolder);
            File.Copy(review, Absolute(ThrustModeEnterFinalPath), true);
            AssetDatabase.ImportAsset(
                ThrustModeEnterFinalPath,
                ImportAssetOptions.ForceSynchronousImport |
                ImportAssetOptions.ForceUpdate);
            RequireNoNewUnityConsoleErrors(consoleErrorsBefore);
            Debug.Log(
                "[LightsaberThrustModeEnter] One final image copied from the passed " +
                "natural Play Mode review. Path=" +
                Absolute(ThrustModeEnterFinalPath));
        }

