        [MenuItem("Bellerophon/Player/Apply Lightsaber Thrust Mode Exit Sequence")]
        internal static void ApplyLightsaberThrustModeExitSequence()
        {
            RequireEditMode();
            int consoleErrorsBefore = ConsoleErrorCount();
            Scene scene = RequireScene();
            if (scene.isDirty)
                throw new InvalidOperationException(
                    "Lightsaber_ThrustMode_Exit setup requires a clean CargoRunMvp scene.");
            InspectLightsaberThrustModeEnterTransitionInternal(scene, false);
            GameObject enterObject = FindUnique(scene, ThrustModeEnterTargetName);
            GameObject target = FindUnique(scene, ThrustModeExitTargetName);
            Animator animator = target.GetComponent<Animator>() ??
                throw new InvalidOperationException(
                    ThrustModeExitTargetName + " Animator is missing.");
            if (animator.avatar == null)
                throw new InvalidOperationException(
                    ThrustModeExitTargetName + " Avatar is missing.");
            Transform prop = RequireLightsaberProp(
                RequireRightHand(target), target.name);
            RequireAuthoredPropTransform(prop, target.name);

            var rootBefore = new TransformSnapshot(target.transform);
            var propBefore = new TransformSnapshot(prop);
            Dictionary<string, DiagonalSlashLocalPose> poseBefore =
                CaptureDiagonalSlashPose(target.transform, prop);
            string rendererBefore = RendererSignature(target.transform);
            string avatarBefore = ObjectIdentity(animator.avatar);
            string enterAnimatorBefore = AnimatorSignature(enterObject);
            string enterRendererBefore = RendererSignature(enterObject.transform);
            string enterClipHash = Sha256File(Absolute(ThrustModeEnterCycleClipPath));
            string enterControllerHash =
                Sha256File(Absolute(ThrustModeEnterControllerPath));
            string offIdleClipHash = Sha256File(Absolute(LocomotionIdleClipPath));

            AnimationClip enter = RequireDiagonalSlashAsset<AnimationClip>(
                ThrustModeEnterCycleClipPath);
            EnsureFolder(ThrustModeExitAssetFolder);
            AnimationClip exit = CreateOrUpdateThrustModeExitCycleClip(enter);
            AnimatorController controller =
                CreateOrUpdateThrustModeExitController(exit);

            Undo.RecordObject(animator,
                "Configure Lightsaber_ThrustMode_Exit exact reverse sequence");
            animator.runtimeAnimatorController = controller;
            animator.applyRootMotion = false;
            animator.enabled = true;
            animator.cullingMode = AnimatorCullingMode.AlwaysAnimate;
            PrefabUtility.RecordPrefabInstancePropertyModifications(animator);
            EditorUtility.SetDirty(animator);
            AssetDatabase.SaveAssets();

            RequireEqual(enterClipHash,
                Sha256File(Absolute(ThrustModeEnterCycleClipPath)),
                "protected Lightsaber_ThrustMode_Enter cycle");
            RequireEqual(enterControllerHash,
                Sha256File(Absolute(ThrustModeEnterControllerPath)),
                "protected Lightsaber_ThrustMode_Enter controller");
            RequireEqual(offIdleClipHash,
                Sha256File(Absolute(LocomotionIdleClipPath)),
                "protected Lightsaber_Off_Idle clip");
            RequireEqual(enterAnimatorBefore, AnimatorSignature(enterObject),
                "protected Lightsaber_ThrustMode_Enter Animator");
            RequireEqual(enterRendererBefore,
                RendererSignature(enterObject.transform),
                "protected Lightsaber_ThrustMode_Enter renderer hierarchy");
            rootBefore.RequireUnchanged();
            propBefore.RequireUnchanged();
            RequireDiagonalSlashPoseEqual(
                poseBefore,
                CaptureDiagonalSlashPose(target.transform, prop),
                "Lightsaber_ThrustMode_Exit scene pose after setup");
            RequireEqual(rendererBefore, RendererSignature(target.transform),
                "Lightsaber_ThrustMode_Exit renderer hierarchy");
            RequireEqual(avatarBefore, ObjectIdentity(animator.avatar),
                "Lightsaber_ThrustMode_Exit Avatar");
            if (!EditorSceneManager.SaveScene(scene))
                throw new InvalidOperationException(
                    "CargoRunMvp could not save Lightsaber_ThrustMode_Exit sequence.");
            InspectLightsaberThrustModeExitSequenceInternal(scene, false);
            RequireNoNewUnityConsoleErrors(consoleErrorsBefore);
            Debug.Log(
                "[LightsaberThrustModeExit] Applied exact reverse of the Enter " +
                "transition without its two-hand hold, followed by a 0.5-second " +
                "Lightsaber_Off_Idle hold and immediate repeat.");
        }

