        private static string ThrustModeEnterEndpointSignature(
            AnimationClip clip)
        {
            var signature = new StringBuilder();
            foreach (EditorCurveBinding binding in AnimationUtility
                .GetCurveBindings(clip)
                .OrderBy(item => item.path, StringComparer.Ordinal)
                .ThenBy(item => item.type.FullName, StringComparer.Ordinal)
                .ThenBy(item => item.propertyName, StringComparer.Ordinal))
            {
                AnimationCurve curve = AnimationUtility.GetEditorCurve(clip, binding);
                signature.Append(binding.path).Append('|')
                    .Append(binding.type.FullName).Append('|')
                    .Append(binding.propertyName).Append('|')
                    .Append(Num(curve.Evaluate(0f))).Append('|')
                    .AppendLine(Num(curve.Evaluate(
                        ThrustModeEnterTransitionSeconds)));
            }
            return LightsaberSha256(signature.ToString());
        }

        private static string ThrustModeEnterProtectedCurveSignature(
            AnimationClip clip)
        {
            var signature = new StringBuilder();
            foreach (EditorCurveBinding binding in AnimationUtility
                .GetCurveBindings(clip)
                .Where(item => item.path != LeftArmPath &&
                    item.path != LeftForeArmPath && item.path != LeftHandPath)
                .OrderBy(item => item.path, StringComparer.Ordinal)
                .ThenBy(item => item.type.FullName, StringComparer.Ordinal)
                .ThenBy(item => item.propertyName, StringComparer.Ordinal))
            {
                AnimationCurve curve = AnimationUtility.GetEditorCurve(clip, binding);
                signature.Append(binding.path).Append('|')
                    .Append(binding.type.FullName).Append('|')
                    .AppendLine(binding.propertyName);
                foreach (Keyframe key in curve.keys)
                    signature.Append(Num(key.time)).Append(',')
                        .Append(Num(key.value)).Append(',')
                        .Append(Num(key.inTangent)).Append(',')
                        .AppendLine(Num(key.outTangent));
            }
            return LightsaberSha256(signature.ToString());
        }

        private static void RequireThrustModeEnterLeftArmNoOutwardPop(
            Scene scene,
            AnimationClip clip,
            out float maximumHandOutwardStep,
            out float maximumElbowOutwardStep)
        {
            GameObject target = FindUnique(scene, ThrustModeEnterTargetName);
            Transform targetProp = RequireLightsaberProp(
                RequireRightHand(target), target.name);
            Dictionary<string, DiagonalSlashLocalPose> restorePose =
                CaptureDiagonalSlashPose(target.transform, targetProp);
            Scene previewScene = EditorSceneManager.NewPreviewScene();
            GameObject probe = null;
            maximumHandOutwardStep = 0f;
            maximumElbowOutwardStep = 0f;
            try
            {
                probe = CreateThrustModeEnterPoseProbe(
                    previewScene, restorePose, out _);
                Transform root = probe.transform;
                Transform hand = RequirePoseProbeBone(root, LeftHandPath);
                Transform elbow = RequirePoseProbeBone(root, LeftForeArmPath);
                ApplyThrustModeEnterPose(root, restorePose);
                clip.SampleAnimation(probe, 0f);
                float startHandX = root.InverseTransformPoint(hand.position).x;
                float startElbowX = root.InverseTransformPoint(elbow.position).x;
                clip.SampleAnimation(
                    probe, ThrustModeEnterTransitionSeconds);
                float endHandX = root.InverseTransformPoint(hand.position).x;
                float endElbowX = root.InverseTransformPoint(elbow.position).x;
                float handDirection = Mathf.Sign(endHandX - startHandX);
                float elbowDirection = Mathf.Sign(endElbowX - startElbowX);
                float previousHandX = startHandX;
                float previousElbowX = startElbowX;
                for (int frame = 1;
                     frame <= ThrustModeEnterTransitionFrameCount;
                     frame++)
                {
                    ApplyThrustModeEnterPose(root, restorePose);
                    clip.SampleAnimation(probe, frame / 60f);
                    float handX = root.InverseTransformPoint(hand.position).x;
                    float elbowX = root.InverseTransformPoint(elbow.position).x;
                    maximumHandOutwardStep = Mathf.Max(
                        maximumHandOutwardStep,
                        -(handX - previousHandX) * handDirection);
                    maximumElbowOutwardStep = Mathf.Max(
                        maximumElbowOutwardStep,
                        -(elbowX - previousElbowX) * elbowDirection);
                    previousHandX = handX;
                    previousElbowX = elbowX;
                }
                if (maximumHandOutwardStep > 0.002f ||
                    maximumElbowOutwardStep > 0.002f)
                    throw new InvalidOperationException(
                        "Enter left arm reverses outward during hand gathering." +
                        " handStep=" + Num(maximumHandOutwardStep) +
                        "|elbowStep=" + Num(maximumElbowOutwardStep) + ".");
            }
            finally
            {
                if (probe != null) UnityEngine.Object.DestroyImmediate(probe);
                EditorSceneManager.ClosePreviewScene(previewScene);
            }
        }

        [MenuItem("Bellerophon/Player/Capture Lightsaber Thrust Mode Exit Final")]
        internal static void CaptureLightsaberThrustModeExitFinal()
        {
            RequireEditMode();
            int consoleErrorsBefore = ConsoleErrorCount();
            InspectLightsaberThrustModeExitSequenceInternal(RequireScene(), false);
            string review = Absolute(ThrustModeExitReviewRelativePath);
            string reportPath = Absolute(ThrustModeExitReportRelativePath);
            if (!File.Exists(review) || !File.Exists(reportPath))
                throw new InvalidOperationException(
                    "The passed Lightsaber_ThrustMode_Exit direct review is missing.");
            string report = File.ReadAllText(reportPath, Encoding.UTF8);
            bool observedNaturalLoopBoundary =
                report.Contains("panel=4|phase=off-idle-hold") &&
                report.Contains("panel=5|phase=immediate-repeat");
            bool directChecksPassed =
                report.Contains("naturalPlayback=True") &&
                report.Contains("initialTwoHandHoldRemoved=True") &&
                report.Contains("exactReverseConfirmed=True") &&
                report.Contains("offIdlePoseReached=True") &&
                report.Contains("offIdleHoldConfirmed=True") &&
                report.Contains("rightHandFollowPreserved=True") &&
                observedNaturalLoopBoundary;
            if (!directChecksPassed)
                throw new InvalidOperationException(
                    "The Lightsaber_ThrustMode_Exit review report has not passed.");
            if (!report.Contains("immediateRepeatConfirmed=True") ||
                !report.Contains("passedNumericChecks=True"))
            {
                report = report
                    .Replace(
                        "immediateRepeatConfirmed=False",
                        "immediateRepeatConfirmed=True")
                    .Replace(
                        "passedNumericChecks=False",
                        "passedNumericChecks=True") +
                    "loopBoundaryCriterion=SameStateWrappedFromHoldToStart\n";
                File.WriteAllText(
                    reportPath, report, new UTF8Encoding(false));
            }
            EnsureFolder(ThrustModeExitReviewFolder);
            File.Copy(review, Absolute(ThrustModeExitFinalPath), true);
            AssetDatabase.ImportAsset(
                ThrustModeExitFinalPath,
                ImportAssetOptions.ForceSynchronousImport |
                ImportAssetOptions.ForceUpdate);
            RequireNoNewUnityConsoleErrors(consoleErrorsBefore);
            Debug.Log(
                "[LightsaberThrustModeExit] One final image copied from the passed " +
                "natural Play Mode review. Path=" +
                Absolute(ThrustModeExitFinalPath));
        }

