                expected, expectedPropRotation);
            AnimatorController controller =
                CreateOrUpdateLightsaberThrustStartPoseController(clip);

            Undo.RecordObject(targetAnimator,
                "Configure Lightsaber_Thrust exact start pose");
            targetAnimator.runtimeAnimatorController = controller;
            targetAnimator.applyRootMotion = false;
            targetAnimator.enabled = true;
            targetAnimator.cullingMode = AnimatorCullingMode.AlwaysAnimate;
            PrefabUtility.RecordPrefabInstancePropertyModifications(targetAnimator);
            EditorUtility.SetDirty(targetAnimator);
            AssetDatabase.SaveAssets();

            RequireEqual(sourceClipHash,
                Sha256File(Absolute(ThrustModeEnterCycleClipPath)),
                "protected Lightsaber_ThrustMode_Enter cycle");
            RequireEqual(sourceControllerHash,
                Sha256File(Absolute(ThrustModeEnterControllerPath)),
                "protected Lightsaber_ThrustMode_Enter controller");
            RequireEqual(sourceAnimatorBefore, AnimatorSignature(source),
                "protected Lightsaber_ThrustMode_Enter Animator");
            RequireEqual(sourceRendererBefore, RendererSignature(source.transform),
                "protected Lightsaber_ThrustMode_Enter renderer hierarchy");
            sourcePropBefore.RequireUnchanged();
            RequireDiagonalSlashPoseEqual(
                sourceScenePoseBefore,
                CaptureDiagonalSlashPose(source.transform, sourceProp),
                "protected Lightsaber_ThrustMode_Enter scene pose");
            targetRootBefore.RequireUnchanged();
            targetPropBefore.RequireUnchanged();
            RequireDiagonalSlashPoseEqual(
                targetScenePoseBefore,
                CaptureDiagonalSlashPose(target.transform, targetProp),
                "Lightsaber_Thrust scene pose after controller setup");
            RequireEqual(targetRendererBefore, RendererSignature(target.transform),
                "Lightsaber_Thrust renderer hierarchy");
            RequireEqual(targetAvatarBefore, ObjectIdentity(targetAnimator.avatar),
                "Lightsaber_Thrust Avatar");
            if (!EditorSceneManager.SaveScene(scene))
                throw new InvalidOperationException(
                    "CargoRunMvp could not save Lightsaber_Thrust start pose.");
            InspectLightsaberThrustStartPoseInternal(scene, false);
            RequireNoNewUnityConsoleErrors(consoleErrorsBefore);
            Debug.Log(
                "[LightsaberThrustStartPose] Applied exact " +
                "Lightsaber_ThrustMode_Enter last hold pose to the " +
                "Lightsaber_Thrust first pose. Source assets, scene transforms, " +
                "renderers, Avatar, prop position/scale and right-hand parent were " +
                "preserved.");
        }

