        [MenuItem("Bellerophon/Player/Capture Lightsaber Thrust Start Pose Final")]
        internal static void CaptureLightsaberThrustStartPoseFinal()
        {
            RequireEditMode();
            int consoleErrorsBefore = ConsoleErrorCount();
            InspectLightsaberThrustStartPoseInternal(RequireScene(), false);
            string review = Absolute(ThrustStartPoseReviewRelativePath);
            string reportPath = Absolute(ThrustStartPoseReportRelativePath);
            if (!File.Exists(review) || !File.Exists(reportPath))
                throw new InvalidOperationException(
                    "The passed Lightsaber_Thrust start-pose review is missing.");
            string report = File.ReadAllText(reportPath, Encoding.UTF8);
            if (!report.Contains("naturalPlayback=True") ||
                !report.Contains("sourceLastPoseTargetFirstPoseMatch=True") ||
                !report.Contains("rightHandFollowPreserved=True") ||
                !report.Contains("verificationTargetTransformManipulated=False") ||
                !report.Contains("passedNumericChecks=True"))
                throw new InvalidOperationException(
                    "The Lightsaber_Thrust start-pose review report has not passed.");
            EnsureFolder(ThrustStartPoseReviewFolder);
            File.Copy(review, Absolute(ThrustStartPoseFinalPath), true);
            AssetDatabase.ImportAsset(
                ThrustStartPoseFinalPath,
                ImportAssetOptions.ForceSynchronousImport |
                ImportAssetOptions.ForceUpdate);
            RequireNoNewUnityConsoleErrors(consoleErrorsBefore);
            Debug.Log(
                "[LightsaberThrustStartPose] One final image copied from the passed " +
                "natural Play Mode comparison. Path=" +
                Absolute(ThrustStartPoseFinalPath));
        }

        internal static Color[] CaptureLightsaberThrustStartPosePanel(
            Transform target)
        {
            GameObject cameraObject = new GameObject(
                "LightsaberThrustStartPoseReviewCamera")
            {
                hideFlags = HideFlags.HideAndDontSave
            };
            GameObject lightObject = new GameObject(
                "LightsaberThrustStartPoseReviewLight")
            {
                hideFlags = HideFlags.HideAndDontSave
            };
            Camera camera = cameraObject.AddComponent<Camera>();
            Light light = lightObject.AddComponent<Light>();
            Transform[] targetNodes = target.GetComponentsInChildren<Transform>(true);
            int[] originalLayers = targetNodes
                .Select(item => item.gameObject.layer)
                .ToArray();
            var occupiedOutsideLayers = new HashSet<int>(
                Resources.FindObjectsOfTypeAll<Renderer>()
                    .Where(item => item != null && item.transform != target &&
                        !item.transform.IsChildOf(target) &&
                        item.gameObject.scene.IsValid() &&
                        item.gameObject.scene.isLoaded)
                    .Select(item => item.gameObject.layer));
            int reviewLayer = Enumerable.Range(0, 32)
                .Reverse()
                .First(layer => !occupiedOutsideLayers.Contains(layer));
            foreach (Transform node in targetNodes)
                node.gameObject.layer = reviewLayer;
            camera.enabled = false;
            camera.cullingMask = 1 << reviewLayer;
            camera.clearFlags = CameraClearFlags.SolidColor;
            camera.backgroundColor = new Color(0.015f, 0.02f, 0.03f, 1f);
            camera.orthographic = true;
            camera.aspect = PanelWidth / (float)PanelHeight;
            camera.orthographicSize = 1.15f;
            Vector3 viewDirection =
                (target.forward + target.right * 0.2f).normalized;
            const float cameraDistance = 4f;
            Vector3 stableCenter = target.position +
                target.up * 0.98f + target.forward * 0.2f;
            camera.nearClipPlane = 0.01f;
            camera.farClipPlane = 10f;
            camera.transform.SetPositionAndRotation(
                stableCenter + viewDirection * cameraDistance,
                Quaternion.LookRotation(-viewDirection, target.up));
            light.type = LightType.Directional;
            light.intensity = 1.2f;
            light.transform.rotation = Quaternion.LookRotation(
                -viewDirection - target.up * 0.25f, target.up);
            RenderTexture render = RenderTexture.GetTemporary(
                PanelWidth, PanelHeight, 24, RenderTextureFormat.ARGB32);
            RenderTexture previousActive = RenderTexture.active;
            var texture = new Texture2D(
                PanelWidth, PanelHeight, TextureFormat.RGB24, false);
            try
            {
                camera.targetTexture = render;
                camera.Render();
                RenderTexture.active = render;
                texture.ReadPixels(
                    new Rect(0f, 0f, PanelWidth, PanelHeight), 0, 0, false);
                texture.Apply(false, false);
                return texture.GetPixels();
            }
            finally
            {
                camera.targetTexture = null;
                RenderTexture.active = previousActive;
                RenderTexture.ReleaseTemporary(render);
                for (int index = 0; index < targetNodes.Length; index++)
                    if (targetNodes[index] != null)
                        targetNodes[index].gameObject.layer = originalLayers[index];
                UnityEngine.Object.DestroyImmediate(texture);
                UnityEngine.Object.DestroyImmediate(cameraObject);
                UnityEngine.Object.DestroyImmediate(lightObject);
            }
        }

        private static Dictionary<string, DiagonalSlashLocalPose>
            CaptureLightsaberThrustModeEnterLastPose(
                Scene scene,
                out Quaternion propRotation)
        {
            GameObject source = FindUnique(scene, ThrustModeEnterTargetName);
            Transform sourceProp = RequireLightsaberProp(
                RequireRightHand(source), source.name);
            Dictionary<string, DiagonalSlashLocalPose> restorePose =
                CaptureDiagonalSlashPose(source.transform, sourceProp);
            AnimationClip sourceCycle = RequireDiagonalSlashAsset<AnimationClip>(
                ThrustModeEnterCycleClipPath);
            float holdTime = ThrustModeEnterTransitionSeconds +
                ThrustModeEnterHoldSeconds * 0.5f;
            Dictionary<string, DiagonalSlashLocalPose> result =
                SampleDiagonalSlashPose(
                    source, sourceProp, sourceCycle, holdTime, restorePose);
            propRotation = EvaluatePropRotation(sourceCycle, holdTime);
            return result;
        }

        private static AnimationClip CreateOrUpdateLightsaberThrustStartPoseClip(
            IReadOnlyDictionary<string, DiagonalSlashLocalPose> pose,
            Quaternion propRotation)
        {
            var generated = new AnimationClip
            {
                name = "LightsaberThrust_StartPoseExact",
                frameRate = 60f,
                legacy = false,
                wrapMode = WrapMode.Loop
            };
            foreach (KeyValuePair<string, DiagonalSlashLocalPose> item in pose
                .OrderBy(entry => entry.Key, StringComparer.Ordinal))
            {
                SetLightsaberThrustStartPoseCurve(
                    generated, item.Key, "m_LocalPosition.x", item.Value.Position.x);
                SetLightsaberThrustStartPoseCurve(
                    generated, item.Key, "m_LocalPosition.y", item.Value.Position.y);
                SetLightsaberThrustStartPoseCurve(
                    generated, item.Key, "m_LocalPosition.z", item.Value.Position.z);
                SetLightsaberThrustStartPoseCurve(
                    generated, item.Key, "m_LocalRotation.x", item.Value.Rotation.x);
                SetLightsaberThrustStartPoseCurve(
                    generated, item.Key, "m_LocalRotation.y", item.Value.Rotation.y);
                SetLightsaberThrustStartPoseCurve(
                    generated, item.Key, "m_LocalRotation.z", item.Value.Rotation.z);
                SetLightsaberThrustStartPoseCurve(
                    generated, item.Key, "m_LocalRotation.w", item.Value.Rotation.w);
                SetLightsaberThrustStartPoseCurve(
                    generated, item.Key, "m_LocalScale.x", item.Value.Scale.x);
                SetLightsaberThrustStartPoseCurve(
                    generated, item.Key, "m_LocalScale.y", item.Value.Scale.y);
                SetLightsaberThrustStartPoseCurve(
                    generated, item.Key, "m_LocalScale.z", item.Value.Scale.z);
            }
            SetLightsaberThrustStartPoseCurve(
                generated, DiagonalSlashPropPath, "m_LocalRotation.x", propRotation.x);
            SetLightsaberThrustStartPoseCurve(
                generated, DiagonalSlashPropPath, "m_LocalRotation.y", propRotation.y);
            SetLightsaberThrustStartPoseCurve(
                generated, DiagonalSlashPropPath, "m_LocalRotation.z", propRotation.z);
            SetLightsaberThrustStartPoseCurve(
                generated, DiagonalSlashPropPath, "m_LocalRotation.w", propRotation.w);
            generated.EnsureQuaternionContinuity();
            AnimationClipSettings settings =
                AnimationUtility.GetAnimationClipSettings(generated);
            settings.loopTime = true;
            settings.loopBlend = false;
            AnimationUtility.SetAnimationClipSettings(generated, settings);
            AnimationClip clip = AssetDatabase.LoadAssetAtPath<AnimationClip>(
                ThrustStartPoseClipPath);
            if (clip == null)
            {
                AssetDatabase.CreateAsset(generated, ThrustStartPoseClipPath);
                clip = generated;
            }
            else
            {
                EditorUtility.CopySerialized(generated, clip);
                clip.name = generated.name;
                EditorUtility.SetDirty(clip);
                UnityEngine.Object.DestroyImmediate(generated);
            }
            RequireLightsaberThrustStartPoseClip(clip, pose, propRotation);
            return clip;
        }

        private static void SetLightsaberThrustStartPoseCurve(
            AnimationClip clip,
            string path,
            string property,
            float value)
        {
            var curve = new AnimationCurve(
                new Keyframe(0f, value, 0f, 0f),
                new Keyframe(1f, value, 0f, 0f))
            {
                preWrapMode = WrapMode.ClampForever,
                postWrapMode = WrapMode.ClampForever
            };
            AnimationUtility.SetEditorCurve(
                clip,
                EditorCurveBinding.FloatCurve(
                    path, typeof(Transform), property),
                curve);
        }

        private static AnimatorController
            CreateOrUpdateLightsaberThrustStartPoseController(AnimationClip clip)
        {
            AnimatorController controller =
                AssetDatabase.LoadAssetAtPath<AnimatorController>(
                    ThrustStartPoseControllerPath);
            if (controller == null)
                controller = AnimatorController.CreateAnimatorControllerAtPath(
                    ThrustStartPoseControllerPath);
            while (controller.layers.Length > 1)
                controller.RemoveLayer(controller.layers.Length - 1);
            if (controller.layers.Length != 1)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust start-pose controller must contain one layer.");
            AnimatorControllerLayer layer = controller.layers[0];
            AnimatorStateMachine stateMachine = layer.stateMachine;
            foreach (AnimatorState existingState in stateMachine.states
                .Select(item => item.state).ToArray())
                stateMachine.RemoveState(existingState);
            foreach (AnimatorStateMachine nested in stateMachine.stateMachines
                .Select(item => item.stateMachine).ToArray())
                stateMachine.RemoveStateMachine(nested);
            controller.parameters = Array.Empty<AnimatorControllerParameter>();
            layer.name = "Lightsaber Thrust Start Pose";
            layer.defaultWeight = 1f;
            layer.blendingMode = AnimatorLayerBlendingMode.Override;
            layer.avatarMask = null;
            AnimatorState state = stateMachine.AddState(ThrustStartPoseStateName);
            state.motion = clip;
            state.speed = 1f;
            state.cycleOffset = 0f;
            state.mirror = false;
            state.writeDefaultValues = false;
            stateMachine.defaultState = state;
            controller.layers = new[] { layer };
            EditorUtility.SetDirty(stateMachine);
            EditorUtility.SetDirty(controller);
            return controller;
        }

        private static void InspectLightsaberThrustStartPoseInternal(
            Scene scene,
            bool requireCleanScene,
            bool allowMotionController = false)
        {
            if (requireCleanScene && scene.isDirty)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust start-pose inspection requires a clean scene.");
            InspectLightsaberThrustModeEnterTransitionInternal(scene, false);
            GameObject target = FindUnique(scene, ThrustTargetName);
            Animator animator = target.GetComponent<Animator>() ??
                throw new InvalidOperationException(
                    ThrustTargetName + " Animator is missing.");
            if (animator.avatar == null)
                throw new InvalidOperationException(
                    ThrustTargetName + " Avatar is missing.");
            Transform prop = RequireLightsaberProp(
                RequireRightHand(target), target.name);
            RequireAuthoredPropTransform(prop, target.name);
            Dictionary<string, DiagonalSlashLocalPose> expected =
                CaptureLightsaberThrustModeEnterLastPose(
                    scene, out Quaternion expectedPropRotation);
            Dictionary<string, DiagonalSlashLocalPose> restorePose =
                CaptureDiagonalSlashPose(target.transform, prop);
            RequireGripOneHandPosePathSets(restorePose, expected);
            AnimationClip clip = RequireDiagonalSlashAsset<AnimationClip>(
                ThrustStartPoseClipPath);
            RequireLightsaberThrustStartPoseClip(
                clip, expected, expectedPropRotation);
            RequireDiagonalSlashPoseEqual(
                expected,
                SampleDiagonalSlashPose(target, prop, clip, 0f, restorePose),
                "Lightsaber_Thrust first pose");
            RequireDiagonalSlashPoseEqual(
                expected,
                SampleDiagonalSlashPose(target, prop, clip, 0.5f, restorePose),
                "Lightsaber_Thrust held start pose");

            AnimatorController controller = animator.runtimeAnimatorController as
                AnimatorController ?? throw new InvalidOperationException(
                    "Lightsaber_Thrust start-pose controller is missing.");
            string controllerPath = AssetDatabase.GetAssetPath(controller);
            bool startPoseController = controllerPath ==
                ThrustStartPoseControllerPath;
            if ((!startPoseController &&
                    (!allowMotionController ||
                     controllerPath != ThrustMotionControllerPath)) ||
                animator.applyRootMotion || !animator.enabled ||
                animator.cullingMode != AnimatorCullingMode.AlwaysAnimate)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust Animator settings differ.");
            if (!startPoseController) return;
            if (controller.layers.Length != 1 || controller.parameters.Length != 0)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust start-pose controller structure differs.");
            AnimatorControllerLayer layer = controller.layers[0];
            AnimatorState[] states = layer.stateMachine.states
                .Select(item => item.state).ToArray();
            if (layer.avatarMask != null ||
                layer.blendingMode != AnimatorLayerBlendingMode.Override ||
                !Mathf.Approximately(layer.defaultWeight, 1f) ||
                layer.stateMachine.stateMachines.Length != 0 ||
                states.Length != 1)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust start-pose layer structure differs.");
            AnimatorState state = states[0];
            if (state.name != ThrustStartPoseStateName || state.motion != clip ||
                !Mathf.Approximately(state.speed, 1f) || state.mirror ||
                state.writeDefaultValues || state.behaviours.Length != 0 ||
                state.transitions.Length != 0 ||
                layer.stateMachine.defaultState != state)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust start-pose state settings differ.");
        }

        private static void RequireLightsaberThrustStartPoseClip(
            AnimationClip clip,
            IReadOnlyDictionary<string, DiagonalSlashLocalPose> expected,
            Quaternion expectedPropRotation)
        {
            if (Mathf.Abs(clip.length - 1f) > 0.0001f ||
                Mathf.Abs(clip.frameRate - 60f) > 0.0001f || !clip.isLooping)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust start-pose clip settings differ.");
            EditorCurveBinding[] bindings = AnimationUtility.GetCurveBindings(clip);
            if (bindings.Length != expected.Count * 10 + 4 ||
                AnimationUtility.GetObjectReferenceCurveBindings(clip).Length != 0 ||
                AnimationUtility.GetAnimationEvents(clip).Length != 0)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust start-pose curve structure differs.");
            foreach (EditorCurveBinding binding in bindings)
            {
                AnimationCurve curve = AnimationUtility.GetEditorCurve(clip, binding);
                if (curve == null || curve.length != 2 ||
                    Mathf.Abs(curve.keys[0].time) > 0.0001f ||
                    Mathf.Abs(curve.keys[1].time - 1f) > 0.0001f ||
                    Mathf.Abs(curve.keys[0].value - curve.keys[1].value) > 0.0001f)
                    throw new InvalidOperationException(
                        "Lightsaber_Thrust start-pose curve differs at " +
                        binding.path + "/" + binding.propertyName + ".");
            }
            RequirePropRotationCurves(clip, 2, "Lightsaber_Thrust start pose");
            if (Quaternion.Angle(
                    EvaluatePropRotation(clip, 0f), expectedPropRotation) > 0.02f ||
                Quaternion.Angle(
                    EvaluatePropRotation(clip, 1f), expectedPropRotation) > 0.02f)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust prop rotation does not match the source last pose.");
        }

        private static void MeasureLightsaberThrustStartPoseDelta(
            IReadOnlyDictionary<string, DiagonalSlashLocalPose> expected,
            IReadOnlyDictionary<string, DiagonalSlashLocalPose> actual,
            out float maximumPositionDelta,
            out float maximumRotationDelta,
            out float maximumScaleDelta)
        {
            RequireGripOneHandPosePathSets(expected, actual);
            maximumPositionDelta = 0f;
            maximumRotationDelta = 0f;
            maximumScaleDelta = 0f;
            foreach (KeyValuePair<string, DiagonalSlashLocalPose> item in expected)
            {
                DiagonalSlashLocalPose value = actual[item.Key];
                maximumPositionDelta = Mathf.Max(
                    maximumPositionDelta,
                    Vector3.Distance(item.Value.Position, value.Position));
                maximumRotationDelta = Mathf.Max(
                    maximumRotationDelta,
                    Quaternion.Angle(item.Value.Rotation, value.Rotation));
                maximumScaleDelta = Mathf.Max(
                    maximumScaleDelta,
                    Vector3.Distance(item.Value.Scale, value.Scale));
            }
        }

        [MenuItem("Bellerophon/Player/Inspect Lightsaber Thrust Motion Sources")]
        internal static void InspectLightsaberThrustMotionSources()
        {
            RequireEditMode();
            int consoleErrorsBefore = ConsoleErrorCount();
            Scene scene = RequireScene();
            InspectLightsaberThrustStartPoseInternal(scene, false, true);
            GameObject target = FindUnique(scene, ThrustTargetName);
            Transform rightHand = RequireRightHand(target);
            Transform prop = RequireLightsaberProp(rightHand, target.name);
            Transform[] targetProps = target.GetComponentsInChildren<Transform>(true)
                .Where(item => item.name == "Lightsaber_Prop")
                .ToArray();
            Transform[] targetBlades = target.GetComponentsInChildren<Transform>(true)
                .Where(item => item.name == BladeName)
                .ToArray();
            if (targetProps.Length != 1 || targetProps[0] != prop ||
                prop.parent != rightHand)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust must contain one Lightsaber_Prop directly " +
                    "under RightHand.");
            if (targetBlades.Length != 1 || targetBlades[0].parent != prop)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust must contain one Lightsaber_Blade directly " +
                    "under Lightsaber_Prop.");
            Dictionary<string, DiagonalSlashLocalPose> start =
                CaptureLightsaberThrustModeEnterLastPose(
                    scene, out Quaternion propRotation);
            Dictionary<string, DiagonalSlashLocalPose> destination =
                CreateLightsaberThrustMotionDestination(start, propRotation);
            ThrustMotionPoseMetrics metrics =
                RequireLightsaberThrustMotionDestination(
                    start, destination, propRotation);
            RequireNoNewUnityConsoleErrors(consoleErrorsBefore);
            Debug.Log(
                "[LightsaberThrustMotion] Sources inspected read-only." +
                " boneCount=" + start.Count +
                "|propCount=" + targetProps.Length +
                "|bladeCount=" + targetBlades.Length +
                "|propDirectRightHandChild=" + (prop.parent == rightHand) +
                "|bladeDirectPropChild=" + (targetBlades[0].parent == prop) +
                "|propLocalPosition=" + prop.localPosition.ToString("F6") +
                "|propLocalRotation=" + prop.localRotation.eulerAngles.ToString("F4") +
                "|lowerBodyPositionDelta=" +
                    Num(metrics.LowerBodyPositionDeltaMeters) +
                "|lowerBodyRotationDelta=" +
                    Num(metrics.LowerBodyRotationDeltaDegrees) +
                "|lowerBodyScaleDelta=" + Num(metrics.LowerBodyScaleDelta) +
                "|torsoForwardLean=" + Num(metrics.TorsoForwardLeanDegrees) +
                "|torsoForwardLeanError=" +
                    Num(metrics.TorsoForwardLeanErrorDegrees) +
                "|rightArmForwardAngle=" + Num(metrics.RightArmForwardAngleDegrees) +
                "|leftArmForwardAngle=" + Num(metrics.LeftArmForwardAngleDegrees) +
                "|armForwardAngleDifference=" + Num(Mathf.Abs(
                    metrics.RightArmForwardAngleDegrees -
                    metrics.LeftArmForwardAngleDegrees)) +
                "|rightElbowBend=" + Num(metrics.RightElbowDegrees) +
                "|leftElbowBend=" + Num(metrics.LeftElbowDegrees) +
                "|handleChestHeightOffset=" +
                    Num(metrics.HandleChestHeightOffsetMeters) +
                "|bladeDirectionDelta=" + Num(metrics.BladeDirectionDeltaDegrees) +
                "|verificationTargetTransformManipulated=False");
        }

        [MenuItem("Bellerophon/Player/Apply Lightsaber Thrust Motion")]
        internal static void ApplyLightsaberThrustMotion()
        {
            RequireEditMode();
            int consoleErrorsBefore = ConsoleErrorCount();
            Scene scene = RequireScene();
            if (scene.isDirty)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust motion setup requires a clean CargoRunMvp scene.");
            InspectLightsaberThrustStartPoseInternal(scene, false, true);

            GameObject source = FindUnique(scene, ThrustModeEnterTargetName);
            GameObject target = FindUnique(scene, ThrustTargetName);
            Animator targetAnimator = target.GetComponent<Animator>() ??
                throw new InvalidOperationException(
                    ThrustTargetName + " Animator is missing.");
            if (targetAnimator.avatar == null)
                throw new InvalidOperationException(
                    ThrustTargetName + " Avatar is missing.");
            Transform targetProp = RequireLightsaberProp(
                RequireRightHand(target), target.name);
            RequireAuthoredPropTransform(targetProp, target.name);

            var targetRootBefore = new TransformSnapshot(target.transform);
            var targetPropBefore = new TransformSnapshot(targetProp);
            Dictionary<string, DiagonalSlashLocalPose> targetScenePoseBefore =
                CaptureDiagonalSlashPose(target.transform, targetProp);
            string targetRendererBefore = RendererSignature(target.transform);
            string targetAvatarBefore = ObjectIdentity(targetAnimator.avatar);
            string sourceAnimatorBefore = AnimatorSignature(source);
            string sourceRendererBefore = RendererSignature(source.transform);
            Transform sourceProp = RequireLightsaberProp(
                RequireRightHand(source), source.name);
            var sourcePropBefore = new TransformSnapshot(sourceProp);
            Dictionary<string, DiagonalSlashLocalPose> sourceScenePoseBefore =
                CaptureDiagonalSlashPose(source.transform, sourceProp);
            string enterClipHash = Sha256File(Absolute(ThrustModeEnterCycleClipPath));
            string enterControllerHash =
                Sha256File(Absolute(ThrustModeEnterControllerPath));
            string startClipHash = Sha256File(Absolute(ThrustStartPoseClipPath));
            string startControllerHash =
                Sha256File(Absolute(ThrustStartPoseControllerPath));

            Dictionary<string, DiagonalSlashLocalPose> start =
                CaptureLightsaberThrustModeEnterLastPose(
                    scene, out Quaternion propRotation);
            Dictionary<string, DiagonalSlashLocalPose> destination =
                CreateLightsaberThrustMotionDestination(start, propRotation);
            RequireLightsaberThrustMotionDestination(
                start, destination, propRotation);
            List<Dictionary<string, DiagonalSlashLocalPose>> samples =
                CreateLightsaberThrustMotionSamples(
                    start, destination, propRotation);
            EnsureFolder(ThrustAssetFolder);
            AnimationClip clip = CreateOrUpdateLightsaberThrustMotionClip(
                start, destination, propRotation, samples);
            AnimatorController controller =
                CreateOrUpdateLightsaberThrustMotionController(clip);

            Undo.RecordObject(targetAnimator,
                "Configure Lightsaber_Thrust motion");
            targetAnimator.runtimeAnimatorController = controller;
            targetAnimator.applyRootMotion = false;
            targetAnimator.enabled = true;
            targetAnimator.cullingMode = AnimatorCullingMode.AlwaysAnimate;
            PrefabUtility.RecordPrefabInstancePropertyModifications(targetAnimator);
            EditorUtility.SetDirty(targetAnimator);
            AssetDatabase.SaveAssets();

            RequireEqual(enterClipHash,
                Sha256File(Absolute(ThrustModeEnterCycleClipPath)),
                "protected Lightsaber_ThrustMode_Enter cycle");
            RequireEqual(enterControllerHash,
                Sha256File(Absolute(ThrustModeEnterControllerPath)),
                "protected Lightsaber_ThrustMode_Enter controller");
            RequireEqual(startClipHash,
                Sha256File(Absolute(ThrustStartPoseClipPath)),
                "protected Lightsaber_Thrust exact start clip");
            RequireEqual(startControllerHash,
                Sha256File(Absolute(ThrustStartPoseControllerPath)),
                "protected Lightsaber_Thrust exact start controller");
            RequireEqual(sourceAnimatorBefore, AnimatorSignature(source),
                "protected Lightsaber_ThrustMode_Enter Animator");
            RequireEqual(sourceRendererBefore, RendererSignature(source.transform),
                "protected Lightsaber_ThrustMode_Enter renderer hierarchy");
            sourcePropBefore.RequireUnchanged();
            RequireDiagonalSlashPoseEqual(
                sourceScenePoseBefore,
                CaptureDiagonalSlashPose(source.transform, sourceProp),
                "protected Lightsaber_ThrustMode_Enter scene pose");
            targetRootBefore.RequireUnchanged();
            targetPropBefore.RequireUnchanged();
            RequireDiagonalSlashPoseEqual(
                targetScenePoseBefore,
                CaptureDiagonalSlashPose(target.transform, targetProp),
                "Lightsaber_Thrust scene pose after motion setup");
            RequireEqual(targetRendererBefore, RendererSignature(target.transform),
                "Lightsaber_Thrust renderer hierarchy");
            RequireEqual(targetAvatarBefore, ObjectIdentity(targetAnimator.avatar),
                "Lightsaber_Thrust Avatar");
            if (!EditorSceneManager.SaveScene(scene))
                throw new InvalidOperationException(
                    "CargoRunMvp could not save Lightsaber_Thrust motion.");
            InspectLightsaberThrustMotionInternal(scene, false);
            RequireNoNewUnityConsoleErrors(consoleErrorsBefore);
            Debug.Log(
                "[LightsaberThrustMotion] Applied 0.9-second forward thrust, " +
                "0.5-second hold and immediate loop reset. The complete lower " +
                "body, two-hand grip, " +
                "blade direction, protected assets, scene transforms, renderers " +
                "and Avatar were preserved.");
        }

        [MenuItem("Bellerophon/Player/Inspect Lightsaber Thrust Motion")]
        internal static void InspectLightsaberThrustMotion()
        {
            RequireEditMode();
            int consoleErrorsBefore = ConsoleErrorCount();
            InspectLightsaberThrustMotionInternal(RequireScene(), false);
            RequireNoNewUnityConsoleErrors(consoleErrorsBefore);
            Debug.Log(
                "[LightsaberThrustMotion] Inspected read-only: exact start, " +
                "0.9-second thrust, 0.5-second hold and immediate repeat are intact.");
        }

        [MenuItem("Bellerophon/Player/Capture Lightsaber Thrust Motion Final")]
        internal static void CaptureLightsaberThrustMotionFinal()
        {
            RequireEditMode();
            int consoleErrorsBefore = ConsoleErrorCount();
            InspectLightsaberThrustMotionInternal(RequireScene(), false);
            string review = Absolute(ThrustMotionReviewRelativePath);
            string reportPath = Absolute(ThrustMotionReportRelativePath);
            if (!File.Exists(review) || !File.Exists(reportPath))
                throw new InvalidOperationException(
                    "The passed Lightsaber_Thrust motion review is missing.");
            string report = File.ReadAllText(reportPath, Encoding.UTF8);
            string[] required =
            {
                "naturalPlayback=True",
                "verificationTargetTransformManipulated=False",
                "exactStartPoseConfirmed=True",
                "torsoForwardLeanFifteenDegreesConfirmed=True",
                "bothArmsForwardConfirmed=True",
                "bothElbowsFiveDegreesConfirmed=True",
                "handleCenteredAtChestHeightConfirmed=True",
                "lowerBodyUnchangedConfirmed=True",
                "bothFeetPlantedConfirmed=True",
                "bladeDirectionWithinTwoDegreesConfirmed=True",
                "holdPoseConfirmed=True",
                "immediateRepeatConfirmed=True",
                "rightHandFollowPreserved=True",
                "passedNumericChecks=True"
            };
            if (required.Any(token => !report.Contains(token)))
                throw new InvalidOperationException(
                    "The Lightsaber_Thrust motion review report has not passed.");
            EnsureFolder(ThrustStartPoseReviewFolder);
            File.Copy(review, Absolute(ThrustMotionFinalPath), true);
            AssetDatabase.ImportAsset(
                ThrustMotionFinalPath,
                ImportAssetOptions.ForceSynchronousImport |
                ImportAssetOptions.ForceUpdate);
            RequireNoNewUnityConsoleErrors(consoleErrorsBefore);
            Debug.Log(
                "[LightsaberThrustMotion] One final image copied from the passed " +
                "natural Play Mode review. Path=" + Absolute(ThrustMotionFinalPath));
        }

        private static Dictionary<string, DiagonalSlashLocalPose>
            CreateLightsaberThrustMotionDestination(
                IReadOnlyDictionary<string, DiagonalSlashLocalPose> start,
                Quaternion propLocalRotation)
        {
            Dictionary<string, DiagonalSlashLocalPose> best = null;
            float bestScore = float.PositiveInfinity;
            for (float yaw = ThrustMotionTorsoYawMinimumDegrees;
                 yaw <= ThrustMotionTorsoYawMaximumDegrees + 0.001f;
                 yaw += ThrustMotionTorsoYawStepDegrees)
            {
                Dictionary<string, DiagonalSlashLocalPose> candidate;
                try
                {
                    candidate = CreateLightsaberThrustMotionDestinationAtYaw(
                        start, propLocalRotation, yaw);
                }
                catch (InvalidOperationException)
                {
                    continue;
                }
                ThrustMotionPoseMetrics metrics =
                    MeasureLightsaberThrustMotionPose(
                        start, candidate, propLocalRotation);
                float maximumForwardAngle = Mathf.Max(
                    metrics.RightArmForwardAngleDegrees,
                    metrics.LeftArmForwardAngleDegrees);
                float forwardDifference = Mathf.Abs(
                    metrics.RightArmForwardAngleDegrees -
                    metrics.LeftArmForwardAngleDegrees);
                if (maximumForwardAngle >
                        ThrustMotionArmForwardToleranceDegrees ||
                    Mathf.Abs(metrics.RightElbowDegrees -
                        ThrustMotionElbowBendDegrees) >
                        ThrustMotionElbowToleranceDegrees ||
                    Mathf.Abs(metrics.LeftElbowDegrees -
                        ThrustMotionElbowBendDegrees) >
                        ThrustMotionElbowToleranceDegrees ||
                    metrics.GripOffsetErrorMeters >
                        ThrustMotionGripToleranceMeters ||
                    metrics.BladeDirectionDeltaDegrees >
                        ThrustMotionBladeToleranceDegrees ||
                    metrics.BladeHeadClearanceMeters <
                        ThrustMotionClearanceMeters ||
                    metrics.BladeTorsoClearanceMeters <
                        ThrustMotionClearanceMeters)
                    continue;
                float score = maximumForwardAngle +
                    forwardDifference * 8f;
                if (score >= bestScore) continue;
                bestScore = score;
                best = candidate;
            }
            return best ?? throw new InvalidOperationException(
                "Lightsaber_Thrust has no anatomical symmetric two-arm " +
                "destination in the approved torso-yaw search range.");
        }

        private static Dictionary<string, DiagonalSlashLocalPose>
            CreateLightsaberThrustMotionDestinationAtYaw(
                IReadOnlyDictionary<string, DiagonalSlashLocalPose> start,
                Quaternion propLocalRotation,
                float torsoYawDegrees)
        {
            Scene previewScene = EditorSceneManager.NewPreviewScene();
            GameObject probe = null;
            try
            {
                probe = CreateThrustModeEnterPoseProbe(
                    previewScene, start, out Transform prop);
                prop.localRotation = propLocalRotation;
                Transform root = probe.transform;
                Transform rightArm = RequirePoseProbeBone(root, RightArmPath);
                Transform rightForeArm =
                    RequirePoseProbeBone(root, RightForeArmPath);
                Transform rightHand = RequirePoseProbeBone(root, RightHandPath);
                Transform leftArm = RequirePoseProbeBone(root, LeftArmPath);
                Transform leftForeArm = RequirePoseProbeBone(root, LeftForeArmPath);
                Transform leftHand = RequirePoseProbeBone(root, LeftHandPath);
                Quaternion initialPropWorldRotation = prop.rotation;
                Vector3 initialShoulderCenter =
                    (RequirePoseProbeBone(root, RightShoulderPath).position +
                     RequirePoseProbeBone(root, LeftShoulderPath).position) * 0.5f;
                float thrustSide = Mathf.Sign(Vector3.Dot(
                    ((rightHand.position + leftHand.position) * 0.5f) -
                        initialShoulderCenter,
                    root.right));
                if (Mathf.Abs(thrustSide) < 0.5f) thrustSide = 1f;
                ApplyLightsaberThrustTorsoYaw(
                    root, thrustSide, torsoYawDegrees);
                ApplyLightsaberThrustForwardTorsoLean(root);
                ApplyLightsaberThrustShoulderProtraction(root);

                rightArm = RequirePoseProbeBone(root, RightArmPath);
                rightForeArm = RequirePoseProbeBone(root, RightForeArmPath);
                rightHand = RequirePoseProbeBone(root, RightHandPath);
                leftArm = RequirePoseProbeBone(root, LeftArmPath);
                leftForeArm = RequirePoseProbeBone(root, LeftForeArmPath);
                leftHand = RequirePoseProbeBone(root, LeftHandPath);
                float rightReach = Vector3.Distance(
                    rightArm.position, rightForeArm.position) +
                    Vector3.Distance(rightForeArm.position, rightHand.position);
                float leftReach = Vector3.Distance(
                    leftArm.position, leftForeArm.position) +
                    Vector3.Distance(leftForeArm.position, leftHand.position);
                Transform rightShoulder =
                    RequirePoseProbeBone(root, RightShoulderPath);
                Transform leftShoulder =
                    RequirePoseProbeBone(root, LeftShoulderPath);
                Vector3 shoulderCenter =
                    (rightShoulder.position + leftShoulder.position) * 0.5f;
                Transform hips = RequirePoseProbeBone(root, HipsPath);
                Vector3 chestCenter = Vector3.LerpUnclamped(
                    hips.position,
                    shoulderCenter,
                    ThrustMotionChestHeightFraction);
                Vector3 initialBladeDirection =
                    (initialPropWorldRotation *
                        DiagonalSlashBladeAxisLocal()).normalized;
                Quaternion desiredRightHandRotation =
                    FindLightsaberThrustHandRotation(
                        root,
                        rightHand,
                        prop,
                        initialPropWorldRotation,
                        initialBladeDirection);
                rightHand.rotation = desiredRightHandRotation;
                Vector3 bladeDirection = prop.TransformDirection(
                    DiagonalSlashBladeAxisLocal()).normalized;
                Vector3 handToPropWorldOffset = prop.position - rightHand.position;
                Vector3 rightTarget = SolveLightsaberThrustExtendedGripTarget(
                    root,
                    rightArm,
                    rightForeArm,
                    leftArm,
                    leftForeArm,
                    chestCenter,
                    bladeDirection,
                    handToPropWorldOffset,
                    out Vector3 leftGripWorldOffset);
                SolveThrustModeEnterTwoBone(
                    rightArm,
                    rightForeArm,
                    rightHand,
                    rightTarget,
                    rightArm.position +
                        root.forward * (rightReach * 0.62f) +
                        root.right * (rightReach * 0.28f) -
                        root.up * (rightReach * 0.08f),
                    "right thrust arm");
                rightHand.rotation = desiredRightHandRotation;

                Vector3 leftTarget = rightHand.position + leftGripWorldOffset;
                SolveThrustModeEnterTwoBone(
                    leftArm,
                    leftForeArm,
                    leftHand,
                    leftTarget,
                    leftArm.position +
                        root.forward * (leftReach * 0.62f) -
                        root.right * (leftReach * 0.28f) -
                        root.up * (leftReach * 0.08f),
                    "left thrust arm");
                AlignThrustModeEnterLeftPalm(
                    leftForeArm,
                    leftHand,
                    prop.TransformDirection(DiagonalSlashBladeAxisLocal()));
                return CaptureDiagonalSlashPose(root, prop);
            }
            finally
            {
                if (probe != null) UnityEngine.Object.DestroyImmediate(probe);
                EditorSceneManager.ClosePreviewScene(previewScene);
            }
        }

        private static Vector3 SolveLightsaberThrustExtendedGripTarget(
            Transform root,
            Transform rightArm,
            Transform rightForeArm,
            Transform leftArm,
            Transform leftForeArm,
            Vector3 chestCenter,
            Vector3 bladeDirection,
            Vector3 handToPropWorldOffset,
            out Vector3 leftGripWorldOffset)
        {
            float rightUpperLength = Vector3.Distance(
                rightArm.position, rightForeArm.position);
            float rightLowerLength = Vector3.Distance(
                rightForeArm.position,
                RequirePoseProbeBone(root, RightHandPath).position);
            float leftUpperLength = Vector3.Distance(
                leftArm.position, leftForeArm.position);
            float leftLowerLength = Vector3.Distance(
                leftForeArm.position,
                RequirePoseProbeBone(root, LeftHandPath).position);
            float rightDistance = ArmReachForElbowBend(
                rightUpperLength, rightLowerLength, ThrustMotionElbowBendDegrees);
            float leftDistance = ArmReachForElbowBend(
                leftUpperLength, leftLowerLength, ThrustMotionElbowBendDegrees);

            float targetHandUp = Vector3.Dot(
                chestCenter - handToPropWorldOffset - root.position, root.up);
            float rightShoulderUp = Vector3.Dot(
                rightArm.position - root.position, root.up);
            float rightHorizontalSquared = rightDistance * rightDistance -
                Mathf.Pow(targetHandUp - rightShoulderUp, 2f);
            if (rightHorizontalSquared <= 0f)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust cannot place the extended grip at chest height.");

            Vector2 rightCenter = new Vector2(
                Vector3.Dot(rightArm.position - root.position, root.right),
                Vector3.Dot(rightArm.position - root.position, root.forward));
            float rightRadius = Mathf.Sqrt(rightHorizontalSquared);
            float bestScore = float.PositiveInfinity;
            Vector3 bestTarget = Vector3.zero;
            Vector3 bestOffset = Vector3.zero;
            bool found = false;
            for (int directionIndex = 0; directionIndex < 2; directionIndex++)
            {
                float directionSign = directionIndex == 0 ? -1f : 1f;
                for (float spacing = ThrustMotionGripMinimumMeters;
                     spacing <= ThrustMotionGripMaximumMeters + 0.0001f;
                     spacing += 0.005f)
                {
                    Vector3 candidateOffset =
                        bladeDirection * (spacing * directionSign);
                    Vector3 effectiveLeftShoulder =
                        leftArm.position - candidateOffset;
                    float leftShoulderUp = Vector3.Dot(
                        effectiveLeftShoulder - root.position, root.up);
                    float leftHorizontalSquared = leftDistance * leftDistance -
                        Mathf.Pow(targetHandUp - leftShoulderUp, 2f);
                    if (leftHorizontalSquared <= 0f) continue;
                    Vector2 leftCenter = new Vector2(
                        Vector3.Dot(
                            effectiveLeftShoulder - root.position, root.right),
                        Vector3.Dot(
                            effectiveLeftShoulder - root.position, root.forward));
                    if (!TrySolveLightsaberThrustGripCircles(
                            root,
                            rightArm,
                            leftArm,
                            rightCenter,
                            leftCenter,
                            rightRadius,
                            Mathf.Sqrt(leftHorizontalSquared),
                            targetHandUp,
                            candidateOffset,
                            out Vector3 candidateTarget,
                            out float candidateScore))
                        continue;
                    candidateScore += Mathf.Abs(
                        spacing - ThrustModeEnterRearHandSpacingMeters) * 2f;
                    if (candidateScore >= bestScore) continue;
                    bestScore = candidateScore;
                    bestTarget = candidateTarget;
                    bestOffset = candidateOffset;
                    found = true;
                }
            }
            float selectedMaximumForwardAngle = found
                ? Mathf.Max(
                    MeasureLightsaberThrustForwardAngle(
                        root, rightArm.position, bestTarget),
                    MeasureLightsaberThrustForwardAngle(
                        root,
                        leftArm.position,
                        bestTarget + bestOffset))
                : float.PositiveInfinity;
            if (!found ||
                selectedMaximumForwardAngle >
                    ThrustMotionArmForwardToleranceDegrees)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust extended two-hand grip has no forward " +
                    "chest-height solution. bestForwardAngle=" +
                        Num(selectedMaximumForwardAngle) +
                    "|rightReach=" + Num(rightDistance) +
                    "|leftReach=" + Num(leftDistance) +
                    "|targetHandUp=" + Num(targetHandUp) +
                    "|rightShoulderUp=" + Num(rightShoulderUp) +
                    "|rightVerticalDrop=" +
                        Num(rightShoulderUp - targetHandUp) + ".");
            leftGripWorldOffset = bestOffset;
            return bestTarget;
        }

        private static Quaternion FindLightsaberThrustHandRotation(
            Transform root,
            Transform rightHand,
            Transform prop,
            Quaternion initialPropWorldRotation,
            Vector3 bladeDirection)
        {
            Quaternion originalHandRotation = rightHand.rotation;
            Quaternion bestHandRotation = initialPropWorldRotation *
                Quaternion.Inverse(prop.localRotation);
            float bestScore = float.PositiveInfinity;
            for (int rollDegrees = -180; rollDegrees <= 180; rollDegrees++)
            {
                Quaternion desiredPropWorldRotation = Quaternion.AngleAxis(
                    rollDegrees, bladeDirection) * initialPropWorldRotation;
                Quaternion handRotation = desiredPropWorldRotation *
                    Quaternion.Inverse(prop.localRotation);
                rightHand.rotation = handRotation;
                Vector3 handToPropOffset = prop.position - rightHand.position;
                float score = Mathf.Abs(Vector3.Dot(
                        handToPropOffset, root.up)) +
                    Mathf.Abs(rollDegrees) * 0.00005f;
                if (score >= bestScore) continue;
                bestScore = score;
                bestHandRotation = handRotation;
            }
            rightHand.rotation = originalHandRotation;
            return bestHandRotation;
        }

        private static bool TrySolveLightsaberThrustGripCircles(
            Transform root,
            Transform rightArm,
            Transform leftArm,
            Vector2 rightCenter,
            Vector2 leftCenter,
            float rightRadius,
            float leftRadius,
            float targetHandUp,
            Vector3 leftGripWorldOffset,
            out Vector3 target,
            out float score)
        {
            target = Vector3.zero;
            score = float.PositiveInfinity;
            Vector2 centers = leftCenter - rightCenter;
            float centerDistance = centers.magnitude;
            if (centerDistance <= 0.0001f ||
                centerDistance > rightRadius + leftRadius + 0.0001f ||
                centerDistance < Mathf.Abs(rightRadius - leftRadius) - 0.0001f)
                return false;
            Vector2 centerDirection = centers / centerDistance;
            float along = (rightRadius * rightRadius -
                leftRadius * leftRadius + centerDistance * centerDistance) /
                (2f * centerDistance);
            float perpendicularDistance = Mathf.Sqrt(Mathf.Max(
                0f, rightRadius * rightRadius - along * along));
            Vector2 basePoint = rightCenter + centerDirection * along;
            Vector2 perpendicular = new Vector2(
                -centerDirection.y, centerDirection.x);
            Vector2[] candidates =
            {
                basePoint + perpendicular * perpendicularDistance,
                basePoint - perpendicular * perpendicularDistance
            };
            foreach (Vector2 candidate in candidates)
            {
                Vector3 world = root.position +
                    root.right * candidate.x +
                    root.up * targetHandUp +
                    root.forward * candidate.y;
                float rightForwardAngle = MeasureLightsaberThrustForwardAngle(
                    root, rightArm.position, world);
                float leftForwardAngle = MeasureLightsaberThrustForwardAngle(
                    root,
                    leftArm.position,
                    world + leftGripWorldOffset);
                float candidateScore = Mathf.Max(
                    rightForwardAngle, leftForwardAngle) +
                    Mathf.Abs(rightForwardAngle - leftForwardAngle) * 3f;
                if (candidateScore >= score) continue;
                target = world;
                score = candidateScore;
            }
            return !float.IsPositiveInfinity(score);
        }

        internal static float MeasureLightsaberThrustGripAxisError(
            Transform rightHand,
            Transform leftHand,
            Vector3 bladeDirection)
        {
            Vector3 gripOffset = leftHand.position - rightHand.position;
            float spacing = Mathf.Abs(Vector3.Dot(gripOffset, bladeDirection));
            float rangeError = Mathf.Max(
                ThrustMotionGripMinimumMeters - spacing,
                spacing - ThrustMotionGripMaximumMeters,
                0f);
            return Vector3.ProjectOnPlane(
                gripOffset, bladeDirection).magnitude + rangeError;
        }

        internal static float MeasureLightsaberThrustForwardAngle(
            Transform root,
            Vector3 armOrigin,
            Vector3 handPosition)
        {
            Vector3 horizontal = Vector3.ProjectOnPlane(
                handPosition - armOrigin, root.up);
            if (horizontal.sqrMagnitude <= 0.000001f) return 180f;
            return Vector3.Angle(horizontal, root.forward);
        }

        private static float ArmReachForElbowBend(
            float upperLength,
            float lowerLength,
            float elbowBendDegrees)
        {
            return Mathf.Sqrt(
                upperLength * upperLength +
                lowerLength * lowerLength +
                2f * upperLength * lowerLength *
                    Mathf.Cos(elbowBendDegrees * Mathf.Deg2Rad));
        }

        private static void ApplyLightsaberThrustForwardTorsoLean(Transform root)
        {
            Transform spine02 = RequirePoseProbeBone(root, Spine02Path);
            Transform spine01 = RequirePoseProbeBone(root, Spine01Path);
            Transform spine = RequirePoseProbeBone(root, SpinePath);
            Vector3 targetDirection = LightsaberThrustForwardTorsoDirection(root);
            ApplyLightsaberThrustTorsoCorrection(
                root, spine02, targetDirection, 0.34f);
            ApplyLightsaberThrustTorsoCorrection(
                root, spine01, targetDirection, 0.50f);
            ApplyLightsaberThrustTorsoCorrection(
                root, spine, targetDirection, 1f);
        }

        private static void ApplyLightsaberThrustTorsoYaw(
            Transform root,
            float side,
            float degrees)
        {
            Quaternion fullYaw = Quaternion.AngleAxis(
                degrees * side,
                root.up);
            Transform spine02 = RequirePoseProbeBone(root, Spine02Path);
            Transform spine01 = RequirePoseProbeBone(root, Spine01Path);
            Transform spine = RequirePoseProbeBone(root, SpinePath);
            spine02.rotation = Quaternion.Slerp(
                Quaternion.identity, fullYaw, 0.28f) * spine02.rotation;
            spine01.rotation = Quaternion.Slerp(
                Quaternion.identity, fullYaw, 0.34f) * spine01.rotation;
            spine.rotation = Quaternion.Slerp(
                Quaternion.identity, fullYaw, 0.38f) * spine.rotation;
        }

        private static void ApplyLightsaberThrustShoulderProtraction(Transform root)
        {
            ApplyLightsaberThrustShoulderProtraction(
                root,
                RequirePoseProbeBone(root, RightShoulderPath),
                RequirePoseProbeBone(root, RightArmPath),
                -1f);
            ApplyLightsaberThrustShoulderProtraction(
                root,
                RequirePoseProbeBone(root, LeftShoulderPath),
                RequirePoseProbeBone(root, LeftArmPath),
                1f);
        }

        private static void ApplyLightsaberThrustShoulderProtraction(
            Transform root,
            Transform shoulder,
            Transform upperArm,
            float inwardSign)
        {
            Vector3 current = upperArm.position - shoulder.position;
            float length = current.magnitude;
            if (length <= 0.0001f)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust shoulder chain is degenerate.");
            Vector3 desired = (
                current.normalized +
                root.forward * 0.42f +
                root.right * (inwardSign * 0.08f) -
                root.up * 0.04f).normalized * length;
            shoulder.rotation = Quaternion.FromToRotation(current, desired) *
                shoulder.rotation;
        }

        internal static Vector3 LightsaberThrustForwardTorsoDirection(
            Transform root)
        {
            float radians = ThrustMotionTorsoForwardLeanDegrees * Mathf.Deg2Rad;
            return (root.up * Mathf.Cos(radians) +
                root.forward * Mathf.Sin(radians)).normalized;
        }

        private static void ApplyLightsaberThrustTorsoCorrection(
            Transform root,
            Transform bone,
            Vector3 targetDirection,
            float fraction)
        {
            Transform spine = RequirePoseProbeBone(root, SpinePath);
            Transform leftShoulder = RequirePoseProbeBone(root, LeftShoulderPath);
            Transform rightShoulder = RequirePoseProbeBone(root, RightShoulderPath);
            Vector3 shoulderCenter =
                (leftShoulder.position + rightShoulder.position) * 0.5f;
            Vector3 current = (shoulderCenter - spine.position).normalized;
            if (current.sqrMagnitude < 0.99f)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust torso direction is degenerate.");
            Quaternion correction = Quaternion.FromToRotation(
                current, targetDirection);
            bone.rotation = Quaternion.Slerp(
                Quaternion.identity, correction, fraction) * bone.rotation;
        }

        private static List<Dictionary<string, DiagonalSlashLocalPose>>
            CreateLightsaberThrustMotionSamples(
                IReadOnlyDictionary<string, DiagonalSlashLocalPose> start,
                IReadOnlyDictionary<string, DiagonalSlashLocalPose> destination,
                Quaternion propLocalRotation)
        {
            RequireGripOneHandPosePathSets(start, destination);
            Scene previewScene = EditorSceneManager.NewPreviewScene();
            GameObject startProbe = null;
            GameObject endProbe = null;
            GameObject frameProbe = null;
            try
            {
                startProbe = CreateThrustModeEnterPoseProbe(
                    previewScene, start, out Transform startProp);
                endProbe = CreateThrustModeEnterPoseProbe(
                    previewScene, destination, out Transform endProp);
                frameProbe = CreateThrustModeEnterPoseProbe(
                    previewScene, start, out Transform frameProp);
                startProp.localRotation = propLocalRotation;
                endProp.localRotation = propLocalRotation;
                frameProp.localRotation = propLocalRotation;
                Transform startRoot = startProbe.transform;
                Transform endRoot = endProbe.transform;
                Transform frameRoot = frameProbe.transform;

                Transform startRightHand =
                    RequirePoseProbeBone(startRoot, RightHandPath);
                Transform endRightHand =
                    RequirePoseProbeBone(endRoot, RightHandPath);
                Transform startLeftHand =
                    RequirePoseProbeBone(startRoot, LeftHandPath);
                Transform endLeftHand =
                    RequirePoseProbeBone(endRoot, LeftHandPath);
                Vector3 startRightPosition =
                    startRoot.InverseTransformPoint(startRightHand.position);
                Vector3 endRightPosition =
                    endRoot.InverseTransformPoint(endRightHand.position);
                Vector3 startLeftPosition =
                    startRoot.InverseTransformPoint(startLeftHand.position);
                Vector3 startRightPole = startRoot.InverseTransformPoint(
                    RequirePoseProbeBone(startRoot, RightForeArmPath).position);
                Vector3 endRightPole = endRoot.InverseTransformPoint(
                    RequirePoseProbeBone(endRoot, RightForeArmPath).position);
                Vector3 startLeftPole = startRoot.InverseTransformPoint(
                    RequirePoseProbeBone(startRoot, LeftForeArmPath).position);
                Vector3 endLeftPole = endRoot.InverseTransformPoint(
                    RequirePoseProbeBone(endRoot, LeftForeArmPath).position);
                Vector3 startGrip =
                    startRightHand.InverseTransformPoint(startLeftHand.position);
                Vector3 endGrip =
                    endRightHand.InverseTransformPoint(endLeftHand.position);
                Quaternion startPropWorld = startProp.rotation;
                Quaternion endPropWorld = endProp.rotation;
                Quaternion startLeftHandWorld = startLeftHand.rotation;
                Quaternion endLeftHandWorld = endLeftHand.rotation;
                Transform startRightArm =
                    RequirePoseProbeBone(startRoot, RightArmPath);
                Transform startLeftArm =
                    RequirePoseProbeBone(startRoot, LeftArmPath);
                Vector3 shoulderCenterLocal = startRoot.InverseTransformPoint(
                    (startRightArm.position + startLeftArm.position) * 0.5f);
                float sharedHandSide = Mathf.Sign(
                    ((startRightPosition.x + startLeftPosition.x) * 0.5f) -
                    shoulderCenterLocal.x);
                if (Mathf.Abs(sharedHandSide) < 0.5f)
                    sharedHandSide = Mathf.Sign(
                        startRightPosition.x - shoulderCenterLocal.x);
                if (Mathf.Abs(sharedHandSide) < 0.5f)
                    sharedHandSide = 1f;
                float rightElbowSide = Mathf.Sign(
                    startRoot.InverseTransformPoint(startRightArm.position).x -
                    shoulderCenterLocal.x);
                float leftElbowSide = Mathf.Sign(
                    startRoot.InverseTransformPoint(startLeftArm.position).x -
                    shoulderCenterLocal.x);
                if (Mathf.Abs(rightElbowSide) < 0.5f) rightElbowSide = 1f;
                if (Mathf.Abs(leftElbowSide) < 0.5f) leftElbowSide = -1f;

                // Move the joined hands in front of the torso before they
                // converge on the final thrust line. This prevents the direct
                // start/end interpolation from dragging either forearm through
                // the suit chest. The two elbows use opposite outward arcs so
                // the shoulder chains never collapse into one another.
                Vector3 rightHandControlOne = startRightPosition +
                    Vector3.forward * 0.26f +
                    Vector3.right * (sharedHandSide * 0.12f);
                Vector3 rightHandControlTwo = endRightPosition -
                    Vector3.forward * 0.10f +
                    Vector3.right * (sharedHandSide * 0.08f);

                var samples = new List<Dictionary<string, DiagonalSlashLocalPose>>(
                    ThrustMotionTransitionFrameCount + 1);
                for (int index = 0; index <= ThrustMotionTransitionFrameCount; index++)
                {
                    if (index == 0)
                    {
                        samples.Add(new Dictionary<string, DiagonalSlashLocalPose>(
                            start, StringComparer.Ordinal));
                        continue;
                    }
                    if (index == ThrustMotionTransitionFrameCount)
                    {
                        samples.Add(new Dictionary<string, DiagonalSlashLocalPose>(
                            destination, StringComparer.Ordinal));
                        continue;
                    }
                    float linear = index / (float)ThrustMotionTransitionFrameCount;
                    float eased = SmootherStep(linear);
                    ApplyLightsaberThrustPoseBlend(
                        frameRoot, start, destination, eased);
                    frameProp.localRotation = propLocalRotation;

                    Transform rightArm =
                        RequirePoseProbeBone(frameRoot, RightArmPath);
                    Transform rightForeArm =
                        RequirePoseProbeBone(frameRoot, RightForeArmPath);
                    Transform rightHand =
                        RequirePoseProbeBone(frameRoot, RightHandPath);
                    Vector3 rightHandTargetLocal = CubicBezier(
                        startRightPosition,
                        rightHandControlOne,
                        rightHandControlTwo,
                        endRightPosition,
                        eased);
                    float clearanceArc = Mathf.Sin(eased * Mathf.PI);
                    Vector3 rightPoleLocal = Vector3.Lerp(
                        startRightPole, endRightPole, eased) +
                        Vector3.right *
                            (rightElbowSide * clearanceArc * 0.18f) +
                        Vector3.forward * (clearanceArc * 0.12f);
                    SolveThrustModeEnterTwoBone(
                        rightArm,
                        rightForeArm,
                        rightHand,
                        frameRoot.TransformPoint(rightHandTargetLocal),
                        frameRoot.TransformPoint(rightPoleLocal),
                        "baked right thrust arm");
                    Quaternion desiredPropWorld = Quaternion.Slerp(
                        startPropWorld, endPropWorld, eased);
                    rightHand.rotation = desiredPropWorld *
                        Quaternion.Inverse(frameProp.localRotation);

                    Transform leftArm =
                        RequirePoseProbeBone(frameRoot, LeftArmPath);
                    Transform leftForeArm =
                        RequirePoseProbeBone(frameRoot, LeftForeArmPath);
                    Transform leftHand =
                        RequirePoseProbeBone(frameRoot, LeftHandPath);
                    Vector3 grip = Vector3.Lerp(startGrip, endGrip, eased);
                    Vector3 leftPoleLocal = Vector3.Lerp(
                        startLeftPole, endLeftPole, eased) +
                        Vector3.right *
                            (leftElbowSide * clearanceArc * 0.18f) +
                        Vector3.forward * (clearanceArc * 0.12f);
                    SolveThrustModeEnterTwoBone(
                        leftArm,
                        leftForeArm,
                        leftHand,
                        rightHand.TransformPoint(grip),
                        frameRoot.TransformPoint(leftPoleLocal),
                        "baked left thrust arm");
                    leftHand.rotation = Quaternion.Slerp(
                        startLeftHandWorld, endLeftHandWorld, eased);
                    samples.Add(CaptureDiagonalSlashPose(frameRoot, frameProp));
                }
                return samples;
            }
            finally
            {
                if (frameProbe != null)
                    UnityEngine.Object.DestroyImmediate(frameProbe);
                if (endProbe != null)
                    UnityEngine.Object.DestroyImmediate(endProbe);
                if (startProbe != null)
                    UnityEngine.Object.DestroyImmediate(startProbe);
                EditorSceneManager.ClosePreviewScene(previewScene);
            }
        }

        private static Vector3 CubicBezier(
            Vector3 start,
            Vector3 controlOne,
            Vector3 controlTwo,
            Vector3 end,
            float t)
        {
            float inverse = 1f - t;
            return inverse * inverse * inverse * start +
                3f * inverse * inverse * t * controlOne +
                3f * inverse * t * t * controlTwo +
                t * t * t * end;
        }

        private static float SmootherStep(float value)
        {
            value = Mathf.Clamp01(value);
            return value * value * value *
                (value * (value * 6f - 15f) + 10f);
        }

        private static void ApplyLightsaberThrustPoseBlend(
            Transform root,
            IReadOnlyDictionary<string, DiagonalSlashLocalPose> start,
            IReadOnlyDictionary<string, DiagonalSlashLocalPose> destination,
            float blend)
        {
            foreach (string path in start.Keys)
            {
                DiagonalSlashLocalPose a = start[path];
                DiagonalSlashLocalPose b = destination[path];
                Transform bone = RequirePoseProbeBone(root, path);
                bone.localPosition = Vector3.Lerp(a.Position, b.Position, blend);
                bone.localRotation = Quaternion.Slerp(a.Rotation, b.Rotation, blend);
                bone.localScale = Vector3.Lerp(a.Scale, b.Scale, blend);
            }
        }

        private static AnimationClip CreateOrUpdateLightsaberThrustMotionClip(
            IReadOnlyDictionary<string, DiagonalSlashLocalPose> start,
            IReadOnlyDictionary<string, DiagonalSlashLocalPose> destination,
            Quaternion propLocalRotation,
            IReadOnlyList<Dictionary<string, DiagonalSlashLocalPose>> samples)
        {
            var generated = new AnimationClip
            {
                name = "LightsaberThrust_ThrustHold_1_4s",
                frameRate = 60f,
                legacy = false,
                wrapMode = WrapMode.Loop
            };
            foreach (string path in start.Keys.OrderBy(
                item => item, StringComparer.Ordinal))
            {
                SetLightsaberThrustMotionCurve(generated, path,
                    "m_LocalPosition.x", samples.Select(p => p[path].Position.x));
                SetLightsaberThrustMotionCurve(generated, path,
                    "m_LocalPosition.y", samples.Select(p => p[path].Position.y));
                SetLightsaberThrustMotionCurve(generated, path,
                    "m_LocalPosition.z", samples.Select(p => p[path].Position.z));
                SetLightsaberThrustMotionCurve(generated, path,
                    "m_LocalRotation.x", samples.Select(p => p[path].Rotation.x));
                SetLightsaberThrustMotionCurve(generated, path,
                    "m_LocalRotation.y", samples.Select(p => p[path].Rotation.y));
                SetLightsaberThrustMotionCurve(generated, path,
                    "m_LocalRotation.z", samples.Select(p => p[path].Rotation.z));
                SetLightsaberThrustMotionCurve(generated, path,
                    "m_LocalRotation.w", samples.Select(p => p[path].Rotation.w));
                SetLightsaberThrustMotionCurve(generated, path,
                    "m_LocalScale.x", samples.Select(p => p[path].Scale.x));
                SetLightsaberThrustMotionCurve(generated, path,
                    "m_LocalScale.y", samples.Select(p => p[path].Scale.y));
                SetLightsaberThrustMotionCurve(generated, path,
                    "m_LocalScale.z", samples.Select(p => p[path].Scale.z));
            }
            SetLightsaberThrustMotionCurve(generated, DiagonalSlashPropPath,
                "m_LocalRotation.x", Enumerable.Repeat(
                    propLocalRotation.x, samples.Count));
            SetLightsaberThrustMotionCurve(generated, DiagonalSlashPropPath,
                "m_LocalRotation.y", Enumerable.Repeat(
                    propLocalRotation.y, samples.Count));
            SetLightsaberThrustMotionCurve(generated, DiagonalSlashPropPath,
                "m_LocalRotation.z", Enumerable.Repeat(
                    propLocalRotation.z, samples.Count));
            SetLightsaberThrustMotionCurve(generated, DiagonalSlashPropPath,
                "m_LocalRotation.w", Enumerable.Repeat(
                    propLocalRotation.w, samples.Count));
            generated.EnsureQuaternionContinuity();
            AnimationClipSettings settings =
                AnimationUtility.GetAnimationClipSettings(generated);
            settings.loopTime = true;
            settings.loopBlend = false;
            AnimationUtility.SetAnimationClipSettings(generated, settings);

            AnimationClip clip = AssetDatabase.LoadAssetAtPath<AnimationClip>(
                ThrustMotionClipPath);
            if (clip == null)
            {
                AssetDatabase.CreateAsset(generated, ThrustMotionClipPath);
                clip = generated;
            }
            else
            {
                EditorUtility.CopySerialized(generated, clip);
                clip.name = generated.name;
                EditorUtility.SetDirty(clip);
                UnityEngine.Object.DestroyImmediate(generated);
            }
            RequireLightsaberThrustMotionClip(
                clip, start, destination, propLocalRotation);
            return clip;
        }

        private static void SetLightsaberThrustMotionCurve(
            AnimationClip clip,
            string path,
            string property,
            IEnumerable<float> sourceValues)
        {
            float[] values = sourceValues.ToArray();
            if (values.Length != ThrustMotionTransitionFrameCount + 1)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust motion sample count differs.");
            var keys = new List<Keyframe>(values.Length + 2);
            for (int index = 0; index < values.Length; index++)
                keys.Add(new Keyframe(index / 60f, values[index], 0f, 0f));
            keys.Add(new Keyframe(
                ThrustMotionTransitionSeconds + 0.0001f,
                values[values.Length - 1], 0f, 0f));
            keys.Add(new Keyframe(
                ThrustMotionTransitionSeconds + ThrustMotionHoldSeconds,
                values[values.Length - 1], 0f, 0f));
            var curve = new AnimationCurve(keys.ToArray());
            for (int index = 0; index <= ThrustMotionTransitionFrameCount; index++)
            {
                AnimationUtility.SetKeyLeftTangentMode(
                    curve, index, AnimationUtility.TangentMode.Linear);
                AnimationUtility.SetKeyRightTangentMode(
                    curve, index, AnimationUtility.TangentMode.Linear);
            }
            int holdStart = values.Length;
            int holdEnd = values.Length + 1;
            AnimationUtility.SetKeyLeftTangentMode(
                curve, holdStart, AnimationUtility.TangentMode.Constant);
            AnimationUtility.SetKeyRightTangentMode(
                curve, holdStart, AnimationUtility.TangentMode.Constant);
            AnimationUtility.SetKeyLeftTangentMode(
                curve, holdEnd, AnimationUtility.TangentMode.Constant);
            AnimationUtility.SetKeyRightTangentMode(
                curve, holdEnd, AnimationUtility.TangentMode.Constant);
            AnimationUtility.SetEditorCurve(
                clip,
                EditorCurveBinding.FloatCurve(path, typeof(Transform), property),
                curve);
        }

        private static AnimatorController
            CreateOrUpdateLightsaberThrustMotionController(AnimationClip clip)
        {
            AnimatorController controller =
                AssetDatabase.LoadAssetAtPath<AnimatorController>(
                    ThrustMotionControllerPath);
            if (controller == null)
                controller = AnimatorController.CreateAnimatorControllerAtPath(
                    ThrustMotionControllerPath);
            while (controller.layers.Length > 1)
                controller.RemoveLayer(controller.layers.Length - 1);
            if (controller.layers.Length != 1)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust motion controller must contain one layer.");
            AnimatorControllerLayer layer = controller.layers[0];
            AnimatorStateMachine stateMachine = layer.stateMachine;
            foreach (AnimatorState existingState in stateMachine.states
                .Select(item => item.state).ToArray())
                stateMachine.RemoveState(existingState);
            foreach (AnimatorStateMachine nested in stateMachine.stateMachines
                .Select(item => item.stateMachine).ToArray())
                stateMachine.RemoveStateMachine(nested);
            controller.parameters = Array.Empty<AnimatorControllerParameter>();
            layer.name = "Lightsaber Thrust Motion";
            layer.defaultWeight = 1f;
            layer.blendingMode = AnimatorLayerBlendingMode.Override;
            layer.avatarMask = null;
            AnimatorState state = stateMachine.AddState(ThrustMotionStateName);
            state.motion = clip;
            state.speed = 1f;
            state.cycleOffset = 0f;
            state.mirror = false;
            state.writeDefaultValues = false;
            stateMachine.defaultState = state;
            controller.layers = new[] { layer };
            EditorUtility.SetDirty(stateMachine);
            EditorUtility.SetDirty(controller);
            return controller;
        }

        private static void InspectLightsaberThrustMotionInternal(
            Scene scene,
            bool requireCleanScene)
        {
            if (requireCleanScene && scene.isDirty)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust motion inspection requires a clean scene.");
            InspectLightsaberThrustModeEnterTransitionInternal(scene, false);
            Dictionary<string, DiagonalSlashLocalPose> start =
                CaptureLightsaberThrustModeEnterLastPose(
                    scene, out Quaternion propRotation);
            Dictionary<string, DiagonalSlashLocalPose> destination =
                CreateLightsaberThrustMotionDestination(start, propRotation);
            RequireLightsaberThrustMotionDestination(
                start, destination, propRotation);
            AnimationClip clip = RequireDiagonalSlashAsset<AnimationClip>(
                ThrustMotionClipPath);
            RequireLightsaberThrustMotionClip(
                clip, start, destination, propRotation);
            GameObject target = FindUnique(scene, ThrustTargetName);
            Animator animator = target.GetComponent<Animator>() ??
                throw new InvalidOperationException(
                    ThrustTargetName + " Animator is missing.");
            if (animator.avatar == null || animator.applyRootMotion ||
                !animator.enabled ||
                animator.cullingMode != AnimatorCullingMode.AlwaysAnimate)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust Animator settings differ.");
            Transform prop = RequireLightsaberProp(
                RequireRightHand(target), target.name);
            RequireAuthoredPropTransform(prop, target.name);
            AnimatorController controller = animator.runtimeAnimatorController as
                AnimatorController ?? throw new InvalidOperationException(
                    "Lightsaber_Thrust motion controller is missing.");
            if (AssetDatabase.GetAssetPath(controller) !=
                    ThrustMotionControllerPath ||
                controller.layers.Length != 1 ||
                controller.parameters.Length != 0)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust motion controller structure differs.");
            AnimatorControllerLayer layer = controller.layers[0];
            AnimatorState[] states = layer.stateMachine.states
                .Select(item => item.state).ToArray();
            if (layer.avatarMask != null ||
                layer.blendingMode != AnimatorLayerBlendingMode.Override ||
                !Mathf.Approximately(layer.defaultWeight, 1f) ||
                layer.stateMachine.stateMachines.Length != 0 ||
                states.Length != 1)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust motion layer structure differs.");
            AnimatorState state = states[0];
            if (state.name != ThrustMotionStateName || state.motion != clip ||
                !Mathf.Approximately(state.speed, 1f) || state.mirror ||
                state.writeDefaultValues || state.behaviours.Length != 0 ||
                state.transitions.Length != 0 ||
                layer.stateMachine.defaultState != state)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust motion state settings differ.");

            float maximumBladeDelta = 0f;
            for (int index = 0; index <= ThrustMotionTransitionFrameCount; index++)
            {
                Dictionary<string, DiagonalSlashLocalPose> sampled =
                    SampleDiagonalSlashPose(
                        target,
                        prop,
                        clip,
                        index / 60f,
                        start);
                ThrustMotionPoseMetrics metrics =
                    MeasureLightsaberThrustMotionPose(
                        start, sampled, propRotation);
                maximumBladeDelta = Mathf.Max(
                    maximumBladeDelta, metrics.BladeDirectionDeltaDegrees);
                if (metrics.LowerBodyPositionDeltaMeters >
                        ThrustMotionLowerBodyPositionToleranceMeters ||
                    metrics.LowerBodyRotationDeltaDegrees >
                        ThrustMotionLowerBodyRotationToleranceDegrees ||
                    metrics.LowerBodyScaleDelta >
                        ThrustMotionLowerBodyScaleTolerance)
                    throw new InvalidOperationException(
                        "Lightsaber_Thrust lower body changed inside the baked " +
                        "transition at " +
                        index + "/60 seconds.");
            }
            if (maximumBladeDelta > ThrustMotionBladeToleranceDegrees)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust baked transition exceeds blade tolerance. " +
                    "blade=" + Num(maximumBladeDelta) + ".");
        }

        private static void RequireLightsaberThrustMotionClip(
            AnimationClip clip,
            IReadOnlyDictionary<string, DiagonalSlashLocalPose> start,
            IReadOnlyDictionary<string, DiagonalSlashLocalPose> destination,
            Quaternion propLocalRotation)
        {
            float duration =
                ThrustMotionTransitionSeconds + ThrustMotionHoldSeconds;
            if (Mathf.Abs(clip.length - duration) > 0.0001f ||
                Mathf.Abs(clip.frameRate - 60f) > 0.0001f || !clip.isLooping)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust motion duration or loop differs.");
            EditorCurveBinding[] bindings = AnimationUtility.GetCurveBindings(clip);
            if (bindings.Length != start.Count * 10 + 4 ||
                AnimationUtility.GetObjectReferenceCurveBindings(clip).Length != 0 ||
                AnimationUtility.GetAnimationEvents(clip).Length != 0)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust motion curve structure differs.");
            foreach (EditorCurveBinding binding in bindings)
            {
                AnimationCurve curve = AnimationUtility.GetEditorCurve(clip, binding);
                int expectedCount = ThrustMotionTransitionFrameCount + 3;
                int holdStart = ThrustMotionTransitionFrameCount + 1;
                int holdEnd = ThrustMotionTransitionFrameCount + 2;
                if (curve == null || curve.keys.Length != expectedCount ||
                    Enumerable.Range(0, ThrustMotionTransitionFrameCount + 1)
                        .Any(index => Mathf.Abs(
                            curve.keys[index].time - index / 60f) > 0.0001f) ||
                    Mathf.Abs(curve.keys[holdStart].time -
                        (ThrustMotionTransitionSeconds + 0.0001f)) > 0.00001f ||
                    Mathf.Abs(curve.keys[holdEnd].time - duration) > 0.0001f ||
                    Mathf.Abs(curve.keys[ThrustMotionTransitionFrameCount].value -
                        curve.keys[holdStart].value) > 0.0001f ||
                    Mathf.Abs(curve.keys[holdStart].value -
                        curve.keys[holdEnd].value) > 0.0001f)
                    throw new InvalidOperationException(
                        "Lightsaber_Thrust motion key timing or hold value differs at " +
                        binding.path + "/" + binding.propertyName + ".");
            }
            RequirePropRotationCurves(
                clip,
                ThrustMotionTransitionFrameCount + 3,
                "Lightsaber_Thrust motion");
            if (Quaternion.Angle(
                    EvaluatePropRotation(clip, 0f), propLocalRotation) > 0.02f ||
                Quaternion.Angle(EvaluatePropRotation(
                    clip, ThrustMotionTransitionSeconds), propLocalRotation) > 0.02f ||
                Quaternion.Angle(EvaluatePropRotation(
                    clip, duration), propLocalRotation) > 0.02f)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust prop local rotation changed.");
            RequireDiagonalSlashPoseEqual(
                start,
                SampleDiagonalSlashPose(
                    FindUnique(RequireScene(), ThrustTargetName), null,
                    clip, 0f, start),
                "Lightsaber_Thrust exact start pose");
            RequireDiagonalSlashPoseEqual(
                destination,
                SampleDiagonalSlashPose(
                    FindUnique(RequireScene(), ThrustTargetName), null,
                    clip, ThrustMotionTransitionSeconds, start),
                "Lightsaber_Thrust destination pose");
            RequireDiagonalSlashPoseEqual(
                destination,
                SampleDiagonalSlashPose(
                    FindUnique(RequireScene(), ThrustTargetName), null,
                    clip, ThrustMotionTransitionSeconds +
                        ThrustMotionHoldSeconds * 0.5f, start),
                "Lightsaber_Thrust hold pose");
        }

        private static ThrustMotionPoseMetrics
            RequireLightsaberThrustMotionDestination(
                IReadOnlyDictionary<string, DiagonalSlashLocalPose> start,
                IReadOnlyDictionary<string, DiagonalSlashLocalPose> destination,
                Quaternion propLocalRotation)
        {
            RequireGripOneHandPosePathSets(start, destination);
            foreach (string path in start.Keys)
            {
                DiagonalSlashLocalPose before = start[path];
                DiagonalSlashLocalPose after = destination[path];
                if (Vector3.Distance(before.Position, after.Position) > 0.0001f)
                    throw new InvalidOperationException(
                        "Lightsaber_Thrust changed an unapproved local position at " +
                        path + ".");
                if (Vector3.Distance(before.Scale, after.Scale) > 0.0001f)
                    throw new InvalidOperationException(
                        "Lightsaber_Thrust changed scale at " + path + ".");
                bool rotationApproved =
                    path == Spine02Path || path == Spine01Path || path == SpinePath ||
                    path == RightShoulderPath || path == LeftShoulderPath ||
                    path == RightArmPath || path == RightForeArmPath ||
                    path == RightHandPath || path == LeftArmPath ||
                    path == LeftForeArmPath || path == LeftHandPath;
                if (!rotationApproved &&
                    Quaternion.Angle(before.Rotation, after.Rotation) > 0.02f)
                    throw new InvalidOperationException(
                        "Lightsaber_Thrust changed an unapproved rotation at " + path +
                        ".");
            }
            ThrustMotionPoseMetrics metrics = MeasureLightsaberThrustMotionPose(
                start, destination, propLocalRotation);
            if (metrics.LowerBodyPositionDeltaMeters >
                    ThrustMotionLowerBodyPositionToleranceMeters ||
                metrics.LowerBodyRotationDeltaDegrees >
                    ThrustMotionLowerBodyRotationToleranceDegrees ||
                metrics.LowerBodyScaleDelta >
                    ThrustMotionLowerBodyScaleTolerance)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust lower body did not remain identical to the " +
                    "start pose. position=" +
                    Num(metrics.LowerBodyPositionDeltaMeters) +
                    "|rotation=" + Num(metrics.LowerBodyRotationDeltaDegrees) +
                    "|scale=" + Num(metrics.LowerBodyScaleDelta) + ".");
            if (metrics.TorsoForwardLeanErrorDegrees >
                    ThrustMotionTorsoToleranceDegrees ||
                metrics.RightArmForwardAngleDegrees >
                    ThrustMotionArmForwardToleranceDegrees ||
                metrics.LeftArmForwardAngleDegrees >
                    ThrustMotionArmForwardToleranceDegrees ||
                Mathf.Abs(metrics.RightArmForwardAngleDegrees -
                    metrics.LeftArmForwardAngleDegrees) >
                    ThrustMotionArmForwardSymmetryToleranceDegrees)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust torso or arms do not face the approved " +
                    "directions. torsoLean=" +
                    Num(metrics.TorsoForwardLeanDegrees) +
                    "|torsoError=" +
                    Num(metrics.TorsoForwardLeanErrorDegrees) +
                    "|rightArm=" + Num(metrics.RightArmForwardAngleDegrees) +
                    "|leftArm=" + Num(metrics.LeftArmForwardAngleDegrees) +
                    "|difference=" + Num(Mathf.Abs(
                        metrics.RightArmForwardAngleDegrees -
                        metrics.LeftArmForwardAngleDegrees)) + ".");
            if (metrics.BladeDirectionDeltaDegrees >
                    ThrustMotionBladeToleranceDegrees ||
                metrics.GripOffsetErrorMeters > ThrustMotionGripToleranceMeters)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust blade direction or two-hand grip differs. blade=" +
                    Num(metrics.BladeDirectionDeltaDegrees) +
                    "|grip=" + Num(metrics.GripOffsetErrorMeters) + ".");
            if (Mathf.Abs(metrics.RightElbowDegrees -
                    ThrustMotionElbowBendDegrees) >
                    ThrustMotionElbowToleranceDegrees ||
                Mathf.Abs(metrics.LeftElbowDegrees -
                    ThrustMotionElbowBendDegrees) >
                    ThrustMotionElbowToleranceDegrees)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust elbows are not extended to five degrees. " +
                    "right=" + Num(metrics.RightElbowDegrees) +
                    "|left=" + Num(metrics.LeftElbowDegrees) + ".");
            if (metrics.HandleChestHeightOffsetMeters >
                    ThrustMotionChestHeightToleranceMeters)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust handle center is not at chest height. offset=" +
                    Num(metrics.HandleChestHeightOffsetMeters) + ".");
            if (metrics.LeftFootPositionDriftMeters >
                    ThrustModeEnterFootPositionToleranceMeters ||
                metrics.RightFootPositionDriftMeters >
                    ThrustModeEnterFootPositionToleranceMeters ||
                metrics.LeftFootRotationDriftDegrees >
                    ThrustModeEnterFootRotationToleranceDegrees ||
                metrics.RightFootRotationDriftDegrees >
                    ThrustModeEnterFootRotationToleranceDegrees)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust destination feet are not planted.");
            if (metrics.BladeHeadClearanceMeters < ThrustMotionClearanceMeters ||
                metrics.BladeTorsoClearanceMeters < ThrustMotionClearanceMeters)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust blade intersects the head or torso. head=" +
                    Num(metrics.BladeHeadClearanceMeters) +
                    "|torso=" + Num(metrics.BladeTorsoClearanceMeters) + ".");
            return metrics;
        }

        private static ThrustMotionPoseMetrics MeasureLightsaberThrustMotionPose(
            IReadOnlyDictionary<string, DiagonalSlashLocalPose> start,
            IReadOnlyDictionary<string, DiagonalSlashLocalPose> actual,
            Quaternion propLocalRotation)
        {
            Scene previewScene = EditorSceneManager.NewPreviewScene();
            GameObject startProbe = null;
            GameObject actualProbe = null;
            try
            {
                startProbe = CreateThrustModeEnterPoseProbe(
                    previewScene, start, out Transform startProp);
                actualProbe = CreateThrustModeEnterPoseProbe(
                    previewScene, actual, out Transform actualProp);
                startProp.localRotation = propLocalRotation;
                actualProp.localRotation = propLocalRotation;
                Transform startRoot = startProbe.transform;
                Transform root = actualProbe.transform;
                Transform rightArm = RequirePoseProbeBone(root, RightArmPath);
                Transform rightForeArm =
                    RequirePoseProbeBone(root, RightForeArmPath);
                Transform rightHand = RequirePoseProbeBone(root, RightHandPath);
                Transform leftArm = RequirePoseProbeBone(root, LeftArmPath);
                Transform leftForeArm =
                    RequirePoseProbeBone(root, LeftForeArmPath);
                Transform leftHand = RequirePoseProbeBone(root, LeftHandPath);
                Transform leftShoulder =
                    RequirePoseProbeBone(root, LeftShoulderPath);
                Transform rightShoulder =
                    RequirePoseProbeBone(root, RightShoulderPath);
                Transform spine = RequirePoseProbeBone(root, SpinePath);
                Transform hips = RequirePoseProbeBone(root, HipsPath);
                Transform head = root.GetComponentsInChildren<Transform>(true)
                    .Single(item => item.name == "Head");
                Transform startLeftFoot =
                    RequirePoseProbeBone(startRoot, LeftFootPath);
                Transform startRightFoot =
                    RequirePoseProbeBone(startRoot, RightFootPath);
                Transform leftFoot = RequirePoseProbeBone(root, LeftFootPath);
                Transform rightFoot = RequirePoseProbeBone(root, RightFootPath);
                Vector3 startBladeDirection = startProp.TransformDirection(
                    DiagonalSlashBladeAxisLocal()).normalized;
                Vector3 bladeDirection = actualProp.TransformDirection(
                    DiagonalSlashBladeAxisLocal()).normalized;
                Vector3 bladeStart = actualProp.position;
                Vector3 bladeEnd = bladeStart +
                    bladeDirection * LightsaberTotalLengthMeters;
                Vector3 shoulderCenter =
                    (leftShoulder.position + rightShoulder.position) * 0.5f;
                Vector3 middleTorso = Vector3.LerpUnclamped(
                    hips.position,
                    shoulderCenter,
                    ThrustMotionChestHeightFraction);
                Vector3 torsoDirection =
                    (shoulderCenter - spine.position).normalized;
                MeasureLightsaberThrustLowerBodyPoseDelta(
                    start,
                    actual,
                    out float lowerBodyPositionDelta,
                    out float lowerBodyRotationDelta,
                    out float lowerBodyScaleDelta);
                return new ThrustMotionPoseMetrics(
                    lowerBodyPositionDelta,
                    lowerBodyRotationDelta,
                    lowerBodyScaleDelta,
                    Vector3.SignedAngle(root.up, torsoDirection, root.right),
                    Vector3.Angle(
                        torsoDirection,
                        LightsaberThrustForwardTorsoDirection(root)),
                    MeasureLightsaberThrustForwardAngle(
                        root, rightArm.position, rightHand.position),
                    MeasureLightsaberThrustForwardAngle(
                        root, leftArm.position, leftHand.position),
                    Vector3.Angle(startBladeDirection, bladeDirection),
                    MeasureLightsaberThrustGripAxisError(
                        rightHand, leftHand, bladeDirection),
                    Mathf.Abs(Vector3.Dot(
                        actualProp.position - middleTorso, root.up)),
                    Vector3.Angle(
                        rightForeArm.position - rightArm.position,
                        rightHand.position - rightForeArm.position),
                    Vector3.Angle(
                        leftForeArm.position - leftArm.position,
                        leftHand.position - leftForeArm.position),
                    Vector3.Distance(startLeftFoot.position, leftFoot.position),
                    Vector3.Distance(startRightFoot.position, rightFoot.position),
                    Quaternion.Angle(startLeftFoot.rotation, leftFoot.rotation),
                    Quaternion.Angle(startRightFoot.rotation, rightFoot.rotation),
                    DistancePointToSegment(
                        head.position, bladeStart, bladeEnd),
                    Mathf.Min(
                        DistancePointToSegment(
                            shoulderCenter, bladeStart, bladeEnd),
                        DistancePointToSegment(
                            middleTorso, bladeStart, bladeEnd)));
            }
            finally
            {
                if (actualProbe != null)
                    UnityEngine.Object.DestroyImmediate(actualProbe);
                if (startProbe != null)
                    UnityEngine.Object.DestroyImmediate(startProbe);
                EditorSceneManager.ClosePreviewScene(previewScene);
            }
        }

        private static void MeasureLightsaberThrustLowerBodyPoseDelta(
            IReadOnlyDictionary<string, DiagonalSlashLocalPose> start,
            IReadOnlyDictionary<string, DiagonalSlashLocalPose> actual,
            out float maximumPositionDelta,
            out float maximumRotationDelta,
            out float maximumScaleDelta)
        {
            maximumPositionDelta = 0f;
            maximumRotationDelta = 0f;
            maximumScaleDelta = 0f;
            foreach (string path in start.Keys.Where(IsLightsaberThrustLowerBodyPath))
            {
                DiagonalSlashLocalPose before = start[path];
                DiagonalSlashLocalPose after = actual[path];
                maximumPositionDelta = Mathf.Max(
                    maximumPositionDelta,
                    Vector3.Distance(before.Position, after.Position));
                maximumRotationDelta = Mathf.Max(
                    maximumRotationDelta,
                    Quaternion.Angle(before.Rotation, after.Rotation));
                maximumScaleDelta = Mathf.Max(
                    maximumScaleDelta,
                    Vector3.Distance(before.Scale, after.Scale));
            }
        }

        private static bool IsLightsaberThrustLowerBodyPath(string path)
        {
            return path == HipsPath ||
                path == LeftUpLegPath ||
                path.StartsWith(LeftUpLegPath + "/", StringComparison.Ordinal) ||
                path == RightUpLegPath ||
                path.StartsWith(RightUpLegPath + "/", StringComparison.Ordinal);
        }

        private readonly struct ThrustMotionPoseMetrics
        {
            internal ThrustMotionPoseMetrics(
                float lowerBodyPositionDeltaMeters,
                float lowerBodyRotationDeltaDegrees,
                float lowerBodyScaleDelta,
                float torsoForwardLeanDegrees,
                float torsoForwardLeanErrorDegrees,
                float rightArmForwardAngleDegrees,
                float leftArmForwardAngleDegrees,
                float bladeDirectionDeltaDegrees,
                float gripOffsetErrorMeters,
                float handleChestHeightOffsetMeters,
                float rightElbowDegrees,
                float leftElbowDegrees,
                float leftFootPositionDriftMeters,
                float rightFootPositionDriftMeters,
                float leftFootRotationDriftDegrees,
                float rightFootRotationDriftDegrees,
                float bladeHeadClearanceMeters,
                float bladeTorsoClearanceMeters)
            {
                LowerBodyPositionDeltaMeters = lowerBodyPositionDeltaMeters;
                LowerBodyRotationDeltaDegrees = lowerBodyRotationDeltaDegrees;
                LowerBodyScaleDelta = lowerBodyScaleDelta;
                TorsoForwardLeanDegrees = torsoForwardLeanDegrees;
                TorsoForwardLeanErrorDegrees = torsoForwardLeanErrorDegrees;
                RightArmForwardAngleDegrees = rightArmForwardAngleDegrees;
                LeftArmForwardAngleDegrees = leftArmForwardAngleDegrees;
                BladeDirectionDeltaDegrees = bladeDirectionDeltaDegrees;
                GripOffsetErrorMeters = gripOffsetErrorMeters;
                HandleChestHeightOffsetMeters = handleChestHeightOffsetMeters;
                RightElbowDegrees = rightElbowDegrees;
                LeftElbowDegrees = leftElbowDegrees;
                LeftFootPositionDriftMeters = leftFootPositionDriftMeters;
                RightFootPositionDriftMeters = rightFootPositionDriftMeters;
                LeftFootRotationDriftDegrees = leftFootRotationDriftDegrees;
                RightFootRotationDriftDegrees = rightFootRotationDriftDegrees;
                BladeHeadClearanceMeters = bladeHeadClearanceMeters;
                BladeTorsoClearanceMeters = bladeTorsoClearanceMeters;
            }

            internal float LowerBodyPositionDeltaMeters { get; }
            internal float LowerBodyRotationDeltaDegrees { get; }
            internal float LowerBodyScaleDelta { get; }
            internal float TorsoForwardLeanDegrees { get; }
            internal float TorsoForwardLeanErrorDegrees { get; }
            internal float RightArmForwardAngleDegrees { get; }
            internal float LeftArmForwardAngleDegrees { get; }
            internal float BladeDirectionDeltaDegrees { get; }
            internal float GripOffsetErrorMeters { get; }
            internal float HandleChestHeightOffsetMeters { get; }
            internal float RightElbowDegrees { get; }
            internal float LeftElbowDegrees { get; }
            internal float LeftFootPositionDriftMeters { get; }
            internal float RightFootPositionDriftMeters { get; }
            internal float LeftFootRotationDriftDegrees { get; }
            internal float RightFootRotationDriftDegrees { get; }
            internal float BladeHeadClearanceMeters { get; }
            internal float BladeTorsoClearanceMeters { get; }
        }

        private static void ConfigureThrustModeEnterSourceImporter()
        {
            ModelImporter importer =
                AssetImporter.GetAtPath(ThrustModeEnterSourcePath) as ModelImporter ??
                throw new InvalidOperationException(
                    "Thrust-mode-enter FBX ModelImporter is unavailable.");
            importer.importAnimation = true;
            importer.animationType = ModelImporterAnimationType.Generic;
            importer.resampleCurves = false;
            importer.animationCompression = ModelImporterAnimationCompression.Off;
            importer.SaveAndReimport();
            importer = AssetImporter.GetAtPath(ThrustModeEnterSourcePath) as
                ModelImporter ?? throw new InvalidOperationException(
                    "Thrust-mode-enter FBX importer disappeared after reimport.");
            ModelImporterClipAnimation[] clips = importer.clipAnimations;
            if (clips == null || clips.Length == 0)
                clips = importer.defaultClipAnimations;
            if (clips == null || clips.Length != 1)
                throw new InvalidOperationException(
                    "Thrust-mode-enter FBX must expose exactly one embedded take; actual=" +
                    (clips == null ? "0" : clips.Length.ToString(
                        CultureInfo.InvariantCulture)) + ".");
            clips[0].loopTime = false;
            clips[0].loopPose = false;
            importer.clipAnimations = clips;
            importer.SaveAndReimport();
            RequireThrustModeEnterImporter();
        }

        private static void RequireThrustModeEnterImporter()
        {
            ModelImporter importer =
                AssetImporter.GetAtPath(ThrustModeEnterSourcePath) as ModelImporter ??
                throw new InvalidOperationException(
                    "Thrust-mode-enter FBX ModelImporter is unavailable.");
            if (!importer.importAnimation ||
                importer.animationType != ModelImporterAnimationType.Generic ||
                importer.resampleCurves ||
                importer.animationCompression != ModelImporterAnimationCompression.Off)
                throw new InvalidOperationException(
                    "Thrust-mode-enter FBX importer settings differ.");
            ModelImporterClipAnimation[] clips = importer.clipAnimations;
            if (clips == null || clips.Length == 0)
                clips = importer.defaultClipAnimations;
            if (clips == null || clips.Length != 1 ||
                clips[0].loopTime || clips[0].loopPose)
                throw new InvalidOperationException(
                    "Thrust-mode-enter embedded take settings differ.");
        }

        private static AnimationClip RequireSingleThrustModeEnterClip()
        {
            AnimationClip[] clips = AssetDatabase
                .LoadAllAssetsAtPath(ThrustModeEnterSourcePath)
                .OfType<AnimationClip>()
                .Where(item => !item.name.StartsWith(
                    "__preview__", StringComparison.Ordinal))
                .ToArray();
            if (clips.Length != 1)
                throw new InvalidOperationException(
                    "Thrust-mode-enter FBX must expose exactly one AnimationClip; actual=" +
                    clips.Length.ToString(CultureInfo.InvariantCulture) + ".");
            return clips[0];
        }

        private static void RequireThrustModeEnterBindingCompatibility(
            Transform target,
            AnimationClip clip)
        {
            EditorCurveBinding[] bindings = AnimationUtility.GetCurveBindings(clip);
            string[] missing = bindings
                .Concat(AnimationUtility.GetObjectReferenceCurveBindings(clip))
                .Select(item => item.path)
                .Where(path => !string.IsNullOrEmpty(path) && target.Find(path) == null)
                .Distinct(StringComparer.Ordinal)
                .OrderBy(path => path, StringComparer.Ordinal)
                .ToArray();
            if (missing.Length > 0)
                throw new InvalidOperationException(
                    "Thrust-mode-enter clip contains target-missing paths: " +
                    string.Join(",", missing.Take(12)));
            if (bindings.Length == 0)
                throw new InvalidOperationException(
                    "Thrust-mode-enter clip has no animation curves.");
        }

        private static AnimationClip CreateOrUpdateThrustModeEnterCycleClip(
            IReadOnlyDictionary<string, DiagonalSlashLocalPose> currentPose,
            IReadOnlyDictionary<string, DiagonalSlashLocalPose> correctedDestination)
        {
            RequireGripOneHandPosePathSets(currentPose, correctedDestination);
            float cycleSeconds =
                ThrustModeEnterTransitionSeconds + ThrustModeEnterHoldSeconds;
            List<Dictionary<string, DiagonalSlashLocalPose>> transitionPoses =
                CreateThrustModeEnterFootPlantedTransitionPoses(
                    currentPose, correctedDestination);
            var generated = new AnimationClip
            {
                name = "LightsaberThrustModeEnter_CurrentToFirstPose_Hold_1_0s",
                frameRate = 60f,
                legacy = false,
                wrapMode = WrapMode.Loop
            };
            foreach (string posePath in currentPose.Keys.OrderBy(
                item => item, StringComparer.Ordinal))
            {
                Quaternion[] rotations = transitionPoses
                    .Select(item => item[posePath].Rotation)
                    .ToArray();
                for (int index = 1; index < rotations.Length; index++)
                    if (Quaternion.Dot(rotations[index - 1], rotations[index]) < 0f)
                        rotations[index] = NegateQuaternion(rotations[index]);
                SetThrustModeEnterCycleCurve(generated, posePath,
                    "m_LocalPosition.x", transitionPoses.Select(
                        item => item[posePath].Position.x).ToArray(), cycleSeconds);
                SetThrustModeEnterCycleCurve(generated, posePath,
                    "m_LocalPosition.y", transitionPoses.Select(
                        item => item[posePath].Position.y).ToArray(), cycleSeconds);
                SetThrustModeEnterCycleCurve(generated, posePath,
                    "m_LocalPosition.z", transitionPoses.Select(
                        item => item[posePath].Position.z).ToArray(), cycleSeconds);
                SetThrustModeEnterCycleCurve(generated, posePath,
                    "m_LocalRotation.x", rotations.Select(item => item.x).ToArray(),
                    cycleSeconds);
                SetThrustModeEnterCycleCurve(generated, posePath,
                    "m_LocalRotation.y", rotations.Select(item => item.y).ToArray(),
                    cycleSeconds);
                SetThrustModeEnterCycleCurve(generated, posePath,
                    "m_LocalRotation.z", rotations.Select(item => item.z).ToArray(),
                    cycleSeconds);
                SetThrustModeEnterCycleCurve(generated, posePath,
                    "m_LocalRotation.w", rotations.Select(item => item.w).ToArray(),
                    cycleSeconds);
                SetThrustModeEnterCycleCurve(generated, posePath,
                    "m_LocalScale.x", transitionPoses.Select(
                        item => item[posePath].Scale.x).ToArray(), cycleSeconds);
                SetThrustModeEnterCycleCurve(generated, posePath,
                    "m_LocalScale.y", transitionPoses.Select(
                        item => item[posePath].Scale.y).ToArray(), cycleSeconds);
                SetThrustModeEnterCycleCurve(generated, posePath,
                    "m_LocalScale.z", transitionPoses.Select(
                        item => item[posePath].Scale.z).ToArray(), cycleSeconds);
            }
            Quaternion targetPropRotation =
                CreateThrustModeEnterTiltedPropLocalRotation(correctedDestination);
            Quaternion[] propRotations = Enumerable.Range(
                    0, ThrustModeEnterTransitionFrameCount + 1)
                .Select(index =>
                {
                    float blend = index / (float)ThrustModeEnterTransitionFrameCount;
                    float eased = blend * blend * (3f - 2f * blend);
                    return Quaternion.Slerp(
                        AuthoredPropLocalRotation, targetPropRotation, eased);
                })
                .ToArray();
            for (int index = 1; index < propRotations.Length; index++)
                if (Quaternion.Dot(propRotations[index - 1], propRotations[index]) < 0f)
                    propRotations[index] = NegateQuaternion(propRotations[index]);
            SetThrustModeEnterCycleCurve(generated, DiagonalSlashPropPath,
                "m_LocalRotation.x", propRotations.Select(item => item.x).ToArray(),
                cycleSeconds);
            SetThrustModeEnterCycleCurve(generated, DiagonalSlashPropPath,
                "m_LocalRotation.y", propRotations.Select(item => item.y).ToArray(),
                cycleSeconds);
            SetThrustModeEnterCycleCurve(generated, DiagonalSlashPropPath,
                "m_LocalRotation.z", propRotations.Select(item => item.z).ToArray(),
                cycleSeconds);
            SetThrustModeEnterCycleCurve(generated, DiagonalSlashPropPath,
                "m_LocalRotation.w", propRotations.Select(item => item.w).ToArray(),
                cycleSeconds);
            generated.EnsureQuaternionContinuity();
            FlattenThrustModeEnterHoldTangents(generated);
            AnimationClipSettings settings =
                AnimationUtility.GetAnimationClipSettings(generated);
            settings.loopTime = true;
            settings.loopBlend = false;
            AnimationUtility.SetAnimationClipSettings(generated, settings);
            AnimationClip clip = AssetDatabase.LoadAssetAtPath<AnimationClip>(
                ThrustModeEnterCycleClipPath);
            if (clip == null)
            {
                AssetDatabase.CreateAsset(generated, ThrustModeEnterCycleClipPath);
                clip = generated;
            }
            else
            {
                EditorUtility.CopySerialized(generated, clip);
                clip.name = generated.name;
                EditorUtility.SetDirty(clip);
                UnityEngine.Object.DestroyImmediate(generated);
            }
            RequireThrustModeEnterCycleClip(clip);
            RequireThrustModeEnterPropTiltCurves(clip, correctedDestination);
            return clip;
        }

        private static void FlattenThrustModeEnterHoldTangents(AnimationClip clip)
        {
            foreach (EditorCurveBinding binding in
                AnimationUtility.GetCurveBindings(clip))
            {
                AnimationCurve curve = AnimationUtility.GetEditorCurve(clip, binding);
                if (curve == null || curve.length !=
                    ThrustModeEnterTransitionFrameCount + 3) continue;
                Keyframe[] keys = curve.keys;
                int transitionEnd = ThrustModeEnterTransitionFrameCount;
                int holdStart = transitionEnd + 1;
                int holdEnd = transitionEnd + 2;
                keys[transitionEnd].outTangent = 0f;
                keys[holdStart].inTangent = 0f;
                keys[holdStart].outTangent = 0f;
                keys[holdEnd].inTangent = 0f;
                keys[holdEnd].outTangent = 0f;
                curve.keys = keys;
                for (int index = 0; index <= transitionEnd; index++)
                {
                    if (index > 0)
                        AnimationUtility.SetKeyLeftTangentMode(
                            curve, index, AnimationUtility.TangentMode.Linear);
                    if (index < transitionEnd)
                        AnimationUtility.SetKeyRightTangentMode(
                            curve, index, AnimationUtility.TangentMode.Linear);
                }
                AnimationUtility.SetKeyRightTangentMode(
                    curve, transitionEnd, AnimationUtility.TangentMode.Constant);
                AnimationUtility.SetKeyLeftTangentMode(
                    curve, holdStart, AnimationUtility.TangentMode.Constant);
                AnimationUtility.SetKeyRightTangentMode(
                    curve, holdStart, AnimationUtility.TangentMode.Constant);
                AnimationUtility.SetKeyLeftTangentMode(
                    curve, holdEnd, AnimationUtility.TangentMode.Constant);
                AnimationUtility.SetEditorCurve(clip, binding, curve);
            }
        }

        private static void SetThrustModeEnterCycleCurve(
            AnimationClip clip,
            string posePath,
            string property,
            IReadOnlyList<float> transitionValues,
            float cycleSeconds)
        {
            if (transitionValues.Count != ThrustModeEnterTransitionFrameCount + 1)
                throw new InvalidOperationException(
                    "Thrust-mode-enter baked transition sample count differs.");
            var keys = new List<Keyframe>(transitionValues.Count + 2);
            for (int index = 0; index < transitionValues.Count; index++)
                keys.Add(new Keyframe(index / 60f, transitionValues[index], 0f, 0f));
            float heldValue = transitionValues[transitionValues.Count - 1];
            keys.Add(new Keyframe(
                ThrustModeEnterTransitionSeconds + 0.0001f,
                heldValue,
                0f,
                0f));
            keys.Add(new Keyframe(cycleSeconds, heldValue, 0f, 0f));
            var curve = new AnimationCurve(keys.ToArray())
            {
                preWrapMode = WrapMode.ClampForever,
                postWrapMode = WrapMode.ClampForever
            };
            AnimationUtility.SetEditorCurve(
                clip,
                EditorCurveBinding.FloatCurve(
                    posePath, typeof(Transform), property),
                curve);
        }

        internal static Vector3 ThrustModeEnterBladeTiltDirectionLocal()
        {
            float down = Mathf.Tan(
                ThrustModeEnterBladeDownTiltDegrees * Mathf.Deg2Rad);
            float left = Mathf.Tan(
                ThrustModeEnterBladeLeftTiltDegrees * Mathf.Deg2Rad);
            return new Vector3(-left, -down, 1f).normalized;
        }

        internal static Vector3 ThrustModeEnterBladeTiltDirection(Transform root)
        {
            return root.TransformDirection(
                ThrustModeEnterBladeTiltDirectionLocal()).normalized;
        }

        private static Quaternion CreateThrustModeEnterTiltedPropLocalRotation(
            IReadOnlyDictionary<string, DiagonalSlashLocalPose> destinationPose)
        {
            Scene previewScene = EditorSceneManager.NewPreviewScene();
            GameObject probe = null;
            try
            {
                probe = CreateThrustModeEnterPoseProbe(
                    previewScene, destinationPose, out Transform prop);
                Transform root = probe.transform;
                Vector3 currentDirection = prop.TransformDirection(
                    DiagonalSlashBladeAxisLocal()).normalized;
                Vector3 targetDirection =
                    ThrustModeEnterBladeTiltDirection(root);
                Quaternion targetWorldRotation = Quaternion.FromToRotation(
                    currentDirection, targetDirection) * prop.rotation;
                return (Quaternion.Inverse(prop.parent.rotation) *
                    targetWorldRotation).normalized;
            }
            finally
            {
                if (probe != null) UnityEngine.Object.DestroyImmediate(probe);
                EditorSceneManager.ClosePreviewScene(previewScene);
            }
        }

        private static void RequireThrustModeEnterPropTiltCurves(
            AnimationClip clip,
            IReadOnlyDictionary<string, DiagonalSlashLocalPose> destinationPose)
        {
            const string label = "ThrustModeEnter blade tilt";
            RequirePropRotationCurves(
                clip, ThrustModeEnterTransitionFrameCount + 3, label);
            Quaternion expectedEnd =
                CreateThrustModeEnterTiltedPropLocalRotation(destinationPose);
            Quaternion start = EvaluatePropRotation(clip, 0f);
            Quaternion end = EvaluatePropRotation(
                clip, ThrustModeEnterTransitionSeconds);
            Quaternion hold = EvaluatePropRotation(
                clip,
                ThrustModeEnterTransitionSeconds +
                ThrustModeEnterHoldSeconds * 0.5f);
            if (Quaternion.Angle(start, AuthoredPropLocalRotation) > 0.02f ||
                Quaternion.Angle(end, expectedEnd) > 0.02f ||
                Quaternion.Angle(hold, expectedEnd) > 0.02f)
                throw new InvalidOperationException(
                    label + " rotation endpoints or hold differ.");

            Scene previewScene = EditorSceneManager.NewPreviewScene();
            GameObject probe = null;
            try
            {
                probe = CreateThrustModeEnterPoseProbe(
                    previewScene, destinationPose, out Transform prop);
                prop.localRotation = end;
                Vector3 bladeLocal = probe.transform.InverseTransformDirection(
                    prop.TransformDirection(DiagonalSlashBladeAxisLocal())).normalized;
                float downDegrees = Mathf.Atan2(
                    -bladeLocal.y, bladeLocal.z) * Mathf.Rad2Deg;
                float leftDegrees = Mathf.Atan2(
                    -bladeLocal.x, bladeLocal.z) * Mathf.Rad2Deg;
                float directionError = Vector3.Angle(
                    bladeLocal, ThrustModeEnterBladeTiltDirectionLocal());
                if (Mathf.Abs(
                        downDegrees - ThrustModeEnterBladeDownTiltDegrees) >
                        ThrustModeEnterBladeTiltToleranceDegrees ||
                    Mathf.Abs(
                        leftDegrees - ThrustModeEnterBladeLeftTiltDegrees) >
                        ThrustModeEnterBladeTiltToleranceDegrees ||
                    directionError > ThrustModeEnterBladeTiltToleranceDegrees ||
                    bladeLocal.z <= 0f)
                    throw new InvalidOperationException(
                        label + " direction differs. down=" + Num(downDegrees) +
                        "|left=" + Num(leftDegrees) +
                        "|directionError=" + Num(directionError) + ".");
            }
            finally
            {
                if (probe != null) UnityEngine.Object.DestroyImmediate(probe);
                EditorSceneManager.ClosePreviewScene(previewScene);
            }
        }

        private static List<Dictionary<string, DiagonalSlashLocalPose>>
            CreateThrustModeEnterFootPlantedTransitionPoses(
                IReadOnlyDictionary<string, DiagonalSlashLocalPose> currentPose,
                IReadOnlyDictionary<string, DiagonalSlashLocalPose> destinationPose)
        {
            RequireGripOneHandPosePathSets(currentPose, destinationPose);
            Scene previewScene = EditorSceneManager.NewPreviewScene();
            GameObject probe = null;
            try
            {
                probe = CreateThrustModeEnterPoseProbe(
                    previewScene, currentPose, out Transform prop);
                Transform root = probe.transform;
                ThrustModeEnterFootReferences feet =
                    CaptureThrustModeEnterFootReferences(root);
                ApplyThrustModeEnterPose(root, currentPose);
                Transform rightForeArm = RequirePoseProbeBone(root, RightForeArmPath);
                Transform rightHand = RequirePoseProbeBone(root, RightHandPath);
                Transform leftForeArm = RequirePoseProbeBone(root, LeftForeArmPath);
                Transform leftHand = RequirePoseProbeBone(root, LeftHandPath);
                Vector3 startRightHandLocal = root.InverseTransformPoint(rightHand.position);
                Vector3 startRightElbowLocal = root.InverseTransformPoint(rightForeArm.position);
                Vector3 startLeftHandLocal = root.InverseTransformPoint(leftHand.position);
                Vector3 startLeftElbowLocal = root.InverseTransformPoint(leftForeArm.position);
                Vector3 startBladeLocal = root.InverseTransformDirection(
                    prop.TransformDirection(DiagonalSlashBladeAxisLocal())).normalized;
                ApplyThrustModeEnterPose(root, destinationPose);
                Vector3 endRightHandLocal = root.InverseTransformPoint(rightHand.position);
                Vector3 endRightElbowLocal = root.InverseTransformPoint(rightForeArm.position);
                Vector3 endLeftHandLocal = root.InverseTransformPoint(leftHand.position);
                Vector3 endLeftElbowLocal = root.InverseTransformPoint(leftForeArm.position);
                Vector3 endBladeLocal = root.InverseTransformDirection(
                    prop.TransformDirection(DiagonalSlashBladeAxisLocal())).normalized;
                var samples = new List<Dictionary<string, DiagonalSlashLocalPose>>(
                    ThrustModeEnterTransitionFrameCount + 1);
                for (int frame = 0; frame <= ThrustModeEnterTransitionFrameCount; frame++)
                {
                    if (frame == 0)
                    {
                        ApplyThrustModeEnterPose(root, currentPose);
                    }
                    else if (frame == ThrustModeEnterTransitionFrameCount)
                    {
                        ApplyThrustModeEnterPose(root, destinationPose);
                    }
                    else
                    {
                        float blend = frame /
                            (float)ThrustModeEnterTransitionFrameCount;
                        ApplyThrustModeEnterInterpolatedPose(
                            root, currentPose, destinationPose, blend);
                        ApplyThrustModeEnterFootPlant(root, currentPose, feet);
                        ApplyThrustModeEnterClearanceArmArc(
                            root,
                            prop,
                            blend,
                            startRightHandLocal,
                            endRightHandLocal,
                            startRightElbowLocal,
                            endRightElbowLocal,
                            startLeftHandLocal,
                            endLeftHandLocal,
                            startLeftElbowLocal,
                            endLeftElbowLocal,
                            startBladeLocal,
                            endBladeLocal);
                    }
                    samples.Add(CaptureDiagonalSlashPose(root, prop));
                }
                return samples;
            }
            finally
            {
                if (probe != null) UnityEngine.Object.DestroyImmediate(probe);
                EditorSceneManager.ClosePreviewScene(previewScene);
            }
        }

        private static void ApplyThrustModeEnterClearanceArmArc(
            Transform root,
            Transform prop,
            float blend,
            Vector3 startRightHandLocal,
            Vector3 endRightHandLocal,
            Vector3 startRightElbowLocal,
            Vector3 endRightElbowLocal,
            Vector3 startLeftHandLocal,
            Vector3 endLeftHandLocal,
            Vector3 startLeftElbowLocal,
            Vector3 endLeftElbowLocal,
            Vector3 startBladeLocal,
            Vector3 endBladeLocal)
        {
            float eased = blend * blend * (3f - 2f * blend);
            float outwardArc = Mathf.Sin(blend * Mathf.PI) * 0.12f;
            Vector3 arcOffset = Vector3.right * outwardArc;
            Transform rightArm = RequirePoseProbeBone(root, RightArmPath);
            Transform rightForeArm = RequirePoseProbeBone(root, RightForeArmPath);
            Transform rightHand = RequirePoseProbeBone(root, RightHandPath);
            SolveThrustModeEnterTwoBone(
                rightArm,
                rightForeArm,
                rightHand,
                root.TransformPoint(
                    Vector3.Lerp(startRightHandLocal, endRightHandLocal, eased) +
                    arcOffset),
                root.TransformPoint(
                    Vector3.Lerp(startRightElbowLocal, endRightElbowLocal, eased) +
                    arcOffset * 0.7f + Vector3.up * (outwardArc * 0.15f)),
                "right arm clearance arc");
            Vector3 desiredBladeDirection = root.TransformDirection(
                Vector3.Slerp(startBladeLocal, endBladeLocal, eased).normalized);
            rightHand.rotation = Quaternion.FromToRotation(
                prop.TransformDirection(DiagonalSlashBladeAxisLocal()),
                desiredBladeDirection) * rightHand.rotation;

            Transform leftArm = RequirePoseProbeBone(root, LeftArmPath);
            Transform leftForeArm = RequirePoseProbeBone(root, LeftForeArmPath);
            Transform leftHand = RequirePoseProbeBone(root, LeftHandPath);
            // Route the left chain in front of the torso without a carrier-left
            // lateral excursion. The hand and elbow X coordinates therefore move
            // monotonically toward the approved two-hand grip, while this smooth
            // zero-endpoint depth arc supplies the required chest clearance.
            float leftClearanceEnvelope = Mathf.Sin(blend * Mathf.PI);
            leftClearanceEnvelope *= leftClearanceEnvelope;
            Vector3 leftHandClearanceOffset =
                Vector3.forward * (leftClearanceEnvelope * 0.055f);
            Vector3 leftElbowClearanceOffset =
                Vector3.forward * (leftClearanceEnvelope * 0.095f) +
                Vector3.up * (leftClearanceEnvelope * 0.015f);
            SolveThrustModeEnterTwoBoneWithElbowRootX(
                root,
                leftArm,
                leftForeArm,
                leftHand,
                root.TransformPoint(
                    Vector3.Lerp(startLeftHandLocal, endLeftHandLocal, eased) +
                    leftHandClearanceOffset),
                root.TransformPoint(
                    Vector3.Lerp(startLeftElbowLocal, endLeftElbowLocal, eased) +
                    leftElbowClearanceOffset),
                Mathf.Lerp(startLeftElbowLocal.x, endLeftElbowLocal.x, eased),
                "left arm clearance arc");
        }

        private static void SolveThrustModeEnterTwoBoneWithElbowRootX(
            Transform root,
            Transform upperArm,
            Transform foreArm,
            Transform hand,
            Vector3 target,
            Vector3 preferredPole,
            float desiredElbowRootX,
            string label)
        {
            Vector3 shoulder = upperArm.position;
            float upperLength = Vector3.Distance(shoulder, foreArm.position);
            float lowerLength = Vector3.Distance(foreArm.position, hand.position);
            if (upperLength <= 0.0001f || lowerLength <= 0.0001f)
                throw new InvalidOperationException(
                    "Thrust-mode-enter " + label + " has a degenerate bone length.");
            Vector3 targetOffset = target - shoulder;
            float targetDistance = Mathf.Clamp(
                targetOffset.magnitude,
                Mathf.Abs(upperLength - lowerLength) + 0.0005f,
                upperLength + lowerLength - 0.0005f);
            Vector3 direction = targetOffset.normalized;
            if (direction.sqrMagnitude < 0.99f)
                throw new InvalidOperationException(
                    "Thrust-mode-enter " + label + " target direction is degenerate.");
            target = shoulder + direction * targetDistance;

            float elbowAlong = (
                upperLength * upperLength +
                targetDistance * targetDistance -
                lowerLength * lowerLength) / (2f * targetDistance);
            float elbowOffset = Mathf.Sqrt(Mathf.Max(
                0f, upperLength * upperLength - elbowAlong * elbowAlong));
            Vector3 elbowCenter = shoulder + direction * elbowAlong;
            Vector3 preferredDirection = Vector3.ProjectOnPlane(
                preferredPole - elbowCenter, direction).normalized;
            if (preferredDirection.sqrMagnitude < 0.5f)
                preferredDirection = Vector3.ProjectOnPlane(
                    root.forward, direction).normalized;
            if (preferredDirection.sqrMagnitude < 0.5f)
                preferredDirection = Vector3.ProjectOnPlane(
                    root.up, direction).normalized;

            Vector3 basisA = Vector3.ProjectOnPlane(
                root.right, direction).normalized;
            if (basisA.sqrMagnitude < 0.5f)
                basisA = Vector3.ProjectOnPlane(root.up, direction).normalized;
            Vector3 basisB = Vector3.Cross(direction, basisA).normalized;
            float coefficientA = root.InverseTransformVector(
                basisA * elbowOffset).x;
            float coefficientB = root.InverseTransformVector(
                basisB * elbowOffset).x;
            float requestedOffset = desiredElbowRootX -
                root.InverseTransformPoint(elbowCenter).x;
            float amplitude = Mathf.Sqrt(
                coefficientA * coefficientA + coefficientB * coefficientB);
            Vector3 elbowDirection = preferredDirection;
            if (amplitude > 0.000001f)
            {
                float phase = Mathf.Atan2(coefficientB, coefficientA);
                float delta = Mathf.Acos(Mathf.Clamp(
                    requestedOffset / amplitude, -1f, 1f));
                Vector3 optionA = basisA * Mathf.Cos(phase + delta) +
                    basisB * Mathf.Sin(phase + delta);
                Vector3 optionB = basisA * Mathf.Cos(phase - delta) +
                    basisB * Mathf.Sin(phase - delta);
                elbowDirection = Vector3.Dot(optionA, preferredDirection) >=
                    Vector3.Dot(optionB, preferredDirection)
                    ? optionA.normalized
                    : optionB.normalized;
            }
            Vector3 elbowTarget = elbowCenter + elbowDirection * elbowOffset;
            upperArm.rotation = Quaternion.FromToRotation(
                foreArm.position - upperArm.position,
                elbowTarget - upperArm.position) * upperArm.rotation;
            foreArm.rotation = Quaternion.FromToRotation(
                hand.position - foreArm.position,
                target - foreArm.position) * foreArm.rotation;
            if (Vector3.Distance(hand.position, target) > 0.002f)
                throw new InvalidOperationException(
                    "Thrust-mode-enter " + label +
                    " constrained IK did not reach its grip target. error=" +
                    Num(Vector3.Distance(hand.position, target)) + ".");
        }

        private static void ApplyThrustModeEnterPose(
            Transform root,
            IReadOnlyDictionary<string, DiagonalSlashLocalPose> pose)
        {
            foreach (KeyValuePair<string, DiagonalSlashLocalPose> item in pose)
            {
                Transform bone = RequirePoseProbeBone(root, item.Key);
                bone.localPosition = item.Value.Position;
                bone.localRotation = item.Value.Rotation;
                bone.localScale = item.Value.Scale;
            }
        }

        private static void ApplyThrustModeEnterInterpolatedPose(
            Transform root,
            IReadOnlyDictionary<string, DiagonalSlashLocalPose> from,
            IReadOnlyDictionary<string, DiagonalSlashLocalPose> to,
            float blend)
        {
            foreach (string path in from.Keys)
            {
                DiagonalSlashLocalPose a = from[path];
                DiagonalSlashLocalPose b = to[path];
                Transform bone = RequirePoseProbeBone(root, path);
                bone.localPosition = Vector3.Lerp(a.Position, b.Position, blend);
                bone.localRotation = Quaternion.Slerp(a.Rotation, b.Rotation, blend);
                bone.localScale = Vector3.Lerp(a.Scale, b.Scale, blend);
            }
        }

        private static AnimatorController CreateOrUpdateThrustModeEnterController(
            AnimationClip cycle)
        {
            AnimatorController controller =
                AssetDatabase.LoadAssetAtPath<AnimatorController>(
                    ThrustModeEnterControllerPath);
            if (controller == null)
                controller = AnimatorController.CreateAnimatorControllerAtPath(
                    ThrustModeEnterControllerPath);
            while (controller.layers.Length > 1)
                controller.RemoveLayer(controller.layers.Length - 1);
            if (controller.layers.Length != 1)
                throw new InvalidOperationException(
                    "Lightsaber_ThrustMode_Enter controller must contain one layer.");
            AnimatorControllerLayer layer = controller.layers[0];
            AnimatorStateMachine stateMachine = layer.stateMachine;
            foreach (AnimatorState state in stateMachine.states
                .Select(item => item.state).ToArray())
                stateMachine.RemoveState(state);
            foreach (AnimatorStateMachine nested in stateMachine.stateMachines
                .Select(item => item.stateMachine).ToArray())
                stateMachine.RemoveStateMachine(nested);
            controller.parameters = Array.Empty<AnimatorControllerParameter>();
            layer.name = "Lightsaber Thrust Mode Enter Sequence";
            layer.defaultWeight = 1f;
            layer.blendingMode = AnimatorLayerBlendingMode.Override;
            layer.avatarMask = null;
            AnimatorState cycleState =
                stateMachine.AddState(ThrustModeEnterStateName);
            cycleState.motion = cycle;
            cycleState.speed = 1f;
            cycleState.cycleOffset = 0f;
            cycleState.mirror = false;
            cycleState.writeDefaultValues = false;
            stateMachine.defaultState = cycleState;
            controller.layers = new[] { layer };
            EditorUtility.SetDirty(stateMachine);
            EditorUtility.SetDirty(controller);
            return controller;
        }

        private static void InspectLightsaberThrustModeEnterTransitionInternal(
            Scene scene,
            bool requireCleanScene)
        {
            if (requireCleanScene && scene.isDirty)
                throw new InvalidOperationException(
                    "Lightsaber_ThrustMode_Enter inspection requires a clean scene.");
            string supplied = Absolute(ThrustModeEnterSourceRelativePath);
            string copied = Absolute(ThrustModeEnterSourcePath);
            if (!File.Exists(supplied) || !File.Exists(copied))
                throw new InvalidOperationException(
                    "Thrust-mode-enter source copy is incomplete.");
            RequireEqual(Sha256File(supplied), Sha256File(copied),
                "thrust-mode-enter FBX binary copy");
            RequireThrustModeEnterImporter();
            AnimationClip source = RequireSingleThrustModeEnterClip();
            AnimationClip cycle = RequireDiagonalSlashAsset<AnimationClip>(
                ThrustModeEnterCycleClipPath);
            RequireThrustModeEnterCycleClip(cycle);

            GameObject target = FindUnique(scene, ThrustModeEnterTargetName);
            Animator animator = target.GetComponent<Animator>() ??
                throw new InvalidOperationException(
                    ThrustModeEnterTargetName + " Animator is missing.");
            if (animator.avatar == null)
                throw new InvalidOperationException(
                    ThrustModeEnterTargetName + " Avatar is missing.");
            RequireThrustModeEnterBindingCompatibility(target.transform, source);
            Transform hand = RequireRightHand(target);
            Transform prop = RequireLightsaberProp(hand, target.name);
            RequireAuthoredPropTransform(prop, target.name);
            Dictionary<string, DiagonalSlashLocalPose> currentPose =
                CaptureDiagonalSlashPose(target.transform, prop);
            Dictionary<string, DiagonalSlashLocalPose> sourceFirst =
                SampleDiagonalSlashPose(target, prop, source, 0f, currentPose);
            Dictionary<string, DiagonalSlashLocalPose> correctedDestination =
                CreateCorrectedThrustModeEnterDestination(currentPose, sourceFirst);
            RequireCorrectedThrustModeEnterDestination(
                currentPose, sourceFirst, correctedDestination);
            RequireThrustModeEnterPropTiltCurves(cycle, correctedDestination);
            RequireDiagonalSlashPoseEqual(
                currentPose,
                SampleDiagonalSlashPose(target, prop, cycle, 0f, currentPose),
                "ThrustModeEnter cycle start/current pose");
            RequireDiagonalSlashPoseEqual(
                correctedDestination,
                SampleDiagonalSlashPose(
                    target, prop, cycle,
                    ThrustModeEnterTransitionSeconds, currentPose),
                "ThrustModeEnter transition end/corrected two-hand pose");
            RequireDiagonalSlashPoseEqual(
                correctedDestination,
                SampleDiagonalSlashPose(
                    target, prop, cycle,
                    ThrustModeEnterTransitionSeconds +
                    ThrustModeEnterHoldSeconds * 0.5f,
                    currentPose),
                "ThrustModeEnter hold midpoint");
            ThrustModeEnterFootPlantMetrics cycleFeet =
                MeasureThrustModeEnterFootPlant(currentPose, cycle);
            cycleFeet.RequireWithinTolerance("the complete one-second cycle");

            AnimatorController controller = animator.runtimeAnimatorController as
                AnimatorController ?? throw new InvalidOperationException(
                    "Lightsaber_ThrustMode_Enter controller is missing.");
            if (AssetDatabase.GetAssetPath(controller) !=
                    ThrustModeEnterControllerPath ||
                animator.applyRootMotion || !animator.enabled ||
                animator.cullingMode != AnimatorCullingMode.AlwaysAnimate)
                throw new InvalidOperationException(
                    "Lightsaber_ThrustMode_Enter Animator settings differ.");
            if (controller.layers.Length != 1 ||
                controller.parameters.Length != 0)
                throw new InvalidOperationException(
                    "Lightsaber_ThrustMode_Enter controller structure differs.");
            AnimatorControllerLayer layer = controller.layers[0];
            if (layer.avatarMask != null ||
                layer.blendingMode != AnimatorLayerBlendingMode.Override ||
                !Mathf.Approximately(layer.defaultWeight, 1f) ||
                layer.stateMachine.stateMachines.Length != 0)
                throw new InvalidOperationException(
                    "Lightsaber_ThrustMode_Enter layer settings differ.");
            AnimatorState[] states = layer.stateMachine.states
                .Select(item => item.state).ToArray();
            if (states.Length != 1)
                throw new InvalidOperationException(
                    "Lightsaber_ThrustMode_Enter state count differs.");
            AnimatorState state = states[0];
            if (state.name != ThrustModeEnterStateName || state.motion != cycle ||
                !Mathf.Approximately(state.speed, 1f) || state.mirror ||
                state.writeDefaultValues || state.behaviours.Length != 0 ||
                state.transitions.Length != 0 ||
                layer.stateMachine.defaultState != state)
                throw new InvalidOperationException(
                    "Lightsaber_ThrustMode_Enter state settings differ.");
        }

        private static void RequireThrustModeEnterCycleClip(AnimationClip clip)
        {
            float duration =
                ThrustModeEnterTransitionSeconds + ThrustModeEnterHoldSeconds;
            if (Mathf.Abs(clip.length - duration) > 0.0001f ||
                Mathf.Abs(clip.frameRate - 60f) > 0.0001f || !clip.isLooping)
                throw new InvalidOperationException(
                    "Lightsaber_ThrustMode_Enter cycle duration or loop differs.");
            foreach (EditorCurveBinding binding in
                AnimationUtility.GetCurveBindings(clip))
            {
                AnimationCurve curve = AnimationUtility.GetEditorCurve(clip, binding);
                int expectedCount = ThrustModeEnterTransitionFrameCount + 3;
                int transitionEnd = ThrustModeEnterTransitionFrameCount;
                int holdStart = transitionEnd + 1;
                int holdEnd = transitionEnd + 2;
                if (curve == null || curve.keys.Length != expectedCount ||
                    Enumerable.Range(0, transitionEnd + 1).Any(index =>
                        Mathf.Abs(curve.keys[index].time - index / 60f) > 0.0001f) ||
                    Mathf.Abs(curve.keys[holdStart].time -
                        (ThrustModeEnterTransitionSeconds + 0.0001f)) > 0.00001f ||
                    Mathf.Abs(curve.keys[holdEnd].time - duration) > 0.0001f ||
                    Mathf.Abs(curve.keys[transitionEnd].value -
                        curve.keys[holdStart].value) > 0.0001f ||
                    Mathf.Abs(curve.keys[holdStart].value -
                        curve.keys[holdEnd].value) > 0.0001f)
                    throw new InvalidOperationException(
                        "Lightsaber_ThrustMode_Enter baked key timing or hold value " +
                        "differs at " +
                        binding.path + "/" + binding.propertyName + ".");
            }
        }

        private static AnimationClip CreateOrUpdateThrustModeExitCycleClip(
            AnimationClip enter)
        {
            RequireThrustModeEnterCycleClip(enter);
            if (AnimationUtility.GetObjectReferenceCurveBindings(enter).Length != 0)
                throw new InvalidOperationException(
                    "Lightsaber_ThrustMode_Enter unexpectedly contains object curves.");
            float duration = ThrustModeExitReverseSeconds + ThrustModeExitHoldSeconds;
            var generated = new AnimationClip
            {
                name = "LightsaberThrustModeExit_EnterReverse_OffIdleHold_1_0s",
                frameRate = 60f,
                legacy = false,
                wrapMode = WrapMode.Loop
            };
            foreach (EditorCurveBinding binding in
                AnimationUtility.GetCurveBindings(enter))
            {
                AnimationCurve source = AnimationUtility.GetEditorCurve(enter, binding);
                if (source == null || source.keys.Length !=
                    ThrustModeEnterTransitionFrameCount + 3)
                    throw new InvalidOperationException(
                        "Enter curve structure differs at " + binding.path + "/" +
                        binding.propertyName + ".");
                var values = new float[ThrustModeEnterTransitionFrameCount + 1];
                for (int index = 0; index < values.Length; index++)
                    values[index] =
                        source.keys[ThrustModeEnterTransitionFrameCount - index].value;
                SetThrustModeExitCycleCurve(generated, binding, values, duration);
            }
            generated.EnsureQuaternionContinuity();
            FlattenThrustModeEnterHoldTangents(generated);
            AnimationClipSettings settings =
                AnimationUtility.GetAnimationClipSettings(generated);
            settings.loopTime = true;
            settings.loopBlend = false;
            AnimationUtility.SetAnimationClipSettings(generated, settings);
            AnimationClip clip = AssetDatabase.LoadAssetAtPath<AnimationClip>(
                ThrustModeExitCycleClipPath);
            if (clip == null)
            {
                AssetDatabase.CreateAsset(generated, ThrustModeExitCycleClipPath);
                clip = generated;
            }
            else
            {
                EditorUtility.CopySerialized(generated, clip);
                clip.name = generated.name;
                EditorUtility.SetDirty(clip);
                UnityEngine.Object.DestroyImmediate(generated);
            }
            RequireThrustModeExitCycleClip(enter, clip);
            return clip;
        }

        private static void SetThrustModeExitCycleCurve(
            AnimationClip clip,
            EditorCurveBinding binding,
            IReadOnlyList<float> reverseValues,
            float duration)
        {
            if (reverseValues.Count != ThrustModeEnterTransitionFrameCount + 1)
                throw new InvalidOperationException(
                    "Thrust-mode-exit reverse sample count differs.");
            var keys = new List<Keyframe>(reverseValues.Count + 2);
            for (int index = 0; index < reverseValues.Count; index++)
                keys.Add(new Keyframe(index / 60f, reverseValues[index], 0f, 0f));
            float offIdleValue = reverseValues[reverseValues.Count - 1];
            keys.Add(new Keyframe(
                ThrustModeExitReverseSeconds + 0.0001f,
                offIdleValue,
                0f,
                0f));
            keys.Add(new Keyframe(duration, offIdleValue, 0f, 0f));
            var curve = new AnimationCurve(keys.ToArray())
            {
                preWrapMode = WrapMode.ClampForever,
                postWrapMode = WrapMode.ClampForever
            };
            AnimationUtility.SetEditorCurve(clip, binding, curve);
        }

