        private static void InspectLightsaberThrustModeExitSequenceInternal(
            Scene scene,
            bool requireCleanScene)
        {
            if (requireCleanScene && scene.isDirty)
                throw new InvalidOperationException(
                    "Lightsaber_ThrustMode_Exit inspection requires a clean scene.");
            InspectLightsaberThrustModeEnterTransitionInternal(scene, false);
            AnimationClip enter = RequireDiagonalSlashAsset<AnimationClip>(
                ThrustModeEnterCycleClipPath);
            AnimationClip exit = RequireDiagonalSlashAsset<AnimationClip>(
                ThrustModeExitCycleClipPath);
            RequireThrustModeExitCycleClip(enter, exit);

            GameObject target = FindUnique(scene, ThrustModeExitTargetName);
            Animator animator = target.GetComponent<Animator>() ??
                throw new InvalidOperationException(
                    ThrustModeExitTargetName + " Animator is missing.");
            if (animator.avatar == null)
                throw new InvalidOperationException(
                    ThrustModeExitTargetName + " Avatar is missing.");
            Transform prop = RequireLightsaberProp(
                RequireRightHand(target), target.name);
            RequireAuthoredPropTransform(prop, target.name);
            Dictionary<string, DiagonalSlashLocalPose> restorePose =
                CaptureDiagonalSlashPose(target.transform, prop);
            Dictionary<string, DiagonalSlashLocalPose> enterGather =
                SampleDiagonalSlashPose(
                    target, prop, enter, ThrustModeEnterTransitionSeconds,
                    restorePose);
            Dictionary<string, DiagonalSlashLocalPose> enterStart =
                SampleDiagonalSlashPose(target, prop, enter, 0f, restorePose);
            RequireDiagonalSlashPoseEqual(
                enterGather,
                SampleDiagonalSlashPose(target, prop, exit, 0f, restorePose),
                "ThrustModeExit start/Enter gather pose");
            RequireDiagonalSlashPoseEqual(
                enterStart,
                SampleDiagonalSlashPose(
                    target, prop, exit, ThrustModeExitReverseSeconds, restorePose),
                "ThrustModeExit reverse end/Enter start pose");
            RequireDiagonalSlashPoseEqual(
                enterStart,
                SampleDiagonalSlashPose(
                    target, prop, exit,
                    ThrustModeExitReverseSeconds +
                    ThrustModeExitHoldSeconds * 0.5f,
                    restorePose),
                "ThrustModeExit Off Idle hold midpoint");

            AnimationClip offIdle = RequireDiagonalSlashAsset<AnimationClip>(
                LocomotionIdleClipPath);
            RequireDiagonalSlashPoseEqual(
                enterStart,
                SampleDiagonalSlashPose(target, prop, offIdle, 0f, restorePose),
                "ThrustModeExit destination/Lightsaber_Off_Idle pose");

            AnimatorController controller = animator.runtimeAnimatorController as
                AnimatorController ?? throw new InvalidOperationException(
                    "Lightsaber_ThrustMode_Exit controller is missing.");
            if (AssetDatabase.GetAssetPath(controller) !=
                    ThrustModeExitControllerPath ||
                animator.applyRootMotion || !animator.enabled ||
                animator.cullingMode != AnimatorCullingMode.AlwaysAnimate)
                throw new InvalidOperationException(
                    "Lightsaber_ThrustMode_Exit Animator settings differ.");
            if (controller.layers.Length != 1 || controller.parameters.Length != 0)
                throw new InvalidOperationException(
                    "Lightsaber_ThrustMode_Exit controller structure differs.");
            AnimatorControllerLayer layer = controller.layers[0];
            AnimatorState[] states = layer.stateMachine.states
                .Select(item => item.state).ToArray();
            if (layer.avatarMask != null ||
                layer.blendingMode != AnimatorLayerBlendingMode.Override ||
                !Mathf.Approximately(layer.defaultWeight, 1f) ||
                layer.stateMachine.stateMachines.Length != 0 ||
                states.Length != 1)
                throw new InvalidOperationException(
                    "Lightsaber_ThrustMode_Exit layer settings differ.");
            AnimatorState state = states[0];
            if (state.name != ThrustModeExitStateName || state.motion != exit ||
                !Mathf.Approximately(state.speed, 1f) || state.mirror ||
                state.writeDefaultValues || state.behaviours.Length != 0 ||
                state.transitions.Length != 0 ||
                layer.stateMachine.defaultState != state)
                throw new InvalidOperationException(
                    "Lightsaber_ThrustMode_Exit state settings differ.");
        }

        private static void RequireThrustModeExitCycleClip(
            AnimationClip enter,
            AnimationClip exit)
        {
            RequireThrustModeEnterCycleClip(enter);
            float duration = ThrustModeExitReverseSeconds + ThrustModeExitHoldSeconds;
            if (Mathf.Abs(exit.length - duration) > 0.0001f ||
                Mathf.Abs(exit.frameRate - 60f) > 0.0001f || !exit.isLooping)
                throw new InvalidOperationException(
                    "Lightsaber_ThrustMode_Exit cycle duration or loop differs.");
            EditorCurveBinding[] enterBindings =
                AnimationUtility.GetCurveBindings(enter)
                    .OrderBy(item => item.path, StringComparer.Ordinal)
                    .ThenBy(item => item.propertyName, StringComparer.Ordinal)
                    .ToArray();
            EditorCurveBinding[] exitBindings =
                AnimationUtility.GetCurveBindings(exit)
                    .OrderBy(item => item.path, StringComparer.Ordinal)
                    .ThenBy(item => item.propertyName, StringComparer.Ordinal)
                    .ToArray();
            if (enterBindings.Length != exitBindings.Length)
                throw new InvalidOperationException(
                    "Lightsaber_ThrustMode_Exit binding count differs from Enter.");
            for (int bindingIndex = 0;
                bindingIndex < enterBindings.Length;
                bindingIndex++)
            {
                EditorCurveBinding sourceBinding = enterBindings[bindingIndex];
                EditorCurveBinding targetBinding = exitBindings[bindingIndex];
                if (sourceBinding.path != targetBinding.path ||
                    sourceBinding.propertyName != targetBinding.propertyName ||
                    sourceBinding.type != targetBinding.type)
                    throw new InvalidOperationException(
                        "Lightsaber_ThrustMode_Exit binding differs from Enter.");
                AnimationCurve source =
                    AnimationUtility.GetEditorCurve(enter, sourceBinding);
                AnimationCurve target =
                    AnimationUtility.GetEditorCurve(exit, targetBinding);
                int expectedCount = ThrustModeEnterTransitionFrameCount + 3;
                if (source == null || target == null ||
                    target.keys.Length != expectedCount)
                    throw new InvalidOperationException(
                        "Lightsaber_ThrustMode_Exit curve structure differs at " +
                        targetBinding.path + "/" + targetBinding.propertyName + ".");
                for (int index = 0;
                    index <= ThrustModeEnterTransitionFrameCount;
                    index++)
                {
                    Keyframe key = target.keys[index];
                    float expectedValue = source.keys[
                        ThrustModeEnterTransitionFrameCount - index].value;
                    if (Mathf.Abs(key.time - index / 60f) > 0.0001f ||
                        Mathf.Abs(key.value - expectedValue) > 0.000001f)
                        throw new InvalidOperationException(
                            "Lightsaber_ThrustMode_Exit is not the exact baked reverse at " +
                            targetBinding.path + "/" + targetBinding.propertyName +
                            " frame " + index + ".");
                }
                int holdStart = ThrustModeEnterTransitionFrameCount + 1;
                int holdEnd = holdStart + 1;
                float offIdleValue = source.keys[0].value;
                if (Mathf.Abs(target.keys[holdStart].time -
                        (ThrustModeExitReverseSeconds + 0.0001f)) > 0.00001f ||
                    Mathf.Abs(target.keys[holdEnd].time - duration) > 0.0001f ||
                    Mathf.Abs(target.keys[holdStart].value - offIdleValue) >
                        0.000001f ||
                    Mathf.Abs(target.keys[holdEnd].value - offIdleValue) >
                        0.000001f)
                    throw new InvalidOperationException(
                        "Lightsaber_ThrustMode_Exit Off Idle hold differs at " +
                        targetBinding.path + "/" + targetBinding.propertyName + ".");
            }
            if (AnimationUtility.GetObjectReferenceCurveBindings(exit).Length != 0)
                throw new InvalidOperationException(
                    "Lightsaber_ThrustMode_Exit unexpectedly contains object curves.");
        }

        private static Dictionary<string, DiagonalSlashLocalPose>
            CreateCorrectedThrustModeEnterDestination(
                IReadOnlyDictionary<string, DiagonalSlashLocalPose> currentPose,
                IReadOnlyDictionary<string, DiagonalSlashLocalPose> sourceFirst)
        {
            RequireGripOneHandPosePathSets(currentPose, sourceFirst);
            ThrustModeEnterPoseMetrics straightBaselineMetrics =
                MeasureThrustModeEnterPose(
                    CreateThrustModeEnterPriorStraightDestination(
                        currentPose, sourceFirst));
            Scene previewScene = EditorSceneManager.NewPreviewScene();
            GameObject probe = null;
            try
            {
                probe = CreateThrustModeEnterPoseProbe(
                    previewScene, sourceFirst, out Transform prop);
                Transform root = probe.transform;
                GameObject currentProbe = CreateThrustModeEnterPoseProbe(
                    previewScene, currentPose, out _);
                ThrustModeEnterFootReferences feet =
                    CaptureThrustModeEnterFootReferences(currentProbe.transform);
                UnityEngine.Object.DestroyImmediate(currentProbe);

                ApplyThrustModeEnterTenDegreeKneePose(
                    root,
                    currentPose,
                    sourceFirst,
                    feet,
                    straightBaselineMetrics.LeftKneeBendDegrees +
                        ThrustModeEnterTargetKneeBendDegrees,
                    straightBaselineMetrics.RightKneeBendDegrees +
                        ThrustModeEnterTargetKneeBendDegrees);

                Transform rightArm = RequirePoseProbeBone(root, RightArmPath);
                Transform rightForeArm = RequirePoseProbeBone(root, RightForeArmPath);
                Transform rightHand = RequirePoseProbeBone(root, RightHandPath);
                float rightReach = Vector3.Distance(
                    rightArm.position, rightForeArm.position) +
                    Vector3.Distance(rightForeArm.position, rightHand.position);
                Vector3 rightHandTarget =
                    rightArm.position +
                    root.forward * (rightReach * 0.02f) +
                    root.right * (rightReach * 0.28f) +
                    root.up * (rightReach * -0.33f);
                SolveThrustModeEnterTwoBone(
                    rightArm,
                    rightForeArm,
                    rightHand,
                    rightHandTarget,
                    rightArm.position +
                    root.right * (rightReach * 0.65f) +
                    root.forward * (rightReach * 0.22f) -
                    root.up * (rightReach * 0.18f),
                    "right arm");

                Vector3 bladeAxisLocal = DiagonalSlashBladeAxisLocal();
                Quaternion bladeCorrection = Quaternion.FromToRotation(
                    prop.TransformDirection(bladeAxisLocal), root.forward);
                rightHand.rotation = bladeCorrection * rightHand.rotation;

                Transform leftArm = RequirePoseProbeBone(root, LeftArmPath);
                Transform leftForeArm = RequirePoseProbeBone(root, LeftForeArmPath);
                Transform leftHand = RequirePoseProbeBone(root, LeftHandPath);
                float leftReach = Vector3.Distance(leftArm.position, leftForeArm.position) +
                    Vector3.Distance(leftForeArm.position, leftHand.position);
                Vector3 leftHandTarget =
                    rightHand.position -
                    root.forward * ThrustModeEnterRearHandSpacingMeters -
                    root.up * ThrustModeEnterRearHandDropMeters;
                SolveThrustModeEnterTwoBone(
                    leftArm,
                    leftForeArm,
                    leftHand,
                    leftHandTarget,
                    leftArm.position +
                    root.forward * (leftReach * 0.55f) +
                    root.right * (leftReach * 0.42f) -
                    root.up * (leftReach * 0.22f),
                    "left arm");
                AlignThrustModeEnterLeftPalm(
                    leftForeArm, leftHand, root.forward);

                ApplyThrustModeEnterFootPlant(root, currentPose, feet);

                return CaptureDiagonalSlashPose(root, prop);
            }
            finally
            {
                if (probe != null) UnityEngine.Object.DestroyImmediate(probe);
                EditorSceneManager.ClosePreviewScene(previewScene);
            }
        }

        private static Dictionary<string, DiagonalSlashLocalPose>
            CreateThrustModeEnterPriorStraightDestination(
                IReadOnlyDictionary<string, DiagonalSlashLocalPose> currentPose,
                IReadOnlyDictionary<string, DiagonalSlashLocalPose> sourceFirst)
        {
            Scene previewScene = EditorSceneManager.NewPreviewScene();
            GameObject probe = null;
            try
            {
                probe = CreateThrustModeEnterPoseProbe(
                    previewScene, sourceFirst, out Transform prop);
                GameObject currentProbe = CreateThrustModeEnterPoseProbe(
                    previewScene, currentPose, out _);
                ThrustModeEnterFootReferences feet =
                    CaptureThrustModeEnterFootReferences(currentProbe.transform);
                UnityEngine.Object.DestroyImmediate(currentProbe);
                float previousHipsY = Mathf.Lerp(
                    currentPose[HipsPath].Position.y,
                    sourceFirst[HipsPath].Position.y,
                    0.5f);
                ResetThrustModeEnterKneeProbe(
                    probe.transform, currentPose, sourceFirst, previousHipsY);
                ApplyThrustModeEnterFootPlant(
                    probe.transform, currentPose, feet);
                return CaptureDiagonalSlashPose(probe.transform, prop);
            }
            finally
            {
                if (probe != null) UnityEngine.Object.DestroyImmediate(probe);
                EditorSceneManager.ClosePreviewScene(previewScene);
            }
        }

        private static GameObject CreateThrustModeEnterPoseProbe(
            Scene previewScene,
            IReadOnlyDictionary<string, DiagonalSlashLocalPose> pose,
            out Transform prop)
        {
            var probe = new GameObject("LightsaberThrustModeEnterPoseProbe")
            {
                hideFlags = HideFlags.HideAndDontSave
            };
            SceneManager.MoveGameObjectToScene(probe, previewScene);
            var nodes = new Dictionary<string, Transform>(StringComparer.Ordinal)
            {
                [string.Empty] = probe.transform
            };
            foreach (KeyValuePair<string, DiagonalSlashLocalPose> item in pose
                .OrderBy(entry => entry.Key.Count(character => character == '/'))
                .ThenBy(entry => entry.Key, StringComparer.Ordinal))
            {
                int separator = item.Key.LastIndexOf('/');
                string parentPath = separator < 0
                    ? string.Empty
                    : item.Key.Substring(0, separator);
                string name = separator < 0
                    ? item.Key
                    : item.Key.Substring(separator + 1);
                if (!nodes.TryGetValue(parentPath, out Transform parent))
                    throw new InvalidOperationException(
                        "Thrust pose-probe parent path is missing: " + parentPath);
                Transform node = new GameObject(name).transform;
                node.SetParent(parent, false);
                node.localPosition = item.Value.Position;
                node.localRotation = item.Value.Rotation;
                node.localScale = item.Value.Scale;
                nodes.Add(item.Key, node);
            }

            Transform hand = RequirePoseProbeBone(probe.transform, RightHandPath);
            prop = new GameObject(PropName).transform;
            prop.SetParent(hand, false);
            prop.localPosition = AuthoredPropLocalPosition;
            prop.localRotation = AuthoredPropLocalRotation;
            prop.localScale = AuthoredPropLocalScale;
            return probe;
        }

        private static Transform RequirePoseProbeBone(Transform root, string path)
        {
            return root.Find(path) ?? throw new InvalidOperationException(
                "Thrust pose-probe bone is missing: " + path);
        }

        private static ThrustModeEnterFootReferences
            CaptureThrustModeEnterFootReferences(Transform root)
        {
            Transform leftUpLeg = RequirePoseProbeBone(root, LeftUpLegPath);
            Transform leftLeg = RequirePoseProbeBone(root, LeftLegPath);
            Transform leftFoot = RequirePoseProbeBone(root, LeftFootPath);
            Transform rightUpLeg = RequirePoseProbeBone(root, RightUpLegPath);
            Transform rightLeg = RequirePoseProbeBone(root, RightLegPath);
            Transform rightFoot = RequirePoseProbeBone(root, RightFootPath);
            return new ThrustModeEnterFootReferences(
                root.InverseTransformPoint(leftFoot.position),
                Quaternion.Inverse(root.rotation) * leftFoot.rotation,
                CreateThrustModeEnterKneePoleLocal(
                    root, leftUpLeg, leftLeg, leftFoot, -1f),
                root.InverseTransformPoint(rightFoot.position),
                Quaternion.Inverse(root.rotation) * rightFoot.rotation,
                CreateThrustModeEnterKneePoleLocal(
                    root, rightUpLeg, rightLeg, rightFoot, 1f));
        }

        private static Vector3 CreateThrustModeEnterKneePoleLocal(
            Transform root,
            Transform upLeg,
            Transform leg,
            Transform foot,
            float side)
        {
            float reach = Vector3.Distance(upLeg.position, leg.position) +
                Vector3.Distance(leg.position, foot.position);
            Vector3 legAxis = (foot.position - upLeg.position).normalized;
            Vector3 currentBend = Vector3.ProjectOnPlane(
                leg.position - upLeg.position, legAxis).normalized;
            if (currentBend.sqrMagnitude < 0.5f)
                currentBend = root.forward;
            Vector3 poleDirection = (
                currentBend * 0.45f +
                root.forward * 0.82f +
                root.right * (side * 0.08f)).normalized;
            return root.InverseTransformPoint(
                upLeg.position + poleDirection * reach);
        }

        private static void ApplyThrustModeEnterFootPlant(
            Transform root,
            IReadOnlyDictionary<string, DiagonalSlashLocalPose> currentPose,
            ThrustModeEnterFootReferences feet)
        {
            Transform leftUpLeg = RequirePoseProbeBone(root, LeftUpLegPath);
            Transform leftLeg = RequirePoseProbeBone(root, LeftLegPath);
            Transform leftFoot = RequirePoseProbeBone(root, LeftFootPath);
            SolveThrustModeEnterTwoBone(
                leftUpLeg,
                leftLeg,
                leftFoot,
                root.TransformPoint(feet.LeftPosition),
                root.TransformPoint(feet.LeftKneePole),
                "left leg foot plant");
            leftFoot.rotation = root.rotation * feet.LeftRotation;

            Transform rightUpLeg = RequirePoseProbeBone(root, RightUpLegPath);
            Transform rightLeg = RequirePoseProbeBone(root, RightLegPath);
            Transform rightFoot = RequirePoseProbeBone(root, RightFootPath);
            SolveThrustModeEnterTwoBone(
                rightUpLeg,
                rightLeg,
                rightFoot,
                root.TransformPoint(feet.RightPosition),
                root.TransformPoint(feet.RightKneePole),
                "right leg foot plant");
            rightFoot.rotation = root.rotation * feet.RightRotation;

            foreach (string path in currentPose.Keys.Where(path =>
                path.StartsWith(LeftFootPath + "/", StringComparison.Ordinal) ||
                path.StartsWith(RightFootPath + "/", StringComparison.Ordinal)))
                RequirePoseProbeBone(root, path).localRotation =
                    currentPose[path].Rotation;
        }

        private static void ApplyThrustModeEnterTenDegreeKneePose(
            Transform root,
            IReadOnlyDictionary<string, DiagonalSlashLocalPose> currentPose,
            IReadOnlyDictionary<string, DiagonalSlashLocalPose> sourceFirst,
            ThrustModeEnterFootReferences feet,
            float leftTargetBend,
            float rightTargetBend)
        {
            DiagonalSlashLocalPose currentHips = currentPose[HipsPath];
            DiagonalSlashLocalPose sourceHips = sourceFirst[HipsPath];
            float searchTop = Mathf.Max(
                currentHips.Position.y, sourceHips.Position.y) + 0.10f;
            float searchBottom = Mathf.Min(
                currentHips.Position.y, sourceHips.Position.y) - 0.80f;
            float bestY = float.NaN;
            float bestScore = float.PositiveInfinity;
            float bestLeftBend = float.NaN;
            float bestRightBend = float.NaN;
            float bestFootError = float.NaN;
            const int sampleCount = 1200;
            for (int index = 0; index <= sampleCount; index++)
            {
                float candidateY = Mathf.Lerp(
                    searchTop, searchBottom, index / (float)sampleCount);
                ResetThrustModeEnterKneeProbe(
                    root, currentPose, sourceFirst, candidateY);
                ApplyThrustModeEnterFootPlant(root, currentPose, feet);
                float footError = Mathf.Max(
                    Vector3.Distance(
                        RequirePoseProbeBone(root, LeftFootPath).position,
                        root.TransformPoint(feet.LeftPosition)),
                    Vector3.Distance(
                        RequirePoseProbeBone(root, RightFootPath).position,
                        root.TransformPoint(feet.RightPosition)));
                if (footError > ThrustModeEnterFootPositionToleranceMeters)
                    continue;
                MeasureThrustModeEnterKneeBends(
                    root, out float leftBend, out float rightBend);
                float score = Mathf.Max(
                    Mathf.Abs(leftBend - leftTargetBend),
                    Mathf.Abs(rightBend - rightTargetBend));
                if (score >= bestScore) continue;
                bestScore = score;
                bestY = candidateY;
                bestLeftBend = leftBend;
                bestRightBend = rightBend;
                bestFootError = footError;
            }
            Vector3 bestPosition = new Vector3(
                currentHips.Position.x, bestY, currentHips.Position.z);
            float searchStep = 0.25f;
            for (int iteration = 0; iteration < 12; iteration++)
            {
                Vector3 iterationOrigin = bestPosition;
                for (int x = -1; x <= 1; x++)
                for (int y = -1; y <= 1; y++)
                for (int z = -1; z <= 1; z++)
                {
                    Vector3 candidate = iterationOrigin +
                        new Vector3(x, y, z) * searchStep;
                    if (Mathf.Abs(candidate.x - currentHips.Position.x) > 0.35f ||
                        Mathf.Abs(candidate.z - currentHips.Position.z) > 0.35f ||
                        candidate.y > searchTop || candidate.y < searchBottom)
                        continue;
                    ResetThrustModeEnterKneeProbe(
                        root, currentPose, sourceFirst, candidate);
                    ApplyThrustModeEnterFootPlant(root, currentPose, feet);
                    float footError = Mathf.Max(
                        Vector3.Distance(
                            RequirePoseProbeBone(root, LeftFootPath).position,
                            root.TransformPoint(feet.LeftPosition)),
                        Vector3.Distance(
                            RequirePoseProbeBone(root, RightFootPath).position,
                            root.TransformPoint(feet.RightPosition)));
                    if (footError > ThrustModeEnterFootPositionToleranceMeters)
                        continue;
                    MeasureThrustModeEnterKneeBends(
                        root, out float leftBend, out float rightBend);
                    float score = Mathf.Max(
                        Mathf.Abs(leftBend - leftTargetBend),
                        Mathf.Abs(rightBend - rightTargetBend));
                    if (score >= bestScore) continue;
                    bestScore = score;
                    bestPosition = candidate;
                    bestY = candidate.y;
                    bestLeftBend = leftBend;
                    bestRightBend = rightBend;
                    bestFootError = footError;
                }
                searchStep *= 0.5f;
            }
            if (float.IsNaN(bestY) ||
                bestScore > ThrustModeEnterKneeBendToleranceDegrees)
                throw new InvalidOperationException(
                    "Could not solve a planted bilateral ten-degree knee pose. " +
                    "bestDeviation=" + Num(bestScore) +
                    "|leftTarget=" + Num(leftTargetBend) +
                    "|rightTarget=" + Num(rightTargetBend) +
                    "|bestLeft=" + Num(bestLeftBend) +
                    "|bestRight=" + Num(bestRightBend) +
                    "|bestHipsY=" + Num(bestY) +
                    "|bestFootError=" + Num(bestFootError) + ".");
            ResetThrustModeEnterKneeProbe(
                root, currentPose, sourceFirst, bestPosition);
            ApplyThrustModeEnterFootPlant(root, currentPose, feet);
        }

        private static void ResetThrustModeEnterKneeProbe(
            Transform root,
            IReadOnlyDictionary<string, DiagonalSlashLocalPose> currentPose,
            IReadOnlyDictionary<string, DiagonalSlashLocalPose> sourceFirst,
            float hipsY)
        {
            ResetThrustModeEnterKneeProbe(
                root,
                currentPose,
                sourceFirst,
                new Vector3(
                    currentPose[HipsPath].Position.x,
                    hipsY,
                    currentPose[HipsPath].Position.z));
        }

        private static void ResetThrustModeEnterKneeProbe(
            Transform root,
            IReadOnlyDictionary<string, DiagonalSlashLocalPose> currentPose,
            IReadOnlyDictionary<string, DiagonalSlashLocalPose> sourceFirst,
            Vector3 hipsPosition)
        {
            Transform hips = RequirePoseProbeBone(root, HipsPath);
            hips.localPosition = hipsPosition;
            foreach (string path in ThrustModeEnterHalfRotationPaths)
                RequirePoseProbeBone(root, path).localRotation = Quaternion.Slerp(
                    currentPose[path].Rotation,
                    sourceFirst[path].Rotation,
                    0.5f);
        }

        private static void MeasureThrustModeEnterKneeBends(
            Transform root,
            out float leftBend,
            out float rightBend)
        {
            leftBend = MeasureThrustModeEnterKneeBend(
                RequirePoseProbeBone(root, LeftUpLegPath),
                RequirePoseProbeBone(root, LeftLegPath),
                RequirePoseProbeBone(root, LeftFootPath));
            rightBend = MeasureThrustModeEnterKneeBend(
                RequirePoseProbeBone(root, RightUpLegPath),
                RequirePoseProbeBone(root, RightLegPath),
                RequirePoseProbeBone(root, RightFootPath));
        }

        private static float MeasureThrustModeEnterKneeBend(
            Transform upLeg,
            Transform leg,
            Transform foot)
        {
            return Vector3.Angle(
                leg.position - upLeg.position,
                foot.position - leg.position);
        }

        private static void SolveThrustModeEnterTwoBone(
            Transform upperArm,
            Transform foreArm,
            Transform hand,
            Vector3 target,
            Vector3 pole,
            string label)
        {
            Vector3 shoulder = upperArm.position;
            float upperLength = Vector3.Distance(shoulder, foreArm.position);
            float lowerLength = Vector3.Distance(foreArm.position, hand.position);
            if (upperLength <= 0.0001f || lowerLength <= 0.0001f)
                throw new InvalidOperationException(
                    "Thrust-mode-enter " + label + " has a degenerate bone length.");
            Vector3 targetOffset = target - shoulder;
            float targetDistance = Mathf.Clamp(
                targetOffset.magnitude,
                Mathf.Abs(upperLength - lowerLength) + 0.0005f,
                upperLength + lowerLength - 0.0005f);
            Vector3 direction = targetOffset.normalized;
            if (direction.sqrMagnitude < 0.99f)
                throw new InvalidOperationException(
                    "Thrust-mode-enter " + label + " target direction is degenerate.");
            target = shoulder + direction * targetDistance;
            Vector3 poleDirection = Vector3.ProjectOnPlane(
                pole - shoulder, direction).normalized;
            if (poleDirection.sqrMagnitude < 0.5f)
                poleDirection = Vector3.Cross(direction, Vector3.up).normalized;
            if (poleDirection.sqrMagnitude < 0.5f)
                poleDirection = Vector3.Cross(direction, Vector3.right).normalized;

            float elbowAlong = (
                upperLength * upperLength +
                targetDistance * targetDistance -
                lowerLength * lowerLength) / (2f * targetDistance);
            float elbowOffset = Mathf.Sqrt(Mathf.Max(
                0f, upperLength * upperLength - elbowAlong * elbowAlong));
            Vector3 elbowTarget = shoulder +
                direction * elbowAlong + poleDirection * elbowOffset;
            upperArm.rotation = Quaternion.FromToRotation(
                foreArm.position - upperArm.position,
                elbowTarget - upperArm.position) * upperArm.rotation;
            foreArm.rotation = Quaternion.FromToRotation(
                hand.position - foreArm.position,
                target - foreArm.position) * foreArm.rotation;
            if (Vector3.Distance(hand.position, target) > 0.002f)
                throw new InvalidOperationException(
                    "Thrust-mode-enter " + label + " IK did not reach its grip target. " +
                    "error=" + Num(Vector3.Distance(hand.position, target)) + ".");
        }

        private static void AlignThrustModeEnterLeftPalm(
            Transform foreArm,
            Transform hand,
            Vector3 handleAxis)
        {
            Transform index = hand.Find("LeftIndexProximal") ??
                throw new InvalidOperationException(
                    "Thrust-mode-enter LeftIndexProximal is missing.");
            Transform little = hand.Find("LeftLittleProximal") ??
                throw new InvalidOperationException(
                    "Thrust-mode-enter LeftLittleProximal is missing.");
            Vector3 foreArmAxis = (hand.position - foreArm.position).normalized;
            Vector3 currentAcross = Vector3.ProjectOnPlane(
                index.position - little.position, foreArmAxis).normalized;
            Vector3 desiredAcross = Vector3.ProjectOnPlane(
                -handleAxis, foreArmAxis).normalized;
            if (currentAcross.sqrMagnitude < 0.5f || desiredAcross.sqrMagnitude < 0.5f)
                throw new InvalidOperationException(
                    "Thrust-mode-enter left palm alignment is degenerate.");
            float twist = Vector3.SignedAngle(
                currentAcross, desiredAcross, foreArmAxis);
            foreArm.rotation = Quaternion.AngleAxis(
                twist * 0.72f, foreArmAxis) * foreArm.rotation;
            currentAcross = Vector3.ProjectOnPlane(
                index.position - little.position, foreArmAxis).normalized;
            float residual = Vector3.SignedAngle(
                currentAcross, desiredAcross, foreArmAxis);
            hand.rotation = Quaternion.AngleAxis(
                residual, foreArmAxis) * hand.rotation;
        }

        private static ThrustModeEnterPoseMetrics
            RequireCorrectedThrustModeEnterDestination(
                IReadOnlyDictionary<string, DiagonalSlashLocalPose> currentPose,
                IReadOnlyDictionary<string, DiagonalSlashLocalPose> sourceFirst,
                IReadOnlyDictionary<string, DiagonalSlashLocalPose> corrected)
        {
            RequireGripOneHandPosePathSets(currentPose, sourceFirst);
            RequireGripOneHandPosePathSets(sourceFirst, corrected);
            foreach (string path in sourceFirst.Keys)
            {
                DiagonalSlashLocalPose source = sourceFirst[path];
                DiagonalSlashLocalPose actual = corrected[path];
                bool positionChanged = path == HipsPath
                    ? Mathf.Abs(actual.Position.x - currentPose[path].Position.x) > 0.3501f ||
                      Mathf.Abs(actual.Position.z - currentPose[path].Position.z) > 0.3501f ||
                      actual.Position.y > Mathf.Max(
                          currentPose[path].Position.y, source.Position.y) + 0.1001f ||
                      actual.Position.y < Mathf.Min(
                          currentPose[path].Position.y, source.Position.y) - 0.8001f
                    : Vector3.Distance(source.Position, actual.Position) > 0.0001f;
                if (positionChanged ||
                    Vector3.Distance(source.Scale, actual.Scale) > 0.0001f)
                    throw new InvalidOperationException(
                        "Thrust-mode-enter correction changed an unapproved position or " +
                        "scale at " + path + ".");

                bool approvedArmRotation =
                    path == RightArmPath || path.StartsWith(
                        RightArmPath + "/", StringComparison.Ordinal) ||
                    path == LeftArmPath || path.StartsWith(
                        LeftArmPath + "/", StringComparison.Ordinal);
                bool approvedLegRotation =
                    path == LeftUpLegPath || path.StartsWith(
                        LeftUpLegPath + "/", StringComparison.Ordinal) ||
                    path == RightUpLegPath || path.StartsWith(
                        RightUpLegPath + "/", StringComparison.Ordinal);
                if (!approvedArmRotation && !approvedLegRotation &&
                    Quaternion.Angle(source.Rotation, actual.Rotation) > 0.02f)
                    throw new InvalidOperationException(
                        "Thrust-mode-enter correction changed an unapproved rotation at " +
                        path + ".");
            }

            ThrustModeEnterPoseMetrics metrics = MeasureThrustModeEnterPose(corrected);
            ThrustModeEnterPoseMetrics straightBaselineMetrics =
                MeasureThrustModeEnterPose(
                    CreateThrustModeEnterPriorStraightDestination(
                        currentPose, sourceFirst));
            if (metrics.BladeForwardAngleDegrees >
                    ThrustModeEnterBladeForwardToleranceDegrees ||
                metrics.BladeForwardDot <= 0f)
                throw new InvalidOperationException(
                    "Lightsaber blade tip is not facing carrier-forward. angle=" +
                    Num(metrics.BladeForwardAngleDegrees) +
                    "|dot=" + Num(metrics.BladeForwardDot) + ".");
            if (metrics.GripOffsetErrorMeters >
                ThrustModeEnterHandSpacingToleranceMeters)
                throw new InvalidOperationException(
                    "Left hand did not meet the handle below the right hand. error=" +
                    Num(metrics.GripOffsetErrorMeters) + ".");
            if (metrics.RightHandOutsideShoulderMeters <
                    ThrustModeEnterHandOutsideShoulderMeters ||
                metrics.LeftHandOutsideShoulderMeters <
                    ThrustModeEnterHandOutsideShoulderMeters)
                throw new InvalidOperationException(
                    "Both hands must remain outside the carrier-right shoulder. " +
                    "right=" + Num(metrics.RightHandOutsideShoulderMeters) +
                    "|left=" + Num(metrics.LeftHandOutsideShoulderMeters) + ".");
            if (metrics.RightHandBelowShoulderMeters <
                    ThrustModeEnterHandBelowShoulderMeters ||
                metrics.LeftHandBelowShoulderMeters <
                    ThrustModeEnterHandBelowShoulderMeters ||
                metrics.RightHandBelowShoulderMeters >
                    ThrustModeEnterHandMaximumBelowShoulderMeters ||
                metrics.LeftHandBelowShoulderMeters >
                    ThrustModeEnterHandMaximumBelowShoulderMeters)
                throw new InvalidOperationException(
                    "Both hands must remain inside the approved upper red-box height below " +
                    "the carrier-right shoulder. right=" +
                    Num(metrics.RightHandBelowShoulderMeters) +
                    "|left=" + Num(metrics.LeftHandBelowShoulderMeters) + ".");
            if (metrics.BladeHeadClearanceMeters <
                    ThrustModeEnterBladeHeadClearanceMeters ||
                metrics.BladeTorsoClearanceMeters <
                    ThrustModeEnterBladeTorsoClearanceMeters)
                throw new InvalidOperationException(
                    "Lightsaber clearance from the head or torso is insufficient. " +
                    "head=" + Num(metrics.BladeHeadClearanceMeters) +
                    "|torso=" + Num(metrics.BladeTorsoClearanceMeters) + ".");
            if (metrics.RightElbowDegrees < 4f || metrics.RightElbowDegrees > 150f ||
                metrics.LeftElbowDegrees < 4f || metrics.LeftElbowDegrees > 150f)
                throw new InvalidOperationException(
                    "Thrust-mode-enter elbow bend is outside the anatomical review " +
                    "range. right=" + Num(metrics.RightElbowDegrees) +
                    "|left=" + Num(metrics.LeftElbowDegrees) + ".");
            if (Mathf.Abs(
                    metrics.LeftKneeBendDegrees -
                    straightBaselineMetrics.LeftKneeBendDegrees -
                    ThrustModeEnterTargetKneeBendDegrees) >
                    ThrustModeEnterKneeBendToleranceDegrees ||
                Mathf.Abs(
                    metrics.RightKneeBendDegrees -
                    straightBaselineMetrics.RightKneeBendDegrees -
                    ThrustModeEnterTargetKneeBendDegrees) >
                    ThrustModeEnterKneeBendToleranceDegrees)
                throw new InvalidOperationException(
                    "Lightsaber_ThrustMode_Enter knee flexion did not increase by " +
                    "approximately ten degrees from its visually straight start. left=" +
                    Num(metrics.LeftKneeBendDegrees -
                        straightBaselineMetrics.LeftKneeBendDegrees) +
                    "|right=" + Num(metrics.RightKneeBendDegrees -
                        straightBaselineMetrics.RightKneeBendDegrees) + ".");
            ThrustModeEnterFootPlantMetrics feet =
                MeasureThrustModeEnterFootPlant(currentPose, corrected);
            feet.RequireWithinTolerance("corrected destination");
            return metrics;
        }

        private static ThrustModeEnterPoseMetrics MeasureThrustModeEnterPose(
            IReadOnlyDictionary<string, DiagonalSlashLocalPose> pose)
        {
            Scene previewScene = EditorSceneManager.NewPreviewScene();
            GameObject probe = null;
            try
            {
                probe = CreateThrustModeEnterPoseProbe(
                    previewScene, pose, out Transform prop);
                Transform root = probe.transform;
                Transform rightArm = RequirePoseProbeBone(root, RightArmPath);
                Transform rightForeArm = RequirePoseProbeBone(root, RightForeArmPath);
                Transform rightHand = RequirePoseProbeBone(root, RightHandPath);
                Transform leftArm = RequirePoseProbeBone(root, LeftArmPath);
                Transform leftForeArm = RequirePoseProbeBone(root, LeftForeArmPath);
                Transform leftHand = RequirePoseProbeBone(root, LeftHandPath);
                Transform leftShoulder = RequirePoseProbeBone(root, LeftShoulderPath);
                Transform rightShoulder = RequirePoseProbeBone(root, RightShoulderPath);
                Transform hips = RequirePoseProbeBone(root, HipsPath);
                Transform leftUpLeg = RequirePoseProbeBone(root, LeftUpLegPath);
                Transform leftLeg = RequirePoseProbeBone(root, LeftLegPath);
                Transform leftFoot = RequirePoseProbeBone(root, LeftFootPath);
                Transform rightUpLeg = RequirePoseProbeBone(root, RightUpLegPath);
                Transform rightLeg = RequirePoseProbeBone(root, RightLegPath);
                Transform rightFoot = RequirePoseProbeBone(root, RightFootPath);
                Transform head = root.GetComponentsInChildren<Transform>(true)
                    .Single(item => item.name == "Head");
                Vector3 bladeDirection = prop.TransformDirection(
                    DiagonalSlashBladeAxisLocal()).normalized;
                Vector3 bladeStart = prop.position;
                Vector3 bladeEnd = bladeStart +
                    bladeDirection * LightsaberTotalLengthMeters;
                Vector3 shoulderCenter =
                    (leftShoulder.position + rightShoulder.position) * 0.5f;
                Vector3 middleTorso = Vector3.Lerp(
                    hips.position, shoulderCenter, 0.58f);
                float torsoClearance = Mathf.Min(
                    DistancePointToSegment(shoulderCenter, bladeStart, bladeEnd),
                    DistancePointToSegment(middleTorso, bladeStart, bladeEnd));
                Vector3 expectedLeftOffset =
                    -root.forward * ThrustModeEnterRearHandSpacingMeters -
                    root.up * ThrustModeEnterRearHandDropMeters;
                return new ThrustModeEnterPoseMetrics(
                    Vector3.Distance(leftHand.position, rightHand.position),
                    Vector3.Distance(
                        leftHand.position - rightHand.position,
                        expectedLeftOffset),
                    Vector3.Angle(bladeDirection, root.forward),
                    Vector3.Dot(bladeDirection, root.forward),
                    Vector3.Angle(
                        rightForeArm.position - rightArm.position,
                        rightHand.position - rightForeArm.position),
                    Vector3.Angle(
                        leftForeArm.position - leftArm.position,
                        leftHand.position - leftForeArm.position),
                    Vector3.Dot(rightHand.position - rightArm.position, root.right),
                    Vector3.Dot(leftHand.position - rightArm.position, root.right),
                    Vector3.Dot(rightArm.position - rightHand.position, root.up),
                    Vector3.Dot(rightArm.position - leftHand.position, root.up),
                    DistancePointToSegment(head.position, bladeStart, bladeEnd),
                    torsoClearance,
                    MeasureThrustModeEnterKneeBend(
                        leftUpLeg, leftLeg, leftFoot),
                    MeasureThrustModeEnterKneeBend(
                        rightUpLeg, rightLeg, rightFoot));
            }
            finally
            {
                if (probe != null) UnityEngine.Object.DestroyImmediate(probe);
                EditorSceneManager.ClosePreviewScene(previewScene);
            }
        }

        private readonly struct ThrustModeEnterPoseMetrics
        {
            internal ThrustModeEnterPoseMetrics(
                float handSpacingMeters,
                float gripOffsetErrorMeters,
                float bladeForwardAngleDegrees,
                float bladeForwardDot,
                float rightElbowDegrees,
                float leftElbowDegrees,
                float rightHandOutsideShoulderMeters,
                float leftHandOutsideShoulderMeters,
                float rightHandBelowShoulderMeters,
                float leftHandBelowShoulderMeters,
                float bladeHeadClearanceMeters,
                float bladeTorsoClearanceMeters,
                float leftKneeBendDegrees,
                float rightKneeBendDegrees)
            {
                HandSpacingMeters = handSpacingMeters;
                GripOffsetErrorMeters = gripOffsetErrorMeters;
                BladeForwardAngleDegrees = bladeForwardAngleDegrees;
                BladeForwardDot = bladeForwardDot;
                RightElbowDegrees = rightElbowDegrees;
                LeftElbowDegrees = leftElbowDegrees;
                RightHandOutsideShoulderMeters = rightHandOutsideShoulderMeters;
                LeftHandOutsideShoulderMeters = leftHandOutsideShoulderMeters;
                RightHandBelowShoulderMeters = rightHandBelowShoulderMeters;
                LeftHandBelowShoulderMeters = leftHandBelowShoulderMeters;
                BladeHeadClearanceMeters = bladeHeadClearanceMeters;
                BladeTorsoClearanceMeters = bladeTorsoClearanceMeters;
                LeftKneeBendDegrees = leftKneeBendDegrees;
                RightKneeBendDegrees = rightKneeBendDegrees;
            }

            internal float HandSpacingMeters { get; }
            internal float GripOffsetErrorMeters { get; }
            internal float BladeForwardAngleDegrees { get; }
            internal float BladeForwardDot { get; }
            internal float RightElbowDegrees { get; }
            internal float LeftElbowDegrees { get; }
            internal float RightHandOutsideShoulderMeters { get; }
            internal float LeftHandOutsideShoulderMeters { get; }
            internal float RightHandBelowShoulderMeters { get; }
            internal float LeftHandBelowShoulderMeters { get; }
            internal float BladeHeadClearanceMeters { get; }
            internal float BladeTorsoClearanceMeters { get; }
            internal float LeftKneeBendDegrees { get; }
            internal float RightKneeBendDegrees { get; }
        }

        private static float DistancePointToSegment(
            Vector3 point,
            Vector3 start,
            Vector3 end)
        {
            Vector3 segment = end - start;
            float denominator = segment.sqrMagnitude;
            if (denominator <= 0.000001f)
                return Vector3.Distance(point, start);
            float distance = Mathf.Clamp01(
                Vector3.Dot(point - start, segment) / denominator);
            return Vector3.Distance(point, start + segment * distance);
        }

        private static ThrustModeEnterFootPlantMetrics
            MeasureThrustModeEnterFootPlant(
                IReadOnlyDictionary<string, DiagonalSlashLocalPose> referencePose,
                IReadOnlyDictionary<string, DiagonalSlashLocalPose> actualPose)
        {
            Scene previewScene = EditorSceneManager.NewPreviewScene();
            GameObject referenceProbe = null;
            GameObject actualProbe = null;
            try
            {
                referenceProbe = CreateThrustModeEnterPoseProbe(
                    previewScene, referencePose, out _);
                actualProbe = CreateThrustModeEnterPoseProbe(
                    previewScene, actualPose, out _);
                Transform referenceRoot = referenceProbe.transform;
                Transform actualRoot = actualProbe.transform;
                Transform referenceLeft = RequirePoseProbeBone(
                    referenceRoot, LeftFootPath);
                Transform referenceRight = RequirePoseProbeBone(
                    referenceRoot, RightFootPath);
                Transform actualLeft = RequirePoseProbeBone(actualRoot, LeftFootPath);
                Transform actualRight = RequirePoseProbeBone(actualRoot, RightFootPath);
                return new ThrustModeEnterFootPlantMetrics(
                    Vector3.Distance(referenceLeft.position, actualLeft.position),
                    Vector3.Distance(referenceRight.position, actualRight.position),
                    Mathf.Abs(referenceLeft.position.y - actualLeft.position.y),
                    Mathf.Abs(referenceRight.position.y - actualRight.position.y),
                    Quaternion.Angle(referenceLeft.rotation, actualLeft.rotation),
                    Quaternion.Angle(referenceRight.rotation, actualRight.rotation));
            }
            finally
            {
                if (referenceProbe != null)
                    UnityEngine.Object.DestroyImmediate(referenceProbe);
                if (actualProbe != null)
                    UnityEngine.Object.DestroyImmediate(actualProbe);
                EditorSceneManager.ClosePreviewScene(previewScene);
            }
        }

        private static ThrustModeEnterFootPlantMetrics
            MeasureThrustModeEnterFootPlant(
                IReadOnlyDictionary<string, DiagonalSlashLocalPose> referencePose,
                AnimationClip clip)
        {
            Scene previewScene = EditorSceneManager.NewPreviewScene();
            GameObject probe = null;
            try
            {
                probe = CreateThrustModeEnterPoseProbe(
                    previewScene, referencePose, out _);
                Transform root = probe.transform;
                Transform leftFoot = RequirePoseProbeBone(root, LeftFootPath);
                Transform rightFoot = RequirePoseProbeBone(root, RightFootPath);
                Vector3 leftPosition = leftFoot.position;
                Vector3 rightPosition = rightFoot.position;
                Quaternion leftRotation = leftFoot.rotation;
                Quaternion rightRotation = rightFoot.rotation;
                float maximumLeftPosition = 0f;
                float maximumRightPosition = 0f;
                float maximumLeftVertical = 0f;
                float maximumRightVertical = 0f;
                float maximumLeftRotation = 0f;
                float maximumRightRotation = 0f;
                int sampleCount = Mathf.CeilToInt(clip.length * 120f);
                for (int index = 0; index <= sampleCount; index++)
                {
                    float time = clip.length * index / sampleCount;
                    clip.SampleAnimation(probe, time);
                    maximumLeftPosition = Mathf.Max(
                        maximumLeftPosition,
                        Vector3.Distance(leftPosition, leftFoot.position));
                    maximumRightPosition = Mathf.Max(
                        maximumRightPosition,
                        Vector3.Distance(rightPosition, rightFoot.position));
                    maximumLeftVertical = Mathf.Max(
                        maximumLeftVertical,
                        Mathf.Abs(leftPosition.y - leftFoot.position.y));
                    maximumRightVertical = Mathf.Max(
                        maximumRightVertical,
                        Mathf.Abs(rightPosition.y - rightFoot.position.y));
                    maximumLeftRotation = Mathf.Max(
                        maximumLeftRotation,
                        Quaternion.Angle(leftRotation, leftFoot.rotation));
                    maximumRightRotation = Mathf.Max(
                        maximumRightRotation,
                        Quaternion.Angle(rightRotation, rightFoot.rotation));
                }
                return new ThrustModeEnterFootPlantMetrics(
                    maximumLeftPosition,
                    maximumRightPosition,
                    maximumLeftVertical,
                    maximumRightVertical,
                    maximumLeftRotation,
                    maximumRightRotation);
            }
            finally
            {
                if (probe != null) UnityEngine.Object.DestroyImmediate(probe);
                EditorSceneManager.ClosePreviewScene(previewScene);
            }
        }

        private readonly struct ThrustModeEnterFootReferences
        {
            internal ThrustModeEnterFootReferences(
                Vector3 leftPosition,
                Quaternion leftRotation,
                Vector3 leftKneePole,
                Vector3 rightPosition,
