                Vector3 rightKneePole)
            {
                LeftPosition = leftPosition;
                LeftRotation = leftRotation;
                LeftKneePole = leftKneePole;
                RightPosition = rightPosition;
                RightRotation = rightRotation;
                RightKneePole = rightKneePole;
            }

            internal Vector3 LeftPosition { get; }
            internal Quaternion LeftRotation { get; }
            internal Vector3 LeftKneePole { get; }
            internal Vector3 RightPosition { get; }
            internal Quaternion RightRotation { get; }
            internal Vector3 RightKneePole { get; }
        }

        private readonly struct ThrustModeEnterFootPlantMetrics
        {
            internal ThrustModeEnterFootPlantMetrics(
                float leftPositionDrift,
                float rightPositionDrift,
                float leftVerticalDrift,
                float rightVerticalDrift,
                float leftRotationDrift,
                float rightRotationDrift)
            {
                LeftPositionDrift = leftPositionDrift;
                RightPositionDrift = rightPositionDrift;
                LeftVerticalDrift = leftVerticalDrift;
                RightVerticalDrift = rightVerticalDrift;
                LeftRotationDrift = leftRotationDrift;
                RightRotationDrift = rightRotationDrift;
            }

            internal float LeftPositionDrift { get; }
            internal float RightPositionDrift { get; }
            internal float LeftVerticalDrift { get; }
            internal float RightVerticalDrift { get; }
            internal float LeftRotationDrift { get; }
            internal float RightRotationDrift { get; }

            internal void RequireWithinTolerance(string label)
            {
                if (LeftPositionDrift > ThrustModeEnterFootPositionToleranceMeters ||
                    RightPositionDrift > ThrustModeEnterFootPositionToleranceMeters ||
                    LeftVerticalDrift > ThrustModeEnterFootPositionToleranceMeters ||
                    RightVerticalDrift > ThrustModeEnterFootPositionToleranceMeters ||
                    LeftRotationDrift > ThrustModeEnterFootRotationToleranceDegrees ||
                    RightRotationDrift > ThrustModeEnterFootRotationToleranceDegrees)
                    throw new InvalidOperationException(
                        "Thrust-mode-enter feet did not stay planted for " + label +
                        ". leftPosition=" + Num(LeftPositionDrift) +
                        "|rightPosition=" + Num(RightPositionDrift) +
                        "|leftVertical=" + Num(LeftVerticalDrift) +
                        "|rightVertical=" + Num(RightVerticalDrift) +
                        "|leftRotation=" + Num(LeftRotationDrift) +
                        "|rightRotation=" + Num(RightRotationDrift) + ".");
            }
        }

        private static void InspectLightsaberDiagonalSlashBladeTrajectoryInternal(
            Scene scene,
            bool requireCleanScene)
        {
            if (requireCleanScene && scene.isDirty)
                throw new InvalidOperationException(
                    "Blade-trajectory inspection requires a clean scene.");
            InspectLightsaberDiagonalSlashSequenceInternal(scene, false);
            AnimationClip baseStart = RequireDiagonalSlashAsset<AnimationClip>(
                DiagonalSlashStartTransitionClipPath);
            AnimationClip baseSlash = RequireDiagonalSlashAsset<AnimationClip>(
                DiagonalSlashClipPath);
            AnimationClip baseBridge = RequireDiagonalSlashAsset<AnimationClip>(
                DiagonalSlashMirrorTransitionClipPath);
            AnimationClip baseMirror = RequireDiagonalSlashAsset<AnimationClip>(
                DiagonalSlashMirrorClipPath);
            AnimationClip trajectoryStart = RequireDiagonalSlashAsset<AnimationClip>(
                DiagonalSlashTrajectoryStartTransitionClipPath);
            AnimationClip trajectorySlash = RequireDiagonalSlashAsset<AnimationClip>(
                DiagonalSlashTrajectoryClipPath);
            AnimationClip trajectoryBridge = RequireDiagonalSlashAsset<AnimationClip>(
                DiagonalSlashTrajectoryMirrorTransitionClipPath);
            AnimationClip trajectoryMirror = RequireDiagonalSlashAsset<AnimationClip>(
                DiagonalSlashTrajectoryMirrorClipPath);
            RequireTrajectoryCharacterEquivalent(baseStart, trajectoryStart,
                "start transition");
            RequireTrajectoryCharacterEquivalent(baseSlash, trajectorySlash,
                "slash source");
            RequireTrajectoryCharacterEquivalent(baseBridge, trajectoryBridge,
                "mirror transition");
            RequireTrajectoryCharacterEquivalent(baseMirror, trajectoryMirror,
                "mirror source");
            RequirePropRotationCurves(trajectoryStart, 2, "start transition");
            RequirePropRotationCurves(
                trajectorySlash,
                DiagonalSlashTrajectoryKeyCount(baseSlash),
                "slash source");
            RequirePropRotationCurves(trajectoryBridge, 2, "mirror transition");
            RequirePropRotationCurves(
                trajectoryMirror,
                DiagonalSlashTrajectoryKeyCount(baseMirror),
                "mirror source");

            GameObject target = FindUnique(scene, DiagonalSlashTargetName);
            Animator animator = target.GetComponent<Animator>() ??
                throw new InvalidOperationException(
                    DiagonalSlashTargetName + " Animator is missing.");
            AnimatorController controller = animator.runtimeAnimatorController as
                AnimatorController ?? throw new InvalidOperationException(
                    "Lightsaber_DiagonalSlash controller is missing.");
            AnimatorState[] states = controller.layers[0].stateMachine.states
                .Select(item => item.state).ToArray();
            RequireDiagonalSlashState(
                states,
                DiagonalSlashStartTransitionStateName,
                trajectoryStart);
            RequireDiagonalSlashState(
                states,
                DiagonalSlashSourceStateName,
                trajectorySlash);
            RequireDiagonalSlashState(
                states,
                DiagonalSlashMirrorTransitionStateName,
                trajectoryBridge);
            RequireDiagonalSlashState(
                states,
                DiagonalSlashMirrorStateName,
                trajectoryMirror);

            Transform hand = RequireRightHand(target);
            Transform prop = RequireLightsaberProp(hand, target.name);
            RequireAuthoredPropTransform(prop, target.name);
            Dictionary<string, DiagonalSlashLocalPose> currentPose =
                CaptureDiagonalSlashPose(target.transform, prop);
            Vector3 bladeAxis = DiagonalSlashBladeAxisLocal();
            Quaternion[] slashRotations = CreateDiagonalSlashTrajectoryRotations(
                target,
                prop,
                baseSlash,
                currentPose,
                bladeAxis,
                false);
            Quaternion[] mirrorRotations = CreateDiagonalSlashTrajectoryRotations(
                target,
                prop,
                baseMirror,
                currentPose,
                bladeAxis,
                true);
            float maximumDirectionError = 0f;
            float maximumLocalRotationChange = 0f;
            if (slashRotations.Length != mirrorRotations.Length)
                throw new InvalidOperationException(
                    "Slash and mirror trajectory sample counts differ.");
            for (int index = 0; index < slashRotations.Length; index++)
            {
                float normalized = index /
                    (float)(slashRotations.Length - 1);
                float slashTime = normalized * trajectorySlash.length;
                float mirrorTime = normalized * trajectoryMirror.length;
                Quaternion slashActual = EvaluatePropRotation(
                    trajectorySlash, slashTime);
                Quaternion mirrorActual = EvaluatePropRotation(
                    trajectoryMirror, mirrorTime);
                maximumLocalRotationChange = Mathf.Max(
                    maximumLocalRotationChange,
                    Quaternion.Angle(AuthoredPropLocalRotation, slashActual),
                    Quaternion.Angle(AuthoredPropLocalRotation, mirrorActual));
                if (Quaternion.Angle(slashActual, slashRotations[index]) > 0.02f ||
                    Quaternion.Angle(mirrorActual, mirrorRotations[index]) > 0.02f)
                    throw new InvalidOperationException(
                        "Blade-trajectory quaternion key differs at index " + index + ".");
                Dictionary<string, DiagonalSlashLocalPose> slashPose =
                    SampleDiagonalSlashPose(
                        target, prop, baseSlash, slashTime, currentPose);
                Dictionary<string, DiagonalSlashLocalPose> mirrorPose =
                    SampleDiagonalSlashPose(
                        target, prop, baseMirror, mirrorTime, currentPose);
                Vector3 slashDirection =
                    DiagonalSlashChainRotation(slashPose, RightHandPath) *
                    slashActual * bladeAxis;
                Vector3 mirrorDirection =
                    DiagonalSlashChainRotation(mirrorPose, RightHandPath) *
                    mirrorActual * bladeAxis;
                maximumDirectionError = Mathf.Max(
                    maximumDirectionError,
                    Vector3.Angle(
                        slashDirection,
                        DiagonalSlashReferenceDirection(normalized, false)),
                    Vector3.Angle(
                        mirrorDirection,
                        DiagonalSlashReferenceDirection(normalized, true)));
            }
            if (maximumDirectionError > 0.2f)
                throw new InvalidOperationException(
                    "Blade direction differs from the 12-point reference; maximum=" +
                    Num(maximumDirectionError) + " degrees.");
            if (maximumLocalRotationChange < 60f)
                throw new InvalidOperationException(
                    "Lightsaber handle rotation is not dynamic enough to trace the reference.");
            RequirePropBridgeEndpoints(
                trajectoryStart,
                AuthoredPropLocalRotation,
                slashRotations[0],
                "start transition");
            RequirePropBridgeEndpoints(
                trajectoryBridge,
                slashRotations[slashRotations.Length - 1],
                mirrorRotations[0],
                "mirror transition");
        }

        private static DiagonalSlashTrajectoryClipResult
            CreateOrUpdateDiagonalSlashTrajectoryClip(
                GameObject target,
                Transform prop,
                AnimationClip source,
                string path,
                string name,
                IReadOnlyDictionary<string, DiagonalSlashLocalPose> currentPose,
                Vector3 bladeAxis,
                bool mirror)
        {
            Quaternion[] rotations = CreateDiagonalSlashTrajectoryRotations(
                target, prop, source, currentPose, bladeAxis, mirror);
            float[] times = Enumerable.Range(0, rotations.Length)
                .Select(index => source.length * index /
                    (rotations.Length - 1f))
                .ToArray();
            AnimationClip clip = CreateOrUpdateClipWithPropRotations(
                source, path, name, times, rotations);
            RequireTrajectoryCharacterEquivalent(source, clip, name);
            RequirePropRotationCurves(clip, rotations.Length, name);
            return new DiagonalSlashTrajectoryClipResult(clip, rotations);
        }

        private static AnimationClip CreateOrUpdateDiagonalSlashPropBridgeClip(
            AnimationClip source,
            string path,
            string name,
            Quaternion from,
            Quaternion to)
        {
            AnimationClip clip = CreateOrUpdateClipWithPropRotations(
                source,
                path,
                name,
                new[] { 0f, source.length },
                new[] { from, to });
            RequireTrajectoryCharacterEquivalent(source, clip, name);
            RequirePropRotationCurves(clip, 2, name);
            return clip;
        }

        private static AnimationClip CreateOrUpdateClipWithPropRotations(
            AnimationClip source,
            string path,
            string name,
            IReadOnlyList<float> times,
            IReadOnlyList<Quaternion> rotations)
        {
            if (times.Count != rotations.Count || times.Count < 2)
                throw new InvalidOperationException(
                    name + " trajectory key data is invalid.");
            var generated = new AnimationClip();
            EditorUtility.CopySerialized(source, generated);
            generated.name = name;
            Quaternion[] continuous = rotations.ToArray();
            for (int index = 1; index < continuous.Length; index++)
                if (Quaternion.Dot(continuous[index - 1], continuous[index]) < 0f)
                    continuous[index] = NegateQuaternion(continuous[index]);
            SetDiagonalSlashQuaternionCurve(
                generated, "m_LocalRotation.x", times,
                continuous.Select(item => item.x).ToArray());
            SetDiagonalSlashQuaternionCurve(
                generated, "m_LocalRotation.y", times,
                continuous.Select(item => item.y).ToArray());
            SetDiagonalSlashQuaternionCurve(
                generated, "m_LocalRotation.z", times,
                continuous.Select(item => item.z).ToArray());
            SetDiagonalSlashQuaternionCurve(
                generated, "m_LocalRotation.w", times,
                continuous.Select(item => item.w).ToArray());
            generated.EnsureQuaternionContinuity();
            AnimationClip existing = AssetDatabase.LoadAssetAtPath<AnimationClip>(path);
            if (existing == null)
            {
                AssetDatabase.CreateAsset(generated, path);
                existing = generated;
            }
            else
            {
                EditorUtility.CopySerialized(generated, existing);
                existing.name = name;
                EditorUtility.SetDirty(existing);
                UnityEngine.Object.DestroyImmediate(generated);
            }
            if (Mathf.Abs(existing.length - source.length) > 0.0001f ||
                Mathf.Abs(existing.frameRate - source.frameRate) > 0.0001f)
                throw new InvalidOperationException(
                    name + " changed the protected clip duration or frame rate.");
            return existing;
        }

        private static void SetDiagonalSlashQuaternionCurve(
            AnimationClip clip,
            string property,
            IReadOnlyList<float> times,
            IReadOnlyList<float> values)
        {
            var curve = new AnimationCurve();
            for (int index = 0; index < times.Count; index++)
                curve.AddKey(new Keyframe(times[index], values[index]));
            for (int index = 0; index < curve.length; index++)
            {
                AnimationUtility.SetKeyLeftTangentMode(
                    curve, index, AnimationUtility.TangentMode.Linear);
                AnimationUtility.SetKeyRightTangentMode(
                    curve, index, AnimationUtility.TangentMode.Linear);
            }
            curve.preWrapMode = WrapMode.ClampForever;
            curve.postWrapMode = WrapMode.ClampForever;
            AnimationUtility.SetEditorCurve(
                clip,
                EditorCurveBinding.FloatCurve(
                    DiagonalSlashPropPath, typeof(Transform), property),
                curve);
        }

        private static Quaternion[] CreateDiagonalSlashTrajectoryRotations(
            GameObject target,
            Transform prop,
            AnimationClip characterClip,
            IReadOnlyDictionary<string, DiagonalSlashLocalPose> currentPose,
            Vector3 bladeAxis,
            bool mirror)
        {
            // Bake at the unchanged source frame rate. Twelve GIF directions remain
            // the visual reference, while per-frame hand compensation prevents the
            // Humanoid hand motion from bending the blade between sparse reference keys.
            var rotations = new Quaternion[
                DiagonalSlashTrajectoryKeyCount(characterClip)];
            for (int index = 0; index < rotations.Length; index++)
            {
                float normalized = index / (float)(rotations.Length - 1);
                Dictionary<string, DiagonalSlashLocalPose> pose =
                    SampleDiagonalSlashPose(
                        target,
                        prop,
                        characterClip,
                        normalized * characterClip.length,
                        currentPose);
                Quaternion handInTarget =
                    DiagonalSlashChainRotation(pose, RightHandPath);
                Quaternion baselinePropInTarget =
                    handInTarget * AuthoredPropLocalRotation;
                Vector3 baselineBladeInTarget =
                    baselinePropInTarget * bladeAxis;
                Vector3 desired = DiagonalSlashReferenceDirection(normalized, mirror);
                Quaternion propInTarget =
                    Quaternion.FromToRotation(baselineBladeInTarget, desired) *
                    baselinePropInTarget;
                rotations[index] =
                    Quaternion.Inverse(handInTarget) * propInTarget;
                if (index > 0 && Quaternion.Dot(rotations[index - 1], rotations[index]) < 0f)
                    rotations[index] = NegateQuaternion(rotations[index]);
            }
            return rotations;
        }

        private static int DiagonalSlashTrajectoryKeyCount(AnimationClip clip)
        {
            return Mathf.CeilToInt(clip.length * clip.frameRate) + 1;
        }

        internal static Vector3 DiagonalSlashReferenceDirection(
            float normalized,
            bool mirror)
        {
            Vector3 screenDirection =
                DiagonalSlashGifScreenDirection(normalized, mirror);
            return new Vector3(
                -screenDirection.x,
                screenDirection.y,
                screenDirection.z).normalized;
        }

        internal static Vector3 DiagonalSlashGifScreenDirection(
            float normalized,
            bool mirror)
        {
            float scaled = Mathf.Clamp01(normalized) *
                (DiagonalSlashGifScreenDirections.Length - 1);
            int left = Mathf.FloorToInt(scaled);
            int right = Mathf.Min(
                left + 1, DiagonalSlashGifScreenDirections.Length - 1);
            float interpolation = scaled - left;
            Vector3 direction;
            if (left == 5 && right == 6)
            {
                direction = interpolation < 0.5f
                    ? Vector3.Slerp(
                        DiagonalSlashGifScreenDirections[left],
                        DiagonalSlashDownstrokeDepthWaypoint,
                        interpolation * 2f)
                    : Vector3.Slerp(
                        DiagonalSlashDownstrokeDepthWaypoint,
                        DiagonalSlashGifScreenDirections[right],
                        (interpolation - 0.5f) * 2f);
            }
            else
            {
                direction = Vector3.Slerp(
                    DiagonalSlashGifScreenDirections[left],
                    DiagonalSlashGifScreenDirections[right],
                    interpolation);
            }
            direction.Normalize();
            if (mirror) direction.x = -direction.x;
            return direction.normalized;
        }

        internal static Vector3 DiagonalSlashBladeAxisLocal()
        {
            GameObject model = AssetDatabase.LoadAssetAtPath<GameObject>(ModelPath) ??
                throw new InvalidOperationException(
                    "Imported lightsaber model is missing.");
            return AnalyzeModelGeometry(model).BladeAxisLocal.normalized;
        }

        private static Quaternion DiagonalSlashChainRotation(
            IReadOnlyDictionary<string, DiagonalSlashLocalPose> pose,
            string path)
        {
            Quaternion rotation = Quaternion.identity;
            string current = string.Empty;
            foreach (string part in path.Split('/'))
            {
                current = string.IsNullOrEmpty(current)
                    ? part
                    : current + "/" + part;
                if (!pose.TryGetValue(current, out DiagonalSlashLocalPose local))
                    throw new InvalidOperationException(
                        "Blade-trajectory pose path is missing: " + current);
                rotation *= local.Rotation;
            }
            return rotation;
        }

        private static Quaternion EvaluatePropRotation(AnimationClip clip, float time)
        {
            float[] values = new float[4];
            string[] properties =
            {
                "m_LocalRotation.x", "m_LocalRotation.y",
                "m_LocalRotation.z", "m_LocalRotation.w"
            };
            for (int index = 0; index < properties.Length; index++)
            {
                EditorCurveBinding binding = EditorCurveBinding.FloatCurve(
                    DiagonalSlashPropPath, typeof(Transform), properties[index]);
                AnimationCurve curve = AnimationUtility.GetEditorCurve(clip, binding) ??
                    throw new InvalidOperationException(
                        clip.name + " is missing " + properties[index] + ".");
                values[index] = curve.Evaluate(Mathf.Clamp(time, 0f, clip.length));
            }
            return new Quaternion(values[0], values[1], values[2], values[3]).normalized;
        }

        private static void RequirePropBridgeEndpoints(
            AnimationClip clip,
            Quaternion expectedStart,
            Quaternion expectedEnd,
            string label)
        {
            if (Quaternion.Angle(EvaluatePropRotation(clip, 0f), expectedStart) > 0.02f ||
                Quaternion.Angle(
                    EvaluatePropRotation(clip, clip.length), expectedEnd) > 0.02f)
                throw new InvalidOperationException(
                    label + " blade-rotation endpoints differ.");
        }

        private static void RequireNoPropCurves(AnimationClip clip, string label)
        {
            if (AnimationUtility.GetCurveBindings(clip).Any(IsPropBinding) ||
                AnimationUtility.GetObjectReferenceCurveBindings(clip).Any(IsPropBinding))
                throw new InvalidOperationException(
                    label + " unexpectedly contains Lightsaber_Prop curves.");
        }

        private static void RequirePropRotationCurves(
            AnimationClip clip,
            int expectedKeyCount,
            string label)
        {
            EditorCurveBinding[] propBindings = AnimationUtility.GetCurveBindings(clip)
                .Where(IsPropBinding).ToArray();
            string[] expectedProperties =
            {
                "m_LocalRotation.x", "m_LocalRotation.y",
                "m_LocalRotation.z", "m_LocalRotation.w"
            };
            if (propBindings.Length != expectedProperties.Length ||
                expectedProperties.Any(property => !propBindings.Any(binding =>
                    binding.type == typeof(Transform) &&
                    binding.propertyName == property)))
                throw new InvalidOperationException(
                    label + " must contain only four prop quaternion curves.");
            foreach (EditorCurveBinding binding in propBindings)
            {
                AnimationCurve curve = AnimationUtility.GetEditorCurve(clip, binding);
                if (curve == null || curve.length != expectedKeyCount)
                    throw new InvalidOperationException(
                        label + " prop rotation key count differs for " +
                        binding.propertyName + ".");
            }
            if (AnimationUtility.GetObjectReferenceCurveBindings(clip).Any(IsPropBinding) ||
                propBindings.Any(binding =>
                    binding.propertyName.StartsWith("m_LocalPosition", StringComparison.Ordinal) ||
                    binding.propertyName.StartsWith("m_LocalScale", StringComparison.Ordinal)))
                throw new InvalidOperationException(
                    label + " animates prop position, scale, or object references.");
        }

        private static bool IsPropBinding(EditorCurveBinding binding)
        {
            return binding.path == DiagonalSlashPropPath ||
                binding.path.StartsWith(
                    DiagonalSlashPropPath + "/", StringComparison.Ordinal);
        }

        private static void RequireTrajectoryCharacterEquivalent(
            AnimationClip source,
            AnimationClip trajectory,
            string label)
        {
            RequireEqual(
                LightsaberClipSignatureWithoutProp(source),
                LightsaberClipSignatureWithoutProp(trajectory),
                label + " protected character curves and timing");
        }

        private static string LightsaberClipSignatureWithoutProp(AnimationClip clip)
        {
            var result = new StringBuilder()
                .AppendLine("length=" + Num(clip.length))
                .AppendLine("frameRate=" + Num(clip.frameRate))
                .AppendLine("legacy=" + clip.legacy)
                .AppendLine("wrapMode=" + clip.wrapMode)
                .AppendLine("settings=" + EditorJsonUtility.ToJson(
                    AnimationUtility.GetAnimationClipSettings(clip)));
            foreach (EditorCurveBinding binding in AnimationUtility.GetCurveBindings(clip)
                .Where(item => !IsPropBinding(item))
                .OrderBy(item => item.path, StringComparer.Ordinal)
                .ThenBy(item => item.type.FullName, StringComparer.Ordinal)
                .ThenBy(item => item.propertyName, StringComparer.Ordinal))
            {
                result.Append("curve|").Append(binding.path).Append('|')
                    .Append(binding.type.FullName).Append('|')
                    .AppendLine(binding.propertyName);
                AnimationCurve curve = AnimationUtility.GetEditorCurve(clip, binding);
                result.AppendLine("wrap=" + curve.preWrapMode + "," + curve.postWrapMode);
                foreach (Keyframe key in curve.keys)
                    result.AppendLine(string.Join(",", new[]
                    {
                        Num(key.time), Num(key.value), Num(key.inTangent), Num(key.outTangent),
                        Num(key.inWeight), Num(key.outWeight), key.weightedMode.ToString()
                    }));
            }
            foreach (EditorCurveBinding binding in AnimationUtility
                .GetObjectReferenceCurveBindings(clip)
                .Where(item => !IsPropBinding(item))
                .OrderBy(item => item.path, StringComparer.Ordinal)
                .ThenBy(item => item.type.FullName, StringComparer.Ordinal)
                .ThenBy(item => item.propertyName, StringComparer.Ordinal))
            {
                result.Append("objectCurve|").Append(binding.path).Append('|')
                    .Append(binding.type.FullName).Append('|')
                    .AppendLine(binding.propertyName);
                foreach (ObjectReferenceKeyframe key in AnimationUtility
                    .GetObjectReferenceCurve(clip, binding))
                    result.AppendLine(Num(key.time) + "|" + ObjectIdentity(key.value));
            }
            foreach (AnimationEvent item in AnimationUtility.GetAnimationEvents(clip))
                result.AppendLine("event|" + Num(item.time) + "|" + item.functionName + "|" +
                    item.stringParameter + "|" + item.intParameter + "|" +
                    Num(item.floatParameter) + "|" + ObjectIdentity(
                        item.objectReferenceParameter) + "|" + item.messageOptions);
            return LightsaberSha256(result.ToString());
        }

        private static Quaternion NegateQuaternion(Quaternion value)
        {
            return new Quaternion(-value.x, -value.y, -value.z, -value.w);
        }

        private readonly struct DiagonalSlashTrajectoryClipResult
        {
            internal DiagonalSlashTrajectoryClipResult(
                AnimationClip clip,
                IReadOnlyList<Quaternion> rotations)
            {
                Clip = clip;
                Rotations = rotations;
            }

            internal AnimationClip Clip { get; }
            internal IReadOnlyList<Quaternion> Rotations { get; }
        }

        private static void InspectLightsaberDiagonalSlashSequenceInternal(
            Scene scene,
            bool requireCleanScene)
        {
            if (requireCleanScene && scene.isDirty)
                throw new InvalidOperationException(
                    "Lightsaber_DiagonalSlash inspection requires a clean scene.");
            string externalSlash = Absolute(DiagonalSlashSourceRelativePath);
            string externalMirror = Absolute(DiagonalSlashMirrorSourceRelativePath);
            string assetSlash = Absolute(DiagonalSlashSourcePath);
            string assetMirror = Absolute(DiagonalSlashMirrorSourcePath);
            if (!File.Exists(externalSlash) || !File.Exists(externalMirror) ||
                !File.Exists(assetSlash) || !File.Exists(assetMirror))
                throw new InvalidOperationException(
                    "Lightsaber diagonal slash source copies are incomplete.");
            RequireEqual(Sha256File(externalSlash), Sha256File(assetSlash),
                "slash FBX binary copy");
            RequireEqual(Sha256File(externalMirror), Sha256File(assetMirror),
                "mirror slash FBX binary copy");
            RequireDiagonalSlashImporter(DiagonalSlashSourcePath, "slash");
            RequireDiagonalSlashImporter(DiagonalSlashMirrorSourcePath, "mirror slash");

            AnimationClip sourceSlash = RequireSingleDiagonalSlashClip(
                DiagonalSlashSourcePath, "slash");
            AnimationClip sourceMirror = RequireSingleDiagonalSlashClip(
                DiagonalSlashMirrorSourcePath, "mirror slash");
            AnimationClip startTransition = RequireDiagonalSlashAsset<AnimationClip>(
                DiagonalSlashStartTransitionClipPath);
            AnimationClip slash = RequireDiagonalSlashAsset<AnimationClip>(
                DiagonalSlashClipPath);
            AnimationClip mirrorTransition = RequireDiagonalSlashAsset<AnimationClip>(
                DiagonalSlashMirrorTransitionClipPath);
            AnimationClip mirror = RequireDiagonalSlashAsset<AnimationClip>(
                DiagonalSlashMirrorClipPath);
            RequireEqual(LightsaberClipSignature(sourceSlash),
                LightsaberClipSignature(slash), "exact slash clip copy");
            RequireEqual(LightsaberClipSignature(sourceMirror),
                LightsaberClipSignature(mirror), "exact mirror slash clip copy");
            RequireTransitionClipDuration(startTransition,
                "current-pose to slash-first-frame bridge");
            RequireTransitionClipDuration(mirrorTransition,
                "slash-last-frame to mirror-first-frame bridge");

            GameObject target = FindUnique(scene, DiagonalSlashTargetName);
            Animator animator = target.GetComponent<Animator>() ??
                throw new InvalidOperationException(
                    DiagonalSlashTargetName + " Animator is missing.");
            AnimatorController controller = animator.runtimeAnimatorController as AnimatorController;
            if (controller == null ||
                AssetDatabase.GetAssetPath(controller) != DiagonalSlashControllerPath)
                throw new InvalidOperationException(
                    "Lightsaber_DiagonalSlash sequence controller connection differs.");
            if (animator.applyRootMotion || !animator.enabled ||
                animator.cullingMode != AnimatorCullingMode.AlwaysAnimate)
                throw new InvalidOperationException(
                    "Lightsaber_DiagonalSlash root-lock Animator settings differ.");
            if (controller.layers.Length != 1 || controller.parameters.Length != 0)
                throw new InvalidOperationException(
                    "Lightsaber_DiagonalSlash controller layer or parameter count differs.");
            AnimatorControllerLayer layer = controller.layers[0];
            if (layer.avatarMask != null ||
                layer.blendingMode != AnimatorLayerBlendingMode.Override ||
                !Mathf.Approximately(layer.defaultWeight, 1f))
                throw new InvalidOperationException(
                    "Lightsaber_DiagonalSlash controller layer settings differ.");
            AnimatorState[] states = layer.stateMachine.states
                .Select(item => item.state).ToArray();
            if (states.Length != 4 || states.Any(state =>
                    state == null || state.writeDefaultValues || state.mirror ||
                    !Mathf.Approximately(state.speed, 1f) ||
                    state.behaviours.Any(item => item == null)))
                throw new InvalidOperationException(
                    "Lightsaber_DiagonalSlash state settings differ or contain a missing script.");
            AnimatorState startState = RequireDiagonalSlashState(
                states, DiagonalSlashStartTransitionStateName, null);
            AnimatorState slashState = RequireDiagonalSlashState(
                states, DiagonalSlashSourceStateName, null);
            AnimatorState bridgeState = RequireDiagonalSlashState(
                states, DiagonalSlashMirrorTransitionStateName, null);
            AnimatorState mirrorState = RequireDiagonalSlashState(
                states, DiagonalSlashMirrorStateName, null);
            bool baseMotionsConnected = startState.motion == startTransition &&
                slashState.motion == slash && bridgeState.motion == mirrorTransition &&
                mirrorState.motion == mirror;
            AnimationClip trajectoryStart = AssetDatabase.LoadAssetAtPath<AnimationClip>(
                DiagonalSlashTrajectoryStartTransitionClipPath);
            AnimationClip trajectorySlash = AssetDatabase.LoadAssetAtPath<AnimationClip>(
                DiagonalSlashTrajectoryClipPath);
            AnimationClip trajectoryBridge = AssetDatabase.LoadAssetAtPath<AnimationClip>(
                DiagonalSlashTrajectoryMirrorTransitionClipPath);
            AnimationClip trajectoryMirror = AssetDatabase.LoadAssetAtPath<AnimationClip>(
                DiagonalSlashTrajectoryMirrorClipPath);
            bool trajectoryMotionsConnected = trajectoryStart != null &&
                trajectorySlash != null && trajectoryBridge != null &&
                trajectoryMirror != null && startState.motion == trajectoryStart &&
                slashState.motion == trajectorySlash && bridgeState.motion == trajectoryBridge &&
                mirrorState.motion == trajectoryMirror;
            if (!baseMotionsConnected && !trajectoryMotionsConnected)
                throw new InvalidOperationException(
                    "Lightsaber_DiagonalSlash states contain a partial or unknown motion set.");
            if (layer.stateMachine.defaultState != startState)
                throw new InvalidOperationException(
                    "Lightsaber_DiagonalSlash must begin at the current-pose bridge.");
            RequireImmediateDiagonalSlashTransition(startState, slashState,
                "start bridge to slash");
            RequireImmediateDiagonalSlashTransition(slashState, bridgeState,
                "slash to mirror bridge");
            RequireImmediateDiagonalSlashTransition(bridgeState, mirrorState,
                "mirror bridge to mirror slash");
            RequireImmediateDiagonalSlashTransition(mirrorState, startState,
                "mirror slash immediate return to start pose");

            Transform hand = RequireRightHand(target);
            Transform prop = RequireLightsaberProp(hand, target.name);
            if (prop.parent != hand)
                throw new InvalidOperationException(
                    "Lightsaber_Prop no longer follows RightHand.");
            RequireAuthoredPropTransform(prop, target.name);
            Dictionary<string, DiagonalSlashLocalPose> currentPose =
                CaptureDiagonalSlashPose(target.transform, prop);
            Dictionary<string, DiagonalSlashLocalPose> bridgeStart =
                SampleDiagonalSlashPose(
                    target, prop, startTransition, 0f, currentPose);
            Dictionary<string, DiagonalSlashLocalPose> bridgeEnd =
                SampleDiagonalSlashPose(
                    target, prop, startTransition,
                    DiagonalSlashTransitionSeconds, currentPose);
            Dictionary<string, DiagonalSlashLocalPose> slashFirst =
                SampleDiagonalSlashPose(target, prop, slash, 0f, currentPose);
            Dictionary<string, DiagonalSlashLocalPose> slashLast =
                SampleDiagonalSlashPose(target, prop, slash, slash.length, currentPose);
            Dictionary<string, DiagonalSlashLocalPose> mirrorBridgeStart =
                SampleDiagonalSlashPose(
                    target, prop, mirrorTransition, 0f, currentPose);
            Dictionary<string, DiagonalSlashLocalPose> mirrorBridgeEnd =
                SampleDiagonalSlashPose(
                    target, prop, mirrorTransition,
                    DiagonalSlashTransitionSeconds, currentPose);
            Dictionary<string, DiagonalSlashLocalPose> mirrorFirst =
                SampleDiagonalSlashPose(target, prop, mirror, 0f, currentPose);
            RequireDiagonalSlashPoseEqual(currentPose, bridgeStart,
                "current pose/start bridge first frame");
            RequireDiagonalSlashPoseEqual(bridgeEnd, slashFirst,
                "start bridge last frame/slash first frame");
            RequireDiagonalSlashPoseEqual(slashLast, mirrorBridgeStart,
                "slash last frame/mirror bridge first frame");
            RequireDiagonalSlashPoseEqual(mirrorBridgeEnd, mirrorFirst,
                "mirror bridge last frame/mirror first frame");
        }

        private static void EnsureDiagonalSlashSourceCopy(
            string suppliedRelativePath,
            string assetPath,
            string label)
        {
            string supplied = Absolute(suppliedRelativePath);
            string destination = Absolute(assetPath);
            if (!File.Exists(supplied))
                throw new FileNotFoundException(
                    "Supplied " + label + " FBX is missing.", supplied);
            Directory.CreateDirectory(Path.GetDirectoryName(destination) ??
                throw new InvalidOperationException(
                    "Destination folder for " + label + " is unavailable."));
            string expectedHash = Sha256File(supplied);
            if (!File.Exists(destination) ||
                !string.Equals(expectedHash, Sha256File(destination),
                    StringComparison.OrdinalIgnoreCase))
                File.Copy(supplied, destination, true);
            AssetDatabase.ImportAsset(
                assetPath,
                ImportAssetOptions.ForceSynchronousImport | ImportAssetOptions.ForceUpdate);
            RequireEqual(expectedHash, Sha256File(destination),
                label + " FBX binary copy");
        }

        private static void ConfigureDiagonalSlashSourceImporter(
            string path,
            string label)
        {
            ModelImporter importer = AssetImporter.GetAtPath(path) as ModelImporter ??
                throw new InvalidOperationException(
                    label + " FBX ModelImporter is unavailable.");
            importer.importAnimation = true;
            importer.animationType = ModelImporterAnimationType.Generic;
            importer.resampleCurves = false;
            importer.animationCompression = ModelImporterAnimationCompression.Off;
            importer.SaveAndReimport();
            importer = AssetImporter.GetAtPath(path) as ModelImporter ??
                throw new InvalidOperationException(
                    label + " FBX importer disappeared after reimport.");
            ModelImporterClipAnimation[] clips = importer.clipAnimations;
            if (clips == null || clips.Length == 0)
                clips = importer.defaultClipAnimations;
            ModelImporterClipAnimation[] mixamo = clips.Where(item =>
                    ContainsMixamo(item.name) || ContainsMixamo(item.takeName))
                .ToArray();
            if (mixamo.Length != 1 || clips.Length != 1)
                throw new InvalidOperationException(
                    label + " FBX must expose exactly one embedded Mixamo take; actual=" +
                    clips.Length.ToString(CultureInfo.InvariantCulture) + ".");
            clips[0].loopTime = false;
            clips[0].loopPose = false;
            importer.clipAnimations = clips;
            importer.SaveAndReimport();
            RequireDiagonalSlashImporter(path, label);
        }

        private static void RequireDiagonalSlashImporter(string path, string label)
        {
            ModelImporter importer = AssetImporter.GetAtPath(path) as ModelImporter ??
                throw new InvalidOperationException(
                    label + " FBX ModelImporter is unavailable.");
            if (!importer.importAnimation ||
                importer.animationType != ModelImporterAnimationType.Generic ||
                importer.resampleCurves ||
                importer.animationCompression != ModelImporterAnimationCompression.Off)
                throw new InvalidOperationException(
                    label + " FBX importer settings differ.");
            ModelImporterClipAnimation[] clips = importer.clipAnimations;
            if (clips == null || clips.Length == 0)
                clips = importer.defaultClipAnimations;
            if (clips.Length != 1 || clips[0].loopTime || clips[0].loopPose ||
                (!ContainsMixamo(clips[0].name) && !ContainsMixamo(clips[0].takeName)))
                throw new InvalidOperationException(
                    label + " embedded Mixamo take settings differ.");
        }

        private static AnimationClip RequireSingleDiagonalSlashClip(
            string path,
            string label)
        {
            AnimationClip[] clips = AssetDatabase.LoadAllAssetsAtPath(path)
                .OfType<AnimationClip>()
                .Where(item => !item.name.StartsWith("__preview__", StringComparison.Ordinal))
                .ToArray();
            if (clips.Length != 1 || !ContainsMixamo(clips[0].name))
                throw new InvalidOperationException(
                    label + " FBX must expose exactly one mixamo-named AnimationClip; actual=" +
                    clips.Length.ToString(CultureInfo.InvariantCulture) + ".");
            return clips[0];
        }

        private static bool ContainsMixamo(string value)
        {
            return !string.IsNullOrWhiteSpace(value) &&
                value.IndexOf("mixamo", StringComparison.OrdinalIgnoreCase) >= 0;
        }

        private static void RequireDiagonalSlashBindingCompatibility(
            Transform target,
            AnimationClip clip,
            string label)
        {
            string[] missing = AnimationUtility.GetCurveBindings(clip)
                .Concat(AnimationUtility.GetObjectReferenceCurveBindings(clip))
                .Select(item => item.path)
                .Where(path => !string.IsNullOrEmpty(path) && target.Find(path) == null)
                .Distinct(StringComparer.Ordinal)
                .OrderBy(path => path, StringComparer.Ordinal)
                .ToArray();
            if (missing.Length > 0)
                throw new InvalidOperationException(
                    label + " clip contains paths missing from Lightsaber_DiagonalSlash: " +
                    string.Join(",", missing.Take(12)));
            if (AnimationUtility.GetCurveBindings(clip).Length == 0)
                throw new InvalidOperationException(label + " clip has no animation curves.");
        }

        private static AnimationClip CopyExactDiagonalSlashClip(
            AnimationClip source,
            string path,
            string name)
        {
            AnimationClip copy = AssetDatabase.LoadAssetAtPath<AnimationClip>(path);
            if (copy == null)
            {
                copy = new AnimationClip();
                EditorUtility.CopySerialized(source, copy);
                copy.name = name;
                AssetDatabase.CreateAsset(copy, path);
            }
            else
            {
                EditorUtility.CopySerialized(source, copy);
                copy.name = name;
                EditorUtility.SetDirty(copy);
            }
            RequireEqual(LightsaberClipSignature(source),
                LightsaberClipSignature(copy), name + " exact serialized copy");
            return copy;
        }

        private static AnimationClip CreateOrUpdateDiagonalSlashTransitionClip(
            string path,
            string name,
            IReadOnlyDictionary<string, DiagonalSlashLocalPose> from,
            IReadOnlyDictionary<string, DiagonalSlashLocalPose> to)
        {
            if (!from.Keys.OrderBy(item => item, StringComparer.Ordinal)
                    .SequenceEqual(to.Keys.OrderBy(item => item, StringComparer.Ordinal)))
                throw new InvalidOperationException(
                    name + " pose path sets differ.");
            var generated = new AnimationClip
            {
                name = name,
                frameRate = 60f,
                legacy = false,
                wrapMode = WrapMode.ClampForever
            };
            foreach (string pathKey in from.Keys.OrderBy(item => item, StringComparer.Ordinal))
            {
                DiagonalSlashLocalPose a = from[pathKey];
                DiagonalSlashLocalPose b = to[pathKey];
                Quaternion endRotation = b.Rotation;
                if (Quaternion.Dot(a.Rotation, endRotation) < 0f)
                    endRotation = new Quaternion(
                        -endRotation.x, -endRotation.y, -endRotation.z, -endRotation.w);
                SetDiagonalSlashCurve(generated, pathKey, "m_LocalPosition.x",
                    a.Position.x, b.Position.x);
                SetDiagonalSlashCurve(generated, pathKey, "m_LocalPosition.y",
                    a.Position.y, b.Position.y);
                SetDiagonalSlashCurve(generated, pathKey, "m_LocalPosition.z",
                    a.Position.z, b.Position.z);
                SetDiagonalSlashCurve(generated, pathKey, "m_LocalRotation.x",
                    a.Rotation.x, endRotation.x);
                SetDiagonalSlashCurve(generated, pathKey, "m_LocalRotation.y",
                    a.Rotation.y, endRotation.y);
                SetDiagonalSlashCurve(generated, pathKey, "m_LocalRotation.z",
                    a.Rotation.z, endRotation.z);
                SetDiagonalSlashCurve(generated, pathKey, "m_LocalRotation.w",
                    a.Rotation.w, endRotation.w);
                SetDiagonalSlashCurve(generated, pathKey, "m_LocalScale.x",
                    a.Scale.x, b.Scale.x);
                SetDiagonalSlashCurve(generated, pathKey, "m_LocalScale.y",
                    a.Scale.y, b.Scale.y);
                SetDiagonalSlashCurve(generated, pathKey, "m_LocalScale.z",
                    a.Scale.z, b.Scale.z);
            }
            generated.EnsureQuaternionContinuity();
            AnimationClipSettings settings = AnimationUtility.GetAnimationClipSettings(generated);
            settings.loopTime = false;
            settings.loopBlend = false;
            AnimationUtility.SetAnimationClipSettings(generated, settings);
            AnimationClip existing = AssetDatabase.LoadAssetAtPath<AnimationClip>(path);
            if (existing == null)
            {
                AssetDatabase.CreateAsset(generated, path);
                existing = generated;
            }
            else
            {
                EditorUtility.CopySerialized(generated, existing);
                existing.name = name;
                EditorUtility.SetDirty(existing);
                UnityEngine.Object.DestroyImmediate(generated);
            }
            RequireTransitionClipDuration(existing, name);
            return existing;
        }

        private static void SetDiagonalSlashCurve(
            AnimationClip clip,
            string path,
            string property,
            float from,
            float to)
        {
            var first = new Keyframe(0f, from, 0f, 0f);
            var last = new Keyframe(DiagonalSlashTransitionSeconds, to, 0f, 0f);
            var curve = new AnimationCurve(first, last)
            {
                preWrapMode = WrapMode.ClampForever,
                postWrapMode = WrapMode.ClampForever
            };
            AnimationUtility.SetEditorCurve(
                clip,
                EditorCurveBinding.FloatCurve(path, typeof(Transform), property),
                curve);
        }

        private static AnimatorController CreateOrUpdateDiagonalSlashController(
            AnimationClip startTransition,
            AnimationClip slash,
            AnimationClip mirrorTransition,
            AnimationClip mirror)
        {
            AnimatorController controller =
                AssetDatabase.LoadAssetAtPath<AnimatorController>(
                    DiagonalSlashControllerPath);
            if (controller == null)
                controller = AnimatorController.CreateAnimatorControllerAtPath(
                    DiagonalSlashControllerPath);
            while (controller.layers.Length > 1)
                controller.RemoveLayer(controller.layers.Length - 1);
            if (controller.layers.Length != 1)
                throw new InvalidOperationException(
                    "Lightsaber_DiagonalSlash controller must contain one layer.");
            AnimatorControllerLayer layer = controller.layers[0];
            AnimatorStateMachine stateMachine = layer.stateMachine;
            foreach (AnimatorState state in stateMachine.states
                .Select(item => item.state).ToArray())
                stateMachine.RemoveState(state);
            foreach (AnimatorStateMachine nested in stateMachine.stateMachines
                .Select(item => item.stateMachine).ToArray())
                stateMachine.RemoveStateMachine(nested);
            controller.parameters = Array.Empty<AnimatorControllerParameter>();
            layer.name = "Lightsaber Diagonal Slash Sequence";
            layer.defaultWeight = 1f;
            layer.blendingMode = AnimatorLayerBlendingMode.Override;
            layer.avatarMask = null;

            AnimatorState startState = AddDiagonalSlashState(
                stateMachine, DiagonalSlashStartTransitionStateName, startTransition);
            AnimatorState slashState = AddDiagonalSlashState(
                stateMachine, DiagonalSlashSourceStateName, slash);
            AnimatorState bridgeState = AddDiagonalSlashState(
                stateMachine, DiagonalSlashMirrorTransitionStateName, mirrorTransition);
            AnimatorState mirrorState = AddDiagonalSlashState(
                stateMachine, DiagonalSlashMirrorStateName, mirror);
            AddImmediateDiagonalSlashTransition(startState, slashState);
            AddImmediateDiagonalSlashTransition(slashState, bridgeState);
            AddImmediateDiagonalSlashTransition(bridgeState, mirrorState);
            AddImmediateDiagonalSlashTransition(mirrorState, startState);
            stateMachine.defaultState = startState;
            controller.layers = new[] { layer };
            EditorUtility.SetDirty(stateMachine);
            EditorUtility.SetDirty(controller);
            return controller;
        }

        private static AnimatorState AddDiagonalSlashState(
            AnimatorStateMachine stateMachine,
            string name,
            Motion motion)
        {
            AnimatorState state = stateMachine.AddState(name);
            state.motion = motion;
            state.speed = 1f;
            state.cycleOffset = 0f;
            state.mirror = false;
            state.writeDefaultValues = false;
            return state;
        }

        private static void AddImmediateDiagonalSlashTransition(
            AnimatorState source,
            AnimatorState destination)
        {
            AnimatorStateTransition transition = source.AddTransition(destination);
            transition.hasExitTime = true;
            transition.exitTime = 1f;
            transition.hasFixedDuration = true;
            transition.duration = 0f;
            transition.offset = 0f;
            transition.interruptionSource = TransitionInterruptionSource.None;
            transition.orderedInterruption = true;
            transition.canTransitionToSelf = false;
        }

        private static AnimatorState RequireDiagonalSlashState(
            IEnumerable<AnimatorState> states,
            string name,
            Motion motion)
        {
            AnimatorState state = states.SingleOrDefault(item => item.name == name) ??
                throw new InvalidOperationException(
                    "Lightsaber_DiagonalSlash state is missing: " + name);
            if (motion != null && state.motion != motion)
                throw new InvalidOperationException(
                    "Lightsaber_DiagonalSlash state motion differs: " + name);
            return state;
        }

        private static void RequireImmediateDiagonalSlashTransition(
            AnimatorState source,
            AnimatorState destination,
            string label)
        {
            if (source.transitions.Length != 1)
                throw new InvalidOperationException(label + " transition count differs.");
            AnimatorStateTransition transition = source.transitions[0];
            if (transition.destinationState != destination || !transition.hasExitTime ||
                Mathf.Abs(transition.exitTime - 1f) > 0.0001f ||
                !transition.hasFixedDuration || Mathf.Abs(transition.duration) > 0.0001f ||
                Mathf.Abs(transition.offset) > 0.0001f ||
                transition.conditions.Length != 0 || transition.canTransitionToSelf)
                throw new InvalidOperationException(label + " transition settings differ.");
        }

        private static void RequireTransitionClipDuration(AnimationClip clip, string label)
        {
            if (Mathf.Abs(clip.length - DiagonalSlashTransitionSeconds) > 0.0001f ||
                Mathf.Abs(clip.frameRate - 60f) > 0.0001f || clip.isLooping)
                throw new InvalidOperationException(
                    label + " must be exactly 0.4 seconds and non-looping.");
        }

        private static T RequireDiagonalSlashAsset<T>(string path)
            where T : UnityEngine.Object
        {
            return AssetDatabase.LoadAssetAtPath<T>(path) ??
                throw new InvalidOperationException(
                    "Lightsaber_DiagonalSlash asset is missing: " + path);
        }

        private static Dictionary<string, DiagonalSlashLocalPose>
            CaptureDiagonalSlashPose(Transform root, Transform prop)
        {
            return root.GetComponentsInChildren<Transform>(true)
                .Where(item => item != root &&
                    (prop == null || (item != prop && !item.IsChildOf(prop))))
                .ToDictionary(
                    item => AnimationUtility.CalculateTransformPath(item, root),
                    item => new DiagonalSlashLocalPose(
                        item.localPosition, item.localRotation, item.localScale),
                    StringComparer.Ordinal);
        }

        private static Dictionary<string, DiagonalSlashLocalPose>
            SampleDiagonalSlashPose(
                GameObject target,
                Transform prop,
                AnimationClip clip,
            float time,
            IReadOnlyDictionary<string, DiagonalSlashLocalPose> restorePose)
        {
            Scene previewScene = EditorSceneManager.NewPreviewScene();
            GameObject probe = null;
            try
            {
                probe = new GameObject("LightsaberDiagonalSlashPoseProbe")
                {
                    hideFlags = HideFlags.HideAndDontSave
                };
                SceneManager.MoveGameObjectToScene(probe, previewScene);
                Animator sourceAnimator = target.GetComponent<Animator>();
                if (sourceAnimator != null)
                {
                    Animator probeAnimator = probe.AddComponent<Animator>();
                    probeAnimator.avatar = sourceAnimator.avatar;
                    probeAnimator.applyRootMotion = false;
                    probeAnimator.enabled = false;
                }
                var nodes = new Dictionary<string, Transform>(StringComparer.Ordinal)
                {
                    [string.Empty] = probe.transform
                };
                foreach (KeyValuePair<string, DiagonalSlashLocalPose> item in restorePose
                    .OrderBy(entry => entry.Key.Count(character => character == '/'))
                    .ThenBy(entry => entry.Key, StringComparer.Ordinal))
                {
                    int separator = item.Key.LastIndexOf('/');
                    string parentPath = separator < 0
                        ? string.Empty
                        : item.Key.Substring(0, separator);
                    string name = separator < 0
                        ? item.Key
                        : item.Key.Substring(separator + 1);
                    if (!nodes.TryGetValue(parentPath, out Transform parent))
                        throw new InvalidOperationException(
                            "Pose-probe parent path is missing: " + parentPath);
                    Transform node = new GameObject(name).transform;
                    node.SetParent(parent, false);
                    node.localPosition = item.Value.Position;
                    node.localRotation = item.Value.Rotation;
                    node.localScale = item.Value.Scale;
                    nodes.Add(item.Key, node);
                }
                clip.SampleAnimation(probe, Mathf.Clamp(time, 0f, clip.length));
                return CaptureDiagonalSlashPose(probe.transform, null);
            }
            finally
            {
                if (probe != null) UnityEngine.Object.DestroyImmediate(probe);
                EditorSceneManager.ClosePreviewScene(previewScene);
            }
        }

        private static void RequireDiagonalSlashPoseEqual(
            IReadOnlyDictionary<string, DiagonalSlashLocalPose> expected,
            IReadOnlyDictionary<string, DiagonalSlashLocalPose> actual,
            string label)
        {
            if (expected.Count != actual.Count || expected.Keys.Any(key => !actual.ContainsKey(key)))
                throw new InvalidOperationException(label + " path set differs.");
            foreach (KeyValuePair<string, DiagonalSlashLocalPose> item in expected)
            {
                DiagonalSlashLocalPose value = actual[item.Key];
                if (Vector3.Distance(item.Value.Position, value.Position) > 0.0001f ||
                    Quaternion.Angle(item.Value.Rotation, value.Rotation) > 0.02f ||
                    Vector3.Distance(item.Value.Scale, value.Scale) > 0.0001f)
                    throw new InvalidOperationException(
                        label + " differs at " + item.Key +
                        ". positionDelta=" + Num(Vector3.Distance(
                            item.Value.Position, value.Position)) +
                        "|rotationDelta=" + Num(Quaternion.Angle(
                            item.Value.Rotation, value.Rotation)) +
                        "|scaleDelta=" + Num(Vector3.Distance(
                            item.Value.Scale, value.Scale)) + ".");
            }
        }

        [MenuItem("Bellerophon/Player/Inspect Lightsaber Thrust Stabbing Sources")]
        internal static void InspectLightsaberThrustStabbingSources()
        {
            RequireEditMode();
            int consoleErrorsBefore = ConsoleErrorCount();
            Scene scene = RequireScene();
            string supplied = Absolute(ThrustStabbingSourceRelativePath);
            if (!File.Exists(supplied))
                throw new FileNotFoundException(
                    "Supplied lightsaber stabbing FBX is missing.", supplied);
            GameObject target = FindUnique(scene, ThrustTargetName);
            GameObject enter = FindUnique(scene, ThrustModeEnterTargetName);
            Animator targetAnimator = target.GetComponent<Animator>() ??
                throw new InvalidOperationException(
                    ThrustTargetName + " Animator is missing.");
            Animator enterAnimator = enter.GetComponent<Animator>() ??
                throw new InvalidOperationException(
                    ThrustModeEnterTargetName + " Animator is missing.");
            if (targetAnimator.avatar == null || enterAnimator.avatar == null ||
                targetAnimator.avatar != enterAnimator.avatar)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust and Lightsaber_ThrustMode_Enter Avatars differ.");
            Transform targetHand = RequireRightHand(target);
            Transform targetProp = RequireLightsaberProp(targetHand, target.name);
            Transform enterProp = RequireLightsaberProp(
                RequireRightHand(enter), enter.name);
            RequireAuthoredPropTransform(targetProp, target.name);
            if (targetProp.parent != targetHand || enterProp.parent != RequireRightHand(enter))
                throw new InvalidOperationException(
                    "Lightsaber props must remain direct RightHand children.");
            int existingAssetCount = Directory.Exists(Absolute(ThrustAssetFolder))
                ? Directory.GetFiles(
                    Absolute(ThrustAssetFolder), "*", SearchOption.AllDirectories).Length
                : 0;
            RequireNoNewUnityConsoleErrors(consoleErrorsBefore);
            Debug.Log(
                "[LightsaberThrustStabbing] Sources inspected read-only." +
                " suppliedHash=" + Sha256File(supplied) +
                "|existingAssetFileCount=" + existingAssetCount +
                "|targetController=" +
                    ObjectIdentity(targetAnimator.runtimeAnimatorController) +
                "|enterController=" +
                    ObjectIdentity(enterAnimator.runtimeAnimatorController) +
                "|targetPropDirectRightHandChild=True" +
                "|verificationTargetTransformManipulated=False");
        }

