        [MenuItem(
            "Bellerophon/Player/Inspect Lightsaber Thrust Arm-Pop Sources")]
        internal static void InspectLightsaberThrustArmPopSources()
        {
            RequireEditMode();
            int consoleErrorsBefore = ConsoleErrorCount();
            Scene scene = RequireScene();
            GameObject target = FindUnique(scene, ThrustTargetName);
            Transform hand = RequireRightHand(target);
            Transform prop = RequireLightsaberProp(hand, target.name);
            AnimationClip bridge = RequireDiagonalSlashAsset<AnimationClip>(
                ThrustStabbingBridgeClipPath);
            AnimationClip hold = RequireDiagonalSlashAsset<AnimationClip>(
                ThrustStabbingHoldClipPath);
            Dictionary<string, DiagonalSlashLocalPose> start =
                CaptureLightsaberThrustModeEnterLastPose(scene, out _);
            Dictionary<string, DiagonalSlashLocalPose> holdEnd =
                SampleDiagonalSlashPose(
                    target, prop, hold, hold.length, start);
            Dictionary<string, DiagonalSlashLocalPose> bridgeStart =
                SampleDiagonalSlashPose(target, prop, bridge, 0f, start);
            float boundaryArmDelta = MaximumStabbingRightArmRotationDelta(
                holdEnd, bridgeStart);
            float boundaryPropDelta = Quaternion.Angle(
                EvaluatePropRotation(hold, hold.length),
                EvaluatePropRotation(bridge, 0f));
            float bridgeMaximumFrameStep =
                MeasureMaximumStabbingRightArmFrameStep(
                    target, prop, bridge, start);
            RequireNoNewUnityConsoleErrors(consoleErrorsBefore);
            Debug.Log(
                "[LightsaberThrustArmPop] Sources inspected read-only. " +
                "holdToBridgeArmRotationDelta=" + Num(boundaryArmDelta) +
                "|holdToBridgePropRotationDelta=" + Num(boundaryPropDelta) +
                "|bridgeMaximumFrameStep=" + Num(bridgeMaximumFrameStep) +
                "|bridgeSeconds=" + Num(bridge.length) +
                "|verificationTargetTransformManipulated=False");
        }

        [MenuItem(
            "Bellerophon/Player/Apply Lightsaber Thrust Arm-Pop Correction")]
        internal static void ApplyLightsaberThrustArmPopCorrection()
        {
            RequireEditMode();
            int consoleErrorsBefore = ConsoleErrorCount();
            Scene scene = RequireScene();
            if (scene.isDirty)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust arm-pop correction requires a clean scene.");
            GameObject target = FindUnique(scene, ThrustTargetName);
            Animator animator = target.GetComponent<Animator>() ??
                throw new InvalidOperationException(
                    ThrustTargetName + " Animator is missing.");
            Transform hand = RequireRightHand(target);
            Transform prop = RequireLightsaberProp(hand, target.name);
            var rootBefore = new TransformSnapshot(target.transform);
            var propBefore = new TransformSnapshot(prop);
            Dictionary<string, DiagonalSlashLocalPose> scenePoseBefore =
                CaptureDiagonalSlashPose(target.transform, prop);
            string rendererBefore = RendererSignature(target.transform);
            string controllerBefore = ObjectIdentity(
                animator.runtimeAnimatorController);
            string suppliedHash = Sha256File(
                Absolute(ThrustStabbingSourceRelativePath));
            string copiedHash = Sha256File(Absolute(ThrustStabbingSourcePath));
            AnimationClip bridge = RequireDiagonalSlashAsset<AnimationClip>(
                ThrustStabbingBridgeClipPath);
            AnimationClip exact = RequireDiagonalSlashAsset<AnimationClip>(
                ThrustStabbingExactClipPath);
            AnimationClip hold = RequireDiagonalSlashAsset<AnimationClip>(
                ThrustStabbingHoldClipPath);
            string unapprovedBefore = StabbingUnapprovedClipSignature(bridge);
            string exactUnapprovedBefore =
                StabbingUnapprovedClipSignature(exact);
            Dictionary<string, DiagonalSlashLocalPose> start =
                CaptureLightsaberThrustModeEnterLastPose(scene, out _);

            CreateOrUpdateStabbingRightHandBladeForwardClip(
                target,
                prop,
                exact,
                ThrustStabbingExactClipPath,
                "LightsaberThrust_Stabbing_SourceExact",
                start,
                EvaluatePropRotation(exact, 0f));
            exact = RequireDiagonalSlashAsset<AnimationClip>(
                ThrustStabbingExactClipPath);
            Dictionary<string, DiagonalSlashLocalPose> exactEnd =
                SampleDiagonalSlashPose(
                    target, prop, exact, exact.length, start);
            Quaternion exactEndPropRotation =
                EvaluatePropRotation(exact, exact.length);
            ApplyStabbingRightArmHoldPose(
                hold, exactEnd, exactEndPropRotation);

            Dictionary<string, DiagonalSlashLocalPose> holdEnd =
                SampleDiagonalSlashPose(
                    target, prop, hold, hold.length, start);
            Dictionary<string, DiagonalSlashLocalPose> bridgeEnd =
                SampleDiagonalSlashPose(
                    target, prop, bridge, bridge.length, start);
            Quaternion holdPropEnd = EvaluatePropRotation(hold, hold.length);
            Quaternion bridgePropEnd = EvaluatePropRotation(
                bridge, bridge.length);

            ApplySmoothedStabbingRightArmBridge(
                target,
                prop,
                bridge,
                holdEnd,
                bridgeEnd,
                holdPropEnd,
                bridgePropEnd,
                start);
            AssetDatabase.SaveAssets();
            AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);

            bridge = RequireDiagonalSlashAsset<AnimationClip>(
                ThrustStabbingBridgeClipPath);
            RequireEqual(
                unapprovedBefore,
                StabbingUnapprovedClipSignature(bridge),
                "Lightsaber_Thrust bridge curves outside the approved right arm");
            RequireEqual(
                exactUnapprovedBefore,
                StabbingUnapprovedClipSignature(exact),
                "Lightsaber_Thrust source curves outside the approved right arm");
            RequireEqual(suppliedHash,
                Sha256File(Absolute(ThrustStabbingSourceRelativePath)),
                "protected supplied stabbing FBX");
            RequireEqual(copiedHash,
                Sha256File(Absolute(ThrustStabbingSourcePath)),
                "protected imported stabbing FBX");
            RequireEqual(controllerBefore,
                ObjectIdentity(animator.runtimeAnimatorController),
                "Lightsaber_Thrust Animator controller");
            rootBefore.RequireUnchanged();
            propBefore.RequireUnchanged();
            RequireDiagonalSlashPoseEqual(
                scenePoseBefore,
                CaptureDiagonalSlashPose(target.transform, prop),
                "Lightsaber_Thrust scene pose after arm-pop correction");
            RequireEqual(rendererBefore, RendererSignature(target.transform),
                "Lightsaber_Thrust renderer hierarchy");
            RequireLightsaberThrustArmPopCorrection(scene);
            RequireNoNewUnityConsoleErrors(consoleErrorsBefore);
            Debug.Log(
                "[LightsaberThrustArmPop] Corrected only the looping bridge " +
                "right-arm rotations. holdToBridgeArmRotationDelta=0.000000" +
                "|holdToBridgePropRotationDelta=0.000000" +
                "|bridgeMaximumFrameStep=" +
                    Num(MeasureMaximumStabbingRightArmFrameStep(
                        target, prop, bridge, start)) +
                "|sourceMaximumFrameStep=" +
                    Num(MeasureMaximumStabbingRightArmFrameStep(
                        target, prop, exact, start)) +
                "|bridgeSeconds=" + Num(bridge.length));
        }

