            Dictionary<string, DiagonalSlashLocalPose> poseBefore =
                CaptureDiagonalSlashPose(target.transform, prop);
            SkinnedMeshRenderer renderer =
                RequireLightsaberThrustBodyRenderer(target.transform);
            Mesh meshBefore = renderer.sharedMesh;
            string controllerBefore = ObjectIdentity(
                target.GetComponent<Animator>()?.runtimeAnimatorController);

            DistalForearmSkinningAnalysis analysis =
                AnalyzeLightsaberThrustDistalForearmSkinning(scene, target);
            string absoluteReport = Absolute(
                ThrustDistalForearmDiagnosticRelativePath);
            Directory.CreateDirectory(Path.GetDirectoryName(absoluteReport) ??
                throw new InvalidOperationException(
                    "Lightsaber_Thrust distal-forearm diagnostic directory " +
                    "is unavailable."));
            File.WriteAllText(
                absoluteReport,
                analysis.Describe() + Environment.NewLine +
                "verificationTargetTransformManipulated=False" +
                Environment.NewLine +
                "animationMotionModified=False" + Environment.NewLine,
                Encoding.UTF8);

            rootBefore.RequireUnchanged();
            propBefore.RequireUnchanged();
            RequireDiagonalSlashPoseEqual(
                poseBefore,
                CaptureDiagonalSlashPose(target.transform, prop),
                "Lightsaber_Thrust pose after distal-forearm inspection");
            RequireEqual(
                ObjectIdentity(meshBefore),
                ObjectIdentity(renderer.sharedMesh),
                "Lightsaber_Thrust body mesh after read-only inspection");
            RequireEqual(
                controllerBefore,
                ObjectIdentity(
                    target.GetComponent<Animator>()?.runtimeAnimatorController),
                "Lightsaber_Thrust Animator controller after inspection");
            RequireNoNewUnityConsoleErrors(consoleErrorsBefore);
            Debug.Log(
                "[LightsaberThrustDistalForearmSkinning] Inspected read-only. " +
                analysis.Describe() +
                "|verificationTargetTransformManipulated=False" +
                "|animationMotionModified=False");
        }

        private static DistalForearmSkinningAnalysis
            AnalyzeLightsaberThrustDistalForearmSkinning(
                Scene scene,
                GameObject target)
        {
            AnimationClip clip = RequireDiagonalSlashAsset<AnimationClip>(
                ThrustStabbingExactClipPath);
            Dictionary<string, DiagonalSlashLocalPose> restorePose =
                CaptureLightsaberThrustModeEnterLastPose(scene, out _);
            Scene previewScene = EditorSceneManager.NewPreviewScene();
            GameObject probe = null;
            try
            {
                probe = UnityEngine.Object.Instantiate(target);
                probe.name = "LightsaberThrustDistalForearmProbe";
                EditorSceneManager.MoveGameObjectToScene(probe, previewScene);
                Animator probeAnimator = probe.GetComponent<Animator>();
                if (probeAnimator != null) probeAnimator.enabled = false;
                Transform probeRoot = probe.transform;
                SkinnedMeshRenderer renderer =
                    RequireLightsaberThrustBodyRenderer(probeRoot);
                Mesh shared = renderer.sharedMesh ??
                    throw new InvalidOperationException(
                        "Lightsaber_Thrust body mesh is missing.");
                BoneWeight[] weights = shared.boneWeights;
                int[] triangles = shared.triangles;
                if (weights.Length != shared.vertexCount)
                    throw new InvalidOperationException(
                        "Lightsaber_Thrust body skin weights are unavailable.");
                Transform[] bones = renderer.bones;
                Transform foreArm = RequirePoseProbeBone(
                    probeRoot, RightForeArmPath);
                Transform hand = RequirePoseProbeBone(probeRoot, RightHandPath);
                Transform upperArm = RequirePoseProbeBone(
                    probeRoot, RightArmPath);
                int foreIndex = Array.IndexOf(bones, foreArm);
                int handIndex = Array.IndexOf(bones, hand);
                int upperIndex = Array.IndexOf(bones, upperArm);
                if (foreIndex < 0 || handIndex < 0 || upperIndex < 0)
                    throw new InvalidOperationException(
                        "Lightsaber_Thrust body renderer does not contain the " +
                        "complete right-arm skin chain.");

                ApplyThrustModeEnterPose(probeRoot, restorePose);
                clip.SampleAnimation(probe, 0f);
                Vector3[] reference = BakeWorldVertices(renderer);
                Vector3 forePosition = foreArm.position;
                Vector3 handPosition = hand.position;
                Vector3 axis = handPosition - forePosition;
                float length = axis.magnitude;
                if (length <= 0.0001f)
                    throw new InvalidOperationException(
                        "Lightsaber_Thrust forearm length is degenerate.");
                axis /= length;
                var selected = new bool[shared.vertexCount];
                for (int vertex = 0; vertex < reference.Length; vertex++)
                {
                    float foreWeight = BoneInfluence(weights[vertex], foreIndex);
                    float handWeight = BoneInfluence(weights[vertex], handIndex);
                    float upperWeight = BoneInfluence(weights[vertex], upperIndex);
                    float chainWeight = foreWeight + handWeight + upperWeight;
                    float along = Vector3.Dot(
                        reference[vertex] - forePosition, axis) / length;
                    Vector3 radial = reference[vertex] -
                        (forePosition + axis * along * length);
                    bool inRedBoxRegion = along >= 0.02f && along <= 0.72f &&
                        radial.magnitude <= 0.20f && chainWeight >= 0.72f &&
                        foreWeight >= 0.12f;
                    if (!inRedBoxRegion) continue;
                    selected[vertex] = true;
                }
                ExpandDistalForearmSelectionAcrossContaminatedNeighbors(
                    selected,
                    triangles,
                    weights,
                    bones,
                    upperArm,
                    upperIndex,
                    foreIndex,
                    handIndex);
                int selectedVertexCount = 0;
                int mixedForeHandVertexCount = 0;
                int abruptWeightVertexCount = 0;
                int nonRightArmInfluenceVertexCount = 0;
                float maximumNonRightArmInfluence = 0f;
                for (int vertex = 0; vertex < selected.Length; vertex++)
                {
                    if (!selected[vertex]) continue;
                    selectedVertexCount++;
                    float foreWeight = BoneInfluence(weights[vertex], foreIndex);
                    float handWeight = BoneInfluence(weights[vertex], handIndex);
                    float along = Vector3.Dot(
                        reference[vertex] - forePosition, axis) / length;
                    if (foreWeight >= 0.08f && handWeight >= 0.08f)
                        mixedForeHandVertexCount++;
                    if ((along < 0.82f && handWeight > 0.25f) ||
                        (along > 0.88f && foreWeight > 0.75f))
                        abruptWeightVertexCount++;
                    float nonRightArmInfluence =
                        NonRightArmChainInfluence(weights[vertex], bones, upperArm);
                    if (nonRightArmInfluence > 0.001f)
                        nonRightArmInfluenceVertexCount++;
                    maximumNonRightArmInfluence = Mathf.Max(
                        maximumNonRightArmInfluence,
                        nonRightArmInfluence);
                }

                var selectedTriangles = new List<int>();
                for (int index = 0; index + 2 < triangles.Length; index += 3)
                {
                    int selectedCount =
                        (selected[triangles[index]] ? 1 : 0) +
                        (selected[triangles[index + 1]] ? 1 : 0) +
                        (selected[triangles[index + 2]] ? 1 : 0);
                    if (selectedCount >= 2) selectedTriangles.Add(index);
                }
                if (selectedVertexCount < 12 || selectedTriangles.Count < 4)
                    throw new InvalidOperationException(
                        "Lightsaber_Thrust distal-forearm skin region could not " +
                        "be isolated. vertices=" + selectedVertexCount +
                        "|triangles=" + selectedTriangles.Count + ".");

                float minimumAreaRatio = float.PositiveInfinity;
                float worstTime = 0f;
                int worstTriangle = -1;
                int frameCount = Mathf.Max(
                    2, Mathf.RoundToInt(clip.length * 60f));
                for (int frame = 0; frame <= frameCount; frame++)
                {
                    float time = clip.length * frame / frameCount;
                    ApplyThrustModeEnterPose(probeRoot, restorePose);
                    clip.SampleAnimation(probe, time);
                    Vector3[] posed = BakeWorldVertices(renderer);
                    foreach (int triangleIndex in selectedTriangles)
                    {
                        int a = triangles[triangleIndex];
                        int b = triangles[triangleIndex + 1];
                        int c = triangles[triangleIndex + 2];
                        float referenceArea = TriangleArea(
                            reference[a], reference[b], reference[c]);
                        if (referenceArea <= 0.0000001f) continue;
                        float areaRatio = TriangleArea(
                            posed[a], posed[b], posed[c]) / referenceArea;
                        if (areaRatio >= minimumAreaRatio) continue;
                        minimumAreaRatio = areaRatio;
                        worstTime = time;
                        worstTriangle = triangleIndex / 3;
                    }
                }
                if (float.IsPositiveInfinity(minimumAreaRatio))
                    minimumAreaRatio = 0f;
                string worstWeights = worstTriangle < 0
                    ? "none"
                    : string.Join(",", Enumerable.Range(0, 3).Select(offset =>
                        DescribeBoneWeight(
                            weights[triangles[worstTriangle * 3 + offset]],
                            bones)));
                string worstAxialFractions = worstTriangle < 0
                    ? "none"
                    : string.Join(",", Enumerable.Range(0, 3).Select(offset =>
                        Num(Vector3.Dot(
                            reference[triangles[worstTriangle * 3 + offset]] -
                                forePosition,
                            axis) / length)));
                return new DistalForearmSkinningAnalysis(
                    AssetDatabase.GetAssetPath(shared),
                    shared.vertexCount,
                    selectedVertexCount,
                    selectedTriangles.Count,
                    mixedForeHandVertexCount,
                    abruptWeightVertexCount,
                    nonRightArmInfluenceVertexCount,
                    maximumNonRightArmInfluence,
                    minimumAreaRatio,
                    worstTime,
                    worstTriangle,
                    worstWeights,
                    worstAxialFractions);
            }
            finally
            {
                if (probe != null) UnityEngine.Object.DestroyImmediate(probe);
                EditorSceneManager.ClosePreviewScene(previewScene);
            }
        }

        private static SkinnedMeshRenderer
            RequireLightsaberThrustBodyRenderer(Transform root)
        {
            SkinnedMeshRenderer[] matches = root
                .GetComponentsInChildren<SkinnedMeshRenderer>(true)
                .Where(item => item.name == "char1")
                .ToArray();
            if (matches.Length != 1)
                throw new InvalidOperationException(
                    "Expected one Lightsaber_Thrust char1 skin renderer; found " +
                    matches.Length + ".");
            return matches[0];
        }

        private static Vector3[] BakeWorldVertices(
            SkinnedMeshRenderer renderer)
        {
            var baked = new Mesh();
            try
            {
                renderer.BakeMesh(baked);
                return baked.vertices.Select(
                    renderer.transform.TransformPoint).ToArray();
            }
            finally
            {
                UnityEngine.Object.DestroyImmediate(baked);
            }
        }

        private static float TriangleArea(Vector3 a, Vector3 b, Vector3 c)
        {
            return Vector3.Cross(b - a, c - a).magnitude * 0.5f;
        }

        private static string DescribeBoneWeight(
            BoneWeight weight,
            IReadOnlyList<Transform> bones)
        {
            var influences = new[]
            {
                new KeyValuePair<int, float>(weight.boneIndex0, weight.weight0),
                new KeyValuePair<int, float>(weight.boneIndex1, weight.weight1),
                new KeyValuePair<int, float>(weight.boneIndex2, weight.weight2),
                new KeyValuePair<int, float>(weight.boneIndex3, weight.weight3)
            };
            return "[" + string.Join("+", influences
                .Where(item => item.Value > 0.0001f)
                .Select(item =>
                    (item.Key >= 0 && item.Key < bones.Count &&
                     bones[item.Key] != null
                        ? bones[item.Key].name
                        : "bone" + item.Key) + "=" + Num(item.Value))) + "]";
        }

        private static float NonRightArmChainInfluence(
            BoneWeight weight,
            IReadOnlyList<Transform> bones,
            Transform rightArm)
        {
            var influences = new[]
            {
                new KeyValuePair<int, float>(weight.boneIndex0, weight.weight0),
                new KeyValuePair<int, float>(weight.boneIndex1, weight.weight1),
                new KeyValuePair<int, float>(weight.boneIndex2, weight.weight2),
                new KeyValuePair<int, float>(weight.boneIndex3, weight.weight3)
            };
            return influences.Where(item => item.Value > 0.0001f)
                .Where(item => item.Key < 0 || item.Key >= bones.Count ||
                    bones[item.Key] == null ||
                    (bones[item.Key] != rightArm &&
                     !bones[item.Key].IsChildOf(rightArm)))
                .Sum(item => item.Value);
        }

        private static void
            ExpandDistalForearmSelectionAcrossContaminatedNeighbors(
                bool[] selected,
                IReadOnlyList<int> triangles,
                IReadOnlyList<BoneWeight> weights,
                IReadOnlyList<Transform> bones,
                Transform upperArm,
                int upperIndex,
                int foreIndex,
                int handIndex)
        {
            for (int ring = 0; ring < 3; ring++)
            {
                bool changed = false;
                var expanded = (bool[])selected.Clone();
                for (int index = 0; index + 2 < triangles.Count; index += 3)
                {
                    int a = triangles[index];
                    int b = triangles[index + 1];
                    int c = triangles[index + 2];
                    if (!selected[a] && !selected[b] && !selected[c]) continue;
                    foreach (int vertex in new[] { a, b, c })
                    {
                        if (expanded[vertex]) continue;
                        BoneWeight weight = weights[vertex];
                        float foreWeight = BoneInfluence(weight, foreIndex);
                        float armChainWeight = foreWeight +
                            BoneInfluence(weight, upperIndex) +
                            BoneInfluence(weight, handIndex);
                        float contamination = NonRightArmChainInfluence(
                            weight, bones, upperArm);
                        if (foreWeight < 0.08f || armChainWeight < 0.45f ||
                            contamination <= 0.001f)
                            continue;
                        expanded[vertex] = true;
                        changed = true;
                    }
                }
                Array.Copy(expanded, selected, selected.Length);
                if (!changed) break;
            }
        }

        private static void ExpandDistalForearmSelectionAcrossWristBlend(
            bool[] selected,
            IReadOnlyList<int> triangles,
            IReadOnlyList<BoneWeight> weights,
            int foreIndex,
            int handIndex)
        {
            for (int ring = 0; ring < 32; ring++)
            {
                bool changed = false;
                var expanded = (bool[])selected.Clone();
                for (int index = 0; index + 2 < triangles.Count; index += 3)
                {
                    int a = triangles[index];
                    int b = triangles[index + 1];
                    int c = triangles[index + 2];
                    if (!selected[a] && !selected[b] && !selected[c]) continue;
                    foreach (int vertex in new[] { a, b, c })
                    {
                        if (expanded[vertex]) continue;
                        float foreWeight = BoneInfluence(
                            weights[vertex], foreIndex);
                        float handWeight = BoneInfluence(
                            weights[vertex], handIndex);
                        if (foreWeight < 0.05f || handWeight < 0.05f) continue;
                        expanded[vertex] = true;
                        changed = true;
                    }
                }
                Array.Copy(expanded, selected, selected.Length);
                if (!changed) break;
            }
        }

        [MenuItem(
            "Bellerophon/Player/Apply Lightsaber Thrust Distal Forearm Skinning Correction")]
        internal static void ApplyLightsaberThrustDistalForearmSkinningCorrection()
        {
            RequireEditMode();
            int consoleErrorsBefore = ConsoleErrorCount();
            Scene scene = RequireScene();
            if (scene.isDirty)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust distal-forearm correction requires a " +
                    "clean scene.");
            GameObject target = FindUnique(scene, ThrustTargetName);
            Animator animator = target.GetComponent<Animator>() ??
                throw new InvalidOperationException(
                    "Lightsaber_Thrust Animator is missing.");
            Transform prop = RequireLightsaberProp(
                RequireRightHand(target), target.name);
            var rootBefore = new TransformSnapshot(target.transform);
            var propBefore = new TransformSnapshot(prop);
            Dictionary<string, DiagonalSlashLocalPose> poseBefore =
                CaptureDiagonalSlashPose(target.transform, prop);
            string controllerBefore = ObjectIdentity(
                animator.runtimeAnimatorController);
            var protectedHashes = new Dictionary<string, string>(
                StringComparer.Ordinal)
            {
                [ThrustStabbingBridgeClipPath] =
                    Sha256File(Absolute(ThrustStabbingBridgeClipPath)),
                [ThrustStabbingExactClipPath] =
                    Sha256File(Absolute(ThrustStabbingExactClipPath)),
                [ThrustStabbingHoldClipPath] =
                    Sha256File(Absolute(ThrustStabbingHoldClipPath)),
                [ThrustStabbingControllerPath] =
                    Sha256File(Absolute(ThrustStabbingControllerPath))
            };

            SkinnedMeshRenderer targetRenderer =
                RequireLightsaberThrustBodyRenderer(target.transform);
            GameObject playerModel = AssetDatabase.LoadAssetAtPath<GameObject>(
                "Assets/_Project/Art/Player/player.fbx") ??
                throw new InvalidOperationException(
                    "Player model is missing.");
            SkinnedMeshRenderer sourceRenderer = playerModel
                .GetComponentsInChildren<SkinnedMeshRenderer>(true)
                .SingleOrDefault(item => item.name == "char1") ??
                throw new InvalidOperationException(
                    "Player source char1 skin renderer is missing.");
            Mesh sourceMesh = sourceRenderer.sharedMesh ??
                throw new InvalidOperationException(
                    "Player source char1 mesh is missing.");
            BoneWeight[] correctedWeights =
                CreateDistalForearmCorrectedWeights(
                    sourceRenderer,
                    sourceMesh,
                    out int correctedVertexCount,
                    out float maximumRemovedInfluence);
            if (correctedVertexCount <= 0)
                throw new InvalidOperationException(
                    "No contaminated distal-forearm vertices were corrected.");

            EnsureFolder(ThrustDistalForearmMeshFolder);
            Mesh derived = AssetDatabase.LoadAssetAtPath<Mesh>(
                ThrustDistalForearmMeshPath);
            if (derived == null)
            {
                derived = UnityEngine.Object.Instantiate(sourceMesh);
                derived.name =
                    "LightsaberThrust_Player_DistalForearmCorrected";
                AssetDatabase.CreateAsset(
                    derived, ThrustDistalForearmMeshPath);
            }
            else
            {
                EditorUtility.CopySerialized(sourceMesh, derived);
                derived.name =
                    "LightsaberThrust_Player_DistalForearmCorrected";
            }
            derived.boneWeights = correctedWeights;
            EditorUtility.SetDirty(derived);
            AssetDatabase.SaveAssets();
            AssetDatabase.ImportAsset(
                ThrustDistalForearmMeshPath,
                ImportAssetOptions.ForceSynchronousImport |
                ImportAssetOptions.ForceUpdate);
            derived = AssetDatabase.LoadAssetAtPath<Mesh>(
                ThrustDistalForearmMeshPath) ??
                throw new InvalidOperationException(
                    "Corrected distal-forearm mesh asset was not saved.");
            RequireMeshGeometryUnchanged(sourceMesh, derived);

            targetRenderer.sharedMesh = derived;
            EditorUtility.SetDirty(targetRenderer);
            EditorSceneManager.MarkSceneDirty(scene);
            EditorSceneManager.SaveScene(scene);
            AssetDatabase.SaveAssets();

            rootBefore.RequireUnchanged();
            propBefore.RequireUnchanged();
            RequireDiagonalSlashPoseEqual(
                poseBefore,
                CaptureDiagonalSlashPose(target.transform, prop),
                "Lightsaber_Thrust pose after skinning correction");
            RequireEqual(
                controllerBefore,
                ObjectIdentity(animator.runtimeAnimatorController),
                "Lightsaber_Thrust Animator controller");
            foreach (KeyValuePair<string, string> item in protectedHashes)
                RequireEqual(
                    item.Value,
                    Sha256File(Absolute(item.Key)),
                    "protected animation asset " + item.Key);
            RequireOnlyTargetUsesDistalForearmMesh(scene, target, derived);
            DistalForearmSkinningAnalysis analysis =
                AnalyzeLightsaberThrustDistalForearmSkinning(scene, target);
            RequireDistalForearmSkinningCorrected(analysis);
            RequireNoNewUnityConsoleErrors(consoleErrorsBefore);
            Debug.Log(
                "[LightsaberThrustDistalForearmSkinning] First correction " +
                "applied only to the derived target mesh. " +
                "correctedVertexCount=" + correctedVertexCount +
                "|maximumRemovedInfluence=" +
                    Num(maximumRemovedInfluence) + "|" +
                analysis.Describe() +
                "|animationMotionModified=False");
        }

        private static BoneWeight[] CreateDistalForearmCorrectedWeights(
            SkinnedMeshRenderer sourceRenderer,
            Mesh sourceMesh,
            out int correctedVertexCount,
            out float maximumRemovedInfluence)
        {
            Transform root = sourceRenderer.transform.root;
            Transform upperArm = RequirePoseProbeBone(root, RightArmPath);
            Transform foreArm = RequirePoseProbeBone(root, RightForeArmPath);
            Transform hand = RequirePoseProbeBone(root, RightHandPath);
            Transform[] bones = sourceRenderer.bones;
            int upperIndex = Array.IndexOf(bones, upperArm);
            int foreIndex = Array.IndexOf(bones, foreArm);
            int handIndex = Array.IndexOf(bones, hand);
            if (upperIndex < 0 || foreIndex < 0 || handIndex < 0)
                throw new InvalidOperationException(
                    "Player source right-arm skin chain is incomplete.");
            Vector3 axis = hand.position - foreArm.position;
            float length = axis.magnitude;
            if (length <= 0.0001f)
                throw new InvalidOperationException(
                    "Player source forearm length is degenerate.");
            axis /= length;
            Vector3[] bindVertices = sourceMesh.vertices.Select(
                sourceRenderer.transform.TransformPoint).ToArray();
            BoneWeight[] original = sourceMesh.boneWeights;
            BoneWeight[] corrected = original.ToArray();
            correctedVertexCount = 0;
            maximumRemovedInfluence = 0f;
            for (int vertex = 0; vertex < bindVertices.Length; vertex++)
            {
                float upperWeight = BoneInfluence(original[vertex], upperIndex);
                float foreWeight = BoneInfluence(original[vertex], foreIndex);
                float armWeight = upperWeight + foreWeight;
                if (armWeight < 0.45f) continue;
                float along = Vector3.Dot(
                    bindVertices[vertex] - foreArm.position, axis) / length;
                if (along < -0.22f || along > 0.82f) continue;
                Vector3 radial = bindVertices[vertex] -
                    (foreArm.position + axis * along * length);
                if (radial.magnitude > 0.20f) continue;

                float forearmBlend = Mathf.SmoothStep(
                    0f, 1f, Mathf.InverseLerp(-0.10f, 0.22f, along));
                BoneWeight replacement = new BoneWeight
                {
                    boneIndex0 = foreIndex,
                    weight0 = forearmBlend,
                    boneIndex1 = upperIndex,
                    weight1 = 1f - forearmBlend
                };
                float weightDelta =
                    Mathf.Abs(BoneInfluence(original[vertex], foreIndex) -
                        replacement.weight0) +
                    Mathf.Abs(BoneInfluence(original[vertex], upperIndex) -
                        replacement.weight1) +
                    BoneInfluence(original[vertex], handIndex) +
                    NonRightArmChainInfluence(
                        original[vertex], bones, upperArm);
                if (weightDelta <= 0.001f) continue;
                corrected[vertex] = replacement;
                correctedVertexCount++;
                maximumRemovedInfluence = Mathf.Max(
                    maximumRemovedInfluence,
                    Mathf.Clamp01(1f - armWeight));
            }
            return corrected;
        }

        private static BoneWeight NormalizeRightArmChainWeight(
            BoneWeight source,
            IReadOnlyList<Transform> bones,
            Transform rightArm,
            int fallbackForeArmIndex)
        {
            var influences = new[]
            {
                new KeyValuePair<int, float>(source.boneIndex0, source.weight0),
                new KeyValuePair<int, float>(source.boneIndex1, source.weight1),
                new KeyValuePair<int, float>(source.boneIndex2, source.weight2),
                new KeyValuePair<int, float>(source.boneIndex3, source.weight3)
            }.Where(item => item.Value > 0.0001f &&
                item.Key >= 0 && item.Key < bones.Count &&
                bones[item.Key] != null &&
                (bones[item.Key] == rightArm ||
                 bones[item.Key].IsChildOf(rightArm)))
             .OrderByDescending(item => item.Value)
             .ToArray();
            float total = influences.Sum(item => item.Value);
            if (total <= 0.0001f)
                return new BoneWeight
                {
                    boneIndex0 = fallbackForeArmIndex,
                    weight0 = 1f
                };
            var result = new BoneWeight();
            for (int index = 0; index < influences.Length && index < 4; index++)
            {
                int boneIndex = influences[index].Key;
                float weight = influences[index].Value / total;
                switch (index)
                {
                    case 0:
                        result.boneIndex0 = boneIndex;
                        result.weight0 = weight;
                        break;
                    case 1:
                        result.boneIndex1 = boneIndex;
                        result.weight1 = weight;
                        break;
                    case 2:
                        result.boneIndex2 = boneIndex;
                        result.weight2 = weight;
                        break;
                    case 3:
                        result.boneIndex3 = boneIndex;
                        result.weight3 = weight;
                        break;
                }
            }
            return result;
        }

        private static void RequireMeshGeometryUnchanged(
            Mesh source,
            Mesh derived)
        {
            RequireEqual(source.vertexCount.ToString(), derived.vertexCount.ToString(),
                "derived mesh vertex count");
            RequireEqual(source.subMeshCount.ToString(), derived.subMeshCount.ToString(),
                "derived mesh submesh count");
            RequireEqual(
                string.Join(",", source.triangles),
                string.Join(",", derived.triangles),
                "derived mesh triangle indices");
            RequireEqual(
                string.Join("|", source.vertices.Select(Precise)),
                string.Join("|", derived.vertices.Select(Precise)),
                "derived mesh vertex positions");
        }

        private static void RequireOnlyTargetUsesDistalForearmMesh(
            Scene scene,
            GameObject target,
            Mesh derived)
        {
            SkinnedMeshRenderer[] users = scene.GetRootGameObjects()
                .SelectMany(root =>
                    root.GetComponentsInChildren<SkinnedMeshRenderer>(true))
                .Where(renderer => renderer.sharedMesh == derived)
                .ToArray();
            if (users.Length != 1 ||
                !users[0].transform.IsChildOf(target.transform))
                throw new InvalidOperationException(
                    "The derived distal-forearm mesh must be used only by " +
                    "Lightsaber_Thrust. users=" + users.Length + ".");
        }

        private static void RequireDistalForearmSkinningCorrected(
            DistalForearmSkinningAnalysis analysis)
        {
            if (analysis.MeshPath != ThrustDistalForearmMeshPath ||
                analysis.SelectedVertexCount <= 0 ||
                analysis.SelectedTriangleCount <= 0)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust does not use the approved local " +
                    "forearm-correction mesh. " + analysis.Describe());
        }

        private static void RequireDistalForearmCorrectionWeights(
            Mesh derived)
        {
            GameObject playerModel = AssetDatabase.LoadAssetAtPath<GameObject>(
                "Assets/_Project/Art/Player/player.fbx") ??
                throw new InvalidOperationException(
                    "Player model is missing.");
            SkinnedMeshRenderer sourceRenderer = playerModel
                .GetComponentsInChildren<SkinnedMeshRenderer>(true)
                .SingleOrDefault(item => item.name == "char1") ??
                throw new InvalidOperationException(
                    "Player source char1 skin renderer is missing.");
            Mesh sourceMesh = sourceRenderer.sharedMesh ??
                throw new InvalidOperationException(
                    "Player source char1 mesh is missing.");
            RequireMeshGeometryUnchanged(sourceMesh, derived);
            BoneWeight[] expected = CreateDistalForearmCorrectedWeights(
                sourceRenderer,
                sourceMesh,
                out int correctedVertexCount,
                out _);
            if (correctedVertexCount <= 0)
                throw new InvalidOperationException(
                    "Expected local forearm correction contains no vertices.");
            RequireEqual(
                BoneWeightSignature(expected),
                BoneWeightSignature(derived.boneWeights),
                "Lightsaber_Thrust approved forearm correction weights");
        }

        private static string BoneWeightSignature(
            IReadOnlyList<BoneWeight> weights)
        {
            return string.Join("|", weights.Select(weight =>
                weight.boneIndex0 + ":" + Precise(weight.weight0) + "," +
                weight.boneIndex1 + ":" + Precise(weight.weight1) + "," +
                weight.boneIndex2 + ":" + Precise(weight.weight2) + "," +
                weight.boneIndex3 + ":" + Precise(weight.weight3)));
        }

