                animator.runtimeAnimatorController);
            string meshHashBefore = File.Exists(
                Absolute(ThrustDistalForearmMeshPath))
                ? Sha256File(Absolute(ThrustDistalForearmMeshPath))
                : string.Empty;
            Dictionary<string, DiagonalSlashLocalPose> restorePose =
                CaptureLightsaberThrustModeEnterLastPose(scene, out _);
            Quaternion fallbackPropRotation = prop.localRotation;
            string[] paths =
            {
                ThrustStabbingBridgeClipPath,
                ThrustStabbingExactClipPath,
                ThrustStabbingHoldClipPath
            };
            var protectedSignatures = paths.ToDictionary(
                path => path,
                path => WristPanelProtectedClipSignature(
                    RequireDiagonalSlashAsset<AnimationClip>(path)),
                StringComparer.Ordinal);
            var correction = new WristPanelCorrectionSummary();
            foreach (string path in paths)
            {
