        private static void RebuildLightsaberThrustTopGripBaseline(
            GameObject target,
            Transform targetProp,
            IReadOnlyDictionary<string, DiagonalSlashLocalPose> start,
            Quaternion startPropRotation)
        {
            AnimationClip source = RequireSingleDiagonalSlashClip(
                ThrustStabbingSourcePath,
                "lightsaber stabbing top-grip baseline");
            Dictionary<string, DiagonalSlashLocalPose> sourceFirst =
                SampleDiagonalSlashPose(target, targetProp, source, 0f, start);
            AnimationClip bridge = CreateOrUpdateStabbingPoseClip(
                ThrustStabbingBridgeClipPath,
                "LightsaberThrust_EnterLast_To_StabbingFirst_0_2s",
                start,
                sourceFirst,
                ThrustStabbingBridgeSeconds,
                startPropRotation);
            CreateOrUpdateStabbingRightHandBladeForwardClip(
                target,
                targetProp,
                source,
                ThrustStabbingExactClipPath,
                "LightsaberThrust_Stabbing_SourceExact",
                start,
                AuthoredPropLocalRotation);
            AnimationClip exact = RequireDiagonalSlashAsset<AnimationClip>(
                ThrustStabbingExactClipPath);
            Dictionary<string, DiagonalSlashLocalPose> exactStart =
                SampleDiagonalSlashPose(target, targetProp, exact, 0f, start);
            Dictionary<string, DiagonalSlashLocalPose> exactEnd =
                SampleDiagonalSlashPose(
                    target, targetProp, exact, exact.length, start);
            Quaternion exactStartPropRotation =
                EvaluatePropRotation(exact, 0f);
            Quaternion exactEndPropRotation =
                EvaluatePropRotation(exact, exact.length);
            AnimationClip hold = CreateOrUpdateStabbingPoseClip(
                ThrustStabbingHoldClipPath,
                "LightsaberThrust_StabbingLast_Hold_0_5s",
                exactEnd,
                exactEnd,
                ThrustStabbingHoldSeconds,
                exactEndPropRotation);
            Dictionary<string, DiagonalSlashLocalPose> holdEnd =
                SampleDiagonalSlashPose(
                    target, targetProp, hold, hold.length, start);
            ApplySmoothedStabbingRightArmBridge(
                target,
                targetProp,
                bridge,
                holdEnd,
                exactStart,
                EvaluatePropRotation(hold, hold.length),
                exactStartPropRotation,
                start);
            AssetDatabase.SaveAssets();
            AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);
        }

