        private static TopGripCorrectionSummary ApplyTopGripToClip(
            GameObject target,
            Transform targetProp,
            AnimationClip baseClip,
            string assetPath,
            IReadOnlyDictionary<string, DiagonalSlashLocalPose> restorePose,
            Quaternion fallbackPropRotation,
            Transform referenceHand,
            ModelGeometry geometry)
        {
            float[] times = StabbingCorrectionSampleTimes(baseClip);
            var generated = new AnimationClip();
            EditorUtility.CopySerialized(baseClip, generated);
            generated.name = baseClip.name;
            string[] rotationPaths = TopGripRotationPaths();
            var rotations = rotationPaths.ToDictionary(
                path => path,
                _ => new List<Quaternion>(times.Length),
                StringComparer.Ordinal);
            var propPositions = new List<Vector3>(times.Length);
            var summary = new TopGripCorrectionSummary();
            Scene previewScene = EditorSceneManager.NewPreviewScene();
            GameObject probe = null;
            try
            {
                probe = CreateThrustModeEnterPoseProbe(
                    previewScene, restorePose, out Transform prop);
                Animator sourceAnimator = target.GetComponent<Animator>();
                if (sourceAnimator != null && sourceAnimator.avatar != null)
                {
                    Animator probeAnimator = probe.AddComponent<Animator>();
                    probeAnimator.avatar = sourceAnimator.avatar;
                    probeAnimator.applyRootMotion = false;
                    probeAnimator.enabled = false;
                }
                Transform root = probe.transform;
                for (int index = 0; index < times.Length; index++)
                {
                    ApplyThrustModeEnterPose(root, restorePose);
                    prop.localPosition = targetProp.localPosition;
                    prop.localRotation = fallbackPropRotation;
                    prop.localScale = targetProp.localScale;
                    baseClip.SampleAnimation(probe, times[index]);
                    Transform hand = RequirePoseProbeBone(root, RightHandPath);
                    Vector3 originalHandPosition = hand.position;
                    Vector3 originalPropPosition = prop.position;
                    Quaternion originalPropRotation = prop.rotation;
                    ApplyTopGripPose(
                        root,
                        prop,
                        referenceHand,
                        geometry,
                        originalPropPosition,
                        originalPropRotation);
                    TopGripFrame authored = MeasureTopGripFrame(
                        root, prop, referenceHand, geometry);
                    foreach (string path in rotationPaths)
                        rotations[path].Add(
                            RequirePoseProbeBone(root, path).localRotation);
                    propPositions.Add(prop.localPosition);
                    summary.Accumulate(
                        Vector3.Distance(originalPropPosition, prop.position),
                        Quaternion.Angle(originalPropRotation, prop.rotation),
                        Vector3.Distance(originalHandPosition, hand.position),
                        authored.PalmCenterErrorMeters,
                        authored.WristBendDegrees);
                }

                RemoveTopGripCurves(generated);
                foreach (string path in rotationPaths)
                    SetStabbingQuaternionCurves(
                        generated, path, times, rotations[path]);
                SetStabbingVector3Curves(
                    generated, DiagonalSlashPropPath, times, propPositions);
                generated.EnsureQuaternionContinuity();
                AnimationClip output = AssetDatabase.LoadAssetAtPath<AnimationClip>(
                    assetPath) ?? throw new InvalidOperationException(
                        "Lightsaber_Thrust top-grip output clip is missing: " +
                        assetPath);
                EditorUtility.CopySerialized(generated, output);
                output.name = baseClip.name;
                EditorUtility.SetDirty(output);
                return summary;
            }
            finally
            {
                UnityEngine.Object.DestroyImmediate(generated);
                if (probe != null) UnityEngine.Object.DestroyImmediate(probe);
                EditorSceneManager.ClosePreviewScene(previewScene);
            }
        }

        private static void ApplyTopGripPose(
            Transform root,
            Transform prop,
            Transform referenceHand,
            ModelGeometry geometry,
            Vector3 originalPropPosition,
            Quaternion originalPropRotation)
        {
            Transform foreArm = RequirePoseProbeBone(root, RightForeArmPath);
            Transform hand = RequirePoseProbeBone(root, RightHandPath);
            Vector3 lowerAxis = (hand.position - foreArm.position).normalized;
            if (lowerAxis.sqrMagnitude < 0.5f)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust top-grip forearm axis is degenerate.");

            // Keep the supplied shoulder, elbow, wrist position and stabbing
            // motion. Straighten the hand along the forearm first, then put
            // most of the palm-down roll into the forearm where human
            // pronation belongs instead of collapsing the wrist seam.
            hand.rotation = Quaternion.FromToRotation(
                RightHandFingerDirection(hand), lowerAxis) * hand.rotation;
            Vector3 currentBack = Vector3.ProjectOnPlane(
                RightHandBackDirection(hand), lowerAxis).normalized;
            Vector3 desiredBack = Vector3.ProjectOnPlane(
                root.up, lowerAxis).normalized;
            if (currentBack.sqrMagnitude < 0.5f ||
                desiredBack.sqrMagnitude < 0.5f)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust top-grip hand basis is degenerate.");
            float pronation = Vector3.SignedAngle(
                currentBack, desiredBack, lowerAxis);
            foreArm.rotation = Quaternion.AngleAxis(
                pronation * 0.75f, lowerAxis) * foreArm.rotation;
            hand.rotation = Quaternion.FromToRotation(
                RightHandFingerDirection(hand), lowerAxis) * hand.rotation;
            currentBack = Vector3.ProjectOnPlane(
                RightHandBackDirection(hand), lowerAxis).normalized;
            hand.rotation = Quaternion.AngleAxis(
                Vector3.SignedAngle(currentBack, desiredBack, lowerAxis),
                lowerAxis) * hand.rotation;
            CopyFingerGripPose(referenceHand, hand);

            // Preserve the approved blade angle, then recenter only the hilt
            // translation onto the anatomically straight hand. This keeps the
            // item following RightHand without pulling the arm through the
            // torso to chase an obsolete child offset.
            prop.rotation = originalPropRotation;
            prop.position = originalPropPosition;
            Vector3 palmCenter = PalmCenter(root.gameObject, hand);
            prop.position += palmCenter - TopGripContactPoint(
                root, prop, geometry, palmCenter);
        }

        private static void SolveTopGripArm(
            Transform shoulder,
            Transform upperArm,
            Transform foreArm,
            Transform hand,
            Vector3 target,
            Vector3 desiredAlong,
            Vector3 originalElbow)
        {
            Vector3 clavicle = upperArm.position - shoulder.position;
            float clavicleLength = clavicle.magnitude;
            float upperLength = Vector3.Distance(
                upperArm.position, foreArm.position);
            float lowerLength = Vector3.Distance(
                foreArm.position, hand.position);
            float minimumReach = Mathf.Abs(upperLength - lowerLength) + 0.001f;
            float maximumReach = upperLength + lowerLength - 0.001f;
            float currentDistance = Vector3.Distance(upperArm.position, target);
            if (clavicleLength > 0.0001f &&
                (currentDistance < minimumReach ||
                 currentDistance > maximumReach))
            {
                Vector3 originalDirection = clavicle / clavicleLength;
                Vector3 towardTarget =
                    (target - shoulder.position).normalized;
                Vector3 targetDirection = currentDistance > maximumReach
                    ? towardTarget
                    : -towardTarget;
                Vector3 fullyAdjusted = shoulder.position +
                    targetDirection * clavicleLength;
                float fullyAdjustedDistance = Vector3.Distance(
                    fullyAdjusted, target);
                if (fullyAdjustedDistance < minimumReach ||
                    fullyAdjustedDistance > maximumReach)
                    throw new InvalidOperationException(
                        "Lightsaber_Thrust top-grip target is outside the full " +
                        "right-arm reach range.");
                float low = 0f;
                float high = 1f;
                for (int iteration = 0; iteration < 20; iteration++)
                {
                    float middle = (low + high) * 0.5f;
                    Vector3 candidate = shoulder.position +
                        Vector3.Slerp(
                            originalDirection,
                            targetDirection,
                            middle).normalized * clavicleLength;
                    float candidateDistance = Vector3.Distance(
                        candidate, target);
                    bool reachable = candidateDistance >= minimumReach &&
                        candidateDistance <= maximumReach;
                    if (reachable)
                        high = middle;
                    else
                        low = middle;
                }
                Vector3 desiredClavicle = Vector3.Slerp(
                    originalDirection,
                    targetDirection,
                    high).normalized * clavicleLength;
                shoulder.rotation = Quaternion.FromToRotation(
                    clavicle,
                    desiredClavicle) * shoulder.rotation;
            }

            Vector3 desiredElbow = target -
                desiredAlong.normalized * lowerLength;
            if (Vector3.ProjectOnPlane(
                    desiredElbow - upperArm.position,
                    target - upperArm.position).sqrMagnitude < 0.0001f)
                desiredElbow = originalElbow;
            SolveThrustModeEnterTwoBone(
                upperArm,
                foreArm,
                hand,
                target,
                desiredElbow,
                "right top-grip arm");
            float residual = Vector3.Distance(hand.position, target);
            if (residual > 0.002f)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust top-grip arm did not reach the unclamped " +
                    "hand target. residual=" + Num(residual) +
                    "|clavicleLength=" + Num(clavicleLength) +
                    "|minimumReach=" + Num(minimumReach) +
                    "|maximumReach=" + Num(maximumReach) +
                    "|targetDistanceAfterShoulder=" +
                        Num(Vector3.Distance(upperArm.position, target)) + ".");
        }

        private static TopGripSummary MeasureLightsaberThrustTopGrip(
            Scene scene,
            GameObject target,
            Transform targetProp)
        {
            Transform referenceHand = RequireRightHand(
                FindUnique(scene, ThrustTopGripFingerReferenceName));
            RequireGripFingerHierarchy(
                referenceHand, ThrustTopGripFingerReferenceName);
            GameObject model = AssetDatabase.LoadAssetAtPath<GameObject>(ModelPath) ??
                throw new InvalidOperationException(
                    "Imported lightsaber model is missing.");
            ModelGeometry geometry = AnalyzeModelGeometry(model);
            Dictionary<string, DiagonalSlashLocalPose> restorePose =
                CaptureLightsaberThrustModeEnterLastPose(scene, out _);
            var summary = new TopGripSummary();
            Scene previewScene = EditorSceneManager.NewPreviewScene();
            GameObject probe = null;
            try
            {
                probe = CreateThrustModeEnterPoseProbe(
                    previewScene, restorePose, out Transform prop);
                Animator sourceAnimator = target.GetComponent<Animator>();
                if (sourceAnimator != null && sourceAnimator.avatar != null)
                {
                    Animator probeAnimator = probe.AddComponent<Animator>();
                    probeAnimator.avatar = sourceAnimator.avatar;
                    probeAnimator.applyRootMotion = false;
                    probeAnimator.enabled = false;
                }
                foreach (string path in new[]
                {
                    ThrustStabbingBridgeClipPath,
                    ThrustStabbingExactClipPath,
                    ThrustStabbingHoldClipPath
                })
                {
                    AnimationClip clip = RequireDiagonalSlashAsset<AnimationClip>(path);
                    foreach (float time in StabbingCorrectionSampleTimes(clip))
                    {
                        ApplyThrustModeEnterPose(probe.transform, restorePose);
                        prop.localPosition = targetProp.localPosition;
                        prop.localRotation = targetProp.localRotation;
                        prop.localScale = targetProp.localScale;
                        clip.SampleAnimation(probe, time);
                        summary.Accumulate(
                            path,
                            time,
                            MeasureTopGripFrame(
                                probe.transform,
                                prop,
                                referenceHand,
                                geometry));
                    }
                }
            }
            finally
            {
                if (probe != null) UnityEngine.Object.DestroyImmediate(probe);
                EditorSceneManager.ClosePreviewScene(previewScene);
            }
            return summary;
        }

        internal static TopGripFrame MeasureRuntimeTopGrip(
            Transform root,
            Transform prop)
        {
            GameObject model = AssetDatabase.LoadAssetAtPath<GameObject>(ModelPath) ??
                throw new InvalidOperationException(
                    "Imported lightsaber model is missing.");
            ModelGeometry geometry = AnalyzeModelGeometry(model);
            GameObject[] references = Resources.FindObjectsOfTypeAll<GameObject>()
                .Where(item => item.scene.IsValid() && item.scene.isLoaded &&
                    item.name == ThrustTopGripFingerReferenceName)
                .ToArray();
            if (references.Length != 1)
                throw new InvalidOperationException(
                    "Expected one runtime " + ThrustTopGripFingerReferenceName +
                    " grip reference; found " +
                    references.Length + ".");
            Transform referenceHand = RequireRightHand(references[0]);
            return MeasureTopGripFrame(root, prop, referenceHand, geometry);
        }

        private static TopGripFrame MeasureTopGripFrame(
            Transform root,
            Transform prop,
            Transform referenceHand,
            ModelGeometry geometry)
        {
            Transform hand = RequirePoseProbeBone(root, RightHandPath);
            Transform foreArm = RequirePoseProbeBone(root, RightForeArmPath);
            Vector3 handBack = RightHandBackDirection(hand);
            Vector3 along = RightHandFingerDirection(hand);
            Vector3 handleAxis = prop.TransformDirection(
                geometry.BladeAxisLocal).normalized;
            Vector3 projectedAlong = Vector3.ProjectOnPlane(
                along, root.up).normalized;
            Vector3 projectedHandleAxis = Vector3.ProjectOnPlane(
                handleAxis, root.up).normalized;
            Vector3 palmCenter = PalmCenter(root.gameObject, hand);
            return new TopGripFrame(
                Vector3.Angle(handBack, root.up),
                Mathf.Min(
                    Vector3.Angle(projectedAlong, projectedHandleAxis),
                    Vector3.Angle(-projectedAlong, projectedHandleAxis)),
                Vector3.Distance(
                    palmCenter,
                    TopGripContactPoint(
                        root, prop, geometry, palmCenter)),
                MaximumFingerPoseError(referenceHand, hand),
                MeasureTopGripFingerContactError(hand, prop, geometry),
                Vector3.Angle(
                    along,
                    (hand.position - foreArm.position).normalized));
        }

        private static float MeasureTopGripFingerContactError(
            Transform hand,
            Transform prop,
            ModelGeometry geometry)
        {
            Vector3 axis = prop.TransformDirection(
                geometry.BladeAxisLocal).normalized;
            Vector3 center = prop.TransformPoint(geometry.HandleCenterLocal);
            float maximumDigitDistance = 0f;
            foreach (string rootName in new[]
            {
                "RightThumbProximal",
                "RightIndexProximal",
                "RightMiddleProximal",
                "RightRingProximal",
                "RightLittleProximal"
            })
            {
                Transform digitRoot = hand.Find(rootName) ??
                    throw new InvalidOperationException(
                        "Lightsaber_Thrust top-grip finger is missing: " +
                        rootName);
                float nearest = digitRoot
                    .GetComponentsInChildren<Transform>(true)
                    .Min(joint => Vector3.ProjectOnPlane(
                        joint.position - center,
                        axis).magnitude);
                maximumDigitDistance = Mathf.Max(
                    maximumDigitDistance, nearest);
            }
            return maximumDigitDistance;
        }

        private static Vector3 TopGripContactPoint(
            Transform root,
            Transform prop,
            ModelGeometry geometry,
            Vector3 palmCenter)
        {
            Vector3 axis = prop.TransformDirection(
                geometry.BladeAxisLocal).normalized;
            Vector3 center = prop.TransformPoint(geometry.HandleCenterLocal);
            float halfLength = prop.TransformVector(
                geometry.BladeAxisLocal.normalized *
                geometry.HandleLengthLocal).magnitude * 0.5f;
            float usableHalfLength = Mathf.Max(0f, halfLength * 0.82f);
            float along = Mathf.Clamp(
                Vector3.Dot(palmCenter - center, axis),
                -usableHalfLength,
                usableHalfLength);
            Vector3 top = Vector3.ProjectOnPlane(root.up, axis).normalized;
            if (top.sqrMagnitude < 0.5f)
                top = Vector3.ProjectOnPlane(root.forward, axis).normalized;
            return center + axis * along +
                top * ThrustTopGripPalmSurfaceOffsetMeters;
        }

        private static void RequireTopGripCorrected(TopGripSummary summary)
        {
            if (summary.FrameCount <= 0 ||
                summary.MaximumPalmCenterErrorMeters >
                    ThrustTopGripPalmCenterToleranceMeters ||
                summary.MaximumFingerPoseErrorDegrees >
                    ThrustTopGripFingerPoseToleranceDegrees ||
                summary.MaximumFingerContactErrorMeters >
                    ThrustTopGripFingerContactToleranceMeters ||
                summary.MaximumWristBendDegrees >
                    ThrustTopGripWristBendToleranceDegrees)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust right hand does not maintain the " +
                    "approved top grip. " + summary.Describe());
        }

        private static string[] TopGripRotationPaths()
        {
            return new[]
                {
                    RightShoulderPath,
                    RightArmPath,
                    RightForeArmPath,
                    RightHandPath
                }
                .Concat(LocomotionCarryPosePaths.Skip(4))
                .Concat(new[] { DiagonalSlashPropPath })
                .Distinct(StringComparer.Ordinal)
                .ToArray();
        }

        private static bool IsTopGripAllowedBinding(
            EditorCurveBinding binding)
        {
            bool rotation = TopGripRotationPaths().Contains(
                    binding.path, StringComparer.Ordinal) &&
                (binding.propertyName.StartsWith(
                    "m_LocalRotation.", StringComparison.Ordinal) ||
                 binding.propertyName.StartsWith(
                    "localEulerAngles", StringComparison.Ordinal));
            bool propPosition = binding.path == DiagonalSlashPropPath &&
                binding.propertyName.StartsWith(
                    "m_LocalPosition.", StringComparison.Ordinal);
            return rotation || propPosition;
        }

        private static void RemoveTopGripCurves(AnimationClip clip)
        {
            foreach (EditorCurveBinding binding in
                AnimationUtility.GetCurveBindings(clip))
                if (IsTopGripAllowedBinding(binding))
                    AnimationUtility.SetEditorCurve(clip, binding, null);
        }

        private static string TopGripProtectedClipSignature(AnimationClip clip)
        {
            var result = new StringBuilder()
                .AppendLine("length=" + Precise(clip.length))
                .AppendLine("frameRate=" + Precise(clip.frameRate))
                .AppendLine("legacy=" + clip.legacy)
                .AppendLine("wrapMode=" + clip.wrapMode)
                .AppendLine("settings=" + EditorJsonUtility.ToJson(
                    AnimationUtility.GetAnimationClipSettings(clip)));
            foreach (EditorCurveBinding binding in AnimationUtility
                .GetCurveBindings(clip)
                .Where(item => !IsTopGripAllowedBinding(item))
                .OrderBy(item => item.path, StringComparer.Ordinal)
                .ThenBy(item => item.type.FullName, StringComparer.Ordinal)
                .ThenBy(item => item.propertyName, StringComparer.Ordinal))
            {
                result.Append(binding.path).Append('|')
                    .Append(binding.type.FullName).Append('|')
                    .AppendLine(binding.propertyName);
                AnimationCurve curve = AnimationUtility.GetEditorCurve(
                    clip, binding);
                foreach (Keyframe key in curve.keys)
                    result.AppendLine(string.Join(",", new[]
                    {
                        Precise(key.time), Precise(key.value),
                        Precise(key.inTangent), Precise(key.outTangent),
                        Precise(key.inWeight), Precise(key.outWeight),
                        key.weightedMode.ToString()
                    }));
            }
            return result.ToString();
        }

        private static void SetStabbingVector3Curves(
            AnimationClip clip,
            string path,
            IReadOnlyList<float> times,
            IReadOnlyList<Vector3> values)
        {
            if (times.Count != values.Count || times.Count < 2)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust vector samples differ.");
            string[] properties =
            {
                "m_LocalPosition.x", "m_LocalPosition.y", "m_LocalPosition.z"
            };
            Func<Vector3, float>[] selectors =
            {
                item => item.x, item => item.y, item => item.z
            };
            for (int component = 0; component < properties.Length; component++)
            {
                var curve = new AnimationCurve();
                for (int index = 0; index < times.Count; index++)
                    curve.AddKey(new Keyframe(
                        times[index], selectors[component](values[index])));
                for (int index = 0; index < curve.length; index++)
                {
                    AnimationUtility.SetKeyLeftTangentMode(
                        curve, index, AnimationUtility.TangentMode.Linear);
                    AnimationUtility.SetKeyRightTangentMode(
                        curve, index, AnimationUtility.TangentMode.Linear);
                }
                curve.preWrapMode = WrapMode.ClampForever;
                curve.postWrapMode = WrapMode.ClampForever;
                AnimationUtility.SetEditorCurve(
                    clip,
                    EditorCurveBinding.FloatCurve(
                        path, typeof(Transform), properties[component]),
                    curve);
            }
        }

        private static WristPanelCorrectionSummary
            ApplyWristPanelOrientationToClip(
                GameObject target,
                Transform targetProp,
                AnimationClip baseClip,
                string assetPath,
                IReadOnlyDictionary<string, DiagonalSlashLocalPose> restorePose,
                Quaternion fallbackPropRotation)
        {
            float[] times = StabbingCorrectionSampleTimes(baseClip);
            var generated = new AnimationClip();
            EditorUtility.CopySerialized(baseClip, generated);
            generated.name = baseClip.name;
            Vector3 panelNormalLocal = RightForeArmPanelNormalLocal();
            var foreArmRotations = new List<Quaternion>(times.Length);
            var handRotations = new List<Quaternion>(times.Length);
            var originalFrames = new List<WristPanelProtectedFrame>(times.Length);
            Scene previewScene = EditorSceneManager.NewPreviewScene();
            GameObject probe = null;
            try
            {
                probe = CreateThrustModeEnterPoseProbe(
                    previewScene, restorePose, out Transform prop);
                Animator sourceAnimator = target.GetComponent<Animator>();
                if (sourceAnimator != null && sourceAnimator.avatar != null)
                {
                    Animator probeAnimator = probe.AddComponent<Animator>();
                    probeAnimator.avatar = sourceAnimator.avatar;
                    probeAnimator.applyRootMotion = false;
                    probeAnimator.enabled = false;
                }
                Transform root = probe.transform;
                for (int index = 0; index < times.Length; index++)
                {
                    ApplyThrustModeEnterPose(root, restorePose);
                    prop.localPosition = targetProp.localPosition;
                    prop.localRotation = fallbackPropRotation;
                    prop.localScale = targetProp.localScale;
                    baseClip.SampleAnimation(probe, times[index]);
                    Transform upperArm = RequirePoseProbeBone(
                        root, RightArmPath);
                    Transform foreArm = RequirePoseProbeBone(
                        root, RightForeArmPath);
                    Transform hand = RequirePoseProbeBone(root, RightHandPath);
                    WristPanelProtectedFrame original =
                        new WristPanelProtectedFrame(
                            upperArm.localRotation,
                            hand.position,
                            hand.rotation,
                            prop.position,
                            prop.rotation);
                    originalFrames.Add(original);
                    Vector3 axis = (hand.position - foreArm.position).normalized;
                    Vector3 currentPanel = foreArm.TransformDirection(
                        panelNormalLocal);
                    float handBackRightAngle = Vector3.Angle(
                        RightHandBackDirection(hand), root.right);
                    float influence = Mathf.Clamp01(
                        (ThrustWristPanelBlendStartDegrees -
                         handBackRightAngle) /
                        (ThrustWristPanelBlendStartDegrees -
                         ThrustWristPanelPalmLeftToleranceDegrees));
                    influence = Mathf.SmoothStep(0f, 1f, influence);
                    float twist = SignedProjectedAngle(
                        currentPanel, root.right, axis) * influence;
                    foreArm.rotation = Quaternion.AngleAxis(twist, axis) *
                        foreArm.rotation;
                    hand.rotation = original.HandRotation;
                    foreArmRotations.Add(foreArm.localRotation);
                    handRotations.Add(hand.localRotation);
                }

                RemoveWristPanelRotationCurves(generated);
                SetStabbingQuaternionCurves(
                    generated, RightForeArmPath, times, foreArmRotations);
                SetStabbingQuaternionCurves(
                    generated, RightHandPath, times, handRotations);
                generated.EnsureQuaternionContinuity();

                var summary = new WristPanelCorrectionSummary();
                for (int index = 0; index < times.Length; index++)
                {
                    ApplyThrustModeEnterPose(root, restorePose);
                    prop.localPosition = targetProp.localPosition;
                    prop.localRotation = fallbackPropRotation;
                    prop.localScale = targetProp.localScale;
                    generated.SampleAnimation(probe, times[index]);
                    Transform upperArm = RequirePoseProbeBone(
                        root, RightArmPath);
                    Transform hand = RequirePoseProbeBone(root, RightHandPath);
                    WristPanelProtectedFrame original = originalFrames[index];
                    summary.Accumulate(
                        Vector3.Distance(original.HandPosition, hand.position),
                        Quaternion.Angle(original.HandRotation, hand.rotation),
                        Vector3.Distance(original.PropPosition, prop.position),
                        Quaternion.Angle(original.PropRotation, prop.rotation),
                        Quaternion.Angle(
                            original.UpperArmLocalRotation,
                            upperArm.localRotation));
                }

                AnimationClip output = AssetDatabase.LoadAssetAtPath<AnimationClip>(
                    assetPath) ?? throw new InvalidOperationException(
                        "Lightsaber_Thrust wrist-panel output clip is missing: " +
                        assetPath);
                EditorUtility.CopySerialized(generated, output);
                output.name = baseClip.name;
                EditorUtility.SetDirty(output);
                return summary;
            }
            finally
            {
                UnityEngine.Object.DestroyImmediate(generated);
                if (probe != null) UnityEngine.Object.DestroyImmediate(probe);
                EditorSceneManager.ClosePreviewScene(previewScene);
            }
        }

        private static void RemoveWristPanelRotationCurves(AnimationClip clip)
        {
            foreach (EditorCurveBinding binding in
                AnimationUtility.GetCurveBindings(clip))
            {
                if (!IsWristPanelRotationBinding(binding)) continue;
                AnimationUtility.SetEditorCurve(clip, binding, null);
            }
        }

        private static bool IsWristPanelRotationBinding(
            EditorCurveBinding binding)
        {
            bool pathMatches = binding.path == RightForeArmPath ||
                binding.path == RightHandPath;
            return pathMatches &&
                (binding.propertyName.StartsWith(
                    "m_LocalRotation.", StringComparison.Ordinal) ||
                 binding.propertyName.StartsWith(
                    "localEulerAngles", StringComparison.Ordinal));
        }

        private static string WristPanelProtectedClipSignature(
            AnimationClip clip)
        {
            var result = new StringBuilder()
                .AppendLine("length=" + Precise(clip.length))
                .AppendLine("frameRate=" + Precise(clip.frameRate))
                .AppendLine("legacy=" + clip.legacy)
                .AppendLine("wrapMode=" + clip.wrapMode)
                .AppendLine("settings=" + EditorJsonUtility.ToJson(
                    AnimationUtility.GetAnimationClipSettings(clip)));
            foreach (EditorCurveBinding binding in AnimationUtility
                .GetCurveBindings(clip)
                .Where(item => !IsWristPanelRotationBinding(item))
                .OrderBy(item => item.path, StringComparer.Ordinal)
                .ThenBy(item => item.type.FullName, StringComparer.Ordinal)
                .ThenBy(item => item.propertyName, StringComparer.Ordinal))
            {
                result.Append(binding.path).Append('|')
                    .Append(binding.type.FullName).Append('|')
                    .AppendLine(binding.propertyName);
                AnimationCurve curve = AnimationUtility.GetEditorCurve(
                    clip, binding);
                foreach (Keyframe key in curve.keys)
                    result.AppendLine(string.Join(",", new[]
                    {
                        Precise(key.time), Precise(key.value),
                        Precise(key.inTangent), Precise(key.outTangent),
                        Precise(key.inWeight), Precise(key.outWeight),
                        key.weightedMode.ToString()
                    }));
            }
            foreach (EditorCurveBinding binding in AnimationUtility
                .GetObjectReferenceCurveBindings(clip)
                .OrderBy(item => item.path, StringComparer.Ordinal)
                .ThenBy(item => item.propertyName, StringComparer.Ordinal))
            {
                result.Append("object|").Append(binding.path).Append('|')
                    .AppendLine(binding.propertyName);
                foreach (ObjectReferenceKeyframe key in AnimationUtility
                    .GetObjectReferenceCurve(clip, binding))
                    result.AppendLine(
                        Precise(key.time) + "|" + ObjectIdentity(key.value));
            }
            return result.ToString();
        }

        private static WristPanelOrientationSummary
            MeasureLightsaberThrustWristPanelOrientation(
                Scene scene,
                GameObject target,
                Transform targetProp)
        {
            Dictionary<string, DiagonalSlashLocalPose> restorePose =
                CaptureLightsaberThrustModeEnterLastPose(scene, out _);
            Vector3 panelNormalLocal = RightForeArmPanelNormalLocal();
            var summary = new WristPanelOrientationSummary();
            Scene previewScene = EditorSceneManager.NewPreviewScene();
            GameObject probe = null;
            try
            {
                probe = CreateThrustModeEnterPoseProbe(
                    previewScene, restorePose, out Transform prop);
                Animator sourceAnimator = target.GetComponent<Animator>();
                if (sourceAnimator != null && sourceAnimator.avatar != null)
                {
                    Animator probeAnimator = probe.AddComponent<Animator>();
                    probeAnimator.avatar = sourceAnimator.avatar;
                    probeAnimator.applyRootMotion = false;
                    probeAnimator.enabled = false;
                }
                foreach (string path in new[]
                {
                    ThrustStabbingBridgeClipPath,
                    ThrustStabbingExactClipPath,
                    ThrustStabbingHoldClipPath
                })
                {
                    AnimationClip clip = RequireDiagonalSlashAsset<AnimationClip>(
                        path);
                    foreach (float time in StabbingCorrectionSampleTimes(clip))
                    {
                        ApplyThrustModeEnterPose(probe.transform, restorePose);
                        prop.localPosition = targetProp.localPosition;
                        prop.localRotation = targetProp.localRotation;
                        prop.localScale = targetProp.localScale;
                        clip.SampleAnimation(probe, time);
                        Transform root = probe.transform;
                        Transform foreArm = RequirePoseProbeBone(
                            root, RightForeArmPath);
                        Transform hand = RequirePoseProbeBone(
                            root, RightHandPath);
                        float handBackRightAngle = Vector3.Angle(
                            RightHandBackDirection(hand), root.right);
                        if (handBackRightAngle >
                            ThrustWristPanelPalmLeftToleranceDegrees)
                            continue;
                        Vector3 axis = (hand.position - foreArm.position).normalized;
                        float panelRightAngle = Mathf.Abs(
                            SignedProjectedAngle(
                                foreArm.TransformDirection(panelNormalLocal),
                                root.right,
                                axis));
                        summary.Accumulate(
                            path,
                            time,
                            handBackRightAngle,
                            panelRightAngle);
                    }
                }
            }
            finally
            {
                if (probe != null) UnityEngine.Object.DestroyImmediate(probe);
                EditorSceneManager.ClosePreviewScene(previewScene);
            }
            return summary;
        }

        internal static Vector3 RightForeArmPanelNormalLocal()
        {
            GameObject playerModel = AssetDatabase.LoadAssetAtPath<GameObject>(
                "Assets/_Project/Art/Player/player.fbx") ??
                throw new InvalidOperationException(
                    "Player model is missing for wrist-panel axis inspection.");
            Transform root = playerModel.transform;
            Transform foreArm = RequirePoseProbeBone(root, RightForeArmPath);
            Transform hand = RequirePoseProbeBone(root, RightHandPath);
            return foreArm.InverseTransformDirection(
                RightHandBackDirection(hand)).normalized;
        }

        private static void RequireWristPanelOrientationCorrected(
            WristPanelOrientationSummary summary)
        {
            if (summary.RelevantFrameCount <= 0 ||
                summary.MaximumPanelRightAngleDegrees >
                    ThrustWristPanelRightToleranceDegrees)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust wrist panel does not face carrier-right " +
                    "while the palm faces carrier-left. " + summary.Describe());
        }

        [MenuItem(
            "Bellerophon/Player/Apply Lightsaber Thrust Right-Hand Blade-Forward Correction")]
        internal static void ApplyLightsaberThrustRightHandBladeForwardCorrection()
        {
            RequireEditMode();
            int consoleErrorsBefore = ConsoleErrorCount();
            Scene scene = RequireScene();
            if (scene.isDirty)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust right-hand correction requires a clean scene.");

            GameObject target = FindUnique(scene, ThrustTargetName);
            Animator animator = target.GetComponent<Animator>() ??
                throw new InvalidOperationException(
                    ThrustTargetName + " Animator is missing.");
            Transform hand = RequireRightHand(target);
            Transform prop = RequireLightsaberProp(hand, target.name);
            var rootBefore = new TransformSnapshot(target.transform);
            var propBefore = new TransformSnapshot(prop);
            Dictionary<string, DiagonalSlashLocalPose> scenePoseBefore =
                CaptureDiagonalSlashPose(target.transform, prop);
            string rendererBefore = RendererSignature(target.transform);
            string suppliedHash = Sha256File(
                Absolute(ThrustStabbingSourceRelativePath));
            string copiedHash = Sha256File(Absolute(ThrustStabbingSourcePath));

            AnimationClip source = RequireSingleDiagonalSlashClip(
                ThrustStabbingSourcePath,
                "lightsaber stabbing");
            Dictionary<string, DiagonalSlashLocalPose> start =
                CaptureLightsaberThrustModeEnterLastPose(
                    scene, out Quaternion startPropRotation);
            Dictionary<string, DiagonalSlashLocalPose> sourceFirst =
                SampleDiagonalSlashPose(target, prop, source, 0f, start);
            Dictionary<string, DiagonalSlashLocalPose> sourceLast =
                SampleDiagonalSlashPose(
                    target, prop, source, source.length, start);
            bool bridgeRequired = HasMeaningfulStabbingPoseGap(
                start, sourceFirst, out _, out _, out _);
            AnimationClip bridge = bridgeRequired
                ? CreateOrUpdateStabbingPoseClip(
                    ThrustStabbingBridgeClipPath,
                    "LightsaberThrust_EnterLast_To_StabbingFirst_0_2s",
                    start,
                    sourceFirst,
                    ThrustStabbingBridgeSeconds,
                    startPropRotation)
                : null;
            AnimationClip exact = CopyExactDiagonalSlashClip(
                source,
                ThrustStabbingExactClipPath,
                "LightsaberThrust_Stabbing_SourceExact");

            StabbingCorrectionSummary correctedSummary =
                new StabbingCorrectionSummary();
            if (bridge != null)
                bridge = ApplyStabbingRightHandBladeForwardPasses(
                    target,
                    prop,
                    bridge,
                    ThrustStabbingBridgeClipPath,
                    bridge.name,
                    start,
                    startPropRotation,
                    correctedSummary);
            exact = ApplyStabbingRightHandBladeForwardPasses(
                target,
                prop,
                exact,
                ThrustStabbingExactClipPath,
                "LightsaberThrust_Stabbing_SourceExact",
                start,
                AuthoredPropLocalRotation,
                correctedSummary);

            bridge = bridgeRequired
                ? RequireDiagonalSlashAsset<AnimationClip>(
                    ThrustStabbingBridgeClipPath)
                : null;
            exact = RequireDiagonalSlashAsset<AnimationClip>(
                ThrustStabbingExactClipPath);
            Dictionary<string, DiagonalSlashLocalPose> correctedExactLast =
                SampleDiagonalSlashPose(
                    target, prop, exact, exact.length, start);
            Quaternion correctedExactLastPropRotation =
                EvaluatePropRotation(exact, exact.length);
            AnimationClip hold = CreateOrUpdateStabbingPoseClip(
                ThrustStabbingHoldClipPath,
                "LightsaberThrust_StabbingLast_Hold_0_5s",
                correctedExactLast,
                correctedExactLast,
                ThrustStabbingHoldSeconds,
                correctedExactLastPropRotation);
            hold = RequireDiagonalSlashAsset<AnimationClip>(
                ThrustStabbingHoldClipPath);
            correctedSummary.Accumulate(
                MeasureStabbingRightHandBladeDirections(
                    target,
                    prop,
                    hold,
                    start,
                    correctedExactLastPropRotation));
            AnimatorController controller =
                CreateOrUpdateLightsaberThrustStabbingController(
                    bridge, exact, hold);
            Undo.RecordObject(
                animator,
                "Apply Lightsaber_Thrust right-hand and blade-forward correction");
            animator.runtimeAnimatorController = controller;
            // The stabbing source is a Generic transform clip (humanMotion=False).
            // Keeping a Humanoid Avatar assigned makes Mecanim retarget and blend
            // the authored bone rotations a second time during Play Mode.
            animator.avatar = null;
            animator.applyRootMotion = false;
            animator.enabled = true;
            animator.cullingMode = AnimatorCullingMode.AlwaysAnimate;
            PrefabUtility.RecordPrefabInstancePropertyModifications(animator);
            EditorUtility.SetDirty(animator);
            AssetDatabase.SaveAssets();

            RequireEqual(suppliedHash,
                Sha256File(Absolute(ThrustStabbingSourceRelativePath)),
                "protected supplied stabbing FBX");
            RequireEqual(copiedHash,
                Sha256File(Absolute(ThrustStabbingSourcePath)),
                "protected imported stabbing FBX");
            rootBefore.RequireUnchanged();
            propBefore.RequireUnchanged();
            RequireDiagonalSlashPoseEqual(
                scenePoseBefore,
                CaptureDiagonalSlashPose(target.transform, prop),
                "Lightsaber_Thrust scene pose after right-hand correction");
            RequireEqual(rendererBefore, RendererSignature(target.transform),
                "Lightsaber_Thrust renderer hierarchy");
            if (!EditorSceneManager.SaveScene(scene))
                throw new InvalidOperationException(
                    "CargoRunMvp could not save the right-hand correction.");
            RequireLightsaberThrustRightHandBladeForwardCorrection(scene);
            RequireNoNewUnityConsoleErrors(consoleErrorsBefore);
            Debug.Log(
                "[LightsaberThrustRightHandBladeForward] Applied to the full " +
                "loop. maximumHandBackRightAngle=" +
                    Num(correctedSummary.MaximumHandBackRightAngleDegrees) +
                "|maximumBladeForwardAngle=" +
                    Num(correctedSummary.MaximumBladeForwardAngleDegrees) +
                "|maximumWristBend=" +
                    Num(correctedSummary.MaximumWristBendDegrees) +
                "|maximumHandPositionDelta=" +
                    Num(correctedSummary.MaximumHandPositionDeltaMeters) +
                "|bridgeSeconds=" + Num(ThrustStabbingBridgeSeconds) +
                "|sourceSeconds=" + Num(source.length) +
                "|holdSeconds=" + Num(ThrustStabbingHoldSeconds));
        }

