        [MenuItem("Bellerophon/Player/Apply Lightsaber Thrust Stabbing Sequence")]
        internal static void ApplyLightsaberThrustStabbingSequence()
        {
            RequireEditMode();
            int consoleErrorsBefore = ConsoleErrorCount();
            Scene scene = RequireScene();
            if (scene.isDirty)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust stabbing setup requires a clean CargoRunMvp scene.");
            string supplied = Absolute(ThrustStabbingSourceRelativePath);
            if (!File.Exists(supplied))
                throw new FileNotFoundException(
                    "Supplied lightsaber stabbing FBX is missing.", supplied);

            GameObject target = FindUnique(scene, ThrustTargetName);
            GameObject enter = FindUnique(scene, ThrustModeEnterTargetName);
            Animator targetAnimator = target.GetComponent<Animator>() ??
                throw new InvalidOperationException(
                    ThrustTargetName + " Animator is missing.");
            Animator enterAnimator = enter.GetComponent<Animator>() ??
                throw new InvalidOperationException(
                    ThrustModeEnterTargetName + " Animator is missing.");
            if (targetAnimator.avatar == null || enterAnimator.avatar == null ||
                targetAnimator.avatar != enterAnimator.avatar)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust and Lightsaber_ThrustMode_Enter Avatars differ.");
            Transform targetHand = RequireRightHand(target);
            Transform targetProp = RequireLightsaberProp(targetHand, target.name);
            RequireAuthoredPropTransform(targetProp, target.name);
            var rootBefore = new TransformSnapshot(target.transform);
            var propBefore = new TransformSnapshot(targetProp);
            Dictionary<string, DiagonalSlashLocalPose> scenePoseBefore =
                CaptureDiagonalSlashPose(target.transform, targetProp);
            string rendererBefore = RendererSignature(target.transform);
            string avatarBefore = ObjectIdentity(targetAnimator.avatar);
            string enterAnimatorBefore = AnimatorSignature(enter);
            string enterRendererBefore = RendererSignature(enter.transform);
            Transform enterProp = RequireLightsaberProp(
                RequireRightHand(enter), enter.name);
            var enterPropBefore = new TransformSnapshot(enterProp);
            string enterClipHash = Sha256File(Absolute(ThrustModeEnterCycleClipPath));
            string enterControllerHash =
                Sha256File(Absolute(ThrustModeEnterControllerPath));
            string suppliedHash = Sha256File(supplied);
            string[] discardedGuids = AssetDatabase.IsValidFolder(ThrustAssetFolder)
                ? AssetDatabase.FindAssets(string.Empty, new[] { ThrustAssetFolder })
                    .Distinct(StringComparer.Ordinal)
                    .ToArray()
                : Array.Empty<string>();

            Dictionary<string, DiagonalSlashLocalPose> start =
                CaptureLightsaberThrustModeEnterLastPose(
                    scene, out Quaternion startPropRotation);
            RequireGripOneHandPosePathSets(scenePoseBefore, start);

            Undo.RecordObject(targetAnimator,
                "Discard old Lightsaber_Thrust animation connection");
            targetAnimator.runtimeAnimatorController = null;
            EditorUtility.SetDirty(targetAnimator);
            AssetDatabase.SaveAssets();
            if (AssetDatabase.IsValidFolder(ThrustAssetFolder) &&
                !AssetDatabase.DeleteAsset(ThrustAssetFolder))
                throw new InvalidOperationException(
                    "Existing LightsaberThrust animation folder could not be discarded.");
            AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);
            EnsureFolder(ThrustAssetFolder);
            EnsureFolder(ThrustStabbingSourceFolder);
            EnsureDiagonalSlashSourceCopy(
                ThrustStabbingSourceRelativePath,
                ThrustStabbingSourcePath,
                "lightsaber stabbing");
            ConfigureDiagonalSlashSourceImporter(
                ThrustStabbingSourcePath,
                "lightsaber stabbing");
            AnimationClip source = RequireSingleDiagonalSlashClip(
                ThrustStabbingSourcePath,
                "lightsaber stabbing");
            RequireStabbingBindingCompatibility(target.transform, source);
            Dictionary<string, DiagonalSlashLocalPose> sourceFirst =
                SampleDiagonalSlashPose(
                    target, targetProp, source, 0f, start);
            Dictionary<string, DiagonalSlashLocalPose> sourceLast =
                SampleDiagonalSlashPose(
                    target, targetProp, source, source.length, start);
            RequireGripOneHandPosePathSets(start, sourceFirst);
            RequireGripOneHandPosePathSets(start, sourceLast);
            bool bridgeRequired = HasMeaningfulStabbingPoseGap(
                start, sourceFirst,
                out float bridgePositionDelta,
                out float bridgeRotationDelta,
                out float bridgeScaleDelta);

            AnimationClip bridge = bridgeRequired
                ? CreateOrUpdateStabbingPoseClip(
                    ThrustStabbingBridgeClipPath,
                    "LightsaberThrust_EnterLast_To_StabbingFirst_0_2s",
                    start,
                    sourceFirst,
                    ThrustStabbingBridgeSeconds,
                    startPropRotation)
                : null;
            AnimationClip exact = CopyExactDiagonalSlashClip(
                source,
                ThrustStabbingExactClipPath,
                "LightsaberThrust_Stabbing_SourceExact");
            AnimationClip hold = CreateOrUpdateStabbingPoseClip(
                ThrustStabbingHoldClipPath,
                "LightsaberThrust_StabbingLast_Hold_0_5s",
                sourceLast,
                sourceLast,
                ThrustStabbingHoldSeconds,
                startPropRotation);
            AnimatorController controller =
                CreateOrUpdateLightsaberThrustStabbingController(
                    bridge, exact, hold);

            Undo.RecordObject(targetAnimator,
                "Configure Lightsaber_Thrust exact stabbing sequence");
            targetAnimator.runtimeAnimatorController = controller;
            targetAnimator.applyRootMotion = false;
            targetAnimator.enabled = true;
            targetAnimator.cullingMode = AnimatorCullingMode.AlwaysAnimate;
            PrefabUtility.RecordPrefabInstancePropertyModifications(targetAnimator);
            EditorUtility.SetDirty(targetAnimator);
            AssetDatabase.SaveAssets();

            string[] newGuids = AssetDatabase.FindAssets(
                    string.Empty, new[] { ThrustAssetFolder })
                .Distinct(StringComparer.Ordinal)
                .ToArray();
            if (discardedGuids.Intersect(newGuids, StringComparer.Ordinal).Any())
                throw new InvalidOperationException(
                    "A discarded LightsaberThrust asset GUID was unexpectedly reused.");
            RequireEqual(suppliedHash,
                Sha256File(Absolute(ThrustStabbingSourcePath)),
                "lightsaber stabbing FBX binary copy");
            RequireEqual(enterClipHash,
                Sha256File(Absolute(ThrustModeEnterCycleClipPath)),
                "protected Lightsaber_ThrustMode_Enter cycle");
            RequireEqual(enterControllerHash,
                Sha256File(Absolute(ThrustModeEnterControllerPath)),
                "protected Lightsaber_ThrustMode_Enter controller");
            RequireEqual(enterAnimatorBefore, AnimatorSignature(enter),
                "protected Lightsaber_ThrustMode_Enter Animator");
            RequireEqual(enterRendererBefore, RendererSignature(enter.transform),
                "protected Lightsaber_ThrustMode_Enter renderers");
            enterPropBefore.RequireUnchanged();
            rootBefore.RequireUnchanged();
            propBefore.RequireUnchanged();
            RequireDiagonalSlashPoseEqual(
                scenePoseBefore,
                CaptureDiagonalSlashPose(target.transform, targetProp),
                "Lightsaber_Thrust scene pose after stabbing setup");
            RequireEqual(rendererBefore, RendererSignature(target.transform),
                "Lightsaber_Thrust renderer hierarchy");
            RequireEqual(avatarBefore, ObjectIdentity(targetAnimator.avatar),
                "Lightsaber_Thrust Avatar");
            if (!EditorSceneManager.SaveScene(scene))
                throw new InvalidOperationException(
                    "CargoRunMvp could not save Lightsaber_Thrust stabbing sequence.");
            InspectLightsaberThrustStabbingSequenceInternal(scene, false);
            RequireNoNewUnityConsoleErrors(consoleErrorsBefore);
            Debug.Log(
                "[LightsaberThrustStabbing] Applied exact Mixamo stabbing sequence." +
                " bridgeRequired=" + bridgeRequired +
                "|bridgeSeconds=" +
                    (bridgeRequired ? Num(ThrustStabbingBridgeSeconds) : "0") +
                "|sourceSeconds=" + Num(source.length) +
                "|holdSeconds=" + Num(ThrustStabbingHoldSeconds) +
                "|bridgePositionDelta=" + Num(bridgePositionDelta) +
                "|bridgeRotationDelta=" + Num(bridgeRotationDelta) +
                "|bridgeScaleDelta=" + Num(bridgeScaleDelta) +
                "|discardedGuidCount=" + discardedGuids.Length +
                "|sourceMotionGenerated=False");
        }

