        private static void InspectLightsaberThrustStabbingSequenceInternal(
            Scene scene,
            bool requireCleanScene)
        {
            if (requireCleanScene && scene.isDirty)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust stabbing inspection requires a clean scene.");
            string supplied = Absolute(ThrustStabbingSourceRelativePath);
            string copied = Absolute(ThrustStabbingSourcePath);
            if (!File.Exists(supplied) || !File.Exists(copied))
                throw new InvalidOperationException(
                    "Lightsaber stabbing source copy is incomplete.");
            RequireEqual(Sha256File(supplied), Sha256File(copied),
                "lightsaber stabbing FBX binary copy");
            RequireDiagonalSlashImporter(
                ThrustStabbingSourcePath,
                "lightsaber stabbing");
            AnimationClip source = RequireSingleDiagonalSlashClip(
                ThrustStabbingSourcePath,
                "lightsaber stabbing");
            AnimationClip exact = RequireDiagonalSlashAsset<AnimationClip>(
                ThrustStabbingExactClipPath);
            AnimationClip hold = RequireDiagonalSlashAsset<AnimationClip>(
                ThrustStabbingHoldClipPath);
            bool rightHandBladeForwardApplied =
                IsStabbingRightHandBladeForwardClip(exact);
            if (rightHandBladeForwardApplied)
                RequireEqual(
                    StabbingUnapprovedClipSignature(source),
                    StabbingUnapprovedClipSignature(exact),
                    "stabbing Mixamo unapproved curves");
            else
                RequireEqual(LightsaberClipSignature(source),
                    LightsaberClipSignature(exact),
                    "exact stabbing Mixamo clip copy");
            if (Mathf.Abs(hold.length - ThrustStabbingHoldSeconds) > 0.0001f ||
                Mathf.Abs(hold.frameRate - 60f) > 0.0001f || hold.isLooping)
                throw new InvalidOperationException(
                    "Lightsaber stabbing final hold must be exactly 0.5 seconds.");

            GameObject target = FindUnique(scene, ThrustTargetName);
            Animator animator = target.GetComponent<Animator>() ??
                throw new InvalidOperationException(
                    ThrustTargetName + " Animator is missing.");
            if (animator.avatar != null || !animator.enabled ||
                animator.applyRootMotion ||
                animator.cullingMode != AnimatorCullingMode.AlwaysAnimate)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust stabbing Animator settings differ.");
            RequireStabbingBindingCompatibility(target.transform, source);
            Transform hand = RequireRightHand(target);
            Transform prop = RequireLightsaberProp(hand, target.name);
            RequireAuthoredPropTransform(prop, target.name);
            if (prop.parent != hand)
                throw new InvalidOperationException(
                    "Lightsaber_Prop stopped following RightHand.");
            Dictionary<string, DiagonalSlashLocalPose> start =
                CaptureLightsaberThrustModeEnterLastPose(
                    scene, out Quaternion startPropRotation);
            Dictionary<string, DiagonalSlashLocalPose> sourceFirst =
                SampleDiagonalSlashPose(target, prop, source, 0f, start);
            Dictionary<string, DiagonalSlashLocalPose> sourceLast =
                SampleDiagonalSlashPose(target, prop, source, source.length, start);
            bool bridgeRequired = HasMeaningfulStabbingPoseGap(
                start, sourceFirst,
                out _, out _, out _);
            AnimationClip bridge = AssetDatabase.LoadAssetAtPath<AnimationClip>(
                ThrustStabbingBridgeClipPath);
            if (rightHandBladeForwardApplied)
            {
                RequireLightsaberThrustRightHandBladeForwardAssets(
                    target,
                    prop,
                    source,
                    bridge,
                    exact,
                    hold,
                    start,
                    sourceFirst,
                    sourceLast,
                    startPropRotation,
                    bridgeRequired);
                RequireLightsaberThrustStabbingController(
                    animator, bridge, exact, hold, bridgeRequired);
                RequireNoLegacyLightsaberThrustAssets();
                return;
            }
            if (bridgeRequired)
            {
                if (bridge == null ||
                    Mathf.Abs(bridge.length - ThrustStabbingBridgeSeconds) > 0.0001f ||
                    Mathf.Abs(bridge.frameRate - 60f) > 0.0001f ||
                    bridge.isLooping)
                    throw new InvalidOperationException(
                        "Required Lightsaber_Thrust bridge is not exactly 0.2 seconds.");
                RequireDiagonalSlashPoseEqual(
                    start,
                    SampleDiagonalSlashPose(target, prop, bridge, 0f, start),
                    "stabbing bridge first pose/enter last pose");
                RequireDiagonalSlashPoseEqual(
                    sourceFirst,
                    SampleDiagonalSlashPose(
                        target, prop, bridge, bridge.length, start),
                    "stabbing bridge last pose/Mixamo first pose");
                if (Quaternion.Angle(
                        EvaluatePropRotation(bridge, 0f), startPropRotation) > 0.02f ||
                    Quaternion.Angle(
                        EvaluatePropRotation(bridge, bridge.length),
                        startPropRotation) > 0.02f)
                    throw new InvalidOperationException(
                        "Stabbing bridge changed the approved prop grip rotation.");
            }
            else if (bridge != null)
            {
                throw new InvalidOperationException(
                    "A stabbing bridge exists even though the poses already match.");
            }
            RequireDiagonalSlashPoseEqual(
                sourceLast,
                SampleDiagonalSlashPose(target, prop, hold, 0f, start),
                "stabbing hold first pose/source last pose");
            RequireDiagonalSlashPoseEqual(
                sourceLast,
                SampleDiagonalSlashPose(target, prop, hold, hold.length, start),
                "stabbing hold last pose/source last pose");
            if (Quaternion.Angle(
                    EvaluatePropRotation(hold, 0f), startPropRotation) > 0.02f ||
                Quaternion.Angle(
                    EvaluatePropRotation(hold, hold.length),
                    startPropRotation) > 0.02f)
                throw new InvalidOperationException(
                    "Stabbing hold changed the approved prop grip rotation.");
            RequireLightsaberThrustStabbingController(
                animator, bridge, exact, hold, bridgeRequired);
            RequireNoLegacyLightsaberThrustAssets();
        }

        private static void RequireLightsaberThrustRightHandBladeForwardCorrection(
            Scene scene)
        {
            InspectLightsaberThrustStabbingSequenceInternal(scene, false);
            AnimationClip exact = RequireDiagonalSlashAsset<AnimationClip>(
                ThrustStabbingExactClipPath);
            if (!IsStabbingRightHandBladeForwardClip(exact))
                throw new InvalidOperationException(
                    "Lightsaber_Thrust right-hand blade-forward correction is absent.");
        }

        private static void RequireLightsaberThrustRightHandBladeForwardAssets(
            GameObject target,
            Transform prop,
            AnimationClip source,
            AnimationClip bridge,
            AnimationClip exact,
            AnimationClip hold,
            IReadOnlyDictionary<string, DiagonalSlashLocalPose> start,
            IReadOnlyDictionary<string, DiagonalSlashLocalPose> sourceFirst,
            IReadOnlyDictionary<string, DiagonalSlashLocalPose> sourceLast,
            Quaternion startPropRotation,
            bool bridgeRequired)
        {
            if (!IsStabbingRightHandBladeForwardClip(exact) ||
                !IsStabbingRightHandBladeForwardClip(hold) ||
                (bridgeRequired &&
                    !IsStabbingRightHandBladeForwardClip(bridge)))
                throw new InvalidOperationException(
                    "A full-loop right-hand blade-forward correction is missing.");
            RequireEqual(
                StabbingUnapprovedClipSignature(source),
                StabbingUnapprovedClipSignature(exact),
                "stabbing Mixamo unapproved curves");
            if (Mathf.Abs(exact.length - source.length) > 0.0001f ||
                Mathf.Abs(exact.frameRate - source.frameRate) > 0.0001f ||
                exact.isLooping || hold.isLooping ||
                Mathf.Abs(hold.length - ThrustStabbingHoldSeconds) > 0.0001f ||
                (bridgeRequired &&
                    (bridge == null || bridge.isLooping ||
                     Mathf.Abs(bridge.length - ThrustStabbingBridgeSeconds) >
                        0.0001f)))
                throw new InvalidOperationException(
                    "Lightsaber_Thrust corrected clip timing differs.");

            // Sample every sequence clip from the same approved start pose.
            // Imported Mixamo clips can omit unchanged bones; using the live scene
            // pose for only one side of a comparison creates false left-limb deltas.
            IReadOnlyDictionary<string, DiagonalSlashLocalPose> restorePose = start;
            Dictionary<string, DiagonalSlashLocalPose> exactFirst =
                SampleDiagonalSlashPose(target, prop, exact, 0f, restorePose);
            Dictionary<string, DiagonalSlashLocalPose> exactLast =
                SampleDiagonalSlashPose(
                    target, prop, exact, exact.length, restorePose);
            Dictionary<string, DiagonalSlashLocalPose> holdFirst =
                SampleDiagonalSlashPose(target, prop, hold, 0f, restorePose);
            Dictionary<string, DiagonalSlashLocalPose> holdLast =
                SampleDiagonalSlashPose(
                    target, prop, hold, hold.length, restorePose);
            RequireOnlyApprovedStabbingPoseDifferences(
                sourceFirst, exactFirst, "corrected Mixamo first pose");
            RequireOnlyApprovedStabbingPoseDifferences(
                sourceLast, exactLast, "corrected Mixamo last pose");
            RequireDiagonalSlashPoseEqual(
                exactLast, holdFirst,
                "corrected Mixamo last/hold first continuity");
            RequireDiagonalSlashPoseEqual(
                holdFirst, holdLast,
                "corrected 0.5-second hold pose");
            if (bridgeRequired)
            {
                Dictionary<string, DiagonalSlashLocalPose> bridgeFirst =
                    SampleDiagonalSlashPose(
                        target, prop, bridge, 0f, restorePose);
                Dictionary<string, DiagonalSlashLocalPose> bridgeLast =
                    SampleDiagonalSlashPose(
                        target, prop, bridge, bridge.length, restorePose);
                RequireOnlyApprovedStabbingPoseDifferences(
                    start, bridgeFirst, "corrected bridge start pose");
                RequireDiagonalSlashPoseEqual(
                    bridgeLast, exactFirst,
                    "corrected bridge/Mixamo continuity");
            }

            var total = new StabbingCorrectionSummary();
            if (bridgeRequired)
                total.Accumulate(MeasureStabbingRightHandBladeDirections(
                    target,
                    prop,
                    bridge,
                    restorePose,
                    startPropRotation));
            total.Accumulate(MeasureStabbingRightHandBladeDirections(
                target,
                prop,
                exact,
                restorePose,
                AuthoredPropLocalRotation));
            total.Accumulate(MeasureStabbingRightHandBladeDirections(
                target,
                prop,
                hold,
                restorePose,
                startPropRotation));
            if (total.MaximumHandBackRightAngleDegrees >
                    ThrustStabbingHandBackToleranceDegrees ||
                total.MaximumBladeForwardAngleDegrees >
                    ThrustStabbingBladeForwardToleranceDegrees ||
                total.MaximumWristBendDegrees >
                    ThrustStabbingWristBendToleranceDegrees)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust corrected directions exceed tolerance. " +
                    "handBack=" +
                        Num(total.MaximumHandBackRightAngleDegrees) +
                    "|blade=" + Num(total.MaximumBladeForwardAngleDegrees) +
                    "|wrist=" + Num(total.MaximumWristBendDegrees) + ".");
        }

        private static bool IsStabbingRightHandBladeForwardClip(
            AnimationClip clip)
        {
            if (clip == null) return false;
            HashSet<string> properties = new HashSet<string>(
                AnimationUtility.GetCurveBindings(clip)
                    .Where(item => item.path == DiagonalSlashPropPath)
                    .Select(item => item.propertyName),
                StringComparer.Ordinal);
            return properties.Contains("m_LocalRotation.x") &&
                properties.Contains("m_LocalRotation.y") &&
                properties.Contains("m_LocalRotation.z") &&
                properties.Contains("m_LocalRotation.w");
        }

        private static string StabbingUnapprovedClipSignature(
            AnimationClip clip)
        {
            var result = new StringBuilder()
                .AppendLine("length=" + Num(clip.length))
                .AppendLine("frameRate=" + Num(clip.frameRate))
                .AppendLine("legacy=" + clip.legacy)
                .AppendLine("wrapMode=" + clip.wrapMode)
                .AppendLine("settings=" + EditorJsonUtility.ToJson(
                    AnimationUtility.GetAnimationClipSettings(clip)));
            foreach (EditorCurveBinding binding in AnimationUtility
                .GetCurveBindings(clip)
                .Where(item => !IsStabbingCorrectionRotationBinding(item))
                .OrderBy(item => item.path, StringComparer.Ordinal)
                .ThenBy(item => item.type.FullName, StringComparer.Ordinal)
                .ThenBy(item => item.propertyName, StringComparer.Ordinal))
            {
                result.Append("curve|").Append(binding.path).Append('|')
                    .Append(binding.type.FullName).Append('|')
                    .AppendLine(binding.propertyName);
                AnimationCurve curve = AnimationUtility.GetEditorCurve(clip, binding);
                result.AppendLine("wrap=" + curve.preWrapMode + "," +
                    curve.postWrapMode);
                foreach (Keyframe key in curve.keys)
                    result.AppendLine(string.Join(",", new[]
                    {
                        Num(key.time), Num(key.value), Num(key.inTangent),
                        Num(key.outTangent), Num(key.inWeight), Num(key.outWeight),
                        key.weightedMode.ToString()
                    }));
            }
            foreach (EditorCurveBinding binding in AnimationUtility
                .GetObjectReferenceCurveBindings(clip)
                .OrderBy(item => item.path, StringComparer.Ordinal)
                .ThenBy(item => item.type.FullName, StringComparer.Ordinal)
                .ThenBy(item => item.propertyName, StringComparer.Ordinal))
            {
                result.Append("objectCurve|").Append(binding.path).Append('|')
                    .Append(binding.type.FullName).Append('|')
                    .AppendLine(binding.propertyName);
                foreach (ObjectReferenceKeyframe key in AnimationUtility
                    .GetObjectReferenceCurve(clip, binding))
                    result.AppendLine(
                        Num(key.time) + "|" + ObjectIdentity(key.value));
            }
            foreach (AnimationEvent item in
                AnimationUtility.GetAnimationEvents(clip))
                result.AppendLine(
                    "event|" + Num(item.time) + "|" + item.functionName + "|" +
                    item.stringParameter + "|" + item.intParameter + "|" +
                    Num(item.floatParameter) + "|" +
                    ObjectIdentity(item.objectReferenceParameter) + "|" +
                    item.messageOptions);
            return LightsaberSha256(result.ToString());
        }

        private static void RequireOnlyApprovedStabbingPoseDifferences(
            IReadOnlyDictionary<string, DiagonalSlashLocalPose> expected,
            IReadOnlyDictionary<string, DiagonalSlashLocalPose> actual,
            string label)
        {
            RequireGripOneHandPosePathSets(expected, actual);
            foreach (string path in expected.Keys)
            {
                DiagonalSlashLocalPose a = expected[path];
                DiagonalSlashLocalPose b = actual[path];
                if (Vector3.Distance(a.Position, b.Position) > 0.0001f ||
                    Vector3.Distance(a.Scale, b.Scale) > 0.0001f)
                    throw new InvalidOperationException(
                        label + " changed position or scale at " + path + ".");
                bool approvedRotation = path == RightArmPath ||
                    path == RightForeArmPath || path == RightHandPath ||
                    path.StartsWith(
                        RightHandPath + "/", StringComparison.Ordinal) ||
                    path == DiagonalSlashPropPath;
                if (!approvedRotation &&
                    Quaternion.Angle(a.Rotation, b.Rotation) > 0.02f)
                    throw new InvalidOperationException(
                        label + " changed an unapproved rotation at " + path + ".");
            }
        }

        private static void RequireNoLegacyLightsaberThrustAssets()
        {
            string[] legacyPaths =
            {
                ThrustStartPoseClipPath,
                ThrustStartPoseControllerPath,
                ThrustMotionClipPath,
                ThrustMotionControllerPath
            };
            if (legacyPaths.Any(path =>
                    AssetDatabase.LoadMainAssetAtPath(path) != null ||
                    File.Exists(Absolute(path))))
                throw new InvalidOperationException(
                    "A discarded Lightsaber_Thrust animation asset still exists.");
        }

        private static void RequireStabbingBindingCompatibility(
            Transform target,
            AnimationClip clip)
        {
            string[] missing = AnimationUtility.GetCurveBindings(clip)
                .Concat(AnimationUtility.GetObjectReferenceCurveBindings(clip))
                .Select(item => item.path)
                .Where(path => !string.IsNullOrEmpty(path) && target.Find(path) == null)
                .Distinct(StringComparer.Ordinal)
                .OrderBy(path => path, StringComparer.Ordinal)
                .ToArray();
            if (missing.Length > 0)
                throw new InvalidOperationException(
                    "Stabbing Mixamo clip contains paths missing from " +
                    "Lightsaber_Thrust: " + string.Join(",", missing.Take(12)));
            if (AnimationUtility.GetCurveBindings(clip).Length == 0)
                throw new InvalidOperationException(
                    "Stabbing Mixamo clip has no animation curves.");
        }

        private static bool HasMeaningfulStabbingPoseGap(
            IReadOnlyDictionary<string, DiagonalSlashLocalPose> first,
            IReadOnlyDictionary<string, DiagonalSlashLocalPose> second,
            out float maximumPositionDelta,
            out float maximumRotationDelta,
            out float maximumScaleDelta)
        {
            RequireGripOneHandPosePathSets(first, second);
            maximumPositionDelta = 0f;
            maximumRotationDelta = 0f;
            maximumScaleDelta = 0f;
            foreach (string path in first.Keys)
            {
                DiagonalSlashLocalPose a = first[path];
                DiagonalSlashLocalPose b = second[path];
                maximumPositionDelta = Mathf.Max(
                    maximumPositionDelta,
                    Vector3.Distance(a.Position, b.Position));
                maximumRotationDelta = Mathf.Max(
                    maximumRotationDelta,
                    Quaternion.Angle(a.Rotation, b.Rotation));
                maximumScaleDelta = Mathf.Max(
                    maximumScaleDelta,
                    Vector3.Distance(a.Scale, b.Scale));
            }
            return maximumPositionDelta > 0.0001f ||
                maximumRotationDelta > 0.02f ||
                maximumScaleDelta > 0.0001f;
        }

        private static void ApplySmoothedStabbingRightArmBridge(
            GameObject target,
            Transform targetProp,
            AnimationClip bridge,
            IReadOnlyDictionary<string, DiagonalSlashLocalPose> from,
            IReadOnlyDictionary<string, DiagonalSlashLocalPose> to,
            Quaternion fromPropRotation,
            Quaternion toPropRotation,
            IReadOnlyDictionary<string, DiagonalSlashLocalPose> restorePose)
        {
            string[] paths =
            {
                RightArmPath,
                RightForeArmPath,
                RightHandPath,
                DiagonalSlashPropPath
            };
            int frameCount = Mathf.Max(
                2, Mathf.RoundToInt(bridge.length * 60f));
            float[] times = Enumerable.Range(0, frameCount + 1)
                .Select(index => bridge.length * index / frameCount)
                .ToArray();
            var rotations = paths.ToDictionary(
                path => path,
                _ => new List<Quaternion>(times.Length),
                StringComparer.Ordinal);
            Scene previewScene = EditorSceneManager.NewPreviewScene();
            GameObject probe = null;
            try
            {
                probe = CreateThrustModeEnterPoseProbe(
                    previewScene, restorePose, out Transform prop);
                Animator sourceAnimator = target.GetComponent<Animator>();
                if (sourceAnimator != null && sourceAnimator.avatar != null)
                {
                    Animator probeAnimator = probe.AddComponent<Animator>();
                    probeAnimator.avatar = sourceAnimator.avatar;
                    probeAnimator.applyRootMotion = false;
                    probeAnimator.enabled = false;
                }
                Transform root = probe.transform;

                ApplyThrustModeEnterPose(root, restorePose);
                prop.localPosition = targetProp.localPosition;
                prop.localRotation = fromPropRotation;
                prop.localScale = targetProp.localScale;
                bridge.SampleAnimation(probe, 0f);
                ApplyStabbingRightArmLocalRotations(root, from);
                prop.localRotation = fromPropRotation;
                Transform upperArm = RequirePoseProbeBone(root, RightArmPath);
                Transform foreArm = RequirePoseProbeBone(root, RightForeArmPath);
                Transform hand = RequirePoseProbeBone(root, RightHandPath);
                Vector3 fromHandLocal = root.InverseTransformPoint(hand.position);
                Vector3 fromElbowLocal = root.InverseTransformPoint(foreArm.position);
                Quaternion fromHandRootRotation =
                    Quaternion.Inverse(root.rotation) * hand.rotation;

                ApplyThrustModeEnterPose(root, restorePose);
                prop.localPosition = targetProp.localPosition;
                prop.localRotation = toPropRotation;
                prop.localScale = targetProp.localScale;
                bridge.SampleAnimation(probe, bridge.length);
                ApplyStabbingRightArmLocalRotations(root, to);
                prop.localRotation = toPropRotation;
                Vector3 toHandLocal = root.InverseTransformPoint(hand.position);
                Vector3 toElbowLocal = root.InverseTransformPoint(foreArm.position);
                Quaternion toHandRootRotation =
                    Quaternion.Inverse(root.rotation) * hand.rotation;

                for (int index = 0; index < times.Length; index++)
                {
                    ApplyThrustModeEnterPose(root, restorePose);
                    prop.localPosition = targetProp.localPosition;
                    prop.localRotation = fromPropRotation;
                    prop.localScale = targetProp.localScale;
                    bridge.SampleAnimation(probe, times[index]);
                    upperArm = RequirePoseProbeBone(root, RightArmPath);
                    foreArm = RequirePoseProbeBone(root, RightForeArmPath);
                    hand = RequirePoseProbeBone(root, RightHandPath);

                    float linear = index / (float)(times.Length - 1);
                    float eased = linear * linear * (3f - 2f * linear);
                    float outwardArc = Mathf.Sin(linear * Mathf.PI) * 0.025f;
                    Vector3 handTargetLocal = Vector3.Lerp(
                        fromHandLocal, toHandLocal, eased) +
                        Vector3.right * outwardArc;
                    Vector3 elbowPoleLocal = Vector3.Lerp(
                        fromElbowLocal, toElbowLocal, eased) +
                        Vector3.right * (outwardArc * 1.8f) +
                        Vector3.up * (outwardArc * 0.25f);
                    SolveThrustModeEnterTwoBone(
                        upperArm,
                        foreArm,
                        hand,
                        root.TransformPoint(handTargetLocal),
                        root.TransformPoint(elbowPoleLocal),
                        "right-arm loop bridge");
                    Quaternion preferredUpperArmWorld =
                        upperArm.parent.rotation * Quaternion.Slerp(
                            from[RightArmPath].Rotation,
                            to[RightArmPath].Rotation,
                            eased);
                    upperArm.rotation = StabilizeStabbingBoneAxialRotation(
                        upperArm.rotation,
                        (foreArm.position - upperArm.position).normalized,
                        preferredUpperArmWorld);
                    foreArm.rotation = Quaternion.FromToRotation(
                        hand.position - foreArm.position,
                        root.TransformPoint(handTargetLocal) - foreArm.position) *
                        foreArm.rotation;
                    Quaternion preferredForeArmWorld =
                        foreArm.parent.rotation * Quaternion.Slerp(
                            from[RightForeArmPath].Rotation,
                            to[RightForeArmPath].Rotation,
                            eased);
                    foreArm.rotation = StabilizeStabbingBoneAxialRotation(
                        foreArm.rotation,
                        (hand.position - foreArm.position).normalized,
                        preferredForeArmWorld);
                    hand.rotation = root.rotation * Quaternion.Slerp(
                        fromHandRootRotation, toHandRootRotation, eased);
                    prop.localRotation = Quaternion.Slerp(
                        fromPropRotation, toPropRotation, eased);

                    if (index == 0)
                    {
                        ApplyStabbingRightArmLocalRotations(root, from);
                        prop.localRotation = fromPropRotation;
                    }
                    else if (index == times.Length - 1)
                    {
                        ApplyStabbingRightArmLocalRotations(root, to);
                        prop.localRotation = toPropRotation;
                    }
                    rotations[RightArmPath].Add(upperArm.localRotation);
                    rotations[RightForeArmPath].Add(foreArm.localRotation);
                    rotations[RightHandPath].Add(hand.localRotation);
                    rotations[DiagonalSlashPropPath].Add(prop.localRotation);
                }
            }
            finally
            {
                if (probe != null) UnityEngine.Object.DestroyImmediate(probe);
                EditorSceneManager.ClosePreviewScene(previewScene);
            }

            foreach (string path in paths)
                SetStabbingQuaternionCurves(
                    bridge, path, times, rotations[path]);
            bridge.EnsureQuaternionContinuity();
            AnimationClipSettings settings =
                AnimationUtility.GetAnimationClipSettings(bridge);
            settings.loopTime = false;
            settings.loopBlend = false;
            AnimationUtility.SetAnimationClipSettings(bridge, settings);
            EditorUtility.SetDirty(bridge);
        }

        private static void ApplyStabbingRightArmLocalRotations(
            Transform root,
            IReadOnlyDictionary<string, DiagonalSlashLocalPose> pose)
        {
            foreach (string path in new[]
            {
                RightArmPath,
                RightForeArmPath,
                RightHandPath
            })
                RequirePoseProbeBone(root, path).localRotation =
                    pose[path].Rotation;
        }

        private static void ApplyStabbingRightArmHoldPose(
            AnimationClip hold,
            IReadOnlyDictionary<string, DiagonalSlashLocalPose> pose,
            Quaternion propRotation)
        {
            float[] times = { 0f, hold.length };
            foreach (string path in new[]
            {
                RightArmPath,
                RightForeArmPath,
                RightHandPath
            })
                SetStabbingQuaternionCurves(
                    hold,
                    path,
                    times,
                    new[] { pose[path].Rotation, pose[path].Rotation });
            SetStabbingQuaternionCurves(
                hold,
                DiagonalSlashPropPath,
                times,
                new[] { propRotation, propRotation });
            hold.EnsureQuaternionContinuity();
            EditorUtility.SetDirty(hold);
        }

        private static void RequireLightsaberThrustArmPopCorrection(Scene scene)
        {
            GameObject target = FindUnique(scene, ThrustTargetName);
            Transform hand = RequireRightHand(target);
            Transform prop = RequireLightsaberProp(hand, target.name);
            AnimationClip bridge = RequireDiagonalSlashAsset<AnimationClip>(
                ThrustStabbingBridgeClipPath);
            AnimationClip exact = RequireDiagonalSlashAsset<AnimationClip>(
                ThrustStabbingExactClipPath);
            AnimationClip hold = RequireDiagonalSlashAsset<AnimationClip>(
                ThrustStabbingHoldClipPath);
            if (Mathf.Abs(bridge.length - ThrustStabbingBridgeSeconds) > 0.0001f ||
                Mathf.Abs(hold.length - ThrustStabbingHoldSeconds) > 0.0001f)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust arm-pop correction changed clip timing.");
            Dictionary<string, DiagonalSlashLocalPose> start =
                CaptureLightsaberThrustModeEnterLastPose(scene, out _);
            Dictionary<string, DiagonalSlashLocalPose> holdEnd =
                SampleDiagonalSlashPose(
                    target, prop, hold, hold.length, start);
            Dictionary<string, DiagonalSlashLocalPose> bridgeStart =
                SampleDiagonalSlashPose(target, prop, bridge, 0f, start);
            Dictionary<string, DiagonalSlashLocalPose> bridgeEnd =
                SampleDiagonalSlashPose(
                    target, prop, bridge, bridge.length, start);
            Dictionary<string, DiagonalSlashLocalPose> exactStart =
                SampleDiagonalSlashPose(target, prop, exact, 0f, start);
            float boundaryArmDelta = MaximumStabbingRightArmRotationDelta(
                holdEnd, bridgeStart);
            float boundaryPropDelta = Quaternion.Angle(
                EvaluatePropRotation(hold, hold.length),
                EvaluatePropRotation(bridge, 0f));
            float bridgeMaximumFrameStep =
                MeasureMaximumStabbingRightArmFrameStep(
                    target, prop, bridge, start);
            float exactMaximumFrameStep =
                MeasureMaximumStabbingRightArmFrameStep(
                    target, prop, exact, start);
            if (boundaryArmDelta > 0.02f || boundaryPropDelta > 0.02f)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust hold-to-bridge right arm still pops. arm=" +
                    Num(boundaryArmDelta) + "|prop=" + Num(boundaryPropDelta) + ".");
            RequireDiagonalSlashPoseEqual(
                bridgeEnd,
                exactStart,
                "smoothed bridge end/exact source start");
            if (bridgeMaximumFrameStep > ThrustArmPopFrameStepToleranceDegrees)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust smoothed bridge still has a right-arm " +
                    "rotation spike. maximumFrameStep=" +
                    Num(bridgeMaximumFrameStep) + ".");
            if (exactMaximumFrameStep > ThrustArmPopFrameStepToleranceDegrees)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust source motion still has a right-arm " +
                    "rotation spike. maximumFrameStep=" +
                    Num(exactMaximumFrameStep) + ".");
        }

        private static float MaximumStabbingRightArmRotationDelta(
            IReadOnlyDictionary<string, DiagonalSlashLocalPose> first,
            IReadOnlyDictionary<string, DiagonalSlashLocalPose> second)
        {
            float maximum = 0f;
            foreach (string path in new[]
            {
                RightArmPath,
                RightForeArmPath,
                RightHandPath
            })
                maximum = Mathf.Max(
                    maximum,
                    Quaternion.Angle(first[path].Rotation, second[path].Rotation));
            return maximum;
        }

        private static float MeasureMaximumStabbingRightArmFrameStep(
            GameObject target,
            Transform prop,
            AnimationClip clip,
            IReadOnlyDictionary<string, DiagonalSlashLocalPose> restorePose)
        {
            int frameCount = Mathf.Max(2, Mathf.RoundToInt(clip.length * 60f));
            Dictionary<string, DiagonalSlashLocalPose> previous = null;
            Quaternion previousProp = Quaternion.identity;
            float maximum = 0f;
            for (int frame = 0; frame <= frameCount; frame++)
            {
                float time = clip.length * frame / frameCount;
                Dictionary<string, DiagonalSlashLocalPose> current =
                    SampleDiagonalSlashPose(
                        target, prop, clip, time, restorePose);
                Quaternion currentProp = EvaluatePropRotation(clip, time);
                if (previous != null)
                {
                    maximum = Mathf.Max(
                        maximum,
                        MaximumStabbingRightArmRotationDelta(previous, current),
                        Quaternion.Angle(previousProp, currentProp));
                }
                previous = current;
                previousProp = currentProp;
            }
            return maximum;
        }

        private static ForearmDeformationComparison
            MeasureLightsaberThrustForearmDeformation(
                Scene scene,
                GameObject target)
        {
            const string PlayerModelPath =
                "Assets/_Project/Art/Player/player.fbx";
            GameObject playerModel = AssetDatabase.LoadAssetAtPath<GameObject>(
                PlayerModelPath) ?? throw new InvalidOperationException(
                    "Player model is missing: " + PlayerModelPath);
            AnimationClip source = RequireSingleDiagonalSlashClip(
                ThrustStabbingSourcePath,
                "lightsaber stabbing deformation source");
            AnimationClip corrected = RequireDiagonalSlashAsset<AnimationClip>(
                ThrustStabbingExactClipPath);
            if (Mathf.Abs(source.length - corrected.length) > 0.0001f)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust source/corrected durations differ.");
            Dictionary<string, DiagonalSlashLocalPose> restorePose =
                CaptureLightsaberThrustModeEnterLastPose(scene, out _);

            Scene previewScene = EditorSceneManager.NewPreviewScene();
            GameObject sourceProbe = null;
            GameObject correctedProbe = null;
            try
            {
                sourceProbe = CreateFullLightsaberThrustMeshProbe(
                    playerModel, previewScene, restorePose, "SourceMeshProbe");
                correctedProbe = CreateFullLightsaberThrustMeshProbe(
                    playerModel, previewScene, restorePose, "CorrectedMeshProbe");
                int frameCount = Mathf.Max(
                    2, Mathf.RoundToInt(corrected.length * 60f));
                float minimumDiameterRatio = float.PositiveInfinity;
                float worstTime = 0f;
                float sourceDiameterAtWorst = 0f;
                float correctedDiameterAtWorst = 0f;
                float maximumForearmAxialDelta = 0f;
                float maximumUpperArmAxialDelta = 0f;
                float correctedElbowBendAtWorst = 0f;
                int weightedVertices = 0;
                int measuredSliceCount = 0;
                string rendererNames = string.Empty;

                for (int frame = 0; frame <= frameCount; frame++)
                {
                    float time = corrected.length * frame / frameCount;
                    ApplyThrustModeEnterPose(sourceProbe.transform, restorePose);
                    ApplyThrustModeEnterPose(correctedProbe.transform, restorePose);
                    source.SampleAnimation(sourceProbe, time);
                    corrected.SampleAnimation(correctedProbe, time);

                    ForearmSkinMetric sourceMetric =
                        MeasureForearmSkinMetric(sourceProbe.transform);
                    ForearmSkinMetric correctedMetric =
                        MeasureForearmSkinMetric(correctedProbe.transform);
                    weightedVertices = Mathf.Max(
                        weightedVertices, correctedMetric.WeightedVertexCount);
                    measuredSliceCount = Mathf.Max(
                        measuredSliceCount, correctedMetric.MeasuredSliceCount);
                    if (string.IsNullOrEmpty(rendererNames))
                        rendererNames = correctedMetric.RendererNames;

                    Transform sourceUpper = RequirePoseProbeBone(
                        sourceProbe.transform, RightArmPath);
                    Transform sourceFore = RequirePoseProbeBone(
                        sourceProbe.transform, RightForeArmPath);
                    Transform sourceHand = RequirePoseProbeBone(
                        sourceProbe.transform, RightHandPath);
                    Transform correctedUpper = RequirePoseProbeBone(
                        correctedProbe.transform, RightArmPath);
                    Transform correctedFore = RequirePoseProbeBone(
                        correctedProbe.transform, RightForeArmPath);
                    Transform correctedHand = RequirePoseProbeBone(
                        correctedProbe.transform, RightHandPath);
                    maximumUpperArmAxialDelta = Mathf.Max(
                        maximumUpperArmAxialDelta,
                        AlignedBoneAxialDifference(
                            sourceUpper,
                            sourceFore.position - sourceUpper.position,
                            correctedUpper,
                            correctedFore.position - correctedUpper.position));
                    maximumForearmAxialDelta = Mathf.Max(
                        maximumForearmAxialDelta,
                        AlignedBoneAxialDifference(
                            sourceFore,
                            sourceHand.position - sourceFore.position,
                            correctedFore,
                            correctedHand.position - correctedFore.position));

                    if (sourceMetric.MinimumDiameterMeters <= 0.0001f ||
                        correctedMetric.MinimumDiameterMeters <= 0.0001f)
                        continue;
                    float ratio = correctedMetric.MinimumDiameterMeters /
                        sourceMetric.MinimumDiameterMeters;
                    if (ratio >= minimumDiameterRatio) continue;
                    minimumDiameterRatio = ratio;
                    worstTime = time;
                    sourceDiameterAtWorst = sourceMetric.MinimumDiameterMeters;
                    correctedDiameterAtWorst =
                        correctedMetric.MinimumDiameterMeters;
                    correctedElbowBendAtWorst = MeasureElbowBendDegrees(
                        correctedUpper, correctedFore, correctedHand);
                }

                if (float.IsPositiveInfinity(minimumDiameterRatio))
                    throw new InvalidOperationException(
                        "Lightsaber_Thrust forearm skin slices could not be measured. " +
                        "renderers=" + rendererNames +
                        "|weightedVertices=" + weightedVertices +
                        "|measuredSlices=" + measuredSliceCount + ".");
                return new ForearmDeformationComparison(
                    worstTime,
                    minimumDiameterRatio,
                    sourceDiameterAtWorst,
                    correctedDiameterAtWorst,
                    maximumUpperArmAxialDelta,
                    maximumForearmAxialDelta,
                    correctedElbowBendAtWorst,
                    weightedVertices,
                    measuredSliceCount,
                    rendererNames);
            }
            finally
            {
                if (sourceProbe != null)
                    UnityEngine.Object.DestroyImmediate(sourceProbe);
                if (correctedProbe != null)
                    UnityEngine.Object.DestroyImmediate(correctedProbe);
                EditorSceneManager.ClosePreviewScene(previewScene);
            }
        }

        private static GameObject CreateFullLightsaberThrustMeshProbe(
            GameObject playerModel,
            Scene previewScene,
            IReadOnlyDictionary<string, DiagonalSlashLocalPose> restorePose,
            string name)
        {
            GameObject probe = PrefabUtility.InstantiatePrefab(
                playerModel, previewScene) as GameObject ??
                throw new InvalidOperationException(
                    "Could not instantiate the player mesh probe.");
            probe.name = name;
            probe.hideFlags = HideFlags.HideAndDontSave;
            ApplyThrustModeEnterPose(probe.transform, restorePose);
            Transform hand = RequirePoseProbeBone(probe.transform, RightHandPath);
            Transform prop = hand.Find(PropName);
            if (prop == null)
            {
                prop = new GameObject(PropName).transform;
                prop.SetParent(hand, false);
            }
            prop.localPosition = AuthoredPropLocalPosition;
            prop.localRotation = AuthoredPropLocalRotation;
            prop.localScale = AuthoredPropLocalScale;
            foreach (SkinnedMeshRenderer renderer in
                probe.GetComponentsInChildren<SkinnedMeshRenderer>(true))
                renderer.updateWhenOffscreen = true;
            return probe;
        }

        private static ForearmSkinMetric MeasureForearmSkinMetric(
            Transform root)
        {
            Transform upperArm = RequirePoseProbeBone(root, RightArmPath);
            Transform foreArm = RequirePoseProbeBone(root, RightForeArmPath);
            Transform hand = RequirePoseProbeBone(root, RightHandPath);
            Vector3 axis = hand.position - foreArm.position;
            float length = axis.magnitude;
            if (length <= 0.0001f)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust forearm length is degenerate.");
            axis /= length;
            Vector3 basisU = Vector3.ProjectOnPlane(root.up, axis).normalized;
            if (basisU.sqrMagnitude < 0.5f)
                basisU = Vector3.ProjectOnPlane(root.right, axis).normalized;
            Vector3 basisV = Vector3.Cross(axis, basisU).normalized;
            const int BinCount = 7;
            var bins = Enumerable.Range(0, BinCount)
                .Select(_ => new List<Vector2>()).ToArray();
            int weightedVertexCount = 0;
            var rendererNames = new List<string>();

            foreach (SkinnedMeshRenderer renderer in
                root.GetComponentsInChildren<SkinnedMeshRenderer>(true))
            {
                Mesh shared = renderer.sharedMesh;
                if (shared == null || shared.vertexCount == 0) continue;
                Transform[] bones = renderer.bones;
                int upperIndex = Array.IndexOf(bones, upperArm);
                int foreIndex = Array.IndexOf(bones, foreArm);
                int handIndex = Array.IndexOf(bones, hand);
                if (foreIndex < 0) continue;
                BoneWeight[] weights = shared.boneWeights;
                if (weights.Length != shared.vertexCount) continue;
                rendererNames.Add(AnimationUtility.CalculateTransformPath(
                    renderer.transform, root));
                var baked = new Mesh();
                try
                {
                    renderer.BakeMesh(baked);
                    Vector3[] vertices = baked.vertices;
                    for (int vertex = 0; vertex < vertices.Length; vertex++)
                    {
                        BoneWeight weight = weights[vertex];
                        float foreWeight = BoneInfluence(
                            weight, foreIndex);
                        float armChainWeight = foreWeight +
                            BoneInfluence(weight, upperIndex) +
                            BoneInfluence(weight, handIndex);
                        if (foreWeight < 0.2f || armChainWeight < 0.72f)
                            continue;
                        Vector3 world = renderer.transform.TransformPoint(
                            vertices[vertex]);
                        float along = Vector3.Dot(
                            world - foreArm.position, axis);
                        const float StartFraction = 0.04f;
                        const float EndFraction = 0.62f;
                        float normalized = (along / length - StartFraction) /
                            (EndFraction - StartFraction);
                        int bin = Mathf.FloorToInt(normalized * BinCount);
                        if (bin < 0 || bin >= BinCount) continue;
                        Vector3 radial = world -
                            (foreArm.position + axis * along);
                        bins[bin].Add(new Vector2(
                            Vector3.Dot(radial, basisU),
                            Vector3.Dot(radial, basisV)));
                        weightedVertexCount++;
                    }
                }
                finally
                {
                    UnityEngine.Object.DestroyImmediate(baked);
                }
            }

            float minimumDiameter = float.PositiveInfinity;
            int measuredSlices = 0;
            foreach (List<Vector2> points in bins)
            {
                if (points.Count < 12) continue;
                measuredSlices++;
                Vector2 mean = points.Aggregate(
                    Vector2.zero, (sum, point) => sum + point) / points.Count;
                float covarianceXX = 0f;
                float covarianceYY = 0f;
                float covarianceXY = 0f;
                foreach (Vector2 point in points)
                {
                    Vector2 delta = point - mean;
                    covarianceXX += delta.x * delta.x;
                    covarianceYY += delta.y * delta.y;
                    covarianceXY += delta.x * delta.y;
                }
                covarianceXX /= points.Count;
                covarianceYY /= points.Count;
                covarianceXY /= points.Count;
                float trace = covarianceXX + covarianceYY;
                float determinant = covarianceXX * covarianceYY -
                    covarianceXY * covarianceXY;
                float minorEigenvalue = Mathf.Max(
                    0f,
                    trace * 0.5f - Mathf.Sqrt(Mathf.Max(
                        0f, trace * trace * 0.25f - determinant)));
                float minorDiameter = 4f * Mathf.Sqrt(minorEigenvalue);
                minimumDiameter = Mathf.Min(minimumDiameter, minorDiameter);
            }
            if (float.IsPositiveInfinity(minimumDiameter))
                minimumDiameter = 0f;
            return new ForearmSkinMetric(
                minimumDiameter,
                weightedVertexCount,
                measuredSlices,
                string.Join(",", rendererNames.Distinct()));
        }

        internal static float MeasureRightForearmMinimumDiameter(
            Transform root)
        {
            return MeasureForearmSkinMetric(root).MinimumDiameterMeters;
        }

        private static float BoneInfluence(BoneWeight weight, int boneIndex)
        {
            if (boneIndex < 0) return 0f;
            float result = 0f;
            if (weight.boneIndex0 == boneIndex) result += weight.weight0;
            if (weight.boneIndex1 == boneIndex) result += weight.weight1;
            if (weight.boneIndex2 == boneIndex) result += weight.weight2;
            if (weight.boneIndex3 == boneIndex) result += weight.weight3;
            return result;
        }

        private static float AlignedBoneAxialDifference(
            Transform sourceBone,
            Vector3 sourceAxis,
            Transform correctedBone,
            Vector3 correctedAxis)
        {
            sourceAxis.Normalize();
            correctedAxis.Normalize();
            Quaternion alignment = Quaternion.FromToRotation(
                sourceAxis, correctedAxis);
            foreach (Vector3 localReference in new[]
            {
                Vector3.up,
                Vector3.right,
                Vector3.forward
            })
            {
                Vector3 sourceReference = Vector3.ProjectOnPlane(
                    alignment * (sourceBone.rotation * localReference),
                    correctedAxis).normalized;
                Vector3 correctedReference = Vector3.ProjectOnPlane(
                    correctedBone.rotation * localReference,
                    correctedAxis).normalized;
                if (sourceReference.sqrMagnitude < 0.5f ||
                    correctedReference.sqrMagnitude < 0.5f)
                    continue;
                return Mathf.Abs(Vector3.SignedAngle(
                    sourceReference, correctedReference, correctedAxis));
            }
            return 0f;
        }

        private static float MeasureElbowBendDegrees(
            Transform upperArm,
            Transform foreArm,
            Transform hand)
        {
            return Vector3.Angle(
                foreArm.position - upperArm.position,
                hand.position - foreArm.position);
        }

        private static void RequireForearmDeformationCorrected(
            ForearmDeformationComparison comparison)
        {
            if (comparison.MinimumDiameterRatio <
                    ThrustForearmMinimumDiameterRatio ||
                comparison.MaximumForearmAxialDeltaDegrees >
                    ThrustForearmMaximumAxialDeltaDegrees)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust right forearm is still compressed or " +
                    "axially inverted. " + comparison.Describe());
        }

        private static StabbingCorrectionSummary
            CreateOrUpdateStabbingRightHandBladeForwardClip(
                GameObject target,
                Transform targetProp,
                AnimationClip baseClip,
                string assetPath,
                string clipName,
                IReadOnlyDictionary<string, DiagonalSlashLocalPose> restorePose,
                Quaternion fallbackPropRotation)
        {
            float[] times = StabbingCorrectionSampleTimes(baseClip);
            var generated = new AnimationClip();
            EditorUtility.CopySerialized(baseClip, generated);
            generated.name = clipName;
            Scene previewScene = EditorSceneManager.NewPreviewScene();
            GameObject probe = null;
            var rotations = new Dictionary<string, List<Quaternion>>(
                StringComparer.Ordinal)
            {
                [RightArmPath] = new List<Quaternion>(times.Length),
                [RightForeArmPath] = new List<Quaternion>(times.Length),
                [RightHandPath] = new List<Quaternion>(times.Length),
                [DiagonalSlashPropPath] = new List<Quaternion>(times.Length)
            };
            var summary = new StabbingCorrectionSummary();
            try
            {
                probe = CreateThrustModeEnterPoseProbe(
                    previewScene, restorePose, out Transform prop);
                Animator sourceAnimator = target.GetComponent<Animator>();
                if (sourceAnimator != null && sourceAnimator.avatar != null)
                {
                    Animator probeAnimator = probe.AddComponent<Animator>();
                    probeAnimator.avatar = sourceAnimator.avatar;
                    probeAnimator.applyRootMotion = false;
                    probeAnimator.enabled = false;
                }
                Transform root = probe.transform;
                Vector3? previousElbow = null;
                for (int index = 0; index < times.Length; index++)
                {
                    ApplyThrustModeEnterPose(root, restorePose);
                    prop.localPosition = targetProp.localPosition;
                    prop.localRotation = fallbackPropRotation;
                    prop.localScale = targetProp.localScale;
                    baseClip.SampleAnimation(probe, times[index]);
                    StabbingCorrectionFrame frame =
                        ApplyStabbingRightHandBladeForwardPose(
                            root,
                            prop,
                            previousElbow,
                            out Vector3 correctedElbow);
                    previousElbow = correctedElbow;
                    rotations[RightArmPath].Add(
                        RequirePoseProbeBone(root, RightArmPath).localRotation);
                    rotations[RightForeArmPath].Add(
                        RequirePoseProbeBone(root, RightForeArmPath).localRotation);
                    rotations[RightHandPath].Add(
                        RequirePoseProbeBone(root, RightHandPath).localRotation);
                    rotations[DiagonalSlashPropPath].Add(prop.localRotation);
                    summary.Accumulate(frame);
                }
            }
            finally
            {
                if (probe != null) UnityEngine.Object.DestroyImmediate(probe);
                EditorSceneManager.ClosePreviewScene(previewScene);
            }

            RemoveStabbingCorrectionRotationCurves(generated);
            foreach (KeyValuePair<string, List<Quaternion>> item in rotations)
                SetStabbingQuaternionCurves(
                    generated, item.Key, times, item.Value);
            generated.EnsureQuaternionContinuity();
            AnimationClipSettings settings =
                AnimationUtility.GetAnimationClipSettings(generated);
            settings.loopTime = false;
            settings.loopBlend = false;
            AnimationUtility.SetAnimationClipSettings(generated, settings);
            AnimationClip output = AssetDatabase.LoadAssetAtPath<AnimationClip>(
                assetPath);
            if (output == null)
            {
                AssetDatabase.CreateAsset(generated, assetPath);
                output = generated;
            }
            else
            {
                EditorUtility.CopySerialized(generated, output);
                output.name = clipName;
                EditorUtility.SetDirty(output);
                UnityEngine.Object.DestroyImmediate(generated);
            }
            if (Mathf.Abs(output.length - baseClip.length) > 0.0001f ||
                Mathf.Abs(output.frameRate - baseClip.frameRate) > 0.0001f ||
                output.isLooping)
                throw new InvalidOperationException(
                    clipName + " changed the protected clip timing.");
            return summary;
        }

        private static AnimationClip ApplyStabbingRightHandBladeForwardPasses(
            GameObject target,
            Transform targetProp,
            AnimationClip initial,
            string assetPath,
            string clipName,
            IReadOnlyDictionary<string, DiagonalSlashLocalPose> restorePose,
            Quaternion fallbackPropRotation,
            StabbingCorrectionSummary total)
        {
            AnimationClip current = initial;
            const int CorrectionPassCount = 4;
            for (int pass = 0; pass < CorrectionPassCount; pass++)
            {
                total.Accumulate(
                    CreateOrUpdateStabbingRightHandBladeForwardClip(
                        target,
                        targetProp,
                        current,
                        assetPath,
                        clipName,
                        restorePose,
                        fallbackPropRotation));
                current = RequireDiagonalSlashAsset<AnimationClip>(assetPath);
            }
            return current;
        }

        private static float[] StabbingCorrectionSampleTimes(AnimationClip clip)
        {
            float frameRate = Mathf.Max(1f, clip.frameRate);
            int frameCount = Mathf.Max(1, Mathf.CeilToInt(clip.length * frameRate));
            var times = new SortedSet<float>();
            for (int frame = 0; frame <= frameCount; frame++)
                times.Add(Mathf.Min(frame / frameRate, clip.length));
            foreach (EditorCurveBinding binding in
                AnimationUtility.GetCurveBindings(clip))
            {
                AnimationCurve curve = AnimationUtility.GetEditorCurve(clip, binding);
                if (curve == null) continue;
                foreach (Keyframe key in curve.keys)
                    times.Add(Mathf.Clamp(key.time, 0f, clip.length));
            }
            times.Add(0f);
            times.Add(clip.length);
            return times.ToArray();
        }

        private static StabbingCorrectionFrame
            ApplyStabbingRightHandBladeForwardPose(
                Transform root,
                Transform prop,
                Vector3? preferredElbow,
                out Vector3 correctedElbow)
        {
            Transform upperArm = RequirePoseProbeBone(root, RightArmPath);
            Transform foreArm = RequirePoseProbeBone(root, RightForeArmPath);
            Transform hand = RequirePoseProbeBone(root, RightHandPath);
            Vector3 originalHandPosition = hand.position;
            Vector3 originalElbowPosition = foreArm.position;
            Vector3 desiredBack = root.right.normalized;

            Vector3 targetElbow = SelectNaturalStabbingElbowTarget(
                upperArm.position,
                originalElbowPosition,
                originalHandPosition,
                desiredBack,
                preferredElbow);
            Vector3 currentUpper = foreArm.position - upperArm.position;
            Vector3 desiredUpper = targetElbow - upperArm.position;
            if (currentUpper.sqrMagnitude <= 0.000001f ||
                desiredUpper.sqrMagnitude <= 0.000001f)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust right upper-arm direction is degenerate.");
            upperArm.rotation = Quaternion.FromToRotation(
                currentUpper, desiredUpper) * upperArm.rotation;

            Vector3 currentLower = hand.position - foreArm.position;
            Vector3 desiredLower = originalHandPosition - foreArm.position;
            if (currentLower.sqrMagnitude <= 0.000001f ||
                desiredLower.sqrMagnitude <= 0.000001f)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust right forearm direction is degenerate.");
            foreArm.rotation = Quaternion.FromToRotation(
                currentLower, desiredLower) * foreArm.rotation;

            Vector3 lowerAxis = (hand.position - foreArm.position).normalized;
            Quaternion backCorrection = Quaternion.FromToRotation(
                RightHandBackDirection(hand), desiredBack);
            hand.rotation = backCorrection * hand.rotation;
            Vector3 desiredFingerDirection = Vector3.ProjectOnPlane(
                lowerAxis, desiredBack).normalized;
            if (desiredFingerDirection.sqrMagnitude < 0.5f)
                desiredFingerDirection = Vector3.ProjectOnPlane(
                    root.forward, desiredBack).normalized;
            Vector3 currentFingerDirection = Vector3.ProjectOnPlane(
                RightHandFingerDirection(hand), desiredBack).normalized;
            if (currentFingerDirection.sqrMagnitude < 0.5f)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust right-hand finger direction is degenerate.");
            float handRoll = Vector3.SignedAngle(
                currentFingerDirection,
                desiredFingerDirection,
                desiredBack);
            hand.rotation = Quaternion.AngleAxis(
                handRoll, desiredBack) * hand.rotation;

            Vector3 currentBlade = prop.TransformDirection(
                DiagonalSlashBladeAxisLocal()).normalized;
            prop.rotation = Quaternion.FromToRotation(
                currentBlade, root.forward) * prop.rotation;

            float handBackAngle = Vector3.Angle(
                RightHandBackDirection(hand), desiredBack);
            float bladeForwardAngle = Vector3.Angle(
                prop.TransformDirection(DiagonalSlashBladeAxisLocal()),
                root.forward);
            float wristBend = Vector3.Angle(
                RightHandFingerDirection(hand), lowerAxis);
            float handPositionDelta = Vector3.Distance(
                hand.position, originalHandPosition);
            if (handBackAngle > ThrustStabbingHandBackToleranceDegrees ||
                bladeForwardAngle > ThrustStabbingBladeForwardToleranceDegrees ||
                wristBend > ThrustStabbingWristBendToleranceDegrees ||
                handPositionDelta > 0.002f)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust right-hand correction could not satisfy " +
                    "the anatomical target. handBack=" + Num(handBackAngle) +
                    "|blade=" + Num(bladeForwardAngle) +
                    "|wrist=" + Num(wristBend) +
                    "|handPositionDelta=" + Num(handPositionDelta) + ".");
            correctedElbow = foreArm.position;
            return new StabbingCorrectionFrame(
                handBackAngle,
                bladeForwardAngle,
                wristBend,
                handPositionDelta);
        }

        private static Quaternion StabilizeStabbingBoneAxialRotation(
            Quaternion currentRotation,
            Vector3 boneAxis,
            Quaternion preferredRotation)
        {
            if (boneAxis.sqrMagnitude < 0.99f) return currentRotation;
            boneAxis.Normalize();
            foreach (Vector3 localReference in new[]
            {
                Vector3.up,
                Vector3.right,
                Vector3.forward
            })
            {
                Vector3 currentReference = Vector3.ProjectOnPlane(
                    currentRotation * localReference, boneAxis).normalized;
                Vector3 preferredReference = Vector3.ProjectOnPlane(
                    preferredRotation * localReference, boneAxis).normalized;
                if (currentReference.sqrMagnitude < 0.5f ||
                    preferredReference.sqrMagnitude < 0.5f)
                    continue;
                float twist = Vector3.SignedAngle(
                    currentReference, preferredReference, boneAxis);
                return Quaternion.AngleAxis(twist, boneAxis) * currentRotation;
            }
            return currentRotation;
        }

        private static Vector3 SelectNaturalStabbingElbowTarget(
            Vector3 shoulder,
            Vector3 originalElbow,
            Vector3 hand,
            Vector3 desiredHandBack,
            Vector3? preferredElbow)
        {
            float upperLength = Vector3.Distance(shoulder, originalElbow);
            float lowerLength = Vector3.Distance(originalElbow, hand);
            Vector3 shoulderToHand = hand - shoulder;
            float distance = shoulderToHand.magnitude;
            if (upperLength <= 0.0001f || lowerLength <= 0.0001f ||
                distance <= 0.0001f)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust right-arm lengths are degenerate.");

            float reachableDistance = Mathf.Clamp(
                distance,
                Mathf.Abs(upperLength - lowerLength) + 0.0001f,
                upperLength + lowerLength - 0.0001f);
            Vector3 lineAxis = shoulderToHand / distance;
            float along =
                (upperLength * upperLength - lowerLength * lowerLength +
                 reachableDistance * reachableDistance) /
                (2f * reachableDistance);
            float radius = Mathf.Sqrt(Mathf.Max(
                0f, upperLength * upperLength - along * along));
            Vector3 center = shoulder + lineAxis * along;
            Vector3 originalRadial = Vector3.ProjectOnPlane(
                originalElbow - center, lineAxis);
            if (originalRadial.sqrMagnitude <= 0.000001f)
                originalRadial = Vector3.ProjectOnPlane(
                    desiredHandBack, lineAxis);
            if (originalRadial.sqrMagnitude <= 0.000001f)
                originalRadial = Vector3.Cross(lineAxis, Vector3.up);
            if (originalRadial.sqrMagnitude <= 0.000001f)
                originalRadial = Vector3.Cross(lineAxis, Vector3.forward);
            Vector3 basisU = originalRadial.normalized;
            Vector3 basisV = Vector3.Cross(lineAxis, basisU).normalized;

            Vector3 best = originalElbow;
            float bestScore = float.PositiveInfinity;
            const int CandidateCount = 720;
            for (int index = 0; index < CandidateCount; index++)
            {
                float angle = 360f * index / CandidateCount;
                Vector3 radial =
                    basisU * Mathf.Cos(angle * Mathf.Deg2Rad) +
                    basisV * Mathf.Sin(angle * Mathf.Deg2Rad);
                Vector3 candidate = center + radial * radius;
                Vector3 lowerDirection = (hand - candidate).normalized;
                float lateral = Mathf.Abs(Vector3.Dot(
                    lowerDirection, desiredHandBack));
                float deviation = Vector3.Angle(
                    candidate - center, originalElbow - center) / 180f;
                float continuity = preferredElbow.HasValue
                    ? Vector3.Distance(candidate, preferredElbow.Value) /
                        Mathf.Max(radius, 0.0001f)
                    : 0f;
                float maximumLateral = Mathf.Sin(16f * Mathf.Deg2Rad);
                float lateralExcess = Mathf.Max(0f, lateral - maximumLateral);
                float score = preferredElbow.HasValue
                    ? lateralExcess * 100000f + continuity * 1000f +
                        lateral * 10f + deviation * 0.1f
                    : lateralExcess * 100000f + lateral * 10f +
                        deviation * 2f;
                if (score >= bestScore) continue;
                bestScore = score;
                best = candidate;
            }
            return best;
        }

        internal static Vector3 RightHandBackDirection(Transform hand)
        {
            Transform index = hand.Find("RightIndexProximal") ??
                throw new InvalidOperationException(
                    "RightIndexProximal is missing from Lightsaber_Thrust.");
            Transform little = hand.Find("RightLittleProximal") ??
                throw new InvalidOperationException(
                    "RightLittleProximal is missing from Lightsaber_Thrust.");
            Vector3 across = (index.position - little.position).normalized;
            Vector3 finger = RightHandFingerDirection(hand);
            Vector3 back = Vector3.Cross(across, finger).normalized;
            if (back.sqrMagnitude < 0.5f)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust right-hand back direction is degenerate.");
            return back;
        }

        internal static Vector3 RightHandFingerDirection(Transform hand)
        {
            Transform middle = hand.Find("RightMiddleProximal") ??
                throw new InvalidOperationException(
                    "RightMiddleProximal is missing from Lightsaber_Thrust.");
            Vector3 direction = (middle.position - hand.position).normalized;
            if (direction.sqrMagnitude < 0.5f)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust right-hand finger direction is degenerate.");
            return direction;
        }

        private static float SignedProjectedAngle(
            Vector3 from,
            Vector3 to,
            Vector3 axis)
        {
            Vector3 projectedFrom = Vector3.ProjectOnPlane(from, axis).normalized;
            Vector3 projectedTo = Vector3.ProjectOnPlane(to, axis).normalized;
            if (projectedFrom.sqrMagnitude < 0.5f ||
                projectedTo.sqrMagnitude < 0.5f)
                return 0f;
            return Vector3.SignedAngle(projectedFrom, projectedTo, axis);
        }

        private static void RemoveStabbingCorrectionRotationCurves(
            AnimationClip clip)
        {
            foreach (EditorCurveBinding binding in
                AnimationUtility.GetCurveBindings(clip))
            {
                if (!IsStabbingCorrectionRotationBinding(binding)) continue;
                AnimationUtility.SetEditorCurve(clip, binding, null);
            }
        }

        private static bool IsStabbingCorrectionRotationBinding(
            EditorCurveBinding binding)
        {
            bool correctedPath = binding.path == RightArmPath ||
                binding.path == RightForeArmPath ||
                binding.path == RightHandPath ||
                binding.path.StartsWith(
                    RightHandPath + "/", StringComparison.Ordinal) ||
                binding.path == DiagonalSlashPropPath;
            return correctedPath &&
                (binding.propertyName.StartsWith(
                    "m_LocalRotation.", StringComparison.Ordinal) ||
                 binding.propertyName.StartsWith(
                    "localEulerAngles", StringComparison.Ordinal));
        }

        private static void SetStabbingQuaternionCurves(
            AnimationClip clip,
            string path,
            IReadOnlyList<float> times,
            IReadOnlyList<Quaternion> rotations)
        {
            if (times.Count != rotations.Count || times.Count < 2)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust correction quaternion samples differ.");
            Quaternion[] continuous = rotations.ToArray();
            for (int index = 1; index < continuous.Length; index++)
                if (Quaternion.Dot(continuous[index - 1], continuous[index]) < 0f)
                    continuous[index] = NegateQuaternion(continuous[index]);
            string[] properties =
            {
                "m_LocalRotation.x", "m_LocalRotation.y",
                "m_LocalRotation.z", "m_LocalRotation.w"
            };
            Func<Quaternion, float>[] selectors =
            {
                item => item.x, item => item.y,
                item => item.z, item => item.w
            };
            for (int component = 0; component < properties.Length; component++)
            {
                var curve = new AnimationCurve();
                for (int index = 0; index < times.Count; index++)
                    curve.AddKey(new Keyframe(
                        times[index], selectors[component](continuous[index])));
                for (int index = 0; index < curve.length; index++)
                {
                    AnimationUtility.SetKeyLeftTangentMode(
                        curve, index, AnimationUtility.TangentMode.Linear);
                    AnimationUtility.SetKeyRightTangentMode(
                        curve, index, AnimationUtility.TangentMode.Linear);
                }
                curve.preWrapMode = WrapMode.ClampForever;
                curve.postWrapMode = WrapMode.ClampForever;
                AnimationUtility.SetEditorCurve(
                    clip,
                    EditorCurveBinding.FloatCurve(
                        path, typeof(Transform), properties[component]),
                    curve);
            }
        }

        private static StabbingCorrectionSummary
            MeasureStabbingRightHandBladeDirections(
                GameObject target,
                Transform targetProp,
                AnimationClip clip,
                IReadOnlyDictionary<string, DiagonalSlashLocalPose> restorePose,
                Quaternion fallbackPropRotation)
        {
            float[] times = StabbingCorrectionSampleTimes(clip);
            Scene previewScene = EditorSceneManager.NewPreviewScene();
            GameObject probe = null;
            var summary = new StabbingCorrectionSummary();
            try
            {
                probe = CreateThrustModeEnterPoseProbe(
                    previewScene, restorePose, out Transform prop);
                Animator sourceAnimator = target.GetComponent<Animator>();
                if (sourceAnimator != null && sourceAnimator.avatar != null)
                {
                    Animator probeAnimator = probe.AddComponent<Animator>();
                    probeAnimator.avatar = sourceAnimator.avatar;
                    probeAnimator.applyRootMotion = false;
                    probeAnimator.enabled = false;
                }
                Transform root = probe.transform;
                for (int index = 0; index < times.Length; index++)
                {
                    ApplyThrustModeEnterPose(root, restorePose);
                    prop.localPosition = targetProp.localPosition;
                    prop.localRotation = fallbackPropRotation;
                    prop.localScale = targetProp.localScale;
                    clip.SampleAnimation(probe, times[index]);
                    Transform foreArm = RequirePoseProbeBone(
                        root, RightForeArmPath);
                    Transform hand = RequirePoseProbeBone(root, RightHandPath);
                    Vector3 lowerAxis = (hand.position - foreArm.position).normalized;
                    summary.Accumulate(new StabbingCorrectionFrame(
                        Vector3.Angle(RightHandBackDirection(hand), root.right),
                        Vector3.Angle(
                            prop.TransformDirection(DiagonalSlashBladeAxisLocal()),
                            root.forward),
                        Vector3.Angle(
                            RightHandFingerDirection(hand), lowerAxis),
                        0f));
                }
            }
            finally
            {
                if (probe != null) UnityEngine.Object.DestroyImmediate(probe);
                EditorSceneManager.ClosePreviewScene(previewScene);
            }
            return summary;
        }

        internal readonly struct TopGripFrame
        {
            internal TopGripFrame(
                float handBackUpAngleDegrees,
                float handleAxisErrorDegrees,
                float palmCenterErrorMeters,
                float fingerPoseErrorDegrees,
                float fingerContactErrorMeters,
                float wristBendDegrees)
            {
                HandBackUpAngleDegrees = handBackUpAngleDegrees;
                HandleAxisErrorDegrees = handleAxisErrorDegrees;
                PalmCenterErrorMeters = palmCenterErrorMeters;
                FingerPoseErrorDegrees = fingerPoseErrorDegrees;
                FingerContactErrorMeters = fingerContactErrorMeters;
                WristBendDegrees = wristBendDegrees;
            }

            internal float HandBackUpAngleDegrees { get; }
            internal float HandleAxisErrorDegrees { get; }
            internal float PalmCenterErrorMeters { get; }
            internal float FingerPoseErrorDegrees { get; }
            internal float FingerContactErrorMeters { get; }
