        private sealed class TopGripSummary
        {
            internal int FrameCount { get; private set; }
            internal float MaximumHandBackUpAngleDegrees { get; private set; }
            internal float MaximumHandleAxisErrorDegrees { get; private set; }
            internal float MaximumPalmCenterErrorMeters { get; private set; }
            internal float MaximumFingerPoseErrorDegrees { get; private set; }
            internal float MaximumFingerContactErrorMeters { get; private set; }
            internal float MaximumWristBendDegrees { get; private set; }
            internal string WorstClipPath { get; private set; } = string.Empty;
            internal float WorstTimeSeconds { get; private set; }

            internal void Accumulate(
                string clipPath,
                float time,
                TopGripFrame frame)
            {
                FrameCount++;
                float previousWorst = Mathf.Max(
                    MaximumHandBackUpAngleDegrees,
                    MaximumHandleAxisErrorDegrees,
                    MaximumPalmCenterErrorMeters * 1000f,
                    MaximumFingerPoseErrorDegrees,
                    MaximumFingerContactErrorMeters * 1000f,
                    MaximumWristBendDegrees);
                MaximumHandBackUpAngleDegrees = Mathf.Max(
                    MaximumHandBackUpAngleDegrees,
                    frame.HandBackUpAngleDegrees);
                MaximumHandleAxisErrorDegrees = Mathf.Max(
                    MaximumHandleAxisErrorDegrees,
                    frame.HandleAxisErrorDegrees);
                MaximumPalmCenterErrorMeters = Mathf.Max(
                    MaximumPalmCenterErrorMeters,
                    frame.PalmCenterErrorMeters);
                MaximumFingerPoseErrorDegrees = Mathf.Max(
                    MaximumFingerPoseErrorDegrees,
                    frame.FingerPoseErrorDegrees);
                MaximumFingerContactErrorMeters = Mathf.Max(
                    MaximumFingerContactErrorMeters,
                    frame.FingerContactErrorMeters);
                MaximumWristBendDegrees = Mathf.Max(
                    MaximumWristBendDegrees,
                    frame.WristBendDegrees);
                float currentWorst = Mathf.Max(
                    frame.HandBackUpAngleDegrees,
                    frame.HandleAxisErrorDegrees,
                    frame.PalmCenterErrorMeters * 1000f,
                    frame.FingerPoseErrorDegrees,
                    frame.FingerContactErrorMeters * 1000f,
                    frame.WristBendDegrees);
                if (currentWorst <= previousWorst) return;
                WorstClipPath = clipPath;
                WorstTimeSeconds = time;
            }

            internal string Describe()
            {
                return "frameCount=" + FrameCount +
                    "|maximumHandBackUpAngleDegrees=" +
                        Num(MaximumHandBackUpAngleDegrees) +
                    "|maximumHandleAxisErrorDegrees=" +
                        Num(MaximumHandleAxisErrorDegrees) +
                    "|maximumPalmCenterErrorMeters=" +
                        Num(MaximumPalmCenterErrorMeters) +
                    "|maximumFingerPoseErrorDegrees=" +
                        Num(MaximumFingerPoseErrorDegrees) +
                    "|maximumFingerContactErrorMeters=" +
                        Num(MaximumFingerContactErrorMeters) +
                    "|maximumWristBendDegrees=" +
                        Num(MaximumWristBendDegrees) +
                    "|worstClipPath=" + WorstClipPath +
                    "|worstTimeSeconds=" + Num(WorstTimeSeconds);
            }
        }

