        private static AnimationClip CreateOrUpdateStabbingPoseClip(
            string assetPath,
            string clipName,
            IReadOnlyDictionary<string, DiagonalSlashLocalPose> from,
            IReadOnlyDictionary<string, DiagonalSlashLocalPose> to,
            float duration,
            Quaternion propRotation)
        {
            AnimationClip clip = CreateOrUpdateGripOneHandPoseClip(
                assetPath, clipName, from, to, duration);
            Quaternion rotation = propRotation;
            SetGripOneHandCurve(clip, DiagonalSlashPropPath,
                "m_LocalRotation.x", rotation.x, rotation.x, duration);
            SetGripOneHandCurve(clip, DiagonalSlashPropPath,
                "m_LocalRotation.y", rotation.y, rotation.y, duration);
            SetGripOneHandCurve(clip, DiagonalSlashPropPath,
                "m_LocalRotation.z", rotation.z, rotation.z, duration);
            SetGripOneHandCurve(clip, DiagonalSlashPropPath,
                "m_LocalRotation.w", rotation.w, rotation.w, duration);
            clip.EnsureQuaternionContinuity();
            FlattenThrustModeEnterHoldTangents(clip);
            EditorUtility.SetDirty(clip);
            return clip;
        }

        private static AnimatorController
            CreateOrUpdateLightsaberThrustStabbingController(
                AnimationClip bridge,
                AnimationClip source,
                AnimationClip hold)
        {
            AnimatorController controller =
                AssetDatabase.LoadAssetAtPath<AnimatorController>(
                    ThrustStabbingControllerPath);
            if (controller == null)
                controller = AnimatorController.CreateAnimatorControllerAtPath(
                    ThrustStabbingControllerPath);
            while (controller.layers.Length > 1)
                controller.RemoveLayer(controller.layers.Length - 1);
            if (controller.layers.Length != 1)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust stabbing controller must contain one layer.");
            AnimatorControllerLayer layer = controller.layers[0];
            AnimatorStateMachine stateMachine = layer.stateMachine;
            foreach (AnimatorState state in stateMachine.states
                .Select(item => item.state).ToArray())
                stateMachine.RemoveState(state);
            foreach (AnimatorStateMachine nested in stateMachine.stateMachines
                .Select(item => item.stateMachine).ToArray())
                stateMachine.RemoveStateMachine(nested);
            controller.parameters = Array.Empty<AnimatorControllerParameter>();
            layer.name = "Lightsaber Thrust Exact Stabbing Sequence";
            layer.defaultWeight = 1f;
            layer.blendingMode = AnimatorLayerBlendingMode.Override;
            layer.avatarMask = null;

            AnimatorState bridgeState = bridge == null
                ? null
                : AddDiagonalSlashState(
                    stateMachine, ThrustStabbingBridgeStateName, bridge);
            AnimatorState sourceState = AddDiagonalSlashState(
                stateMachine, ThrustStabbingSourceStateName, source);
            sourceState.speed = ThrustStabbingPlaybackSpeed;
            AnimatorState holdState = AddDiagonalSlashState(
                stateMachine, ThrustStabbingHoldStateName, hold);
            if (bridgeState != null)
                AddImmediateDiagonalSlashTransition(bridgeState, sourceState);
            AddImmediateDiagonalSlashTransition(sourceState, holdState);
            AddImmediateDiagonalSlashTransition(
                holdState, bridgeState ?? sourceState);
            stateMachine.defaultState = bridgeState ?? sourceState;
            controller.layers = new[] { layer };
            EditorUtility.SetDirty(stateMachine);
            EditorUtility.SetDirty(controller);
            return controller;
        }

        private static void RequireLightsaberThrustStabbingController(
            Animator animator,
            AnimationClip bridge,
            AnimationClip source,
            AnimationClip hold,
            bool bridgeRequired)
        {
            AnimatorController controller = animator.runtimeAnimatorController as
                AnimatorController ?? throw new InvalidOperationException(
                    "Lightsaber_Thrust stabbing controller is missing.");
            if (AssetDatabase.GetAssetPath(controller) !=
                    ThrustStabbingControllerPath ||
                controller.layers.Length != 1 ||
                controller.parameters.Length != 0)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust stabbing controller structure differs.");
            AnimatorControllerLayer layer = controller.layers[0];
            AnimatorState[] states = layer.stateMachine.states
                .Select(item => item.state).ToArray();
            if (states.Length != (bridgeRequired ? 3 : 2))
                throw new InvalidOperationException(
                    "Lightsaber_Thrust stabbing state count differs.");
            AnimatorState sourceState = RequireStabbingState(
                states, ThrustStabbingSourceStateName, source,
                ThrustStabbingPlaybackSpeed);
            AnimatorState holdState = RequireStabbingState(
                states, ThrustStabbingHoldStateName, hold, 1f);
            AnimatorState firstState = sourceState;
            if (bridgeRequired)
            {
                AnimatorState bridgeState = RequireStabbingState(
                    states, ThrustStabbingBridgeStateName, bridge, 1f);
                RequireImmediateDiagonalSlashTransition(
                    bridgeState, sourceState, "stabbing bridge/source");
                firstState = bridgeState;
            }
            RequireImmediateDiagonalSlashTransition(
                sourceState, holdState, "stabbing source/hold");
            RequireImmediateDiagonalSlashTransition(
                holdState, firstState, "stabbing hold/immediate reset");
            if (layer.stateMachine.defaultState != firstState)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust stabbing default state differs.");
        }

        private static AnimatorState RequireStabbingState(
            IEnumerable<AnimatorState> states,
            string name,
            Motion motion,
            float expectedSpeed)
        {
            AnimatorState state = states.SingleOrDefault(item => item.name == name) ??
                throw new InvalidOperationException(
                    "Lightsaber_Thrust stabbing state is missing: " + name);
            if (state.motion != motion ||
                !Mathf.Approximately(state.speed, expectedSpeed) ||
                state.mirror || state.writeDefaultValues ||
                state.behaviours.Length != 0)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust stabbing state settings differ: " + name);
            return state;
        }

