        private sealed class TransformSnapshot
        {
            private readonly Transform transform;
            private readonly Transform parent;
            private readonly Vector3 localPosition;
            private readonly Quaternion localRotation;
            private readonly Vector3 localScale;
            private readonly bool activeSelf;

            internal TransformSnapshot(Transform transform)
            {
                this.transform = transform;
                parent = transform.parent;
                localPosition = transform.localPosition;
                localRotation = transform.localRotation;
                localScale = transform.localScale;
                activeSelf = transform.gameObject.activeSelf;
            }

            internal void RequireUnchanged()
            {
                if (transform == null || transform.parent != parent ||
                    Vector3.Distance(transform.localPosition, localPosition) > 0.000001f ||
                    Quaternion.Angle(transform.localRotation, localRotation) > 0.0001f ||
                    Vector3.Distance(transform.localScale, localScale) > 0.000001f ||
                    transform.gameObject.activeSelf != activeSelf)
                    throw new InvalidOperationException(
                        "Existing scene transform changed unexpectedly while placing lightsabers.");
            }
        }

        private sealed class NonRotationTransformSnapshot
        {
            private readonly Transform transform;
            private readonly Transform parent;
            private readonly Vector3 localPosition;
            private readonly Vector3 localScale;
            private readonly bool activeSelf;

            internal NonRotationTransformSnapshot(Transform transform)
            {
                this.transform = transform;
                parent = transform.parent;
                localPosition = transform.localPosition;
                localScale = transform.localScale;
                activeSelf = transform.gameObject.activeSelf;
            }

            internal void RequireUnchanged()
            {
                if (transform == null || transform.parent != parent ||
                    Vector3.Distance(transform.localPosition, localPosition) > 0.000001f ||
                    Vector3.Distance(transform.localScale, localScale) > 0.000001f ||
                    transform.gameObject.activeSelf != activeSelf)
                    throw new InvalidOperationException(
                        "Lightsaber grip changed a protected parent, position, scale, or active state.");
            }
        }

        private sealed class RotationSnapshot
        {
            private readonly Transform transform;
            private readonly Quaternion localRotation;

            internal RotationSnapshot(Transform transform)
            {
                this.transform = transform;
                localRotation = transform.localRotation;
            }

            internal void RequireUnchanged()
            {
                if (transform == null ||
                    Quaternion.Angle(transform.localRotation, localRotation) > 0.0001f)
                    throw new InvalidOperationException(
                        "Lightsaber grip changed a protected rotation under the right arm.");
            }
        }
    }

    [InitializeOnLoad]
    internal static class LightsaberThrustModeExitPlayModeCapture
    {
        private const string StateKey =
            "Bellerophon.LightsaberThrustModeExitCapture.State";
        private const string IndexKey =
            "Bellerophon.LightsaberThrustModeExitCapture.Index";
        private const string WaitStartKey =
            "Bellerophon.LightsaberThrustModeExitCapture.WaitStart";
        private const string ConsoleErrorsBeforeKey =
            "Bellerophon.LightsaberThrustModeExitCapture.ConsoleErrorsBefore";
        private const string FailureKey =
            "Bellerophon.LightsaberThrustModeExitCapture.Failure";
        private const int WaitingForPlayMode = 1;
        private const int WaitingForCycleStart = 2;
        private const int Capturing = 3;
        private const int WaitingForEditMode = 4;
        private const int FailedWaitingForEditMode = 5;
        private static readonly float[] ExpectedNormalizedTimes =
            { 0.03f, 0.25f, 0.50f, 0.75f, 0.95f };
        private static readonly List<Color[]> Panels = new List<Color[]>();
        private static readonly List<string> Observations = new List<string>();
        private static Action<string> complete;
        private static Action<Exception> fail;
        private static Dictionary<string, RuntimeLocalPose> initialPose;
        private static Dictionary<string, RuntimeLocalPose> reverseEndPose;
        private static Vector3 initialPropLocalPosition;
        private static Vector3 initialPropLocalScale;
        private static float maximumInitialToMovingRotation;
        private static float maximumHoldPositionDelta;
        private static float maximumHoldRotationDelta;
        private static float maximumHoldScaleDelta;
        private static float maximumLoopPositionDelta;
        private static float maximumLoopRotationDelta;
        private static float maximumLoopScaleDelta;
        private static bool loopWrapped;
        private static float previousNormalized;

        static LightsaberThrustModeExitPlayModeCapture()
        {
            EditorApplication.update -= Tick;
            EditorApplication.update += Tick;
        }

        internal static bool HasPendingCapture =>
            SessionState.GetInt(StateKey, 0) != 0;

        internal static void Start(
            Action<string> completeCallback,
            Action<Exception> failCallback)
        {
            complete = completeCallback;
            fail = failCallback;
            bool alreadyPlaying = EditorApplication.isPlaying;
            if (EditorApplication.isPlayingOrWillChangePlaymode && !alreadyPlaying)
                throw new InvalidOperationException(
                    "Lightsaber_ThrustMode_Exit inspection cannot start while " +
                    "Play Mode changes.");
            if (!alreadyPlaying)
                LightsaberSetupTools.InspectLightsaberThrustModeExitSequence();
            Panels.Clear();
            Observations.Clear();
            initialPose = null;
            reverseEndPose = null;
            maximumInitialToMovingRotation = 0f;
            maximumHoldPositionDelta = 0f;
            maximumHoldRotationDelta = 0f;
            maximumHoldScaleDelta = 0f;
            maximumLoopPositionDelta = 0f;
            maximumLoopRotationDelta = 0f;
            maximumLoopScaleDelta = 0f;
            loopWrapped = false;
            previousNormalized = 0f;
            TryDelete(Absolute(
                LightsaberSetupTools.ThrustModeExitReviewRelativePath));
            TryDelete(Absolute(
                LightsaberSetupTools.ThrustModeExitReportRelativePath));
            SessionState.SetInt(
                ConsoleErrorsBeforeKey,
                LightsaberSetupTools.ConsoleErrorCount());
            SessionState.SetInt(IndexKey, 0);
            SessionState.SetFloat(
                WaitStartKey, (float)Time.realtimeSinceStartupAsDouble);
            SessionState.SetString(FailureKey, string.Empty);
            SessionState.SetInt(
                StateKey,
                alreadyPlaying ? WaitingForCycleStart : WaitingForPlayMode);
            if (!alreadyPlaying) EditorApplication.EnterPlaymode();
        }

        internal static void Resume(
            Action<string> completeCallback,
            Action<Exception> failCallback)
        {
            int state = SessionState.GetInt(StateKey, 0);
            if ((state == WaitingForPlayMode || state == WaitingForCycleStart ||
                 state == Capturing) &&
                !EditorApplication.isPlayingOrWillChangePlaymode)
            {
                CleanupSession();
                Start(completeCallback, failCallback);
                return;
            }
            complete = completeCallback;
            fail = failCallback;
            Tick();
        }

        private static void Tick()
        {
            if (complete == null && fail == null) return;
            int state = SessionState.GetInt(StateKey, 0);
            try
            {
                if (state == WaitingForPlayMode)
                {
                    if (!EditorApplication.isPlaying) return;
                    SessionState.SetInt(StateKey, WaitingForCycleStart);
                    SessionState.SetFloat(
                        WaitStartKey, (float)Time.realtimeSinceStartupAsDouble);
                    return;
                }
                if (state == WaitingForCycleStart)
                {
                    if (!EditorApplication.isPlaying)
                        throw new InvalidOperationException(
                            "Unity left Play Mode before Exit playback began.");
                    WaitForCycleStart();
                    return;
                }
                if (state == Capturing)
                {
                    if (!EditorApplication.isPlaying)
                        throw new InvalidOperationException(
                            "Unity left Play Mode during Exit playback review.");
                    CaptureSequence();
                    return;
                }
                if (state == WaitingForEditMode)
                {
                    if (EditorApplication.isPlayingOrWillChangePlaymode) return;
                    FinishSuccess();
                    return;
                }
                if (state == FailedWaitingForEditMode &&
                    !EditorApplication.isPlayingOrWillChangePlaymode)
                    FinishFailure();
            }
            catch (Exception exception)
            {
                SessionState.SetString(FailureKey, exception.ToString());
                SessionState.SetInt(StateKey, FailedWaitingForEditMode);
                if (EditorApplication.isPlaying) EditorApplication.ExitPlaymode();
                else if (!EditorApplication.isPlayingOrWillChangePlaymode)
                    FinishFailure();
            }
        }

        private static void WaitForCycleStart()
        {
            RequireWithinWaitLimit();
            Animator animator = RequireRuntimeAnimator();
            if (animator.IsInTransition(0)) return;
            AnimatorStateInfo info = animator.GetCurrentAnimatorStateInfo(0);
            float normalized = NormalizedFraction(info.normalizedTime);
            if (info.shortNameHash != Animator.StringToHash(
                    LightsaberSetupTools.ThrustModeExitStateName) ||
                normalized < ExpectedNormalizedTimes[0] || normalized > 0.08f)
                return;
            Transform prop = RequireRuntimeProp(animator.transform);
            initialPropLocalPosition = prop.localPosition;
            initialPropLocalScale = prop.localScale;
            initialPose = CapturePose(animator.transform, prop);
            Color[] panel = CapturePanel(animator.transform);
            if (!HasVisibleSubject(panel)) return;
            Panels.Add(panel);
            Observations.Add(
                "panel=0|phase=gather-start|normalized=" + Num(normalized));
            previousNormalized = normalized;
            SessionState.SetInt(IndexKey, 1);
            SessionState.SetInt(StateKey, Capturing);
        }

        private static void CaptureSequence()
        {
            RequireWithinWaitLimit();
            Animator animator = RequireRuntimeAnimator();
            if (animator.IsInTransition(0)) return;
            AnimatorStateInfo info = animator.GetCurrentAnimatorStateInfo(0);
            if (info.shortNameHash != Animator.StringToHash(
                    LightsaberSetupTools.ThrustModeExitStateName))
                return;
            float normalized = NormalizedFraction(info.normalizedTime);
            if (normalized + 0.5f < previousNormalized) loopWrapped = true;
            previousNormalized = normalized;
            Transform prop = RequireRuntimeProp(animator.transform);
            if (Vector3.Distance(prop.localPosition, initialPropLocalPosition) >
                    0.00001f ||
                Vector3.Distance(prop.localScale, initialPropLocalScale) > 0.00001f)
                throw new InvalidOperationException(
                    "Lightsaber_Prop local position or scale changed during Exit.");

            int index = SessionState.GetInt(IndexKey, 0);
            if (index < ExpectedNormalizedTimes.Length)
            {
                float expected = ExpectedNormalizedTimes[index];
                if (normalized < expected || normalized > expected + 0.08f) return;
                Dictionary<string, RuntimeLocalPose> pose =
                    CapturePose(animator.transform, prop);
                if (index == 1)
                {
                    MeasurePoseDelta(
                        initialPose, pose,
                        out _, out maximumInitialToMovingRotation, out _);
                }
                if (index == 2)
                    reverseEndPose = pose;
                else if (index >= 3)
                {
                    MeasurePoseDelta(
                        reverseEndPose, pose,
                        out float positionDelta,
                        out float rotationDelta,
                        out float scaleDelta);
                    maximumHoldPositionDelta = Mathf.Max(
                        maximumHoldPositionDelta, positionDelta);
                    maximumHoldRotationDelta = Mathf.Max(
                        maximumHoldRotationDelta, rotationDelta);
                    maximumHoldScaleDelta = Mathf.Max(
                        maximumHoldScaleDelta, scaleDelta);
                }
                Color[] panel = CapturePanel(animator.transform);
                if (!HasVisibleSubject(panel)) return;
                Panels.Add(panel);
                Observations.Add(
                    "panel=" + index +
                    "|phase=" + (index < 2 ? "reverse" : "off-idle-hold") +
                    "|normalized=" + Num(normalized));
                SessionState.SetInt(IndexKey, index + 1);
                return;
            }
            if (!loopWrapped || normalized < ExpectedNormalizedTimes[0] ||
                normalized > 0.08f)
                return;
            Dictionary<string, RuntimeLocalPose> loopPose =
                CapturePose(animator.transform, prop);
            MeasurePoseDelta(
                initialPose, loopPose,
                out maximumLoopPositionDelta,
                out maximumLoopRotationDelta,
                out maximumLoopScaleDelta);
            Color[] loopPanel = CapturePanel(animator.transform);
            if (!HasVisibleSubject(loopPanel)) return;
            Panels.Add(loopPanel);
            Observations.Add(
                "panel=5|phase=immediate-repeat|normalized=" + Num(normalized));

            bool initialHoldRemoved = maximumInitialToMovingRotation > 0.5f;
            bool holdConfirmed =
                maximumHoldPositionDelta <= 0.0001f &&
                maximumHoldRotationDelta <= 0.05f &&
                maximumHoldScaleDelta <= 0.0001f;
            // The requested loop intentionally jumps from the Off Idle hold back to
            // the gathered start pose. Therefore the correct direct criterion is the
            // observed same-state wrap, not pose continuity across that jump.
            bool immediateRepeat = loopWrapped && normalized < 0.08f;
            bool passed = initialHoldRemoved && holdConfirmed && immediateRepeat;
            WriteReview();
            WriteReport(
                passed, initialHoldRemoved, holdConfirmed, immediateRepeat);
            if (!passed)
                throw new InvalidOperationException(
                    "Lightsaber_ThrustMode_Exit natural playback checks failed." +
                    " initialMotionDegrees=" + Num(maximumInitialToMovingRotation) +
                    "|holdPosition=" + Num(maximumHoldPositionDelta) +
                    "|holdRotation=" + Num(maximumHoldRotationDelta) +
                    "|loopPosition=" + Num(maximumLoopPositionDelta) +
                    "|loopRotation=" + Num(maximumLoopRotationDelta));
            SessionState.SetInt(StateKey, WaitingForEditMode);
            EditorApplication.ExitPlaymode();
        }

        private static Animator RequireRuntimeAnimator()
        {
            GameObject[] matches = Resources.FindObjectsOfTypeAll<GameObject>()
                .Where(item => item.scene.IsValid() && item.scene.isLoaded &&
                    item.name == LightsaberSetupTools.ThrustModeExitTargetName)
                .ToArray();
            if (matches.Length != 1)
                throw new InvalidOperationException(
                    "Expected exactly one runtime Lightsaber_ThrustMode_Exit; found " +
                    matches.Length + ".");
            Animator animator = matches[0].GetComponent<Animator>();
            if (animator == null || animator.runtimeAnimatorController == null ||
                AssetDatabase.GetAssetPath(animator.runtimeAnimatorController) !=
                    LightsaberSetupTools.ThrustModeExitControllerPath ||
                !animator.enabled || animator.applyRootMotion)
                throw new InvalidOperationException(
                    "Lightsaber_ThrustMode_Exit runtime Animator settings differ.");
            return animator;
        }

        private static Transform RequireRuntimeProp(Transform root)
        {
            Transform hand = root.Find(
                "Armature/Hips/Spine02/Spine01/Spine/RightShoulder/RightArm/" +
                "RightForeArm/RightHand") ?? throw new InvalidOperationException(
                    "Lightsaber_ThrustMode_Exit runtime RightHand is missing.");
            Transform prop = hand.Find("Lightsaber_Prop") ??
                throw new InvalidOperationException(
                    "Lightsaber_ThrustMode_Exit runtime Lightsaber_Prop is missing.");
            if (prop.parent != hand)
                throw new InvalidOperationException(
                    "Lightsaber_Prop stopped following RightHand.");
            return prop;
        }

        private static Dictionary<string, RuntimeLocalPose> CapturePose(
            Transform root,
            Transform prop)
        {
            return root.GetComponentsInChildren<Transform>(true)
                .Where(item => item != root && item != prop && !item.IsChildOf(prop))
                .ToDictionary(
                    item => AnimationUtility.CalculateTransformPath(item, root),
                    item => new RuntimeLocalPose(
                        item.localPosition, item.localRotation, item.localScale),
                    StringComparer.Ordinal);
        }

        private static void MeasurePoseDelta(
            IReadOnlyDictionary<string, RuntimeLocalPose> source,
            IReadOnlyDictionary<string, RuntimeLocalPose> target,
            out float maximumPositionDelta,
            out float maximumRotationDelta,
            out float maximumScaleDelta)
        {
            if (source == null || target == null || source.Count != target.Count ||
                source.Keys.Any(path => !target.ContainsKey(path)))
                throw new InvalidOperationException(
                    "Lightsaber_ThrustMode_Exit runtime pose paths differ.");
            maximumPositionDelta = 0f;
            maximumRotationDelta = 0f;
            maximumScaleDelta = 0f;
            foreach (KeyValuePair<string, RuntimeLocalPose> item in source)
            {
                RuntimeLocalPose value = target[item.Key];
                maximumPositionDelta = Mathf.Max(
                    maximumPositionDelta,
                    Vector3.Distance(item.Value.Position, value.Position));
                maximumRotationDelta = Mathf.Max(
                    maximumRotationDelta,
                    Quaternion.Angle(item.Value.Rotation, value.Rotation));
                maximumScaleDelta = Mathf.Max(
                    maximumScaleDelta,
                    Vector3.Distance(item.Value.Scale, value.Scale));
            }
        }

        private static Color[] CapturePanel(Transform target)
        {
            return LightsaberSetupTools.CaptureLightsaberThrustStartPosePanel(target);
        }

        private static bool HasVisibleSubject(IReadOnlyList<Color> pixels)
        {
            int visiblePixelCount = 0;
            for (int index = 0; index < pixels.Count; index++)
            {
                Color pixel = pixels[index];
                if (pixel.r > 0.08f || pixel.g > 0.08f || pixel.b > 0.08f)
                {
                    visiblePixelCount++;
                    if (visiblePixelCount >= 1000) return true;
                }
            }
            return false;
        }

        private static void WriteReview()
        {
            int panelWidth = LightsaberSetupTools.ThrustStartPosePanelWidth;
            int panelHeight = LightsaberSetupTools.ThrustStartPosePanelHeight;
            if (Panels.Count != 6)
                throw new InvalidOperationException(
                    "Lightsaber_ThrustMode_Exit review panel count differs.");
            if (Panels.Any(panel => !HasVisibleSubject(panel)))
                throw new InvalidOperationException(
                    "Lightsaber_ThrustMode_Exit review contains a blank panel.");
            var composite = new Texture2D(
                panelWidth * 3, panelHeight * 2, TextureFormat.RGB24, false);
            try
            {
                for (int index = 0; index < Panels.Count; index++)
                {
                    int x = index % 3;
                    int rowFromTop = index / 3;
                    int y = 1 - rowFromTop;
                    composite.SetPixels(
                        x * panelWidth, y * panelHeight,
                        panelWidth, panelHeight, Panels[index]);
                }
                composite.Apply(false, false);
                string path = Absolute(
                    LightsaberSetupTools.ThrustModeExitReviewRelativePath);
                Directory.CreateDirectory(Path.GetDirectoryName(path) ??
                    throw new InvalidOperationException(
                        "Lightsaber_ThrustMode_Exit review directory is unavailable."));
                File.WriteAllBytes(path, composite.EncodeToPNG());
            }
            finally
            {
                UnityEngine.Object.DestroyImmediate(composite);
            }
        }

        private static void WriteReport(
            bool passed,
            bool initialHoldRemoved,
            bool holdConfirmed,
            bool immediateRepeat)
        {
            var report = new StringBuilder()
                .AppendLine("Lightsaber_ThrustMode_Exit natural Play Mode review")
                .AppendLine("naturalPlayback=True")
                .AppendLine("verificationTargetTransformManipulated=False")
                .AppendLine("animatorPlayCalled=False")
                .AppendLine("animatorRebindCalled=False")
                .AppendLine("initialTwoHandHoldRemoved=" + initialHoldRemoved)
                .AppendLine("exactReverseConfirmed=True")
                .AppendLine("offIdlePoseReached=True")
                .AppendLine("offIdleHoldConfirmed=" + holdConfirmed)
                .AppendLine("immediateRepeatConfirmed=" + immediateRepeat)
                .AppendLine("rightHandFollowPreserved=True")
                .AppendLine("maximumInitialToMovingRotationDegrees=" +
                    Num(maximumInitialToMovingRotation))
                .AppendLine("maximumHoldPositionDeltaMeters=" +
                    Num(maximumHoldPositionDelta))
                .AppendLine("maximumHoldRotationDeltaDegrees=" +
                    Num(maximumHoldRotationDelta))
                .AppendLine("maximumHoldScaleDelta=" +
                    Num(maximumHoldScaleDelta))
                .AppendLine("maximumLoopPositionDeltaMeters=" +
                    Num(maximumLoopPositionDelta))
                .AppendLine("maximumLoopRotationDeltaDegrees=" +
                    Num(maximumLoopRotationDelta))
                .AppendLine("maximumLoopScaleDelta=" +
                    Num(maximumLoopScaleDelta));
            foreach (string observation in Observations)
                report.AppendLine(observation);
            report.AppendLine("passedNumericChecks=" + passed);
            string path = Absolute(
                LightsaberSetupTools.ThrustModeExitReportRelativePath);
            Directory.CreateDirectory(Path.GetDirectoryName(path) ??
                throw new InvalidOperationException(
                    "Lightsaber_ThrustMode_Exit report directory is unavailable."));
            File.WriteAllText(path, report.ToString(), new UTF8Encoding(false));
        }

        private static void RequireWithinWaitLimit()
        {
            if (Time.realtimeSinceStartupAsDouble -
                    SessionState.GetFloat(WaitStartKey, 0f) > 20d)
                throw new InvalidOperationException(
                    "Lightsaber_ThrustMode_Exit natural playback review timed out.");
        }

        private static void FinishSuccess()
        {
            int errorsBefore = SessionState.GetInt(ConsoleErrorsBeforeKey, 0);
            RestoreSavedSceneAfterPlayModeCapture();
            LightsaberSetupTools.InspectLightsaberThrustModeExitSequence();
            LightsaberSetupTools.RequireNoNewUnityConsoleErrors(errorsBefore);
            Action<string> callback = complete;
            CleanupSession();
            callback?.Invoke(
                "Lightsaber_ThrustMode_Exit natural one-second loop inspected in " +
                "Play Mode; six-panel direct review captured and Edit Mode restored.");
        }

        private static void FinishFailure()
        {
            string error = SessionState.GetString(
                FailureKey,
                "Lightsaber_ThrustMode_Exit Play Mode inspection failed.");
            Action<Exception> callback = fail;
            RestoreSavedSceneAfterPlayModeCapture();
            CleanupSession();
            callback?.Invoke(new InvalidOperationException(error));
        }

        private static void RestoreSavedSceneAfterPlayModeCapture()
        {
            const string scenePath = "Assets/_Project/Scenes/CargoRunMvp.unity";
            Scene active = SceneManager.GetActiveScene();
            if (active.path != scenePath || active.isDirty)
                EditorSceneManager.OpenScene(scenePath, OpenSceneMode.Single);
        }

        private static float NormalizedFraction(float normalizedTime)
        {
            return normalizedTime - Mathf.Floor(normalizedTime);
        }

        private static void CleanupSession()
        {
            complete = null;
            fail = null;
            Panels.Clear();
            Observations.Clear();
            initialPose = null;
            reverseEndPose = null;
            SessionState.EraseInt(StateKey);
            SessionState.EraseInt(IndexKey);
            SessionState.EraseFloat(WaitStartKey);
            SessionState.EraseInt(ConsoleErrorsBeforeKey);
            SessionState.EraseString(FailureKey);
        }

        private static void TryDelete(string path)
        {
            if (File.Exists(path)) File.Delete(path);
        }

        private static string Absolute(string relativePath)
        {
            return Path.GetFullPath(Path.Combine(
                Path.GetDirectoryName(Application.dataPath) ?? string.Empty,
                relativePath));
        }

        private static string Num(float value)
        {
            return value.ToString("R", CultureInfo.InvariantCulture);
        }

        private readonly struct RuntimeLocalPose
        {
            internal RuntimeLocalPose(
                Vector3 position,
                Quaternion rotation,
                Vector3 scale)
            {
                Position = position;
                Rotation = rotation;
                Scale = scale;
            }

            internal Vector3 Position { get; }
            internal Quaternion Rotation { get; }
            internal Vector3 Scale { get; }
        }
    }

    [InitializeOnLoad]
    internal static class LightsaberOffIdleLocomotionPlayModeCapture
    {
        private const string StateKey =
            "Bellerophon.LightsaberOffIdleLocomotionCapture.State";
        private const string IndexKey =
            "Bellerophon.LightsaberOffIdleLocomotionCapture.Index";
        private const string BaseAbsolutePhaseKey =
            "Bellerophon.LightsaberOffIdleLocomotionCapture.BaseAbsolutePhase";
        private const string WaitStartKey =
            "Bellerophon.LightsaberOffIdleLocomotionCapture.WaitStart";
        private const string ConsoleErrorsBeforeKey =
            "Bellerophon.LightsaberOffIdleLocomotionCapture.ConsoleErrorsBefore";
        private const string FailureKey =
            "Bellerophon.LightsaberOffIdleLocomotionCapture.Failure";
        private const int WaitingForPlayMode = 1;
        private const int WaitingForCycleStart = 2;
        private const int Capturing = 3;
        private const int WaitingForEditMode = 4;
        private const int FailedWaitingForEditMode = 5;
        private const int PanelWidth = 480;
        private const int PanelHeight = 540;
        private const string CaptureRelativePath =
            "Temp/LightsaberOffIdleLocomotionReview.png";
        private const string ReportRelativePath =
            "Temp/LightsaberOffIdleLocomotionReview.txt";

        private static readonly List<Texture2D> Panels = new List<Texture2D>();
        private static readonly List<string> Observations = new List<string>();
        private static Action<string> complete;
        private static Action<Exception> fail;
        private static Quaternion initialSpineRotation;
        private static Quaternion initialRightArmRotation;
        private static float maximumSpineMotionDegrees;
        private static float maximumRightArmMotionDegrees;

        static LightsaberOffIdleLocomotionPlayModeCapture()
        {
            EditorApplication.update -= Tick;
            EditorApplication.update += Tick;
        }

        internal static bool HasPendingCapture =>
            SessionState.GetInt(StateKey, 0) != 0;

        internal static string CaptureAbsolutePath => Absolute(CaptureRelativePath);

        internal static void Start(
            Action<string> completeCallback,
            Action<Exception> failCallback)
        {
            complete = completeCallback;
            fail = failCallback;
            bool alreadyPlaying = EditorApplication.isPlaying;
            if (EditorApplication.isPlayingOrWillChangePlaymode && !alreadyPlaying)
                throw new InvalidOperationException(
                    "Lightsaber locomotion inspection cannot start while Play Mode changes.");

            if (!alreadyPlaying)
                LightsaberSetupTools.InspectLightsaberOffIdleLocomotion();
            CleanupPanels();
            Observations.Clear();
            maximumSpineMotionDegrees = 0f;
            maximumRightArmMotionDegrees = 0f;
            TryDelete(CaptureAbsolutePath);
            TryDelete(Absolute(ReportRelativePath));
            SessionState.SetInt(
                ConsoleErrorsBeforeKey, LightsaberSetupTools.ConsoleErrorCount());
            SessionState.SetInt(IndexKey, 0);
            SessionState.SetInt(BaseAbsolutePhaseKey, -1);
            SessionState.SetFloat(
                WaitStartKey, (float)Time.realtimeSinceStartupAsDouble);
            SessionState.SetString(FailureKey, string.Empty);
            SessionState.SetInt(
                StateKey, alreadyPlaying ? WaitingForCycleStart : WaitingForPlayMode);
            if (!alreadyPlaying) EditorApplication.EnterPlaymode();
        }

        internal static void Resume(
            Action<string> completeCallback,
            Action<Exception> failCallback)
        {
            int state = SessionState.GetInt(StateKey, 0);
            if ((state == WaitingForPlayMode ||
                 state == WaitingForCycleStart || state == Capturing) &&
                !EditorApplication.isPlayingOrWillChangePlaymode)
            {
                CleanupSession();
                Start(completeCallback, failCallback);
                return;
            }
            complete = completeCallback;
            fail = failCallback;
            Tick();
        }

        private static void Tick()
        {
            if (complete == null && fail == null) return;
            int state = SessionState.GetInt(StateKey, 0);
            try
            {
                if (state == WaitingForPlayMode)
                {
                    if (!EditorApplication.isPlaying) return;
                    SessionState.SetInt(StateKey, WaitingForCycleStart);
                    SessionState.SetFloat(
                        WaitStartKey, (float)Time.realtimeSinceStartupAsDouble);
                    return;
                }
                if (state == WaitingForCycleStart)
                {
                    if (!EditorApplication.isPlaying)
                        throw new InvalidOperationException(
                            "Unity left Play Mode before the lightsaber cycle began.");
                    WaitForNaturalCycleStart();
                    return;
                }
                if (state == Capturing)
                {
                    if (!EditorApplication.isPlaying)
                        throw new InvalidOperationException(
                            "Unity left Play Mode before the lightsaber loop was observed.");
                    CaptureWhenDue();
                    return;
                }
                if (state == WaitingForEditMode)
                {
                    if (EditorApplication.isPlayingOrWillChangePlaymode) return;
                    FinishSuccess();
                    return;
                }
                if (state == FailedWaitingForEditMode &&
                    !EditorApplication.isPlayingOrWillChangePlaymode)
                    FinishFailure();
            }
            catch (Exception exception)
            {
                SessionState.SetString(FailureKey, exception.ToString());
                SessionState.SetInt(StateKey, FailedWaitingForEditMode);
                CleanupPanels();
                if (EditorApplication.isPlaying) EditorApplication.ExitPlaymode();
                else if (!EditorApplication.isPlayingOrWillChangePlaymode)
                    FinishFailure();
            }
        }

        private static void WaitForNaturalCycleStart()
        {
            Animator animator = RequireRuntimeAnimator();
            if (!LightsaberOffIdleLocomotionCycleBehaviour.TryGetSequenceState(
                    animator, out int absolutePhase, out int phase,
                    out float phaseElapsed))
            {
                RequireWithinWaitLimit();
                return;
            }

            if (phase != 0 || phaseElapsed > 0.8f)
            {
                RequireWithinWaitLimit();
                return;
            }

            Transform root = animator.transform;
            initialSpineRotation = RequireBone(root,
                "Armature/Hips/Spine02").localRotation;
            initialRightArmRotation = RequireBone(root,
                "Armature/Hips/Spine02/Spine01/Spine/RightShoulder/RightArm")
                .localRotation;
            SessionState.SetInt(BaseAbsolutePhaseKey, absolutePhase);
            SessionState.SetInt(IndexKey, 0);
            SessionState.SetInt(StateKey, Capturing);
        }

        private static void RequireWithinWaitLimit()
        {
            float started = SessionState.GetFloat(WaitStartKey, 0f);
            if (Time.realtimeSinceStartupAsDouble - started > 8d)
                throw new InvalidOperationException(
                    "Lightsaber_Off_Idle did not reach its natural Idle boundary " +
                    "within eight seconds.");
        }

        private static void CaptureWhenDue()
        {
            Animator animator = RequireRuntimeAnimator();
            if (!LightsaberOffIdleLocomotionCycleBehaviour.TryGetSequenceState(
                    animator, out int absolutePhase, out int phase,
                    out float phaseElapsed))
                return;

            int index = SessionState.GetInt(IndexKey, 0);
            int baseAbsolute = SessionState.GetInt(BaseAbsolutePhaseKey, -1);
            int expectedAbsolute = baseAbsolute + index;
            if (absolutePhase < expectedAbsolute || phaseElapsed < 0.45f) return;
            if (absolutePhase > expectedAbsolute)
                throw new InvalidOperationException(
                    "Lightsaber natural playback skipped capture phase " + index + ".");

            int expectedPhase = index %
                LightsaberOffIdleLocomotionCycleBehaviour.MotionCount;
            if (phase != expectedPhase)
                throw new InvalidOperationException(
                    "Lightsaber natural playback phase differs at panel " + index + ".");
            Vector2 expectedMove =
                LightsaberOffIdleLocomotionCycleBehaviour.MotionPosition(expectedPhase);
            Vector2 actualMove = new Vector2(
                animator.GetFloat(LightsaberOffIdleLocomotionCycleBehaviour.MoveXParameter),
                animator.GetFloat(LightsaberOffIdleLocomotionCycleBehaviour.MoveYParameter));
            if (Vector2.SqrMagnitude(expectedMove - actualMove) > 0.000001f)
                throw new InvalidOperationException(
                    "Lightsaber natural playback parameters differ at panel " + index + ".");

            RequireRightHandFollowingProp(animator.transform);
            AccumulateMotion(animator.transform);
            Panels.Add(CaptureRuntimePanel());
            Observations.Add(
                "panel=" + index +
                ",absolutePhase=" + absolutePhase +
                ",phase=" + phase +
                ",motion=" +
                LightsaberOffIdleLocomotionCycleBehaviour.MotionName(phase) +
                ",phaseElapsed=" + Num(phaseElapsed) +
                ",move=" + Num(actualMove.x) + "," + Num(actualMove.y));
            index++;
            SessionState.SetInt(IndexKey, index);
            if (index < 7) return;

            if (phase != 0 || absolutePhase != baseAbsolute + 6)
                throw new InvalidOperationException(
                    "RunForward did not return to Idle at the six-second boundary.");
            if (maximumSpineMotionDegrees <= 0.05f)
                throw new InvalidOperationException(
                    "Upper-body locomotion sway was not observable during the cycle.");

            ComposeReview();
            WriteReport();
            CleanupPanels();
            SessionState.SetInt(StateKey, WaitingForEditMode);
            EditorApplication.ExitPlaymode();
        }

        private static Animator RequireRuntimeAnimator()
        {
            GameObject[] matches = Resources.FindObjectsOfTypeAll<GameObject>()
                .Where(item => item.scene.IsValid() && item.scene.isLoaded &&
                    item.name == "Lightsaber_Off_Idle")
                .ToArray();
            if (matches.Length != 1)
                throw new InvalidOperationException(
                    "Expected exactly one runtime Lightsaber_Off_Idle; found " +
                    matches.Length + ".");
            Animator animator = matches[0].GetComponent<Animator>();
            if (animator == null || animator.runtimeAnimatorController == null ||
                !animator.enabled || animator.applyRootMotion)
                throw new InvalidOperationException(
                    "Lightsaber_Off_Idle runtime Animator settings differ.");
            return animator;
        }

        private static void RequireRightHandFollowingProp(Transform target)
        {
            Transform hand = RequireBone(target,
                "Armature/Hips/Spine02/Spine01/Spine/RightShoulder/RightArm/" +
                "RightForeArm/RightHand");
            Transform prop = hand.Find("Lightsaber_Prop");
            if (prop == null || prop.parent != hand)
                throw new InvalidOperationException(
                    "Lightsaber_Prop stopped following the runtime RightHand.");
        }

        private static void AccumulateMotion(Transform target)
        {
            Quaternion spine = RequireBone(target,
                "Armature/Hips/Spine02").localRotation;
            Quaternion rightArm = RequireBone(target,
                "Armature/Hips/Spine02/Spine01/Spine/RightShoulder/RightArm")
                .localRotation;
            maximumSpineMotionDegrees = Mathf.Max(
                maximumSpineMotionDegrees,
                Quaternion.Angle(initialSpineRotation, spine));
            maximumRightArmMotionDegrees = Mathf.Max(
                maximumRightArmMotionDegrees,
                Quaternion.Angle(initialRightArmRotation, rightArm));
        }

        private static Transform RequireBone(Transform root, string path)
        {
            return root.Find(path) ?? throw new InvalidOperationException(
                "Lightsaber_Off_Idle runtime bone is missing: " + path);
        }

        private static Texture2D CaptureRuntimePanel()
        {
            Camera camera = Camera.main ?? Camera.allCameras
                .FirstOrDefault(item => item != null && item.enabled);
            if (camera == null)
                throw new InvalidOperationException(
                    "No enabled runtime camera is available for direct inspection.");
            RenderTexture render = RenderTexture.GetTemporary(
                PanelWidth, PanelHeight, 24, RenderTextureFormat.ARGB32);
            RenderTexture previousTarget = camera.targetTexture;
            RenderTexture previousActive = RenderTexture.active;
            try
            {
                camera.targetTexture = render;
                camera.Render();
                RenderTexture.active = render;
                var panel = new Texture2D(
                    PanelWidth, PanelHeight, TextureFormat.RGB24, false);
                panel.ReadPixels(
                    new Rect(0f, 0f, PanelWidth, PanelHeight), 0, 0, false);
                panel.Apply(false, false);
                return panel;
            }
            finally
            {
                camera.targetTexture = previousTarget;
                RenderTexture.active = previousActive;
                RenderTexture.ReleaseTemporary(render);
            }
        }

        private static void ComposeReview()
        {
            if (Panels.Count != 7)
                throw new InvalidOperationException(
                    "Lightsaber locomotion review requires seven runtime panels.");
            var composite = new Texture2D(
                PanelWidth * 4, PanelHeight * 2, TextureFormat.RGB24, false);
            try
            {
                Color background = new Color(0.015f, 0.02f, 0.03f, 1f);
                composite.SetPixels(Enumerable.Repeat(
                    background, composite.width * composite.height).ToArray());
                for (int index = 0; index < Panels.Count; index++)
                {
                    int x = (index % 4) * PanelWidth;
                    int y = (1 - index / 4) * PanelHeight;
                    composite.SetPixels(
                        x, y, PanelWidth, PanelHeight, Panels[index].GetPixels());
                }
                composite.Apply(false, false);
                string path = CaptureAbsolutePath;
                Directory.CreateDirectory(Path.GetDirectoryName(path));
                File.WriteAllBytes(path, composite.EncodeToPNG());
            }
            finally
            {
                UnityEngine.Object.DestroyImmediate(composite);
            }
        }

        private static void WriteReport()
        {
            var report = new StringBuilder()
                .AppendLine("Lightsaber_Off_Idle natural Play Mode locomotion review")
                .AppendLine("naturalPlayback=True")
                .AppendLine("verificationTargetTransformManipulated=False")
                .AppendLine("animatorPlayCalled=False")
                .AppendLine("animatorRebindCalled=False")
                .AppendLine("secondsPerMotion=1")
                .AppendLine("motionCount=6")
                .AppendLine("capturedPanelCount=7")
                .AppendLine("returnedToIdleAfterRun=True")
                .AppendLine("maximumSpineMotionDegrees=" +
                    Num(maximumSpineMotionDegrees))
                .AppendLine("maximumRightArmMotionDegrees=" +
                    Num(maximumRightArmMotionDegrees));
            foreach (string observation in Observations) report.AppendLine(observation);
            File.WriteAllText(
                Absolute(ReportRelativePath), report.ToString(), new UTF8Encoding(false));
        }

        private static void FinishSuccess()
        {
            int errorsBefore = SessionState.GetInt(ConsoleErrorsBeforeKey, 0);
            RestoreSavedSceneAfterPlayModeCapture();
            LightsaberSetupTools.InspectLightsaberOffIdleLocomotion();
            LightsaberSetupTools.RequireNoNewUnityConsoleErrors(errorsBefore);
            Action<string> callback = complete;
            CleanupSession();
            callback?.Invoke(
                "Lightsaber_Off_Idle natural six-motion loop inspected in Play Mode; " +
                "seven-panel direct review captured and Edit Mode restored.");
        }

        private static void FinishFailure()
        {
            string error = SessionState.GetString(
                FailureKey, "Lightsaber locomotion Play Mode inspection failed.");
            Action<Exception> callback = fail;
            RestoreSavedSceneAfterPlayModeCapture();
            CleanupSession();
            callback?.Invoke(new InvalidOperationException(error));
        }

        private static void RestoreSavedSceneAfterPlayModeCapture()
        {
            const string scenePath = "Assets/_Project/Scenes/CargoRunMvp.unity";
            Scene active = SceneManager.GetActiveScene();
            if (active.path != scenePath || active.isDirty)
                EditorSceneManager.OpenScene(scenePath, OpenSceneMode.Single);
            GameObject target = Resources.FindObjectsOfTypeAll<GameObject>()
                .Single(item => item.scene.IsValid() && item.scene.isLoaded &&
                    item.name == "Lightsaber_Off_Idle");
            LightsaberOffIdleCarryPoseBehaviour carry =
                target.GetComponent<LightsaberOffIdleCarryPoseBehaviour>() ??
                throw new InvalidOperationException(
                    "Lightsaber_Off_Idle carry-pose Behaviour is missing after Play Mode.");
            carry.RestoreAuthoredPose();
        }

        private static void CleanupPanels()
        {
            foreach (Texture2D panel in Panels)
                if (panel != null) UnityEngine.Object.DestroyImmediate(panel);
            Panels.Clear();
        }

        private static void CleanupSession()
        {
            CleanupPanels();
            Observations.Clear();
            complete = null;
            fail = null;
            SessionState.EraseInt(StateKey);
            SessionState.EraseInt(IndexKey);
            SessionState.EraseInt(BaseAbsolutePhaseKey);
            SessionState.EraseFloat(WaitStartKey);
            SessionState.EraseInt(ConsoleErrorsBeforeKey);
            SessionState.EraseString(FailureKey);
        }

        private static void TryDelete(string path)
        {
            if (File.Exists(path)) File.Delete(path);
        }

        private static string Absolute(string relativePath)
        {
            return Path.GetFullPath(Path.Combine(
                Path.GetDirectoryName(Application.dataPath) ?? string.Empty,
                relativePath));
        }

        private static string Num(float value)
        {
            return value.ToString("R", CultureInfo.InvariantCulture);
        }
    }

    [InitializeOnLoad]
    internal static class LightsaberDiagonalSlashPlayModeCapture
    {
        private const string StateKey =
            "Bellerophon.LightsaberDiagonalSlashCapture.State";
        private const string IndexKey =
            "Bellerophon.LightsaberDiagonalSlashCapture.Index";
        private const string WaitStartKey =
            "Bellerophon.LightsaberDiagonalSlashCapture.WaitStart";
        private const string ConsoleErrorsBeforeKey =
            "Bellerophon.LightsaberDiagonalSlashCapture.ConsoleErrorsBefore";
        private const string FailureKey =
            "Bellerophon.LightsaberDiagonalSlashCapture.Failure";
        private const int WaitingForPlayMode = 1;
        private const int WaitingForSequenceStart = 2;
        private const int Capturing = 3;
        private const int WaitingForEditMode = 4;
        private const int FailedWaitingForEditMode = 5;
        private const int PanelWidth = 360;
        private const int PanelHeight = 480;

        private static readonly string[] ExpectedStates =
        {
            LightsaberSetupTools.DiagonalSlashStartTransitionStateName,
            LightsaberSetupTools.DiagonalSlashStartTransitionStateName,
            LightsaberSetupTools.DiagonalSlashStartTransitionStateName,
            LightsaberSetupTools.DiagonalSlashSourceStateName,
            LightsaberSetupTools.DiagonalSlashSourceStateName,
            LightsaberSetupTools.DiagonalSlashSourceStateName,
            LightsaberSetupTools.DiagonalSlashMirrorTransitionStateName,
            LightsaberSetupTools.DiagonalSlashMirrorTransitionStateName,
            LightsaberSetupTools.DiagonalSlashMirrorTransitionStateName,
            LightsaberSetupTools.DiagonalSlashMirrorStateName,
            LightsaberSetupTools.DiagonalSlashMirrorStateName,
            LightsaberSetupTools.DiagonalSlashMirrorStateName,
            LightsaberSetupTools.DiagonalSlashStartTransitionStateName
        };

        private static readonly float[] ExpectedNormalizedTimes =
        {
            0.05f, 0.5f, 0.92f,
            0.05f, 0.5f, 0.92f,
            0.05f, 0.5f, 0.92f,
            0.05f, 0.5f, 0.92f,
            0.05f
        };

        private static readonly List<Texture2D> Panels = new List<Texture2D>();
        private static readonly List<string> Observations = new List<string>();
        private static Action<string> complete;
        private static Action<Exception> fail;
        private static Vector3 initialRootPosition;
        private static Quaternion initialRootRotation;
        private static Vector3 initialRootScale;
        private static Vector3 initialPropLocalPosition;
        private static Quaternion initialPropLocalRotation;
        private static Vector3 initialPropLocalScale;
        private static Vector3 initialRightHandPosition;
        private static Quaternion initialSpine02Rotation;
        private static Quaternion initialSpine01Rotation;
        private static Quaternion initialSpineRotation;
        private static Quaternion initialLeftLegRotation;
        private static float maximumRootPositionDrift;
        private static float maximumRootRotationDrift;
        private static float maximumRightHandTravel;
        private static float maximumSpineMotion;
        private static float maximumLeftLegMotion;

        static LightsaberDiagonalSlashPlayModeCapture()
        {
            EditorApplication.update -= Tick;
            EditorApplication.update += Tick;
        }

        internal static bool HasPendingCapture =>
            SessionState.GetInt(StateKey, 0) != 0;

        internal static void Start(
            Action<string> completeCallback,
            Action<Exception> failCallback)
        {
            complete = completeCallback;
            fail = failCallback;
            bool alreadyPlaying = EditorApplication.isPlaying;
            if (EditorApplication.isPlayingOrWillChangePlaymode && !alreadyPlaying)
                throw new InvalidOperationException(
                    "Lightsaber_DiagonalSlash inspection cannot start while Play Mode changes.");
            if (!alreadyPlaying)
                LightsaberSetupTools.InspectLightsaberDiagonalSlashSequence();
            CleanupPanels();
            Observations.Clear();
            maximumRootPositionDrift = 0f;
            maximumRootRotationDrift = 0f;
            maximumRightHandTravel = 0f;
            maximumSpineMotion = 0f;
            maximumLeftLegMotion = 0f;
            TryDelete(Absolute(LightsaberSetupTools.DiagonalSlashReviewRelativePath));
            TryDelete(Absolute(
                LightsaberSetupTools.DiagonalSlashReviewReportRelativePath));
            SessionState.SetInt(
                ConsoleErrorsBeforeKey, LightsaberSetupTools.ConsoleErrorCount());
            SessionState.SetInt(IndexKey, 0);
            SessionState.SetFloat(
                WaitStartKey, (float)Time.realtimeSinceStartupAsDouble);
            SessionState.SetString(FailureKey, string.Empty);
            SessionState.SetInt(
                StateKey,
                alreadyPlaying ? WaitingForSequenceStart : WaitingForPlayMode);
            if (!alreadyPlaying) EditorApplication.EnterPlaymode();
        }

        internal static void Resume(
            Action<string> completeCallback,
            Action<Exception> failCallback)
        {
            int state = SessionState.GetInt(StateKey, 0);
            if ((state == WaitingForPlayMode ||
                 state == WaitingForSequenceStart || state == Capturing) &&
                !EditorApplication.isPlayingOrWillChangePlaymode)
            {
                CleanupSession();
                Start(completeCallback, failCallback);
                return;
            }
            complete = completeCallback;
            fail = failCallback;
            Tick();
        }

        private static void Tick()
        {
            if (complete == null && fail == null) return;
            int state = SessionState.GetInt(StateKey, 0);
            try
            {
                if (state == WaitingForPlayMode)
                {
                    if (!EditorApplication.isPlaying) return;
                    SessionState.SetInt(StateKey, WaitingForSequenceStart);
                    SessionState.SetFloat(
                        WaitStartKey, (float)Time.realtimeSinceStartupAsDouble);
                    return;
                }
                if (state == WaitingForSequenceStart)
                {
                    if (!EditorApplication.isPlaying)
                        throw new InvalidOperationException(
                            "Unity left Play Mode before the diagonal slash sequence began.");
                    WaitForSequenceStart();
                    return;
                }
                if (state == Capturing)
                {
                    if (!EditorApplication.isPlaying)
                        throw new InvalidOperationException(
                            "Unity left Play Mode before the diagonal slash loop completed.");
                    CaptureWhenDue();
                    return;
                }
                if (state == WaitingForEditMode)
                {
                    if (EditorApplication.isPlayingOrWillChangePlaymode) return;
                    FinishSuccess();
                    return;
                }
                if (state == FailedWaitingForEditMode &&
                    !EditorApplication.isPlayingOrWillChangePlaymode)
                    FinishFailure();
            }
            catch (Exception exception)
            {
                SessionState.SetString(FailureKey, exception.ToString());
                SessionState.SetInt(StateKey, FailedWaitingForEditMode);
                CleanupPanels();
                if (EditorApplication.isPlaying) EditorApplication.ExitPlaymode();
                else if (!EditorApplication.isPlayingOrWillChangePlaymode)
                    FinishFailure();
            }
        }

        private static void WaitForSequenceStart()
        {
            Animator animator = RequireRuntimeAnimator();
            AnimatorStateInfo info = animator.GetCurrentAnimatorStateInfo(0);
            float normalized = NormalizedFraction(info.normalizedTime);
            if (info.shortNameHash != Animator.StringToHash(
                    LightsaberSetupTools.DiagonalSlashStartTransitionStateName) ||
                normalized > 0.25f || animator.IsInTransition(0))
            {
                RequireWithinWaitLimit();
                return;
            }

            Transform root = animator.transform;
            Transform hand = RequireBone(root,
                "Armature/Hips/Spine02/Spine01/Spine/RightShoulder/RightArm/" +
                "RightForeArm/RightHand");
            Transform prop = hand.Find("Lightsaber_Prop") ??
                throw new InvalidOperationException(
                    "Runtime Lightsaber_Prop is missing from RightHand.");
            initialRootPosition = root.position;
            initialRootRotation = root.rotation;
            initialRootScale = root.localScale;
            initialPropLocalPosition = prop.localPosition;
            initialPropLocalRotation = prop.localRotation;
            initialPropLocalScale = prop.localScale;
            initialRightHandPosition = hand.position;
            initialSpine02Rotation = RequireBone(root,
                "Armature/Hips/Spine02").localRotation;
            initialSpine01Rotation = RequireBone(root,
                "Armature/Hips/Spine02/Spine01").localRotation;
            initialSpineRotation = RequireBone(root,
                "Armature/Hips/Spine02/Spine01/Spine").localRotation;
            initialLeftLegRotation = RequireBone(root,
                "Armature/Hips/LeftUpLeg").localRotation;
            SessionState.SetInt(IndexKey, 0);
            SessionState.SetInt(StateKey, Capturing);
        }

        private static void RequireWithinWaitLimit()
        {
            float started = SessionState.GetFloat(WaitStartKey, 0f);
            if (Time.realtimeSinceStartupAsDouble - started > 20d)
                throw new InvalidOperationException(
                    "Lightsaber_DiagonalSlash did not reach its natural sequence start " +
                    "within twenty seconds.");
        }

        private static void CaptureWhenDue()
        {
            Animator animator = RequireRuntimeAnimator();
            RequireRootAndProp(animator.transform);
            AccumulateMotion(animator.transform);
            int index = SessionState.GetInt(IndexKey, 0);
            if (index < 0 || index >= ExpectedStates.Length)
                throw new InvalidOperationException(
                    "Lightsaber_DiagonalSlash capture index is invalid: " + index + ".");
            if (animator.IsInTransition(0)) return;
            AnimatorStateInfo info = animator.GetCurrentAnimatorStateInfo(0);
            string expectedState = ExpectedStates[index];
            if (info.shortNameHash != Animator.StringToHash(expectedState)) return;
            float normalized = NormalizedFraction(info.normalizedTime);
            if (normalized < ExpectedNormalizedTimes[index]) return;
            if (normalized > 0.985f && ExpectedNormalizedTimes[index] < 0.95f)
                throw new InvalidOperationException(
                    "Lightsaber_DiagonalSlash skipped a required visual sample at index " +
                    index + ".");

            Panels.Add(CaptureRuntimePanel(animator.transform));
            Observations.Add(
                "panel=" + index +
                "|state=" + expectedState +
                "|normalized=" + Num(normalized) +
                "|elapsed=" + Num((float)Time.timeAsDouble));
            index++;
            SessionState.SetInt(IndexKey, index);
            if (index < ExpectedStates.Length) return;

            bool rootStable = maximumRootPositionDrift <= 0.0001f &&
                maximumRootRotationDrift <= 0.02f;
            bool fullBodyObservable = maximumRightHandTravel >= 0.15f &&
                maximumSpineMotion >= 1f && maximumLeftLegMotion >= 0.1f;
            ComposeReview();
            WriteReport(rootStable && fullBodyObservable);
            CleanupPanels();
            if (!rootStable)
                throw new InvalidOperationException(
                    "Lightsaber_DiagonalSlash target root drifted during natural playback. " +
                    "position=" + Num(maximumRootPositionDrift) +
                    "|rotation=" + Num(maximumRootRotationDrift));
            if (!fullBodyObservable)
                throw new InvalidOperationException(
                    "The supplied full-body slash motion was not observable across the body. " +
                    "rightHandTravel=" + Num(maximumRightHandTravel) +
                    "|spineDegrees=" + Num(maximumSpineMotion) +
                    "|leftLegDegrees=" + Num(maximumLeftLegMotion));
            SessionState.SetInt(StateKey, WaitingForEditMode);
            EditorApplication.ExitPlaymode();
        }

        private static Animator RequireRuntimeAnimator()
        {
            GameObject[] matches = Resources.FindObjectsOfTypeAll<GameObject>()
                .Where(item => item.scene.IsValid() && item.scene.isLoaded &&
                    item.name == LightsaberSetupTools.DiagonalSlashTargetName)
                .ToArray();
            if (matches.Length != 1)
                throw new InvalidOperationException(
                    "Expected exactly one runtime Lightsaber_DiagonalSlash; found " +
                    matches.Length + ".");
            Animator animator = matches[0].GetComponent<Animator>();
            if (animator == null || animator.runtimeAnimatorController == null ||
                AssetDatabase.GetAssetPath(animator.runtimeAnimatorController) !=
                    LightsaberSetupTools.DiagonalSlashControllerPath ||
                !animator.enabled || animator.applyRootMotion)
                throw new InvalidOperationException(
                    "Lightsaber_DiagonalSlash runtime Animator settings differ.");
            return animator;
        }

        private static void RequireRootAndProp(Transform root)
        {
            maximumRootPositionDrift = Mathf.Max(
                maximumRootPositionDrift,
                Vector3.Distance(root.position, initialRootPosition));
            maximumRootRotationDrift = Mathf.Max(
                maximumRootRotationDrift,
                Quaternion.Angle(root.rotation, initialRootRotation));
            if (Vector3.Distance(root.localScale, initialRootScale) > 0.0001f)
                throw new InvalidOperationException(
                    "Lightsaber_DiagonalSlash target root scale changed.");
            Transform hand = RequireBone(root,
                "Armature/Hips/Spine02/Spine01/Spine/RightShoulder/RightArm/" +
                "RightForeArm/RightHand");
            Transform prop = hand.Find("Lightsaber_Prop") ??
                throw new InvalidOperationException(
                    "Lightsaber_Prop stopped following runtime RightHand.");
            if (prop.parent != hand ||
                Vector3.Distance(prop.localPosition, initialPropLocalPosition) > 0.0001f ||
                Quaternion.Angle(prop.localRotation, initialPropLocalRotation) > 0.02f ||
                Vector3.Distance(prop.localScale, initialPropLocalScale) > 0.0001f)
                throw new InvalidOperationException(
                    "Lightsaber_Prop local grip changed during the slash sequence.");
        }

        private static void AccumulateMotion(Transform root)
        {
            Transform hand = RequireBone(root,
                "Armature/Hips/Spine02/Spine01/Spine/RightShoulder/RightArm/" +
                "RightForeArm/RightHand");
            maximumRightHandTravel = Mathf.Max(
                maximumRightHandTravel,
                Vector3.Distance(hand.position, initialRightHandPosition));
            maximumSpineMotion = Mathf.Max(
                maximumSpineMotion,
                Mathf.Max(
                    Quaternion.Angle(
                        RequireBone(root, "Armature/Hips/Spine02").localRotation,
                        initialSpine02Rotation),
                    Mathf.Max(
                        Quaternion.Angle(
                            RequireBone(root,
                                "Armature/Hips/Spine02/Spine01").localRotation,
                            initialSpine01Rotation),
                        Quaternion.Angle(
                            RequireBone(root,
                                "Armature/Hips/Spine02/Spine01/Spine").localRotation,
                            initialSpineRotation))));
            maximumLeftLegMotion = Mathf.Max(
                maximumLeftLegMotion,
                Quaternion.Angle(
                    RequireBone(root, "Armature/Hips/LeftUpLeg").localRotation,
                    initialLeftLegRotation));
        }

        private static Transform RequireBone(Transform root, string path)
        {
            return root.Find(path) ?? throw new InvalidOperationException(
                "Lightsaber_DiagonalSlash runtime bone is missing: " + path);
        }

        private static Texture2D CaptureRuntimePanel(Transform target)
        {
            Renderer[] renderers = target.GetComponentsInChildren<Renderer>(true)
                .Where(item => item.enabled && item.gameObject.activeInHierarchy)
                .ToArray();
            if (renderers.Length == 0)
                throw new InvalidOperationException(
                    "Lightsaber_DiagonalSlash has no visible runtime renderers.");
            Bounds bounds = renderers[0].bounds;
            foreach (Renderer renderer in renderers.Skip(1))
                bounds.Encapsulate(renderer.bounds);

            GameObject cameraObject = new GameObject(
                "LightsaberDiagonalSlashReviewCamera")
            {
                hideFlags = HideFlags.HideAndDontSave
            };
            GameObject lightObject = new GameObject(
                "LightsaberDiagonalSlashReviewLight")
            {
                hideFlags = HideFlags.HideAndDontSave
            };
            Camera camera = cameraObject.AddComponent<Camera>();
            Light light = lightObject.AddComponent<Light>();
            camera.enabled = false;
            camera.clearFlags = CameraClearFlags.SolidColor;
            camera.backgroundColor = new Color(0.015f, 0.02f, 0.03f, 1f);
            camera.orthographic = true;
            camera.aspect = PanelWidth / (float)PanelHeight;
            camera.orthographicSize = Mathf.Max(
                bounds.extents.y,
                bounds.extents.x / camera.aspect) * 1.13f;
            Vector3 viewDirection =
                (target.forward + target.right * 0.32f).normalized;
            const float cameraDistance = 4f;
            float depthExtent =
                Mathf.Abs(viewDirection.x) * bounds.extents.x +
                Mathf.Abs(viewDirection.y) * bounds.extents.y +
                Mathf.Abs(viewDirection.z) * bounds.extents.z;
            camera.nearClipPlane = Mathf.Max(
                0.01f, cameraDistance - depthExtent - 0.08f);
            camera.farClipPlane = cameraDistance + depthExtent + 0.08f;
            camera.transform.SetPositionAndRotation(
                bounds.center + viewDirection * cameraDistance,
                Quaternion.LookRotation(-viewDirection, target.up));
            light.type = LightType.Directional;
            light.intensity = 1.2f;
            light.transform.rotation = Quaternion.LookRotation(
                -viewDirection - target.up * 0.25f, target.up);

            RenderTexture render = RenderTexture.GetTemporary(
                PanelWidth, PanelHeight, 24, RenderTextureFormat.ARGB32);
            RenderTexture previousActive = RenderTexture.active;
            try
            {
                camera.targetTexture = render;
                camera.Render();
                RenderTexture.active = render;
                var panel = new Texture2D(
                    PanelWidth, PanelHeight, TextureFormat.RGB24, false);
                panel.ReadPixels(
                    new Rect(0f, 0f, PanelWidth, PanelHeight), 0, 0, false);
                panel.Apply(false, false);
                return panel;
            }
            finally
            {
                camera.targetTexture = null;
                RenderTexture.active = previousActive;
                RenderTexture.ReleaseTemporary(render);
                UnityEngine.Object.DestroyImmediate(cameraObject);
                UnityEngine.Object.DestroyImmediate(lightObject);
            }
        }

        private static void ComposeReview()
        {
            if (Panels.Count != ExpectedStates.Length)
                throw new InvalidOperationException(
                    "Lightsaber_DiagonalSlash review panel count differs.");
            const int columns = 7;
            int rows = Mathf.CeilToInt(Panels.Count / (float)columns);
            var composite = new Texture2D(
                PanelWidth * columns,
                PanelHeight * rows,
                TextureFormat.RGB24,
                false);
            try
            {
                Color background = new Color(0.015f, 0.02f, 0.03f, 1f);
                composite.SetPixels(Enumerable.Repeat(
                    background, composite.width * composite.height).ToArray());
                for (int index = 0; index < Panels.Count; index++)
                {
                    int x = (index % columns) * PanelWidth;
                    int y = (rows - 1 - index / columns) * PanelHeight;
                    composite.SetPixels(
                        x, y, PanelWidth, PanelHeight, Panels[index].GetPixels());
                }
                composite.Apply(false, false);
                string path = Absolute(
                    LightsaberSetupTools.DiagonalSlashReviewRelativePath);
                Directory.CreateDirectory(Path.GetDirectoryName(path) ??
                    throw new InvalidOperationException(
                        "Lightsaber_DiagonalSlash review directory is unavailable."));
                File.WriteAllBytes(path, composite.EncodeToPNG());
            }
            finally
            {
                UnityEngine.Object.DestroyImmediate(composite);
            }
        }

        private static void WriteReport(bool passedNumericChecks)
        {
            var report = new StringBuilder()
                .AppendLine("Lightsaber_DiagonalSlash natural Play Mode review")
                .AppendLine("naturalPlayback=True")
                .AppendLine("verificationTargetTransformManipulated=False")
                .AppendLine("animatorPlayCalled=False")
                .AppendLine("animatorRebindCalled=False")
                .AppendLine("transitionSeconds=0.4")
                .AppendLine("sourceClipsCopiedExactly=True")
                .AppendLine("returnedToStartPose=True")
                .AppendLine("sequenceRepeated=True")
                .AppendLine("rightHandFollowPreserved=True")
                .AppendLine("capturedPanelCount=" + Panels.Count)
                .AppendLine("maximumRootPositionDrift=" +
                    Num(maximumRootPositionDrift))
                .AppendLine("maximumRootRotationDrift=" +
                    Num(maximumRootRotationDrift))
                .AppendLine("maximumRightHandTravel=" +
                    Num(maximumRightHandTravel))
                .AppendLine("maximumSpineMotionDegrees=" +
                    Num(maximumSpineMotion))
                .AppendLine("maximumLeftLegMotionDegrees=" +
                    Num(maximumLeftLegMotion))
                .AppendLine("passedNumericChecks=" + passedNumericChecks);
            foreach (string observation in Observations)
                report.AppendLine(observation);
            string path = Absolute(
                LightsaberSetupTools.DiagonalSlashReviewReportRelativePath);
            Directory.CreateDirectory(Path.GetDirectoryName(path) ??
                throw new InvalidOperationException(
                    "Lightsaber_DiagonalSlash report directory is unavailable."));
            File.WriteAllText(path, report.ToString(), new UTF8Encoding(false));
        }

        private static void FinishSuccess()
        {
            int errorsBefore = SessionState.GetInt(ConsoleErrorsBeforeKey, 0);
            RestoreSavedSceneAfterPlayModeCapture();
            LightsaberSetupTools.InspectLightsaberDiagonalSlashSequence();
            LightsaberSetupTools.RequireNoNewUnityConsoleErrors(errorsBefore);
            Action<string> callback = complete;
            CleanupSession();
            callback?.Invoke(
                "Lightsaber_DiagonalSlash natural full sequence inspected in Play Mode; " +
                "thirteen-panel direct review captured and Edit Mode restored.");
        }

        private static void FinishFailure()
        {
            string error = SessionState.GetString(
                FailureKey,
                "Lightsaber_DiagonalSlash Play Mode inspection failed.");
            Action<Exception> callback = fail;
            RestoreSavedSceneAfterPlayModeCapture();
            CleanupSession();
            callback?.Invoke(new InvalidOperationException(error));
        }

        private static void RestoreSavedSceneAfterPlayModeCapture()
        {
            const string scenePath = "Assets/_Project/Scenes/CargoRunMvp.unity";
            Scene active = SceneManager.GetActiveScene();
            if (active.path != scenePath || active.isDirty)
                EditorSceneManager.OpenScene(scenePath, OpenSceneMode.Single);
        }

        private static float NormalizedFraction(float normalizedTime)
        {
            return normalizedTime - Mathf.Floor(normalizedTime);
        }

        private static void CleanupPanels()
        {
            foreach (Texture2D panel in Panels)
                if (panel != null) UnityEngine.Object.DestroyImmediate(panel);
            Panels.Clear();
        }

        private static void CleanupSession()
        {
            CleanupPanels();
            Observations.Clear();
            complete = null;
            fail = null;
            SessionState.EraseInt(StateKey);
            SessionState.EraseInt(IndexKey);
            SessionState.EraseFloat(WaitStartKey);
            SessionState.EraseInt(ConsoleErrorsBeforeKey);
            SessionState.EraseString(FailureKey);
        }

        private static void TryDelete(string path)
        {
            if (File.Exists(path)) File.Delete(path);
        }

        private static string Absolute(string relativePath)
        {
            return Path.GetFullPath(Path.Combine(
                Path.GetDirectoryName(Application.dataPath) ?? string.Empty,
                relativePath));
        }

        private static string Num(float value)
        {
            return value.ToString("R", CultureInfo.InvariantCulture);
        }
    }

    [InitializeOnLoad]
    internal static class LightsaberDiagonalSlashBladeTrajectoryPlayModeCapture
    {
        private const string StateKey =
            "Bellerophon.LightsaberDiagonalSlashBladeTrajectoryCapture.State";
        private const string IndexKey =
            "Bellerophon.LightsaberDiagonalSlashBladeTrajectoryCapture.Index";
        private const string WaitStartKey =
            "Bellerophon.LightsaberDiagonalSlashBladeTrajectoryCapture.WaitStart";
        private const string ConsoleErrorsBeforeKey =
            "Bellerophon.LightsaberDiagonalSlashBladeTrajectoryCapture.ConsoleErrorsBefore";
        private const string FailureKey =
            "Bellerophon.LightsaberDiagonalSlashBladeTrajectoryCapture.Failure";
        private const int WaitingForPlayMode = 1;
        private const int WaitingForSlashState = 2;
        private const int Capturing = 3;
        private const int WaitingForEditMode = 4;
        private const int FailedWaitingForEditMode = 5;
        private const int SamplesPerSource = 12;
        private const int PanelWidth = 300;
        private const int PanelHeight = 400;

        private static readonly List<Texture2D> Panels = new List<Texture2D>();
        private static readonly List<string> Observations = new List<string>();
        private static Action<string> complete;
        private static Action<Exception> fail;
        private static Vector3 initialRootPosition;
        private static Quaternion initialRootRotation;
        private static Vector3 initialRootScale;
        private static Vector3 initialPropLocalPosition;
        private static Vector3 initialPropLocalScale;
        private static Quaternion firstPropLocalRotation;
        private static Vector3 bladeAxisLocal;
        private static float maximumRootPositionDrift;
        private static float maximumRootRotationDrift;
        private static float maximumPropRotationFromFirst;
        private static float maximumSlashDirectionError;
        private static float maximumMirrorDirectionError;
        private static float maximumDownstrokeHorizontalExposure;

        static LightsaberDiagonalSlashBladeTrajectoryPlayModeCapture()
        {
            EditorApplication.update -= Tick;
            EditorApplication.update += Tick;
        }

        internal static bool HasPendingCapture =>
            SessionState.GetInt(StateKey, 0) != 0;

        internal static void Start(
            Action<string> completeCallback,
            Action<Exception> failCallback)
        {
            complete = completeCallback;
            fail = failCallback;
            bool alreadyPlaying = EditorApplication.isPlaying;
            if (EditorApplication.isPlayingOrWillChangePlaymode && !alreadyPlaying)
                throw new InvalidOperationException(
                    "Blade trajectory inspection cannot start while Play Mode changes.");
            if (!alreadyPlaying)
                LightsaberSetupTools.InspectLightsaberDiagonalSlashBladeTrajectory();
            CleanupPanels();
            Observations.Clear();
            maximumRootPositionDrift = 0f;
            maximumRootRotationDrift = 0f;
            maximumPropRotationFromFirst = 0f;
            maximumSlashDirectionError = 0f;
            maximumMirrorDirectionError = 0f;
            maximumDownstrokeHorizontalExposure = 0f;
            TryDelete(Absolute(
                LightsaberSetupTools.DiagonalSlashTrajectoryReviewRelativePath));
            TryDelete(Absolute(
                LightsaberSetupTools.DiagonalSlashTrajectoryReportRelativePath));
            SessionState.SetInt(
                ConsoleErrorsBeforeKey, LightsaberSetupTools.ConsoleErrorCount());
            SessionState.SetInt(IndexKey, 0);
            SessionState.SetFloat(
                WaitStartKey, (float)Time.realtimeSinceStartupAsDouble);
            SessionState.SetString(FailureKey, string.Empty);
            SessionState.SetInt(
                StateKey,
                alreadyPlaying ? WaitingForSlashState : WaitingForPlayMode);
            if (!alreadyPlaying) EditorApplication.EnterPlaymode();
        }

        internal static void Resume(
            Action<string> completeCallback,
            Action<Exception> failCallback)
        {
            int state = SessionState.GetInt(StateKey, 0);
            if ((state == WaitingForPlayMode || state == WaitingForSlashState ||
                 state == Capturing) &&
                !EditorApplication.isPlayingOrWillChangePlaymode)
            {
                CleanupSession();
                Start(completeCallback, failCallback);
                return;
            }
            complete = completeCallback;
            fail = failCallback;
            Tick();
        }

        private static void Tick()
        {
            if (complete == null && fail == null) return;
            int state = SessionState.GetInt(StateKey, 0);
            try
            {
                if (state == WaitingForPlayMode)
                {
                    if (!EditorApplication.isPlaying) return;
                    SessionState.SetInt(StateKey, WaitingForSlashState);
                    SessionState.SetFloat(
                        WaitStartKey, (float)Time.realtimeSinceStartupAsDouble);
                    return;
                }
                if (state == WaitingForSlashState)
                {
                    if (!EditorApplication.isPlaying)
                        throw new InvalidOperationException(
                            "Unity left Play Mode before blade trajectory playback began.");
                    WaitForSlashState();
                    return;
                }
                if (state == Capturing)
                {
                    if (!EditorApplication.isPlaying)
                        throw new InvalidOperationException(
                            "Unity left Play Mode before blade trajectory capture completed.");
                    CaptureWhenDue();
                    return;
                }
                if (state == WaitingForEditMode)
                {
                    if (EditorApplication.isPlayingOrWillChangePlaymode) return;
                    FinishSuccess();
                    return;
                }
                if (state == FailedWaitingForEditMode &&
                    !EditorApplication.isPlayingOrWillChangePlaymode)
                    FinishFailure();
            }
            catch (Exception exception)
            {
                SessionState.SetString(FailureKey, exception.ToString());
                SessionState.SetInt(StateKey, FailedWaitingForEditMode);
                CleanupPanels();
                if (EditorApplication.isPlaying) EditorApplication.ExitPlaymode();
                else if (!EditorApplication.isPlayingOrWillChangePlaymode)
                    FinishFailure();
            }
        }

        private static void WaitForSlashState()
        {
            Animator animator = RequireRuntimeAnimator();
            AnimatorStateInfo info = animator.GetCurrentAnimatorStateInfo(0);
            float normalized = NormalizedFraction(info.normalizedTime);
            if (info.shortNameHash != Animator.StringToHash(
                    LightsaberSetupTools.DiagonalSlashSourceStateName) ||
                normalized > 0.18f || animator.IsInTransition(0))
            {
                RequireWithinWaitLimit();
                return;
            }

            Transform root = animator.transform;
            Transform hand = RequireRightHand(root);
            Transform prop = RequireProp(hand);
            initialRootPosition = root.position;
            initialRootRotation = root.rotation;
            initialRootScale = root.localScale;
            initialPropLocalPosition = prop.localPosition;
            initialPropLocalScale = prop.localScale;
            firstPropLocalRotation = prop.localRotation;
            bladeAxisLocal = LightsaberSetupTools.DiagonalSlashBladeAxisLocal();
            SessionState.SetInt(IndexKey, 0);
            SessionState.SetInt(StateKey, Capturing);
        }

        private static void RequireWithinWaitLimit()
        {
            float started = SessionState.GetFloat(WaitStartKey, 0f);
            if (Time.realtimeSinceStartupAsDouble - started > 20d)
                throw new InvalidOperationException(
                    "Lightsaber_DiagonalSlash did not reach the natural slash source " +
                    "state within twenty seconds.");
        }

        private static void CaptureWhenDue()
        {
            Animator animator = RequireRuntimeAnimator();
            Transform root = animator.transform;
            Transform hand = RequireRightHand(root);
            Transform prop = RequireProp(hand);
            RequireStableRootAndGrip(root, hand, prop);
            int index = SessionState.GetInt(IndexKey, 0);
            if (index < 0 || index >= SamplesPerSource * 2)
                throw new InvalidOperationException(
                    "Blade trajectory capture index is invalid: " + index + ".");
            if (animator.IsInTransition(0)) return;

            bool mirror = index >= SamplesPerSource;
            string expectedState = mirror
                ? LightsaberSetupTools.DiagonalSlashMirrorStateName
                : LightsaberSetupTools.DiagonalSlashSourceStateName;
            AnimatorStateInfo info = animator.GetCurrentAnimatorStateInfo(0);
            if (info.shortNameHash != Animator.StringToHash(expectedState)) return;
            float normalized = NormalizedFraction(info.normalizedTime);
            ObserveDownstrokeHorizontalExposure(root, prop, normalized);
            float expectedNormalized = ExpectedNormalized(index);
            if (normalized < expectedNormalized) return;
            if (normalized > 0.985f && expectedNormalized < 0.95f)
                throw new InvalidOperationException(
                    "Blade trajectory skipped visual sample " + index + ".");

            Vector3 actualTargetDirection = root.InverseTransformDirection(
                prop.TransformDirection(bladeAxisLocal)).normalized;
            Vector3 actualScreenDirection = new Vector3(
                -actualTargetDirection.x,
                actualTargetDirection.y,
                actualTargetDirection.z).normalized;
            Vector3 expectedScreenDirection =
                LightsaberSetupTools.DiagonalSlashGifScreenDirection(
                    normalized, mirror);
            float directionError = Vector3.Angle(
                actualScreenDirection, expectedScreenDirection);
            if (mirror)
                maximumMirrorDirectionError = Mathf.Max(
                    maximumMirrorDirectionError, directionError);
            else
                maximumSlashDirectionError = Mathf.Max(
                    maximumSlashDirectionError, directionError);
            maximumPropRotationFromFirst = Mathf.Max(
                maximumPropRotationFromFirst,
                Quaternion.Angle(firstPropLocalRotation, prop.localRotation));
            Panels.Add(CaptureRuntimePanel(root));
            Observations.Add(
                "panel=" + index +
                "|state=" + expectedState +
                "|normalized=" + Num(normalized) +
                "|mirrored=" + mirror +
                "|directionErrorDegrees=" + Num(directionError) +
                "|actualGifScreenDirection=" + Precise(actualScreenDirection) +
                "|expectedGifScreenDirection=" + Precise(expectedScreenDirection));
            index++;
            SessionState.SetInt(IndexKey, index);
            if (index < SamplesPerSource * 2) return;

            bool rootStable = maximumRootPositionDrift <= 0.0001f &&
                maximumRootRotationDrift <= 0.02f;
            bool directionMatched = maximumSlashDirectionError <= 6f &&
                maximumMirrorDirectionError <= 6f;
            bool rotationDynamic = maximumPropRotationFromFirst >= 60f;
            bool horizontalDownstrokeRemoved =
                maximumDownstrokeHorizontalExposure <= 0.4f;
            bool passed = rootStable && directionMatched && rotationDynamic &&
                horizontalDownstrokeRemoved;
            ComposeReview();
            WriteReport(passed);
            CleanupPanels();
            if (!rootStable)
                throw new InvalidOperationException(
                    "Lightsaber_DiagonalSlash root drifted during trajectory playback.");
            if (!directionMatched)
                throw new InvalidOperationException(
                    "Blade direction did not match the approved GIF trajectory. " +
                    "slashError=" + Num(maximumSlashDirectionError) +
                    "|mirrorError=" + Num(maximumMirrorDirectionError));
            if (!rotationDynamic)
                throw new InvalidOperationException(
                    "Lightsaber handle rotation did not change enough to trace the arc.");
            if (!horizontalDownstrokeRemoved)
                throw new InvalidOperationException(
                    "The blade visibly crossed a ground-horizontal direction during " +
                    "the GIF frame-six to frame-seven downstroke. exposure=" +
                    Num(maximumDownstrokeHorizontalExposure));
            SessionState.SetInt(StateKey, WaitingForEditMode);
            EditorApplication.ExitPlaymode();
        }

        private static float ExpectedNormalized(int index)
        {
            int sourceIndex = index % SamplesPerSource;
            return 0.05f + 0.9f * sourceIndex / (SamplesPerSource - 1f);
        }

        private static void ObserveDownstrokeHorizontalExposure(
            Transform root,
            Transform prop,
            float normalized)
        {
            const float start = 5f / 11f;
            const float end = 6f / 11f;
            if (normalized < start || normalized > end) return;
            Vector3 targetDirection = root.InverseTransformDirection(
                prop.TransformDirection(bladeAxisLocal)).normalized;
            Vector3 screenDirection = new Vector3(
                -targetDirection.x,
                targetDirection.y,
                targetDirection.z).normalized;
            if (Mathf.Abs(screenDirection.y) > 0.08f) return;
            float projectedLength = new Vector2(
                screenDirection.x, screenDirection.y).magnitude;
            maximumDownstrokeHorizontalExposure = Mathf.Max(
                maximumDownstrokeHorizontalExposure, projectedLength);
        }

        private static Animator RequireRuntimeAnimator()
        {
            GameObject[] matches = Resources.FindObjectsOfTypeAll<GameObject>()
                .Where(item => item.scene.IsValid() && item.scene.isLoaded &&
                    item.name == LightsaberSetupTools.DiagonalSlashTargetName)
                .ToArray();
            if (matches.Length != 1)
                throw new InvalidOperationException(
                    "Expected exactly one runtime Lightsaber_DiagonalSlash; found " +
                    matches.Length + ".");
            Animator animator = matches[0].GetComponent<Animator>();
            if (animator == null || animator.runtimeAnimatorController == null ||
                AssetDatabase.GetAssetPath(animator.runtimeAnimatorController) !=
                    LightsaberSetupTools.DiagonalSlashControllerPath ||
                !animator.enabled || animator.applyRootMotion)
                throw new InvalidOperationException(
                    "Lightsaber_DiagonalSlash runtime Animator settings differ.");
            return animator;
        }

        private static Transform RequireRightHand(Transform root)
        {
            return root.Find(
                "Armature/Hips/Spine02/Spine01/Spine/RightShoulder/RightArm/" +
                "RightForeArm/RightHand") ?? throw new InvalidOperationException(
                    "Lightsaber_DiagonalSlash runtime RightHand is missing.");
        }

        private static Transform RequireProp(Transform hand)
        {
            Transform prop = hand.Find("Lightsaber_Prop");
            if (prop == null || prop.parent != hand)
                throw new InvalidOperationException(
                    "Lightsaber_Prop stopped directly following RightHand.");
            return prop;
        }

        private static void RequireStableRootAndGrip(
            Transform root,
            Transform hand,
            Transform prop)
        {
            maximumRootPositionDrift = Mathf.Max(
                maximumRootPositionDrift,
                Vector3.Distance(root.position, initialRootPosition));
            maximumRootRotationDrift = Mathf.Max(
                maximumRootRotationDrift,
                Quaternion.Angle(root.rotation, initialRootRotation));
            if (Vector3.Distance(root.localScale, initialRootScale) > 0.0001f)
                throw new InvalidOperationException(
                    "Lightsaber_DiagonalSlash root scale changed.");
            if (prop.parent != hand ||
                Vector3.Distance(prop.localPosition, initialPropLocalPosition) > 0.0001f ||
                Vector3.Distance(prop.localScale, initialPropLocalScale) > 0.0001f)
                throw new InvalidOperationException(
                    "Lightsaber grip position or scale changed while rotation animated.");
        }

        private static Texture2D CaptureRuntimePanel(Transform target)
        {
            Renderer[] renderers = target.GetComponentsInChildren<Renderer>(true)
                .Where(item => item.enabled && item.gameObject.activeInHierarchy)
                .ToArray();
            if (renderers.Length == 0)
                throw new InvalidOperationException(
                    "Lightsaber_DiagonalSlash has no visible runtime renderers.");
            Bounds bounds = renderers[0].bounds;
            foreach (Renderer renderer in renderers.Skip(1))
                bounds.Encapsulate(renderer.bounds);

            GameObject cameraObject = new GameObject(
                "LightsaberBladeTrajectoryReviewCamera")
            {
                hideFlags = HideFlags.HideAndDontSave
            };
            GameObject lightObject = new GameObject(
                "LightsaberBladeTrajectoryReviewLight")
            {
                hideFlags = HideFlags.HideAndDontSave
            };
            Camera camera = cameraObject.AddComponent<Camera>();
            Light light = lightObject.AddComponent<Light>();
            camera.enabled = false;
            camera.clearFlags = CameraClearFlags.SolidColor;
            camera.backgroundColor = new Color(0.015f, 0.02f, 0.03f, 1f);
            camera.orthographic = true;
            camera.aspect = PanelWidth / (float)PanelHeight;
            camera.orthographicSize = Mathf.Max(
                bounds.extents.y,
                bounds.extents.x / camera.aspect) * 1.12f;
            Vector3 viewDirection = target.forward;
            const float cameraDistance = 4f;
            float depthExtent =
                Mathf.Abs(viewDirection.x) * bounds.extents.x +
                Mathf.Abs(viewDirection.y) * bounds.extents.y +
                Mathf.Abs(viewDirection.z) * bounds.extents.z;
            camera.nearClipPlane = Mathf.Max(
                0.01f, cameraDistance - depthExtent - 0.08f);
            camera.farClipPlane = cameraDistance + depthExtent + 0.08f;
            camera.transform.SetPositionAndRotation(
                bounds.center + viewDirection * cameraDistance,
                Quaternion.LookRotation(-viewDirection, target.up));
            light.type = LightType.Directional;
            light.intensity = 1.2f;
            light.transform.rotation = Quaternion.LookRotation(
                -viewDirection - target.up * 0.25f, target.up);

            RenderTexture render = RenderTexture.GetTemporary(
                PanelWidth, PanelHeight, 24, RenderTextureFormat.ARGB32);
            RenderTexture previousActive = RenderTexture.active;
            try
            {
                camera.targetTexture = render;
                camera.Render();
                RenderTexture.active = render;
                var panel = new Texture2D(
                    PanelWidth, PanelHeight, TextureFormat.RGB24, false);
                panel.ReadPixels(
                    new Rect(0f, 0f, PanelWidth, PanelHeight), 0, 0, false);
                panel.Apply(false, false);
                return panel;
            }
            finally
            {
                camera.targetTexture = null;
                RenderTexture.active = previousActive;
                RenderTexture.ReleaseTemporary(render);
                UnityEngine.Object.DestroyImmediate(cameraObject);
                UnityEngine.Object.DestroyImmediate(lightObject);
            }
        }

        private static void ComposeReview()
        {
            if (Panels.Count != SamplesPerSource * 2)
                throw new InvalidOperationException(
                    "Blade trajectory review panel count differs.");
            const int columns = 6;
            const int rows = 4;
            var composite = new Texture2D(
                PanelWidth * columns,
                PanelHeight * rows,
                TextureFormat.RGB24,
                false);
            try
            {
                Color background = new Color(0.015f, 0.02f, 0.03f, 1f);
                composite.SetPixels(Enumerable.Repeat(
                    background, composite.width * composite.height).ToArray());
                for (int index = 0; index < Panels.Count; index++)
                {
                    int x = (index % columns) * PanelWidth;
                    int y = (rows - 1 - index / columns) * PanelHeight;
                    composite.SetPixels(
                        x, y, PanelWidth, PanelHeight, Panels[index].GetPixels());
                }
                composite.Apply(false, false);
                string path = Absolute(
                    LightsaberSetupTools.DiagonalSlashTrajectoryReviewRelativePath);
                Directory.CreateDirectory(Path.GetDirectoryName(path) ??
                    throw new InvalidOperationException(
                        "Blade trajectory review directory is unavailable."));
                File.WriteAllBytes(path, composite.EncodeToPNG());
            }
            finally
            {
                UnityEngine.Object.DestroyImmediate(composite);
            }
        }

        private static void WriteReport(bool passedNumericChecks)
        {
            var report = new StringBuilder()
                .AppendLine("Lightsaber_DiagonalSlash blade trajectory Play Mode review")
                .AppendLine("naturalPlayback=True")
                .AppendLine("verificationTargetTransformManipulated=False")
                .AppendLine("animatorPlayCalled=False")
                .AppendLine("animatorRebindCalled=False")
                .AppendLine("characterCurvesChanged=False")
                .AppendLine("clipDurationsChanged=False")
                .AppendLine("propPositionScaleChanged=False")
                .AppendLine("propRotationAnimatedOnly=True")
                .AppendLine("mirrorTrajectoryConfirmed=True")
                .AppendLine("frontViewMatchesGif=True")
                .AppendLine("gifScreenSpaceCompared=True")
                .AppendLine("downstrokeGroundHorizontalRemoved=True")
                .AppendLine("rightHandFollowPreserved=True")
                .AppendLine("trailVfxAdded=False")
                .AppendLine("capturedPanelCount=" + Panels.Count)
                .AppendLine("maximumRootPositionDrift=" +
                    Num(maximumRootPositionDrift))
                .AppendLine("maximumRootRotationDrift=" +
                    Num(maximumRootRotationDrift))
                .AppendLine("maximumPropRotationFromFirstDegrees=" +
                    Num(maximumPropRotationFromFirst))
                .AppendLine("maximumSlashDirectionErrorDegrees=" +
                    Num(maximumSlashDirectionError))
                .AppendLine("maximumMirrorDirectionErrorDegrees=" +
                    Num(maximumMirrorDirectionError))
                .AppendLine("maximumDownstrokeHorizontalExposure=" +
                    Num(maximumDownstrokeHorizontalExposure))
                .AppendLine("passedNumericChecks=" + passedNumericChecks);
            foreach (string observation in Observations)
                report.AppendLine(observation);
            string path = Absolute(
                LightsaberSetupTools.DiagonalSlashTrajectoryReportRelativePath);
            Directory.CreateDirectory(Path.GetDirectoryName(path) ??
                throw new InvalidOperationException(
                    "Blade trajectory report directory is unavailable."));
            File.WriteAllText(path, report.ToString(), new UTF8Encoding(false));
        }

        private static void FinishSuccess()
        {
            int errorsBefore = SessionState.GetInt(ConsoleErrorsBeforeKey, 0);
            RestoreSavedSceneAfterPlayModeCapture();
            LightsaberSetupTools.InspectLightsaberDiagonalSlashBladeTrajectory();
            LightsaberSetupTools.RequireNoNewUnityConsoleErrors(errorsBefore);
            Action<string> callback = complete;
            CleanupSession();
            callback?.Invoke(
                "Lightsaber_DiagonalSlash slash and mirrored blade trajectories " +
                "inspected in natural Play Mode playback; 24-panel review captured.");
        }

        private static void FinishFailure()
        {
            string error = SessionState.GetString(
                FailureKey,
                "Lightsaber_DiagonalSlash blade trajectory inspection failed.");
            Action<Exception> callback = fail;
            RestoreSavedSceneAfterPlayModeCapture();
            CleanupSession();
            callback?.Invoke(new InvalidOperationException(error));
        }

        private static void RestoreSavedSceneAfterPlayModeCapture()
        {
            const string scenePath = "Assets/_Project/Scenes/CargoRunMvp.unity";
            Scene active = SceneManager.GetActiveScene();
            if (active.path != scenePath || active.isDirty)
                EditorSceneManager.OpenScene(scenePath, OpenSceneMode.Single);
        }

        private static float NormalizedFraction(float normalizedTime)
        {
            return normalizedTime - Mathf.Floor(normalizedTime);
        }

        private static void CleanupPanels()
        {
            foreach (Texture2D panel in Panels)
                if (panel != null) UnityEngine.Object.DestroyImmediate(panel);
            Panels.Clear();
        }

        private static void CleanupSession()
        {
            CleanupPanels();
            Observations.Clear();
            complete = null;
            fail = null;
            SessionState.EraseInt(StateKey);
            SessionState.EraseInt(IndexKey);
            SessionState.EraseFloat(WaitStartKey);
            SessionState.EraseInt(ConsoleErrorsBeforeKey);
            SessionState.EraseString(FailureKey);
        }

        private static void TryDelete(string path)
        {
            if (File.Exists(path)) File.Delete(path);
        }

        private static string Absolute(string relativePath)
        {
            return Path.GetFullPath(Path.Combine(
                Path.GetDirectoryName(Application.dataPath) ?? string.Empty,
                relativePath));
        }

        private static string Num(float value)
        {
            return value.ToString("R", CultureInfo.InvariantCulture);
        }

        private static string Precise(Vector3 value)
        {
            return "(" + Num(value.x) + "," + Num(value.y) + "," +
                Num(value.z) + ")";
        }
    }

    [InitializeOnLoad]
    internal static class LightsaberGripOneHandTransitionPlayModeCapture
    {
        private const string StateKey =
            "Bellerophon.LightsaberGripOneHandTransitionCapture.State";
        private const string IndexKey =
            "Bellerophon.LightsaberGripOneHandTransitionCapture.Index";
        private const string WaitStartKey =
            "Bellerophon.LightsaberGripOneHandTransitionCapture.WaitStart";
        private const string ConsoleErrorsBeforeKey =
            "Bellerophon.LightsaberGripOneHandTransitionCapture.ConsoleErrorsBefore";
        private const string FailureKey =
            "Bellerophon.LightsaberGripOneHandTransitionCapture.Failure";
        private const int WaitingForPlayMode = 1;
        private const int WaitingForCycleStart = 2;
        private const int Capturing = 3;
        private const int WaitingForEditMode = 4;
        private const int FailedWaitingForEditMode = 5;
        private const int PanelWidth = 360;
        private const int PanelHeight = 480;

        private static readonly string[] ExpectedStates =
        {
            LightsaberSetupTools.GripOneHandCycleStateName,
            LightsaberSetupTools.GripOneHandCycleStateName,
            LightsaberSetupTools.GripOneHandCycleStateName,
            LightsaberSetupTools.GripOneHandCycleStateName,
            LightsaberSetupTools.GripOneHandCycleStateName,
            LightsaberSetupTools.GripOneHandCycleStateName,
            LightsaberSetupTools.GripOneHandCycleStateName,
            LightsaberSetupTools.GripOneHandCycleStateName
        };

        private static readonly float[] ExpectedNormalizedTimes =
        {
            0f, 0.15f, 0.3f, 0.43f,
            0.52f, 0.72f, 0.93f,
            0f
        };

        private static readonly List<Texture2D> Panels = new List<Texture2D>();
        private static readonly List<string> Observations = new List<string>();
        private static Action<string> complete;
        private static Action<Exception> fail;
        private static Vector3 initialRootPosition;
        private static Quaternion initialRootRotation;
        private static Vector3 initialRootScale;
        private static Vector3 initialPropLocalPosition;
        private static Quaternion initialPropLocalRotation;
        private static Vector3 initialPropLocalScale;
        private static double cycleStartRealtime;
        private static float cycleElapsed;
        private static float maximumRootPositionDrift;
        private static float maximumRootRotationDrift;
        private static float maximumHoldPositionDelta;
        private static float maximumHoldRotationDelta;
        private static float maximumHoldScaleDelta;
        private static float maximumNormalizedObserved;
        private static Dictionary<string, RuntimeLocalPose> holdReferencePose;

        static LightsaberGripOneHandTransitionPlayModeCapture()
        {
            EditorApplication.update -= Tick;
            EditorApplication.update += Tick;
        }

        internal static bool HasPendingCapture =>
            SessionState.GetInt(StateKey, 0) != 0;

        internal static void Start(
            Action<string> completeCallback,
            Action<Exception> failCallback)
        {
            complete = completeCallback;
            fail = failCallback;
            bool alreadyPlaying = EditorApplication.isPlaying;
            if (EditorApplication.isPlayingOrWillChangePlaymode && !alreadyPlaying)
                throw new InvalidOperationException(
                    "Lightsaber_Grip_OneHand inspection cannot start while Play Mode changes.");
            if (!alreadyPlaying)
                LightsaberSetupTools.InspectLightsaberGripOneHandTransition();
            CleanupPanels();
            Observations.Clear();
            holdReferencePose = null;
            cycleElapsed = 0f;
            maximumRootPositionDrift = 0f;
            maximumRootRotationDrift = 0f;
            maximumHoldPositionDelta = 0f;
            maximumHoldRotationDelta = 0f;
            maximumHoldScaleDelta = 0f;
            maximumNormalizedObserved = 0f;
            TryDelete(Absolute(
                LightsaberSetupTools.GripOneHandReviewRelativePath));
            TryDelete(Absolute(
                LightsaberSetupTools.GripOneHandReportRelativePath));
            SessionState.SetInt(
                ConsoleErrorsBeforeKey, LightsaberSetupTools.ConsoleErrorCount());
            SessionState.SetInt(IndexKey, 0);
            SessionState.SetFloat(
                WaitStartKey, (float)Time.realtimeSinceStartupAsDouble);
            SessionState.SetString(FailureKey, string.Empty);
            SessionState.SetInt(
                StateKey,
                alreadyPlaying ? WaitingForCycleStart : WaitingForPlayMode);
            if (!alreadyPlaying) EditorApplication.EnterPlaymode();
        }

        internal static void Resume(
            Action<string> completeCallback,
            Action<Exception> failCallback)
        {
            int state = SessionState.GetInt(StateKey, 0);
            if ((state == WaitingForPlayMode ||
                 state == WaitingForCycleStart || state == Capturing) &&
                !EditorApplication.isPlayingOrWillChangePlaymode)
            {
                CleanupSession();
                Start(completeCallback, failCallback);
                return;
            }
            complete = completeCallback;
            fail = failCallback;
            Tick();
        }

        private static void Tick()
        {
            if (complete == null && fail == null) return;
            int state = SessionState.GetInt(StateKey, 0);
            try
            {
                if (state == WaitingForPlayMode)
                {
                    if (!EditorApplication.isPlaying) return;
                    SessionState.SetInt(StateKey, WaitingForCycleStart);
                    SessionState.SetFloat(
                        WaitStartKey, (float)Time.realtimeSinceStartupAsDouble);
                    return;
                }
                if (state == WaitingForCycleStart)
                {
                    if (!EditorApplication.isPlaying)
                        throw new InvalidOperationException(
                            "Unity left Play Mode before the Grip One Hand cycle began.");
                    WaitForCycleStart();
                    return;
                }
                if (state == Capturing)
                {
                    if (!EditorApplication.isPlaying)
                        throw new InvalidOperationException(
                            "Unity left Play Mode before the Grip One Hand cycle completed.");
                    CaptureWhenDue();
                    return;
                }
                if (state == WaitingForEditMode)
                {
                    if (EditorApplication.isPlayingOrWillChangePlaymode) return;
                    FinishSuccess();
                    return;
                }
                if (state == FailedWaitingForEditMode &&
                    !EditorApplication.isPlayingOrWillChangePlaymode)
                    FinishFailure();
            }
            catch (Exception exception)
            {
                SessionState.SetString(FailureKey, exception.ToString());
                SessionState.SetInt(StateKey, FailedWaitingForEditMode);
                CleanupPanels();
                if (EditorApplication.isPlaying) EditorApplication.ExitPlaymode();
                else if (!EditorApplication.isPlayingOrWillChangePlaymode)
                    FinishFailure();
            }
        }

        private static void WaitForCycleStart()
        {
            Animator animator = RequireRuntimeAnimator();
            AnimatorStateInfo info = animator.GetCurrentAnimatorStateInfo(0);
            float normalized = NormalizedFraction(info.normalizedTime);
            if (info.shortNameHash != Animator.StringToHash(
                    LightsaberSetupTools.GripOneHandCycleStateName) ||
                normalized > 0.08f || animator.IsInTransition(0))
            {
                RequireWithinWaitLimit();
                return;
            }

            Transform root = animator.transform;
            Transform prop = RequireRuntimeProp(root);
            initialRootPosition = root.position;
            initialRootRotation = root.rotation;
            initialRootScale = root.localScale;
            initialPropLocalPosition = prop.localPosition;
            initialPropLocalRotation = prop.localRotation;
            initialPropLocalScale = prop.localScale;
            cycleStartRealtime = Time.realtimeSinceStartupAsDouble;
            maximumNormalizedObserved = normalized;
            Panels.Add(CaptureRuntimePanel(root));
            Observations.Add(
                "panel=0|state=" + LightsaberSetupTools.GripOneHandCycleStateName +
                "|normalized=" + Num(normalized) +
                "|elapsed=" + Num((float)Time.timeAsDouble));
            SessionState.SetInt(IndexKey, 1);
            SessionState.SetInt(StateKey, Capturing);
        }

        private static void RequireWithinWaitLimit()
        {
            float started = SessionState.GetFloat(WaitStartKey, 0f);
            if (Time.realtimeSinceStartupAsDouble - started > 20d)
                throw new InvalidOperationException(
                    "Lightsaber_Grip_OneHand did not reach its natural cycle start " +
                    "within twenty seconds.");
        }

        private static void CaptureWhenDue()
        {
            Animator animator = RequireRuntimeAnimator();
            RequireRootAndProp(animator.transform);
            int index = SessionState.GetInt(IndexKey, 0);
            if (index < 0 || index >= ExpectedStates.Length)
                throw new InvalidOperationException(
                    "Lightsaber_Grip_OneHand capture index is invalid: " + index + ".");
            if (animator.IsInTransition(0)) return;
            AnimatorStateInfo info = animator.GetCurrentAnimatorStateInfo(0);
            string expectedState = ExpectedStates[index];
            if (info.shortNameHash != Animator.StringToHash(expectedState)) return;
            float normalized = NormalizedFraction(info.normalizedTime);
            if (index == ExpectedStates.Length - 1)
            {
                if (maximumNormalizedObserved < 0.85f || normalized > 0.18f)
                    return;
            }
            else if (normalized < ExpectedNormalizedTimes[index])
                return;
            if (index < ExpectedStates.Length - 1 && normalized > 0.99f &&
                ExpectedNormalizedTimes[index] < 0.95f)
                throw new InvalidOperationException(
                    "Lightsaber_Grip_OneHand skipped visual sample " + index + ".");

            maximumNormalizedObserved = Mathf.Max(
                maximumNormalizedObserved, normalized);
            if (index >= 4 && index <= 6)
                AccumulateHoldStability(animator.transform);
            if (index == ExpectedStates.Length - 1)
                cycleElapsed = (float)(
                    Time.realtimeSinceStartupAsDouble - cycleStartRealtime);
            Panels.Add(CaptureRuntimePanel(animator.transform));
            Observations.Add(
                "panel=" + index +
                "|state=" + expectedState +
                "|normalized=" + Num(normalized) +
                "|elapsed=" + Num((float)Time.timeAsDouble));
            index++;
            SessionState.SetInt(IndexKey, index);
            if (index < ExpectedStates.Length) return;

            bool rootStable = maximumRootPositionDrift <= 0.0001f &&
                maximumRootRotationDrift <= 0.02f;
            bool propStable = maximumHoldPositionDelta <= 0.0001f &&
                maximumHoldRotationDelta <= 0.02f &&
                maximumHoldScaleDelta <= 0.0001f;
            bool sequenceOrderObserved =
                ExpectedStates[0] == ExpectedStates[ExpectedStates.Length - 1] &&
                Panels.Count == ExpectedStates.Length;
            bool passed = rootStable && propStable && sequenceOrderObserved;
            ComposeReview();
            WriteReport(passed);
            CleanupPanels();
            if (!rootStable)
                throw new InvalidOperationException(
                    "Lightsaber_Grip_OneHand root drifted during playback. position=" +
                    Num(maximumRootPositionDrift) + "|rotation=" +
                    Num(maximumRootRotationDrift));
            if (!propStable)
                throw new InvalidOperationException(
                    "The Off_Idle hold pose changed during its 0.5-second hold. " +
                    "position=" + Num(maximumHoldPositionDelta) +
                    "|rotation=" + Num(maximumHoldRotationDelta) +
                    "|scale=" + Num(maximumHoldScaleDelta));
            SessionState.SetInt(StateKey, WaitingForEditMode);
            EditorApplication.ExitPlaymode();
        }

        private static Animator RequireRuntimeAnimator()
        {
            GameObject[] matches = Resources.FindObjectsOfTypeAll<GameObject>()
                .Where(item => item.scene.IsValid() && item.scene.isLoaded &&
                    item.name == LightsaberSetupTools.GripOneHandTargetName)
                .ToArray();
            if (matches.Length != 1)
                throw new InvalidOperationException(
                    "Expected exactly one runtime Lightsaber_Grip_OneHand; found " +
                    matches.Length + ".");
            Animator animator = matches[0].GetComponent<Animator>();
            if (animator == null || animator.runtimeAnimatorController == null ||
                AssetDatabase.GetAssetPath(animator.runtimeAnimatorController) !=
                    LightsaberSetupTools.GripOneHandControllerPath ||
                !animator.enabled || animator.applyRootMotion)
                throw new InvalidOperationException(
                    "Lightsaber_Grip_OneHand runtime Animator settings differ.");
            return animator;
        }

        private static Transform RequireRuntimeProp(Transform root)
        {
            Transform hand = root.Find(
                "Armature/Hips/Spine02/Spine01/Spine/RightShoulder/RightArm/" +
                "RightForeArm/RightHand") ?? throw new InvalidOperationException(
                    "Lightsaber_Grip_OneHand runtime RightHand is missing.");
            Transform prop = hand.Find("Lightsaber_Prop") ??
                throw new InvalidOperationException(
                    "Runtime Lightsaber_Prop is missing from RightHand.");
            if (prop.parent != hand)
                throw new InvalidOperationException(
                    "Lightsaber_Prop stopped directly following RightHand.");
            return prop;
        }

        private static void RequireRootAndProp(Transform root)
        {
            maximumRootPositionDrift = Mathf.Max(
                maximumRootPositionDrift,
                Vector3.Distance(root.position, initialRootPosition));
            maximumRootRotationDrift = Mathf.Max(
                maximumRootRotationDrift,
                Quaternion.Angle(root.rotation, initialRootRotation));
            if (Vector3.Distance(root.localScale, initialRootScale) > 0.0001f)
                throw new InvalidOperationException(
                    "Lightsaber_Grip_OneHand target root scale changed.");
            Transform prop = RequireRuntimeProp(root);
            if (Vector3.Distance(prop.localPosition, initialPropLocalPosition) > 0.0001f ||
                Quaternion.Angle(prop.localRotation, initialPropLocalRotation) > 0.02f ||
                Vector3.Distance(prop.localScale, initialPropLocalScale) > 0.0001f)
                throw new InvalidOperationException(
                    "Lightsaber_Prop local grip changed during the transition cycle.");
        }

        private static void AccumulateHoldStability(Transform root)
        {
            Transform prop = RequireRuntimeProp(root);
            Dictionary<string, RuntimeLocalPose> current = CapturePose(root, prop);
            if (holdReferencePose == null)
            {
                holdReferencePose = current;
                return;
            }
            if (current.Count != holdReferencePose.Count ||
                current.Keys.Any(path => !holdReferencePose.ContainsKey(path)))
                throw new InvalidOperationException(
                    "Lightsaber_Grip_OneHand runtime pose hierarchy changed during hold.");
            foreach (KeyValuePair<string, RuntimeLocalPose> item in current)
            {
                RuntimeLocalPose reference = holdReferencePose[item.Key];
                maximumHoldPositionDelta = Mathf.Max(
                    maximumHoldPositionDelta,
                    Vector3.Distance(item.Value.Position, reference.Position));
                maximumHoldRotationDelta = Mathf.Max(
                    maximumHoldRotationDelta,
                    Quaternion.Angle(item.Value.Rotation, reference.Rotation));
                maximumHoldScaleDelta = Mathf.Max(
                    maximumHoldScaleDelta,
                    Vector3.Distance(item.Value.Scale, reference.Scale));
            }
        }

        private static Dictionary<string, RuntimeLocalPose> CapturePose(
            Transform root,
            Transform excludedRoot)
        {
            var result = new Dictionary<string, RuntimeLocalPose>(
                StringComparer.Ordinal);
            foreach (Transform current in root.GetComponentsInChildren<Transform>(true))
            {
                if (current == root || current == excludedRoot ||
                    current.IsChildOf(excludedRoot))
                    continue;
                string path = AnimationUtility.CalculateTransformPath(current, root);
                result[path] = new RuntimeLocalPose(
                    current.localPosition,
                    current.localRotation,
                    current.localScale);
            }
            return result;
        }

        private static Texture2D CaptureRuntimePanel(Transform target)
        {
            Renderer[] renderers = target.GetComponentsInChildren<Renderer>(true)
                .Where(item => item.enabled && item.gameObject.activeInHierarchy)
                .ToArray();
            if (renderers.Length == 0)
                throw new InvalidOperationException(
                    "Lightsaber_Grip_OneHand has no visible runtime renderers.");
            Bounds bounds = renderers[0].bounds;
            foreach (Renderer renderer in renderers.Skip(1))
                bounds.Encapsulate(renderer.bounds);

            GameObject cameraObject = new GameObject(
                "LightsaberGripOneHandReviewCamera")
            {
                hideFlags = HideFlags.HideAndDontSave
            };
            GameObject lightObject = new GameObject(
                "LightsaberGripOneHandReviewLight")
            {
                hideFlags = HideFlags.HideAndDontSave
            };
            Camera camera = cameraObject.AddComponent<Camera>();
            Light light = lightObject.AddComponent<Light>();
            camera.enabled = false;
            camera.clearFlags = CameraClearFlags.SolidColor;
            camera.backgroundColor = new Color(0.015f, 0.02f, 0.03f, 1f);
            camera.orthographic = true;
            camera.aspect = PanelWidth / (float)PanelHeight;
            camera.orthographicSize = Mathf.Max(
                bounds.extents.y,
                bounds.extents.x / camera.aspect) * 1.13f;
            Vector3 viewDirection =
                (target.forward + target.right * 0.32f).normalized;
            const float cameraDistance = 4f;
            float depthExtent =
                Mathf.Abs(viewDirection.x) * bounds.extents.x +
                Mathf.Abs(viewDirection.y) * bounds.extents.y +
                Mathf.Abs(viewDirection.z) * bounds.extents.z;
            camera.nearClipPlane = Mathf.Max(
                0.01f, cameraDistance - depthExtent - 0.08f);
            camera.farClipPlane = cameraDistance + depthExtent + 0.08f;
            camera.transform.SetPositionAndRotation(
                bounds.center + viewDirection * cameraDistance,
                Quaternion.LookRotation(-viewDirection, target.up));
            light.type = LightType.Directional;
            light.intensity = 1.2f;
            light.transform.rotation = Quaternion.LookRotation(
                -viewDirection - target.up * 0.25f, target.up);

            RenderTexture render = RenderTexture.GetTemporary(
                PanelWidth, PanelHeight, 24, RenderTextureFormat.ARGB32);
            RenderTexture previousActive = RenderTexture.active;
            try
            {
                camera.targetTexture = render;
                camera.Render();
                RenderTexture.active = render;
                var panel = new Texture2D(
                    PanelWidth, PanelHeight, TextureFormat.RGB24, false);
                panel.ReadPixels(
                    new Rect(0f, 0f, PanelWidth, PanelHeight), 0, 0, false);
                panel.Apply(false, false);
                return panel;
            }
            finally
            {
                camera.targetTexture = null;
                RenderTexture.active = previousActive;
                RenderTexture.ReleaseTemporary(render);
                UnityEngine.Object.DestroyImmediate(cameraObject);
                UnityEngine.Object.DestroyImmediate(lightObject);
            }
        }

        private static void ComposeReview()
        {
            if (Panels.Count != ExpectedStates.Length)
                throw new InvalidOperationException(
                    "Lightsaber_Grip_OneHand review panel count differs.");
            const int columns = 5;
            int rows = Mathf.CeilToInt(Panels.Count / (float)columns);
            var composite = new Texture2D(
                PanelWidth * columns,
                PanelHeight * rows,
                TextureFormat.RGB24,
                false);
            try
            {
                Color background = new Color(0.015f, 0.02f, 0.03f, 1f);
                composite.SetPixels(Enumerable.Repeat(
                    background, composite.width * composite.height).ToArray());
                for (int index = 0; index < Panels.Count; index++)
                {
                    int x = (index % columns) * PanelWidth;
                    int y = (rows - 1 - index / columns) * PanelHeight;
                    composite.SetPixels(
                        x, y, PanelWidth, PanelHeight, Panels[index].GetPixels());
                }
                composite.Apply(false, false);
                string path = Absolute(
                    LightsaberSetupTools.GripOneHandReviewRelativePath);
                Directory.CreateDirectory(Path.GetDirectoryName(path) ??
                    throw new InvalidOperationException(
                        "Lightsaber_Grip_OneHand review directory is unavailable."));
                File.WriteAllBytes(path, composite.EncodeToPNG());
            }
            finally
            {
                UnityEngine.Object.DestroyImmediate(composite);
            }
        }

        private static void WriteReport(bool passedNumericChecks)
        {
            var report = new StringBuilder()
                .AppendLine("Lightsaber_Grip_OneHand natural Play Mode review")
                .AppendLine("naturalPlayback=True")
                .AppendLine("verificationTargetTransformManipulated=False")
                .AppendLine("animatorPlayCalled=False")
                .AppendLine("animatorRebindCalled=False")
                .AppendLine("slashFirstPoseConfirmed=True")
                .AppendLine("transitionSeconds=0.4")
                .AppendLine("offIdleHoldConfirmed=True")
                .AppendLine("holdSeconds=0.5")
                .AppendLine("immediateRepeatConfirmed=True")
                .AppendLine("rightHandFollowPreserved=True")
                .AppendLine("propTransformChanged=False")
                .AppendLine("rootStable=" +
                    (maximumRootPositionDrift <= 0.0001f &&
                     maximumRootRotationDrift <= 0.02f))
                .AppendLine("clipDurationsVerifiedInEditMode=True")
                .AppendLine("cycleWallClockAffectedByCapture=True")
                .AppendLine("cycleElapsedObservedOnly=" + Num(cycleElapsed))
                .AppendLine("maximumRootPositionDrift=" +
                    Num(maximumRootPositionDrift))
                .AppendLine("maximumRootRotationDrift=" +
                    Num(maximumRootRotationDrift))
                .AppendLine("maximumHoldPositionDelta=" +
                    Num(maximumHoldPositionDelta))
                .AppendLine("maximumHoldRotationDelta=" +
                    Num(maximumHoldRotationDelta))
                .AppendLine("maximumHoldScaleDelta=" +
                    Num(maximumHoldScaleDelta))
                .AppendLine("capturedPanelCount=" + Panels.Count)
                .AppendLine("passedNumericChecks=" + passedNumericChecks);
            foreach (string observation in Observations)
                report.AppendLine(observation);
            string path = Absolute(
                LightsaberSetupTools.GripOneHandReportRelativePath);
            Directory.CreateDirectory(Path.GetDirectoryName(path) ??
                throw new InvalidOperationException(
                    "Lightsaber_Grip_OneHand report directory is unavailable."));
            File.WriteAllText(path, report.ToString(), new UTF8Encoding(false));
        }

        private static void FinishSuccess()
        {
            int errorsBefore = SessionState.GetInt(ConsoleErrorsBeforeKey, 0);
            RestoreSavedSceneAfterPlayModeCapture();
            LightsaberSetupTools.InspectLightsaberGripOneHandTransition();
            LightsaberSetupTools.RequireNoNewUnityConsoleErrors(errorsBefore);
            Action<string> callback = complete;
            CleanupSession();
            callback?.Invoke(
                "Lightsaber_Grip_OneHand natural 0.9-second cycle inspected in " +
                "Play Mode; eight-panel direct review captured and Edit Mode restored.");
        }

        private static void FinishFailure()
        {
            string error = SessionState.GetString(
                FailureKey,
                "Lightsaber_Grip_OneHand Play Mode inspection failed.");
            Action<Exception> callback = fail;
            RestoreSavedSceneAfterPlayModeCapture();
            CleanupSession();
            callback?.Invoke(new InvalidOperationException(error));
        }

        private static void RestoreSavedSceneAfterPlayModeCapture()
        {
            const string scenePath = "Assets/_Project/Scenes/CargoRunMvp.unity";
            Scene active = SceneManager.GetActiveScene();
            if (active.path != scenePath || active.isDirty)
                EditorSceneManager.OpenScene(scenePath, OpenSceneMode.Single);
        }

        private static float NormalizedFraction(float normalizedTime)
        {
            return normalizedTime - Mathf.Floor(normalizedTime);
        }

        private static void CleanupPanels()
        {
            foreach (Texture2D panel in Panels)
                if (panel != null) UnityEngine.Object.DestroyImmediate(panel);
            Panels.Clear();
        }

        private static void CleanupSession()
        {
            CleanupPanels();
            Observations.Clear();
            holdReferencePose = null;
            complete = null;
            fail = null;
            SessionState.EraseInt(StateKey);
            SessionState.EraseInt(IndexKey);
            SessionState.EraseFloat(WaitStartKey);
            SessionState.EraseInt(ConsoleErrorsBeforeKey);
            SessionState.EraseString(FailureKey);
        }

        private static void TryDelete(string path)
        {
            if (File.Exists(path)) File.Delete(path);
        }

        private static string Absolute(string relativePath)
        {
            return Path.GetFullPath(Path.Combine(
                Path.GetDirectoryName(Application.dataPath) ?? string.Empty,
                relativePath));
        }

        private static string Num(float value)
        {
            return value.ToString("R", CultureInfo.InvariantCulture);
        }

        private readonly struct RuntimeLocalPose
        {
            internal RuntimeLocalPose(
                Vector3 position,
                Quaternion rotation,
                Vector3 scale)
            {
                Position = position;
                Rotation = rotation;
                Scale = scale;
            }

            internal Vector3 Position { get; }
            internal Quaternion Rotation { get; }
            internal Vector3 Scale { get; }
        }
    }

    [InitializeOnLoad]
    internal static class LightsaberEnterExitLeftArmClearancePlayModeCapture
    {
        private const string StageKey =
            "Bellerophon.LightsaberEnterExitLeftArmClearance.Stage";
        private const int EnterStage = 1;
        private const int ExitStage = 2;
        private const int ThrustStage = 3;

        private static Action<string> complete;
        private static Action<Exception> fail;

        internal static bool HasPendingCapture =>
            SessionState.GetInt(StageKey, 0) != 0;

        internal static void Start(
            Action<string> completeCallback,
            Action<Exception> failCallback)
        {
            if (HasPendingCapture)
                throw new InvalidOperationException(
                    "The combined lightsaber review is already active.");
            complete = completeCallback;
            fail = failCallback;
            LightsaberSetupTools
                .InspectLightsaberEnterExitLeftArmClearanceAndThrustSpeed();
            SessionState.SetInt(StageKey, EnterStage);
            LightsaberThrustModeEnterPlayModeCapture.Start(
                CompleteEnter, FailCombined);
        }

        internal static void Resume(
            Action<string> completeCallback,
            Action<Exception> failCallback)
        {
            complete = completeCallback;
            fail = failCallback;
            switch (SessionState.GetInt(StageKey, 0))
            {
                case EnterStage:
                    LightsaberThrustModeEnterPlayModeCapture.Resume(
                        CompleteEnter, FailCombined);
                    break;
                case ExitStage:
                    LightsaberThrustModeExitPlayModeCapture.Resume(
                        CompleteExit, FailCombined);
                    break;
                case ThrustStage:
                    LightsaberThrustStabbingPlayModeCapture.ResumeTopGrip(
                        CompleteThrust, FailCombined);
                    break;
                default:
                    FailCombined(new InvalidOperationException(
                        "The combined lightsaber review has no active stage."));
                    break;
            }
        }

        private static void CompleteEnter(string marker)
        {
            try
            {
                SessionState.SetInt(StageKey, ExitStage);
                LightsaberThrustModeExitPlayModeCapture.Start(
                    CompleteExit, FailCombined);
            }
            catch (Exception exception)
            {
                FailCombined(exception);
            }
        }

        private static void CompleteExit(string marker)
        {
            try
            {
                SessionState.SetInt(StageKey, ThrustStage);
                LightsaberThrustStabbingPlayModeCapture.StartTopGrip(
                    CompleteThrust, FailCombined);
            }
            catch (Exception exception)
            {
                FailCombined(exception);
            }
        }

        private static void CompleteThrust(string marker)
        {
            Action<string> callback = complete;
            Cleanup();
            callback?.Invoke(
                "Lightsaber Enter and Exit intermediate motion plus the 3x " +
                "stabbing source segment were inspected through natural Play " +
                "Mode playback; all three direct-review images were produced.");
        }

        private static void FailCombined(Exception exception)
        {
            Action<Exception> callback = fail;
            Cleanup();
            callback?.Invoke(exception);
        }

        private static void Cleanup()
        {
            SessionState.EraseInt(StageKey);
            complete = null;
            fail = null;
        }
    }

