    [InitializeOnLoad]
    internal static class LightsaberThrustModeEnterPlayModeCapture
    {
        private const string StateKey =
            "Bellerophon.LightsaberThrustModeEnterCapture.State";
        private const string IndexKey =
            "Bellerophon.LightsaberThrustModeEnterCapture.Index";
        private const string WaitStartKey =
            "Bellerophon.LightsaberThrustModeEnterCapture.WaitStart";
        private const string ConsoleErrorsBeforeKey =
            "Bellerophon.LightsaberThrustModeEnterCapture.ConsoleErrorsBefore";
        private const string FailureKey =
            "Bellerophon.LightsaberThrustModeEnterCapture.Failure";
        private const string ExpectedLeftKneeKey =
            "Bellerophon.LightsaberThrustModeEnterCapture.ExpectedLeftKnee";
        private const string ExpectedRightKneeKey =
            "Bellerophon.LightsaberThrustModeEnterCapture.ExpectedRightKnee";
        private const int WaitingForPlayMode = 1;
        private const int WaitingForCycleStart = 2;
        private const int Capturing = 3;
        private const int WaitingForEditMode = 4;
        private const int FailedWaitingForEditMode = 5;
        private const int PanelWidth = 360;
        private const int PanelHeight = 480;

        private static readonly float[] ExpectedNormalizedTimes =
        {
            0f, 0.16f, 0.32f, 0.48f,
            0.56f, 0.75f, 0.90f,
            0f
        };

        private static readonly List<Texture2D> Panels = new List<Texture2D>();
        private static readonly List<string> Observations = new List<string>();
        private static Action<string> complete;
        private static Action<Exception> fail;
        private static Vector3 initialRootPosition;
        private static Quaternion initialRootRotation;
        private static Vector3 initialRootScale;
        private static Vector3 initialPropLocalPosition;
        private static Quaternion initialPropLocalRotation;
        private static Vector3 initialPropLocalScale;
        private static float maximumRootPositionDrift;
        private static float maximumRootRotationDrift;
        private static float maximumHoldPositionDelta;
        private static float maximumHoldRotationDelta;
        private static float maximumHoldScaleDelta;
        private static float maximumNormalizedObserved;
        private static float maximumBladeTiltDirectionError;
        private static float maximumBladeDownTiltError;
        private static float maximumBladeLeftTiltError;
        private static float observedBladeDownTilt;
        private static float observedBladeLeftTilt;
        private static float minimumBladeForwardDot;
        private static float maximumPropRotationDelta;
        private static float maximumGripOffsetError;
        private static float minimumRightHandOutsideShoulder;
        private static float minimumLeftHandOutsideShoulder;
        private static float minimumRightHandBelowShoulder;
        private static float minimumLeftHandBelowShoulder;
        private static float minimumBladeHeadClearance;
        private static float minimumBladeTorsoClearance;
        private static float maximumLeftKneeBendDeviation;
        private static float maximumRightKneeBendDeviation;
        private static float expectedLeftKneeChainAngle;
        private static float expectedRightKneeChainAngle;
        private static float observedLeftKneeBend;
        private static float observedRightKneeBend;
        private static Vector3 initialLeftFootPosition;
        private static Vector3 initialRightFootPosition;
        private static Quaternion initialLeftFootRotation;
        private static Quaternion initialRightFootRotation;
        private static float maximumLeftFootPositionDrift;
        private static float maximumRightFootPositionDrift;
        private static float maximumLeftFootVerticalDrift;
        private static float maximumRightFootVerticalDrift;
        private static float maximumLeftFootRotationDrift;
        private static float maximumRightFootRotationDrift;
        private static bool leftArmTrajectoryInitialized;
        private static float previousLeftArmNormalized;
        private static float previousLeftHandLocalX;
        private static float previousLeftElbowLocalX;
        private static float maximumLeftHandOutwardStep;
        private static float maximumLeftElbowOutwardStep;
        private static Dictionary<string, RuntimeLocalPose> holdReferencePose;

        static LightsaberThrustModeEnterPlayModeCapture()
        {
            EditorApplication.update -= Tick;
            EditorApplication.update += Tick;
        }

        internal static bool HasPendingCapture =>
            SessionState.GetInt(StateKey, 0) != 0;

        internal static void Start(
            Action<string> completeCallback,
            Action<Exception> failCallback)
        {
            complete = completeCallback;
            fail = failCallback;
            bool alreadyPlaying = EditorApplication.isPlaying;
            if (EditorApplication.isPlayingOrWillChangePlaymode && !alreadyPlaying)
                throw new InvalidOperationException(
                    "Lightsaber_ThrustMode_Enter inspection cannot start while " +
                    "Play Mode changes.");
            if (!alreadyPlaying)
            {
                LightsaberSetupTools.InspectLightsaberThrustModeEnterTransition();
                LightsaberSetupTools.GetLightsaberThrustModeEnterExpectedKneeChainAngles(
                    out float expectedLeftKnee,
                    out float expectedRightKnee);
                SessionState.SetFloat(ExpectedLeftKneeKey, expectedLeftKnee);
                SessionState.SetFloat(ExpectedRightKneeKey, expectedRightKnee);
            }
            CleanupPanels();
            Observations.Clear();
            holdReferencePose = null;
            maximumRootPositionDrift = 0f;
            maximumRootRotationDrift = 0f;
            maximumHoldPositionDelta = 0f;
            maximumHoldRotationDelta = 0f;
            maximumHoldScaleDelta = 0f;
            maximumNormalizedObserved = 0f;
            maximumBladeTiltDirectionError = 0f;
            maximumBladeDownTiltError = 0f;
            maximumBladeLeftTiltError = 0f;
            observedBladeDownTilt = 0f;
            observedBladeLeftTilt = 0f;
            minimumBladeForwardDot = 1f;
            maximumPropRotationDelta = 0f;
            maximumGripOffsetError = 0f;
            minimumRightHandOutsideShoulder = float.PositiveInfinity;
            minimumLeftHandOutsideShoulder = float.PositiveInfinity;
            minimumRightHandBelowShoulder = float.PositiveInfinity;
            minimumLeftHandBelowShoulder = float.PositiveInfinity;
            minimumBladeHeadClearance = float.PositiveInfinity;
            minimumBladeTorsoClearance = float.PositiveInfinity;
            maximumLeftKneeBendDeviation = 0f;
            maximumRightKneeBendDeviation = 0f;
            observedLeftKneeBend = 0f;
            observedRightKneeBend = 0f;
            maximumLeftFootPositionDrift = 0f;
            maximumRightFootPositionDrift = 0f;
            maximumLeftFootVerticalDrift = 0f;
            maximumRightFootVerticalDrift = 0f;
            maximumLeftFootRotationDrift = 0f;
            maximumRightFootRotationDrift = 0f;
            leftArmTrajectoryInitialized = false;
            previousLeftArmNormalized = 0f;
            previousLeftHandLocalX = 0f;
            previousLeftElbowLocalX = 0f;
            maximumLeftHandOutwardStep = 0f;
            maximumLeftElbowOutwardStep = 0f;
            TryDelete(Absolute(
                LightsaberSetupTools.ThrustModeEnterReviewRelativePath));
            TryDelete(Absolute(
                LightsaberSetupTools.ThrustModeEnterReportRelativePath));
            SessionState.SetInt(
                ConsoleErrorsBeforeKey, LightsaberSetupTools.ConsoleErrorCount());
            SessionState.SetInt(IndexKey, 0);
            SessionState.SetFloat(
                WaitStartKey, (float)Time.realtimeSinceStartupAsDouble);
            SessionState.SetString(FailureKey, string.Empty);
            SessionState.SetInt(
                StateKey,
                alreadyPlaying ? WaitingForCycleStart : WaitingForPlayMode);
            if (!alreadyPlaying) EditorApplication.EnterPlaymode();
        }

        internal static void Resume(
            Action<string> completeCallback,
            Action<Exception> failCallback)
        {
            int state = SessionState.GetInt(StateKey, 0);
            if ((state == WaitingForPlayMode ||
                 state == WaitingForCycleStart || state == Capturing) &&
                !EditorApplication.isPlayingOrWillChangePlaymode)
            {
                CleanupSession();
                Start(completeCallback, failCallback);
                return;
            }
            complete = completeCallback;
            fail = failCallback;
            Tick();
        }

        private static void Tick()
        {
            if (complete == null && fail == null) return;
            int state = SessionState.GetInt(StateKey, 0);
            try
            {
                if (state == WaitingForPlayMode)
                {
                    if (!EditorApplication.isPlaying) return;
                    SessionState.SetInt(StateKey, WaitingForCycleStart);
                    SessionState.SetFloat(
                        WaitStartKey, (float)Time.realtimeSinceStartupAsDouble);
                    return;
                }
                if (state == WaitingForCycleStart)
                {
                    if (!EditorApplication.isPlaying)
                        throw new InvalidOperationException(
                            "Unity left Play Mode before the thrust-mode-enter cycle began.");
                    WaitForCycleStart();
                    return;
                }
                if (state == Capturing)
                {
                    if (!EditorApplication.isPlaying)
                        throw new InvalidOperationException(
                            "Unity left Play Mode before the thrust-mode-enter cycle completed.");
                    CaptureWhenDue();
                    return;
                }
                if (state == WaitingForEditMode)
                {
                    if (EditorApplication.isPlayingOrWillChangePlaymode) return;
                    FinishSuccess();
                    return;
                }
                if (state == FailedWaitingForEditMode &&
                    !EditorApplication.isPlayingOrWillChangePlaymode)
                    FinishFailure();
            }
            catch (Exception exception)
            {
                SessionState.SetString(FailureKey, exception.ToString());
                SessionState.SetInt(StateKey, FailedWaitingForEditMode);
                CleanupPanels();
                if (EditorApplication.isPlaying) EditorApplication.ExitPlaymode();
                else if (!EditorApplication.isPlayingOrWillChangePlaymode)
                    FinishFailure();
            }
        }

        private static void WaitForCycleStart()
        {
            Animator animator = RequireRuntimeAnimator();
            AnimatorStateInfo info = animator.GetCurrentAnimatorStateInfo(0);
            float normalized = NormalizedFraction(info.normalizedTime);
            if (info.shortNameHash != Animator.StringToHash(
                    LightsaberSetupTools.ThrustModeEnterStateName) ||
                normalized > 0.08f || animator.IsInTransition(0))
            {
                RequireWithinWaitLimit();
                return;
            }
            Transform root = animator.transform;
            Transform prop = RequireRuntimeProp(root);
            initialRootPosition = root.position;
            initialRootRotation = root.rotation;
            initialRootScale = root.localScale;
            initialPropLocalPosition = prop.localPosition;
            initialPropLocalRotation = prop.localRotation;
            initialPropLocalScale = prop.localScale;
            Transform initialLeftFoot = RequireRuntimeBone(root, LeftFootRuntimePath);
            Transform initialRightFoot = RequireRuntimeBone(root, RightFootRuntimePath);
            initialLeftFootPosition = initialLeftFoot.position;
            initialRightFootPosition = initialRightFoot.position;
            initialLeftFootRotation = initialLeftFoot.rotation;
            initialRightFootRotation = initialRightFoot.rotation;
            expectedLeftKneeChainAngle = SessionState.GetFloat(
                ExpectedLeftKneeKey, float.NaN);
            expectedRightKneeChainAngle = SessionState.GetFloat(
                ExpectedRightKneeKey, float.NaN);
            if (float.IsNaN(expectedLeftKneeChainAngle) ||
                float.IsNaN(expectedRightKneeChainAngle))
                throw new InvalidOperationException(
                    "Lightsaber_ThrustMode_Enter expected knee angles are missing.");
            maximumBladeTiltDirectionError = 0f;
            maximumBladeDownTiltError = 0f;
            maximumBladeLeftTiltError = 0f;
            observedBladeDownTilt = 0f;
            observedBladeLeftTilt = 0f;
            minimumBladeForwardDot = 1f;
            maximumPropRotationDelta = 0f;
            maximumGripOffsetError = 0f;
            minimumRightHandOutsideShoulder = float.PositiveInfinity;
            minimumLeftHandOutsideShoulder = float.PositiveInfinity;
            minimumRightHandBelowShoulder = float.PositiveInfinity;
            minimumLeftHandBelowShoulder = float.PositiveInfinity;
            minimumBladeHeadClearance = float.PositiveInfinity;
            minimumBladeTorsoClearance = float.PositiveInfinity;
            maximumLeftKneeBendDeviation = 0f;
            maximumRightKneeBendDeviation = 0f;
            observedLeftKneeBend = 0f;
            observedRightKneeBend = 0f;
            maximumNormalizedObserved = normalized;
            AccumulateLeftArmOutwardPop(root, normalized);
            Panels.Add(CaptureRuntimePanel(root));
            Observations.Add(
                "panel=0|state=" + LightsaberSetupTools.ThrustModeEnterStateName +
                "|normalized=" + Num(normalized) +
                "|elapsed=" + Num((float)Time.timeAsDouble));
            SessionState.SetInt(IndexKey, 1);
            SessionState.SetInt(StateKey, Capturing);
        }

        private static void RequireWithinWaitLimit()
        {
            float started = SessionState.GetFloat(WaitStartKey, 0f);
            if (Time.realtimeSinceStartupAsDouble - started > 20d)
                throw new InvalidOperationException(
                    "Lightsaber_ThrustMode_Enter did not reach its natural cycle start " +
                    "within twenty seconds.");
        }

        private static void CaptureWhenDue()
        {
            Animator animator = RequireRuntimeAnimator();
            Transform root = animator.transform;
            RequireRootAndProp(root);
            AccumulateFootPlantMetrics(root);
            int index = SessionState.GetInt(IndexKey, 0);
            if (index < 0 || index >= ExpectedNormalizedTimes.Length)
                throw new InvalidOperationException(
                    "Lightsaber_ThrustMode_Enter capture index is invalid: " +
                    index + ".");
            if (animator.IsInTransition(0)) return;
            AnimatorStateInfo info = animator.GetCurrentAnimatorStateInfo(0);
            if (info.shortNameHash != Animator.StringToHash(
                    LightsaberSetupTools.ThrustModeEnterStateName))
                return;
            float normalized = NormalizedFraction(info.normalizedTime);
            AccumulateLeftArmOutwardPop(root, normalized);
            if (index == ExpectedNormalizedTimes.Length - 1)
            {
                if (maximumNormalizedObserved < 0.85f || normalized > 0.18f)
                    return;
            }
            else if (normalized < ExpectedNormalizedTimes[index])
                return;
            if (index < ExpectedNormalizedTimes.Length - 1 &&
                normalized > 0.99f && ExpectedNormalizedTimes[index] < 0.95f)
                throw new InvalidOperationException(
                    "Lightsaber_ThrustMode_Enter skipped visual sample " + index + ".");

            maximumNormalizedObserved = Mathf.Max(
                maximumNormalizedObserved, normalized);
            if (index >= 4 && index <= 6)
            {
                AccumulateHoldStability(root);
                AccumulateCorrectionMetrics(root);
            }
            Panels.Add(CaptureRuntimePanel(root));
            Observations.Add(
                "panel=" + index +
                "|state=" + LightsaberSetupTools.ThrustModeEnterStateName +
                "|normalized=" + Num(normalized) +
                "|elapsed=" + Num((float)Time.timeAsDouble));
            index++;
            SessionState.SetInt(IndexKey, index);
            if (index < ExpectedNormalizedTimes.Length) return;

            bool rootStable = maximumRootPositionDrift <= 0.0001f &&
                maximumRootRotationDrift <= 0.02f;
            bool holdStable = maximumHoldPositionDelta <= 0.0001f &&
                maximumHoldRotationDelta <= 0.02f &&
                maximumHoldScaleDelta <= 0.0001f;
            bool sequenceObserved = Panels.Count == ExpectedNormalizedTimes.Length &&
                maximumNormalizedObserved >= 0.85f;
            bool correctedPoseStable =
                maximumBladeTiltDirectionError <=
                    LightsaberSetupTools.ThrustModeEnterBladeTiltToleranceDegrees &&
                maximumBladeDownTiltError <=
                    LightsaberSetupTools.ThrustModeEnterBladeTiltToleranceDegrees &&
                maximumBladeLeftTiltError <=
                    LightsaberSetupTools.ThrustModeEnterBladeTiltToleranceDegrees &&
                minimumBladeForwardDot > 0f &&
                maximumPropRotationDelta > 5f &&
                maximumGripOffsetError <= 0.012f &&
                minimumRightHandOutsideShoulder >=
                    LightsaberSetupTools.ThrustModeEnterHandOutsideShoulderMeters &&
                minimumLeftHandOutsideShoulder >=
                    LightsaberSetupTools.ThrustModeEnterHandOutsideShoulderMeters &&
                minimumRightHandBelowShoulder >=
                    LightsaberSetupTools.ThrustModeEnterHandBelowShoulderMeters &&
                minimumLeftHandBelowShoulder >=
                    LightsaberSetupTools.ThrustModeEnterHandBelowShoulderMeters &&
                minimumRightHandBelowShoulder <=
                    LightsaberSetupTools.ThrustModeEnterHandMaximumBelowShoulderMeters &&
                minimumLeftHandBelowShoulder <=
                    LightsaberSetupTools.ThrustModeEnterHandMaximumBelowShoulderMeters &&
                minimumBladeHeadClearance >=
                    LightsaberSetupTools.ThrustModeEnterBladeHeadClearanceMeters &&
                minimumBladeTorsoClearance >=
                    LightsaberSetupTools.ThrustModeEnterBladeTorsoClearanceMeters &&
                maximumLeftKneeBendDeviation <=
                    LightsaberSetupTools.ThrustModeEnterKneeBendToleranceDegrees &&
                maximumRightKneeBendDeviation <=
                    LightsaberSetupTools.ThrustModeEnterKneeBendToleranceDegrees;
            bool feetPlanted =
                maximumLeftFootPositionDrift <=
                    LightsaberSetupTools.ThrustModeEnterFootPositionToleranceMeters &&
                maximumRightFootPositionDrift <=
                    LightsaberSetupTools.ThrustModeEnterFootPositionToleranceMeters &&
                maximumLeftFootVerticalDrift <=
                    LightsaberSetupTools.ThrustModeEnterFootPositionToleranceMeters &&
                maximumRightFootVerticalDrift <=
                    LightsaberSetupTools.ThrustModeEnterFootPositionToleranceMeters &&
                maximumLeftFootRotationDrift <=
                    LightsaberSetupTools.ThrustModeEnterFootRotationToleranceDegrees &&
                maximumRightFootRotationDrift <=
                    LightsaberSetupTools.ThrustModeEnterFootRotationToleranceDegrees;
            bool passed = rootStable && holdStable && sequenceObserved &&
                correctedPoseStable && feetPlanted &&
                maximumLeftHandOutwardStep <= 0.002f &&
                maximumLeftElbowOutwardStep <= 0.002f;
            ComposeReview();
            WriteReport(passed);
            CleanupPanels();
            if (!rootStable)
                throw new InvalidOperationException(
                    "Lightsaber_ThrustMode_Enter root drifted during playback. " +
                    "position=" + Num(maximumRootPositionDrift) +
                    "|rotation=" + Num(maximumRootRotationDrift));
            if (!holdStable)
                throw new InvalidOperationException(
                    "Lightsaber_ThrustMode_Enter destination pose changed during hold. " +
                    "position=" + Num(maximumHoldPositionDelta) +
                    "|rotation=" + Num(maximumHoldRotationDelta) +
                    "|scale=" + Num(maximumHoldScaleDelta));
            if (!correctedPoseStable)
                throw new InvalidOperationException(
                    "Lightsaber_ThrustMode_Enter corrected hold pose differs. " +
                    "bladeDirectionError=" + Num(maximumBladeTiltDirectionError) +
                    "|bladeDownError=" + Num(maximumBladeDownTiltError) +
                    "|bladeLeftError=" + Num(maximumBladeLeftTiltError) +
                    "|bladeDown=" + Num(observedBladeDownTilt) +
                    "|bladeLeft=" + Num(observedBladeLeftTilt) +
                    "|bladeDot=" + Num(minimumBladeForwardDot) +
                    "|gripOffsetError=" + Num(maximumGripOffsetError) +
                    "|rightOutside=" + Num(minimumRightHandOutsideShoulder) +
                    "|leftOutside=" + Num(minimumLeftHandOutsideShoulder) +
                    "|rightBelow=" + Num(minimumRightHandBelowShoulder) +
                    "|leftBelow=" + Num(minimumLeftHandBelowShoulder) +
                    "|bladeHeadClearance=" + Num(minimumBladeHeadClearance) +
                    "|bladeTorsoClearance=" + Num(minimumBladeTorsoClearance) +
                    "|leftKnee=" + Num(observedLeftKneeBend) +
                    "|rightKnee=" + Num(observedRightKneeBend));
            if (!feetPlanted)
                throw new InvalidOperationException(
                    "Lightsaber_ThrustMode_Enter feet moved during playback. " +
                    "leftPosition=" + Num(maximumLeftFootPositionDrift) +
                    "|rightPosition=" + Num(maximumRightFootPositionDrift) +
                    "|leftVertical=" + Num(maximumLeftFootVerticalDrift) +
                    "|rightVertical=" + Num(maximumRightFootVerticalDrift) +
                    "|leftRotation=" + Num(maximumLeftFootRotationDrift) +
                    "|rightRotation=" + Num(maximumRightFootRotationDrift));
            if (maximumLeftHandOutwardStep > 0.002f ||
                maximumLeftElbowOutwardStep > 0.002f)
                throw new InvalidOperationException(
                    "Lightsaber_ThrustMode_Enter left arm popped outward during " +
                    "natural playback. handStep=" +
                    Num(maximumLeftHandOutwardStep) +
                    "|elbowStep=" + Num(maximumLeftElbowOutwardStep));
            SessionState.SetInt(StateKey, WaitingForEditMode);
            EditorApplication.ExitPlaymode();
        }

        private static Animator RequireRuntimeAnimator()
        {
            GameObject[] matches = Resources.FindObjectsOfTypeAll<GameObject>()
                .Where(item => item.scene.IsValid() && item.scene.isLoaded &&
                    item.name == LightsaberSetupTools.ThrustModeEnterTargetName)
                .ToArray();
            if (matches.Length != 1)
                throw new InvalidOperationException(
                    "Expected exactly one runtime Lightsaber_ThrustMode_Enter; found " +
                    matches.Length + ".");
            Animator animator = matches[0].GetComponent<Animator>();
            if (animator == null || animator.runtimeAnimatorController == null ||
                AssetDatabase.GetAssetPath(animator.runtimeAnimatorController) !=
                    LightsaberSetupTools.ThrustModeEnterControllerPath ||
                !animator.enabled || animator.applyRootMotion)
                throw new InvalidOperationException(
                    "Lightsaber_ThrustMode_Enter runtime Animator settings differ.");
            return animator;
        }

        private static Transform RequireRuntimeProp(Transform root)
        {
            Transform hand = root.Find(
                "Armature/Hips/Spine02/Spine01/Spine/RightShoulder/RightArm/" +
                "RightForeArm/RightHand") ?? throw new InvalidOperationException(
                    "Lightsaber_ThrustMode_Enter runtime RightHand is missing.");
            Transform prop = hand.Find("Lightsaber_Prop") ??
                throw new InvalidOperationException(
                    "Runtime Lightsaber_Prop is missing from RightHand.");
            if (prop.parent != hand)
                throw new InvalidOperationException(
                    "Lightsaber_Prop stopped directly following RightHand.");
            return prop;
        }

        private static void RequireRootAndProp(Transform root)
        {
            maximumRootPositionDrift = Mathf.Max(
                maximumRootPositionDrift,
                Vector3.Distance(root.position, initialRootPosition));
            maximumRootRotationDrift = Mathf.Max(
                maximumRootRotationDrift,
                Quaternion.Angle(root.rotation, initialRootRotation));
            if (Vector3.Distance(root.localScale, initialRootScale) > 0.0001f)
                throw new InvalidOperationException(
                    "Lightsaber_ThrustMode_Enter root scale changed.");
            Transform prop = RequireRuntimeProp(root);
            maximumPropRotationDelta = Mathf.Max(
                maximumPropRotationDelta,
                Quaternion.Angle(prop.localRotation, initialPropLocalRotation));
            if (Vector3.Distance(prop.localPosition, initialPropLocalPosition) > 0.0001f ||
                Vector3.Distance(prop.localScale, initialPropLocalScale) > 0.0001f)
                throw new InvalidOperationException(
                    "Lightsaber_Prop local grip position or scale changed during " +
                    "thrust-mode enter.");
        }

        private static void AccumulateHoldStability(Transform root)
        {
            Transform prop = RequireRuntimeProp(root);
            Dictionary<string, RuntimeLocalPose> current = CapturePose(root, prop);
            if (holdReferencePose == null)
            {
                holdReferencePose = current;
                return;
            }
            if (current.Count != holdReferencePose.Count ||
                current.Keys.Any(path => !holdReferencePose.ContainsKey(path)))
                throw new InvalidOperationException(
                    "Lightsaber_ThrustMode_Enter hierarchy changed during hold.");
            foreach (KeyValuePair<string, RuntimeLocalPose> item in current)
            {
                RuntimeLocalPose reference = holdReferencePose[item.Key];
                maximumHoldPositionDelta = Mathf.Max(
                    maximumHoldPositionDelta,
                    Vector3.Distance(item.Value.Position, reference.Position));
                maximumHoldRotationDelta = Mathf.Max(
                    maximumHoldRotationDelta,
                    Quaternion.Angle(item.Value.Rotation, reference.Rotation));
                maximumHoldScaleDelta = Mathf.Max(
                    maximumHoldScaleDelta,
                    Vector3.Distance(item.Value.Scale, reference.Scale));
            }
        }

        private static void AccumulateLeftArmOutwardPop(
            Transform root,
            float normalized)
        {
            if (normalized > 0.5f) return;
            Transform hand = RequireRuntimeBone(root, LeftHandRuntimePath);
            Transform elbow = RequireRuntimeBone(root, LeftForeArmRuntimePath);
            float handX = root.InverseTransformPoint(hand.position).x;
            float elbowX = root.InverseTransformPoint(elbow.position).x;
            if (!leftArmTrajectoryInitialized ||
                normalized < previousLeftArmNormalized)
            {
                leftArmTrajectoryInitialized = true;
                previousLeftArmNormalized = normalized;
                previousLeftHandLocalX = handX;
                previousLeftElbowLocalX = elbowX;
                return;
            }
            maximumLeftHandOutwardStep = Mathf.Max(
                maximumLeftHandOutwardStep,
                previousLeftHandLocalX - handX);
            maximumLeftElbowOutwardStep = Mathf.Max(
                maximumLeftElbowOutwardStep,
                previousLeftElbowLocalX - elbowX);
            previousLeftArmNormalized = normalized;
            previousLeftHandLocalX = handX;
            previousLeftElbowLocalX = elbowX;
        }

        private static void AccumulateCorrectionMetrics(Transform root)
        {
            Transform rightArm = RequireRuntimeBone(root, RightArmRuntimePath);
            Transform rightHand = root.Find(
                "Armature/Hips/Spine02/Spine01/Spine/RightShoulder/RightArm/" +
                "RightForeArm/RightHand") ?? throw new InvalidOperationException(
                    "Runtime right hand is missing during correction review.");
            Transform leftHand = root.Find(
                "Armature/Hips/Spine02/Spine01/Spine/LeftShoulder/LeftArm/" +
                "LeftForeArm/LeftHand") ?? throw new InvalidOperationException(
                    "Runtime left hand is missing during correction review.");
            Transform prop = RequireRuntimeProp(root);
            Vector3 bladeDirection = prop.TransformDirection(
                LightsaberSetupTools.DiagonalSlashBladeAxisLocal()).normalized;
            Vector3 bladeLocal = root.InverseTransformDirection(
                bladeDirection).normalized;
            observedBladeDownTilt = Mathf.Atan2(
                -bladeLocal.y, bladeLocal.z) * Mathf.Rad2Deg;
            observedBladeLeftTilt = Mathf.Atan2(
                -bladeLocal.x, bladeLocal.z) * Mathf.Rad2Deg;
            maximumBladeTiltDirectionError = Mathf.Max(
                maximumBladeTiltDirectionError,
                Vector3.Angle(
                    bladeDirection,
                    LightsaberSetupTools.ThrustModeEnterBladeTiltDirection(root)));
            maximumBladeDownTiltError = Mathf.Max(
                maximumBladeDownTiltError,
                Mathf.Abs(
                    observedBladeDownTilt -
                    LightsaberSetupTools.ThrustModeEnterBladeDownTiltDegrees));
            maximumBladeLeftTiltError = Mathf.Max(
                maximumBladeLeftTiltError,
                Mathf.Abs(
                    observedBladeLeftTilt -
                    LightsaberSetupTools.ThrustModeEnterBladeLeftTiltDegrees));
            minimumBladeForwardDot = Mathf.Min(
                minimumBladeForwardDot,
                Vector3.Dot(bladeDirection, root.forward));
            Vector3 expectedLeftOffset =
                -root.forward * 0.09f - root.up * 0.012f;
            maximumGripOffsetError = Mathf.Max(
                maximumGripOffsetError,
                Vector3.Distance(
                    leftHand.position - rightHand.position,
                    expectedLeftOffset));
            minimumRightHandOutsideShoulder = Mathf.Min(
                minimumRightHandOutsideShoulder,
                Vector3.Dot(rightHand.position - rightArm.position, root.right));
            minimumLeftHandOutsideShoulder = Mathf.Min(
                minimumLeftHandOutsideShoulder,
                Vector3.Dot(leftHand.position - rightArm.position, root.right));
            minimumRightHandBelowShoulder = Mathf.Min(
                minimumRightHandBelowShoulder,
                Vector3.Dot(rightArm.position - rightHand.position, root.up));
            minimumLeftHandBelowShoulder = Mathf.Min(
                minimumLeftHandBelowShoulder,
                Vector3.Dot(rightArm.position - leftHand.position, root.up));
            Transform leftShoulder = RequireRuntimeBone(
                root, LeftShoulderRuntimePath);
            Transform rightShoulder = RequireRuntimeBone(
                root, RightShoulderRuntimePath);
            Transform hips = RequireRuntimeBone(root, HipsRuntimePath);
            Transform head = root.GetComponentsInChildren<Transform>(true)
                .Single(item => item.name == "Head");
            RequireRuntimeBladeSegment(
                prop, bladeDirection, out Vector3 bladeStart, out Vector3 bladeEnd);
            Vector3 shoulderCenter =
                (leftShoulder.position + rightShoulder.position) * 0.5f;
            Vector3 middleTorso = Vector3.Lerp(
                hips.position, shoulderCenter, 0.58f);
            minimumBladeHeadClearance = Mathf.Min(
                minimumBladeHeadClearance,
                DistancePointToRuntimeSegment(
                    head.position, bladeStart, bladeEnd));
            minimumBladeTorsoClearance = Mathf.Min(
                minimumBladeTorsoClearance,
                Mathf.Min(
                    DistancePointToRuntimeSegment(
                        shoulderCenter, bladeStart, bladeEnd),
                    DistancePointToRuntimeSegment(
                        middleTorso, bladeStart, bladeEnd)));
            Transform leftUpLeg = RequireRuntimeBone(root, LeftUpLegRuntimePath);
            Transform leftLeg = RequireRuntimeBone(root, LeftLegRuntimePath);
            Transform leftFoot = RequireRuntimeBone(root, LeftFootRuntimePath);
            Transform rightUpLeg = RequireRuntimeBone(root, RightUpLegRuntimePath);
            Transform rightLeg = RequireRuntimeBone(root, RightLegRuntimePath);
            Transform rightFoot = RequireRuntimeBone(root, RightFootRuntimePath);
            observedLeftKneeBend = MeasureRuntimeKneeBend(
                leftUpLeg, leftLeg, leftFoot);
            observedRightKneeBend = MeasureRuntimeKneeBend(
                rightUpLeg, rightLeg, rightFoot);
            maximumLeftKneeBendDeviation = Mathf.Max(
                maximumLeftKneeBendDeviation,
                Mathf.Abs(observedLeftKneeBend -
                    expectedLeftKneeChainAngle));
            maximumRightKneeBendDeviation = Mathf.Max(
                maximumRightKneeBendDeviation,
                Mathf.Abs(observedRightKneeBend -
                    expectedRightKneeChainAngle));
        }

        private const string RightArmRuntimePath =
            "Armature/Hips/Spine02/Spine01/Spine/RightShoulder/RightArm";
        private const string LeftShoulderRuntimePath =
            "Armature/Hips/Spine02/Spine01/Spine/LeftShoulder";
        private const string LeftForeArmRuntimePath =
            "Armature/Hips/Spine02/Spine01/Spine/LeftShoulder/LeftArm/" +
            "LeftForeArm";
        private const string LeftHandRuntimePath =
            LeftForeArmRuntimePath + "/LeftHand";
        private const string RightShoulderRuntimePath =
            "Armature/Hips/Spine02/Spine01/Spine/RightShoulder";
        private const string HipsRuntimePath = "Armature/Hips";
        private const string LeftUpLegRuntimePath = "Armature/Hips/LeftUpLeg";
        private const string LeftLegRuntimePath =
            "Armature/Hips/LeftUpLeg/LeftLeg";
        private const string LeftFootRuntimePath =
            "Armature/Hips/LeftUpLeg/LeftLeg/LeftFoot";
        private const string RightUpLegRuntimePath = "Armature/Hips/RightUpLeg";
        private const string RightLegRuntimePath =
            "Armature/Hips/RightUpLeg/RightLeg";
        private const string RightFootRuntimePath =
            "Armature/Hips/RightUpLeg/RightLeg/RightFoot";

        private static float MeasureRuntimeKneeBend(
            Transform upLeg,
            Transform leg,
            Transform foot)
        {
            return Vector3.Angle(
                leg.position - upLeg.position,
                foot.position - leg.position);
        }

        private static Transform RequireRuntimeBone(Transform root, string path)
        {
            return root.Find(path) ?? throw new InvalidOperationException(
                "Lightsaber_ThrustMode_Enter runtime bone is missing: " + path);
        }

        private static float DistancePointToRuntimeSegment(
            Vector3 point,
            Vector3 start,
            Vector3 end)
        {
            Vector3 segment = end - start;
            float denominator = segment.sqrMagnitude;
            if (denominator <= 0.000001f)
                return Vector3.Distance(point, start);
            float distance = Mathf.Clamp01(
                Vector3.Dot(point - start, segment) / denominator);
            return Vector3.Distance(point, start + segment * distance);
        }

        private static void RequireRuntimeBladeSegment(
            Transform prop,
            Vector3 bladeDirection,
            out Vector3 start,
            out Vector3 end)
        {
            Transform bladeRoot = prop.Find("Lightsaber_Blade") ??
                prop.GetComponentsInChildren<Transform>(true)
                    .SingleOrDefault(item => item.name == "Lightsaber_Blade") ??
                throw new InvalidOperationException(
                    "Runtime Lightsaber_Blade is missing during clearance review.");
            Renderer[] bladeRenderers = bladeRoot
                .GetComponentsInChildren<Renderer>(true)
                .Where(item => item.enabled && item.gameObject.activeInHierarchy)
                .ToArray();
            if (bladeRenderers.Length == 0)
                throw new InvalidOperationException(
                    "Runtime Lightsaber_Blade has no visible renderer.");
            Bounds bounds = bladeRenderers[0].bounds;
            foreach (Renderer renderer in bladeRenderers.Skip(1))
                bounds.Encapsulate(renderer.bounds);
            Vector3 extents = bounds.extents;
            Vector3 absoluteDirection = new Vector3(
                Mathf.Abs(bladeDirection.x),
                Mathf.Abs(bladeDirection.y),
                Mathf.Abs(bladeDirection.z));
            float halfLength = Mathf.Max(
                0.01f, Vector3.Dot(absoluteDirection, extents));
            start = bounds.center - bladeDirection * halfLength;
            end = bounds.center + bladeDirection * halfLength;
        }

        private static void AccumulateFootPlantMetrics(Transform root)
        {
            Transform leftFoot = RequireRuntimeBone(root, LeftFootRuntimePath);
            Transform rightFoot = RequireRuntimeBone(root, RightFootRuntimePath);
            maximumLeftFootPositionDrift = Mathf.Max(
                maximumLeftFootPositionDrift,
                Vector3.Distance(initialLeftFootPosition, leftFoot.position));
            maximumRightFootPositionDrift = Mathf.Max(
                maximumRightFootPositionDrift,
                Vector3.Distance(initialRightFootPosition, rightFoot.position));
            maximumLeftFootVerticalDrift = Mathf.Max(
                maximumLeftFootVerticalDrift,
                Mathf.Abs(initialLeftFootPosition.y - leftFoot.position.y));
            maximumRightFootVerticalDrift = Mathf.Max(
                maximumRightFootVerticalDrift,
                Mathf.Abs(initialRightFootPosition.y - rightFoot.position.y));
            maximumLeftFootRotationDrift = Mathf.Max(
                maximumLeftFootRotationDrift,
                Quaternion.Angle(initialLeftFootRotation, leftFoot.rotation));
            maximumRightFootRotationDrift = Mathf.Max(
                maximumRightFootRotationDrift,
                Quaternion.Angle(initialRightFootRotation, rightFoot.rotation));
        }

        private static Dictionary<string, RuntimeLocalPose> CapturePose(
            Transform root,
            Transform excludedRoot)
        {
            var result = new Dictionary<string, RuntimeLocalPose>(
                StringComparer.Ordinal);
            foreach (Transform current in root.GetComponentsInChildren<Transform>(true))
            {
                if (current == root || current == excludedRoot ||
                    current.IsChildOf(excludedRoot))
                    continue;
                result[AnimationUtility.CalculateTransformPath(current, root)] =
                    new RuntimeLocalPose(
                        current.localPosition,
                        current.localRotation,
                        current.localScale);
            }
            return result;
        }

        private static Texture2D CaptureRuntimePanel(Transform target)
        {
            Renderer[] renderers = target.GetComponentsInChildren<Renderer>(true)
                .Where(item => item.enabled && item.gameObject.activeInHierarchy)
                .ToArray();
            if (renderers.Length == 0)
                throw new InvalidOperationException(
                    "Lightsaber_ThrustMode_Enter has no visible runtime renderers.");
            GameObject cameraObject = new GameObject(
                "LightsaberThrustModeEnterReviewCamera")
            {
                hideFlags = HideFlags.HideAndDontSave
            };
            GameObject lightObject = new GameObject(
                "LightsaberThrustModeEnterReviewLight")
            {
                hideFlags = HideFlags.HideAndDontSave
            };
            Camera camera = cameraObject.AddComponent<Camera>();
            Light light = lightObject.AddComponent<Light>();
            Transform[] targetNodes = target.GetComponentsInChildren<Transform>(true);
            int[] originalLayers = targetNodes.Select(item => item.gameObject.layer).ToArray();
            var occupiedOutsideLayers = new HashSet<int>(
                Resources.FindObjectsOfTypeAll<Renderer>()
                    .Where(item => item != null && item.transform != target &&
                        !item.transform.IsChildOf(target) && item.gameObject.scene.IsValid() &&
                        item.gameObject.scene.isLoaded)
                    .Select(item => item.gameObject.layer));
            int reviewLayer = Enumerable.Range(0, 32)
                .Reverse()
                .First(layer => !occupiedOutsideLayers.Contains(layer));
            foreach (Transform node in targetNodes)
                node.gameObject.layer = reviewLayer;
            camera.enabled = false;
            camera.cullingMask = 1 << reviewLayer;
            camera.clearFlags = CameraClearFlags.SolidColor;
            camera.backgroundColor = new Color(0.015f, 0.02f, 0.03f, 1f);
            camera.orthographic = true;
            camera.aspect = PanelWidth / (float)PanelHeight;
            camera.orthographicSize = 1.15f;
            Vector3 viewDirection =
                (target.forward + target.right * 0.2f).normalized;
            const float cameraDistance = 4f;
            Vector3 stableCenter = target.position +
                target.up * 0.98f + target.forward * 0.2f;
            camera.nearClipPlane = 0.01f;
            camera.farClipPlane = 10f;
            camera.transform.SetPositionAndRotation(
                stableCenter + viewDirection * cameraDistance,
                Quaternion.LookRotation(-viewDirection, target.up));
            light.type = LightType.Directional;
            light.intensity = 1.2f;
            light.transform.rotation = Quaternion.LookRotation(
                -viewDirection - target.up * 0.25f, target.up);
            RenderTexture render = RenderTexture.GetTemporary(
                PanelWidth, PanelHeight, 24, RenderTextureFormat.ARGB32);
            RenderTexture previousActive = RenderTexture.active;
            try
            {
                camera.targetTexture = render;
                camera.Render();
                RenderTexture.active = render;
                var panel = new Texture2D(
                    PanelWidth, PanelHeight, TextureFormat.RGB24, false);
                panel.ReadPixels(
                    new Rect(0f, 0f, PanelWidth, PanelHeight), 0, 0, false);
                panel.Apply(false, false);
                return panel;
            }
            finally
            {
                camera.targetTexture = null;
                RenderTexture.active = previousActive;
                RenderTexture.ReleaseTemporary(render);
                for (int index = 0; index < targetNodes.Length; index++)
                    if (targetNodes[index] != null)
                        targetNodes[index].gameObject.layer = originalLayers[index];
                UnityEngine.Object.DestroyImmediate(cameraObject);
                UnityEngine.Object.DestroyImmediate(lightObject);
            }
        }

        private static void ComposeReview()
        {
            if (Panels.Count != ExpectedNormalizedTimes.Length)
                throw new InvalidOperationException(
                    "Lightsaber_ThrustMode_Enter review panel count differs.");
            const int columns = 5;
            int rows = Mathf.CeilToInt(Panels.Count / (float)columns);
            var composite = new Texture2D(
                PanelWidth * columns,
                PanelHeight * rows,
                TextureFormat.RGB24,
                false);
            try
            {
                Color background = new Color(0.015f, 0.02f, 0.03f, 1f);
                composite.SetPixels(Enumerable.Repeat(
                    background, composite.width * composite.height).ToArray());
                for (int index = 0; index < Panels.Count; index++)
                {
                    int x = (index % columns) * PanelWidth;
                    int y = (rows - 1 - index / columns) * PanelHeight;
                    composite.SetPixels(
                        x, y, PanelWidth, PanelHeight, Panels[index].GetPixels());
                }
                composite.Apply(false, false);
                string path = Absolute(
                    LightsaberSetupTools.ThrustModeEnterReviewRelativePath);
                Directory.CreateDirectory(Path.GetDirectoryName(path) ??
                    throw new InvalidOperationException(
                        "Lightsaber_ThrustMode_Enter review directory is unavailable."));
                File.WriteAllBytes(path, composite.EncodeToPNG());
            }
            finally
            {
                UnityEngine.Object.DestroyImmediate(composite);
            }
        }

