        private static void FinishSuccess()
        {
            int errorsBefore = SessionState.GetInt(ConsoleErrorsBeforeKey, 0);
            RestoreSavedSceneAfterPlayModeCapture();
            LightsaberSetupTools.InspectLightsaberThrustModeEnterTransition();
            LightsaberSetupTools.RequireNoNewUnityConsoleErrors(errorsBefore);
            Action<string> callback = complete;
            CleanupSession();
            callback?.Invoke(
                "Lightsaber_ThrustMode_Enter natural one-second cycle inspected in " +
                "Play Mode; eight-panel direct review captured and Edit Mode restored.");
        }

        private static void FinishFailure()
        {
            string error = SessionState.GetString(
                FailureKey,
                "Lightsaber_ThrustMode_Enter Play Mode inspection failed.");
            Action<Exception> callback = fail;
            RestoreSavedSceneAfterPlayModeCapture();
            CleanupSession();
            callback?.Invoke(new InvalidOperationException(error));
        }

        private static void RestoreSavedSceneAfterPlayModeCapture()
        {
            const string scenePath = "Assets/_Project/Scenes/CargoRunMvp.unity";
            Scene active = SceneManager.GetActiveScene();
            if (active.path != scenePath || active.isDirty)
                EditorSceneManager.OpenScene(scenePath, OpenSceneMode.Single);
        }

        private static float NormalizedFraction(float normalizedTime)
        {
            return normalizedTime - Mathf.Floor(normalizedTime);
        }

        private static void CleanupPanels()
        {
            foreach (Texture2D panel in Panels)
                if (panel != null) UnityEngine.Object.DestroyImmediate(panel);
            Panels.Clear();
        }

        private static void CleanupSession()
        {
            CleanupPanels();
            Observations.Clear();
            holdReferencePose = null;
            complete = null;
            fail = null;
            SessionState.EraseInt(StateKey);
            SessionState.EraseInt(IndexKey);
            SessionState.EraseFloat(WaitStartKey);
            SessionState.EraseInt(ConsoleErrorsBeforeKey);
            SessionState.EraseString(FailureKey);
        }

        private static void TryDelete(string path)
        {
            if (File.Exists(path)) File.Delete(path);
        }

        private static string Absolute(string relativePath)
        {
            return Path.GetFullPath(Path.Combine(
                Path.GetDirectoryName(Application.dataPath) ?? string.Empty,
                relativePath));
        }

        private static string Num(float value)
        {
            return value.ToString("R", CultureInfo.InvariantCulture);
        }

        private readonly struct RuntimeLocalPose
        {
            internal RuntimeLocalPose(
                Vector3 position,
                Quaternion rotation,
                Vector3 scale)
            {
                Position = position;
                Rotation = rotation;
                Scale = scale;
            }

            internal Vector3 Position { get; }
            internal Quaternion Rotation { get; }
            internal Vector3 Scale { get; }
        }
    }

    [InitializeOnLoad]
    internal static class LightsaberThrustStartPosePlayModeCapture
    {
        private const string StateKey =
            "Bellerophon.LightsaberThrustStartPoseCapture.State";
        private const string WaitStartKey =
            "Bellerophon.LightsaberThrustStartPoseCapture.WaitStart";
        private const string ConsoleErrorsBeforeKey =
            "Bellerophon.LightsaberThrustStartPoseCapture.ConsoleErrorsBefore";
        private const string FailureKey =
            "Bellerophon.LightsaberThrustStartPoseCapture.Failure";
        private const int WaitingForPlayMode = 1;
        private const int WaitingForSourceHold = 2;
        private const int WaitingForEditMode = 3;
        private const int FailedWaitingForEditMode = 4;

        private static Action<string> complete;
        private static Action<Exception> fail;

        static LightsaberThrustStartPosePlayModeCapture()
        {
            EditorApplication.update -= Tick;
            EditorApplication.update += Tick;
        }

        internal static bool HasPendingCapture =>
            SessionState.GetInt(StateKey, 0) != 0;

        internal static void Start(
            Action<string> completeCallback,
            Action<Exception> failCallback)
        {
            complete = completeCallback;
            fail = failCallback;
            bool alreadyPlaying = EditorApplication.isPlaying;
            if (EditorApplication.isPlayingOrWillChangePlaymode && !alreadyPlaying)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust start-pose inspection cannot start while " +
                    "Play Mode changes.");
            if (!alreadyPlaying)
                LightsaberSetupTools.InspectLightsaberThrustStartPose();
            TryDelete(Absolute(
                LightsaberSetupTools.ThrustStartPoseReviewRelativePath));
            TryDelete(Absolute(
                LightsaberSetupTools.ThrustStartPoseReportRelativePath));
            SessionState.SetInt(
                ConsoleErrorsBeforeKey, LightsaberSetupTools.ConsoleErrorCount());
            SessionState.SetFloat(
                WaitStartKey, (float)Time.realtimeSinceStartupAsDouble);
            SessionState.SetString(FailureKey, string.Empty);
            SessionState.SetInt(
                StateKey,
                alreadyPlaying ? WaitingForSourceHold : WaitingForPlayMode);
            if (!alreadyPlaying) EditorApplication.EnterPlaymode();
        }

        internal static void Resume(
            Action<string> completeCallback,
            Action<Exception> failCallback)
        {
            int state = SessionState.GetInt(StateKey, 0);
            if ((state == WaitingForPlayMode || state == WaitingForSourceHold) &&
                !EditorApplication.isPlayingOrWillChangePlaymode)
            {
                CleanupSession();
                Start(completeCallback, failCallback);
                return;
            }
            complete = completeCallback;
            fail = failCallback;
            Tick();
        }

        private static void Tick()
        {
            if (complete == null && fail == null) return;
            int state = SessionState.GetInt(StateKey, 0);
            try
            {
                if (state == WaitingForPlayMode)
                {
                    if (!EditorApplication.isPlaying) return;
                    SessionState.SetInt(StateKey, WaitingForSourceHold);
                    SessionState.SetFloat(
                        WaitStartKey, (float)Time.realtimeSinceStartupAsDouble);
                    return;
                }
                if (state == WaitingForSourceHold)
                {
                    if (!EditorApplication.isPlaying)
                        throw new InvalidOperationException(
                            "Unity left Play Mode before the start-pose comparison.");
                    CaptureWhenSourceHolds();
                    return;
                }
                if (state == WaitingForEditMode)
                {
                    if (EditorApplication.isPlayingOrWillChangePlaymode) return;
                    FinishSuccess();
                    return;
                }
                if (state == FailedWaitingForEditMode &&
                    !EditorApplication.isPlayingOrWillChangePlaymode)
                    FinishFailure();
            }
            catch (Exception exception)
            {
                SessionState.SetString(FailureKey, exception.ToString());
                SessionState.SetInt(StateKey, FailedWaitingForEditMode);
                if (EditorApplication.isPlaying) EditorApplication.ExitPlaymode();
                else if (!EditorApplication.isPlayingOrWillChangePlaymode)
                    FinishFailure();
            }
        }

        private static void CaptureWhenSourceHolds()
        {
            if (Time.realtimeSinceStartupAsDouble -
                    SessionState.GetFloat(WaitStartKey, 0f) > 20d)
                throw new InvalidOperationException(
                    "Lightsaber start-pose comparison did not reach the source hold " +
                    "within twenty seconds.");
            Animator source = RequireRuntimeAnimator(
                LightsaberSetupTools.ThrustModeEnterTargetName,
                LightsaberSetupTools.ThrustModeEnterControllerPath);
            Animator target = RequireRuntimeAnimator(
                LightsaberSetupTools.ThrustTargetName,
                LightsaberSetupTools.ThrustStartPoseControllerPath);
            if (source.IsInTransition(0) || target.IsInTransition(0)) return;
            AnimatorStateInfo sourceInfo = source.GetCurrentAnimatorStateInfo(0);
            AnimatorStateInfo targetInfo = target.GetCurrentAnimatorStateInfo(0);
            if (sourceInfo.shortNameHash != Animator.StringToHash(
                    LightsaberSetupTools.ThrustModeEnterStateName) ||
                targetInfo.shortNameHash != Animator.StringToHash(
                    LightsaberSetupTools.ThrustStartPoseStateName))
                return;
            float sourceNormalized = NormalizedFraction(sourceInfo.normalizedTime);
            if (sourceNormalized < 0.62f || sourceNormalized > 0.88f) return;

            Transform sourceProp = RequireRuntimeProp(source.transform);
            Transform targetProp = RequireRuntimeProp(target.transform);
            Dictionary<string, RuntimeLocalPose> sourcePose =
                CapturePose(source.transform, sourceProp);
            Dictionary<string, RuntimeLocalPose> targetPose =
                CapturePose(target.transform, targetProp);
            MeasurePoseDelta(
                sourcePose, targetPose,
                out float maximumPositionDelta,
                out float maximumRotationDelta,
                out float maximumScaleDelta);
            float propPositionDelta = Vector3.Distance(
                sourceProp.localPosition, targetProp.localPosition);
            float propRotationDelta = Quaternion.Angle(
                sourceProp.localRotation, targetProp.localRotation);
            float propScaleDelta = Vector3.Distance(
                sourceProp.localScale, targetProp.localScale);
            Vector3 sourceBladeLocal = source.transform.InverseTransformDirection(
                sourceProp.TransformDirection(
                    LightsaberSetupTools.DiagonalSlashBladeAxisLocal())).normalized;
            Vector3 targetBladeLocal = target.transform.InverseTransformDirection(
                targetProp.TransformDirection(
                    LightsaberSetupTools.DiagonalSlashBladeAxisLocal())).normalized;
            float bladeDirectionDelta = Vector3.Angle(
                sourceBladeLocal, targetBladeLocal);
            bool passed =
                maximumPositionDelta <= 0.0001f &&
                maximumRotationDelta <= 0.02f &&
                maximumScaleDelta <= 0.0001f &&
                propPositionDelta <= 0.0001f &&
                propRotationDelta <= 0.02f &&
                propScaleDelta <= 0.0001f &&
                bladeDirectionDelta <= 0.02f;
            WriteComparisonImage(source.transform, target.transform);
            WriteReport(
                passed,
                sourceNormalized,
                NormalizedFraction(targetInfo.normalizedTime),
                maximumPositionDelta,
                maximumRotationDelta,
                maximumScaleDelta,
                propPositionDelta,
                propRotationDelta,
                propScaleDelta,
                bladeDirectionDelta);
            if (!passed)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust first pose differs from the " +
                    "Lightsaber_ThrustMode_Enter last hold pose. position=" +
                    Num(maximumPositionDelta) +
                    "|rotation=" + Num(maximumRotationDelta) +
                    "|scale=" + Num(maximumScaleDelta) +
                    "|propPosition=" + Num(propPositionDelta) +
                    "|propRotation=" + Num(propRotationDelta) +
                    "|propScale=" + Num(propScaleDelta) +
                    "|bladeDirection=" + Num(bladeDirectionDelta));
            SessionState.SetInt(StateKey, WaitingForEditMode);
            EditorApplication.ExitPlaymode();
        }

        private static Animator RequireRuntimeAnimator(
            string targetName,
            string controllerPath)
        {
            GameObject[] matches = Resources.FindObjectsOfTypeAll<GameObject>()
                .Where(item => item.scene.IsValid() && item.scene.isLoaded &&
                    item.name == targetName)
                .ToArray();
            if (matches.Length != 1)
                throw new InvalidOperationException(
                    "Expected exactly one runtime " + targetName + "; found " +
                    matches.Length + ".");
            Animator animator = matches[0].GetComponent<Animator>();
            if (animator == null || animator.runtimeAnimatorController == null ||
                AssetDatabase.GetAssetPath(animator.runtimeAnimatorController) !=
                    controllerPath || !animator.enabled || animator.applyRootMotion)
                throw new InvalidOperationException(
                    targetName + " runtime Animator settings differ.");
            return animator;
        }

        private static Transform RequireRuntimeProp(Transform root)
        {
            Transform hand = root.Find(
                "Armature/Hips/Spine02/Spine01/Spine/RightShoulder/RightArm/" +
                "RightForeArm/RightHand") ?? throw new InvalidOperationException(
                    root.name + " runtime RightHand is missing.");
            Transform prop = hand.Find("Lightsaber_Prop") ??
                throw new InvalidOperationException(
                    root.name + " runtime Lightsaber_Prop is missing.");
            if (prop.parent != hand)
                throw new InvalidOperationException(
                    root.name + " Lightsaber_Prop stopped following RightHand.");
            return prop;
        }

        private static Dictionary<string, RuntimeLocalPose> CapturePose(
            Transform root,
            Transform prop)
        {
            return root.GetComponentsInChildren<Transform>(true)
                .Where(item => item != root && item != prop && !item.IsChildOf(prop))
                .ToDictionary(
                    item => AnimationUtility.CalculateTransformPath(item, root),
                    item => new RuntimeLocalPose(
                        item.localPosition, item.localRotation, item.localScale),
                    StringComparer.Ordinal);
        }

        private static void MeasurePoseDelta(
            IReadOnlyDictionary<string, RuntimeLocalPose> source,
            IReadOnlyDictionary<string, RuntimeLocalPose> target,
            out float maximumPositionDelta,
            out float maximumRotationDelta,
            out float maximumScaleDelta)
        {
            if (source.Count != target.Count ||
                source.Keys.Any(path => !target.ContainsKey(path)))
                throw new InvalidOperationException(
                    "Lightsaber thrust source and target hierarchy paths differ.");
            maximumPositionDelta = 0f;
            maximumRotationDelta = 0f;
            maximumScaleDelta = 0f;
            foreach (KeyValuePair<string, RuntimeLocalPose> item in source)
            {
                RuntimeLocalPose value = target[item.Key];
                maximumPositionDelta = Mathf.Max(
                    maximumPositionDelta,
                    Vector3.Distance(item.Value.Position, value.Position));
                maximumRotationDelta = Mathf.Max(
                    maximumRotationDelta,
                    Quaternion.Angle(item.Value.Rotation, value.Rotation));
                maximumScaleDelta = Mathf.Max(
                    maximumScaleDelta,
                    Vector3.Distance(item.Value.Scale, value.Scale));
            }
        }

        private static void WriteComparisonImage(
            Transform source,
            Transform target)
        {
            int width = LightsaberSetupTools.ThrustStartPosePanelWidth;
            int height = LightsaberSetupTools.ThrustStartPosePanelHeight;
            Color[] sourcePixels =
                LightsaberSetupTools.CaptureLightsaberThrustStartPosePanel(source);
            Color[] targetPixels =
                LightsaberSetupTools.CaptureLightsaberThrustStartPosePanel(target);
            var composite = new Texture2D(
                width * 2, height, TextureFormat.RGB24, false);
            try
            {
                composite.SetPixels(0, 0, width, height, sourcePixels);
                composite.SetPixels(width, 0, width, height, targetPixels);
                composite.Apply(false, false);
                string path = Absolute(
                    LightsaberSetupTools.ThrustStartPoseReviewRelativePath);
                Directory.CreateDirectory(Path.GetDirectoryName(path) ??
                    throw new InvalidOperationException(
                        "Lightsaber_Thrust review directory is unavailable."));
                File.WriteAllBytes(path, composite.EncodeToPNG());
            }
            finally
            {
                UnityEngine.Object.DestroyImmediate(composite);
            }
        }

        private static void WriteReport(
            bool passed,
            float sourceNormalized,
            float targetNormalized,
            float maximumPositionDelta,
            float maximumRotationDelta,
            float maximumScaleDelta,
            float propPositionDelta,
            float propRotationDelta,
            float propScaleDelta,
            float bladeDirectionDelta)
        {
            var report = new StringBuilder()
                .AppendLine("Lightsaber_Thrust start-pose natural Play Mode comparison")
                .AppendLine("naturalPlayback=True")
                .AppendLine("verificationTargetTransformManipulated=False")
                .AppendLine("animatorPlayCalled=False")
                .AppendLine("animatorRebindCalled=False")
                .AppendLine("sourceLastPoseTargetFirstPoseMatch=" + passed)
                .AppendLine("rightHandFollowPreserved=True")
                .AppendLine("sourceNormalizedTime=" + Num(sourceNormalized))
                .AppendLine("targetNormalizedTime=" + Num(targetNormalized))
                .AppendLine("maximumBonePositionDeltaMeters=" +
                    Num(maximumPositionDelta))
                .AppendLine("maximumBoneRotationDeltaDegrees=" +
                    Num(maximumRotationDelta))
                .AppendLine("maximumBoneScaleDelta=" + Num(maximumScaleDelta))
                .AppendLine("propLocalPositionDeltaMeters=" +
                    Num(propPositionDelta))
                .AppendLine("propLocalRotationDeltaDegrees=" +
                    Num(propRotationDelta))
                .AppendLine("propLocalScaleDelta=" + Num(propScaleDelta))
                .AppendLine("bladeLocalDirectionDeltaDegrees=" +
                    Num(bladeDirectionDelta))
                .AppendLine("passedNumericChecks=" + passed);
            string path = Absolute(
                LightsaberSetupTools.ThrustStartPoseReportRelativePath);
            Directory.CreateDirectory(Path.GetDirectoryName(path) ??
                throw new InvalidOperationException(
                    "Lightsaber_Thrust report directory is unavailable."));
            File.WriteAllText(path, report.ToString(), new UTF8Encoding(false));
        }

        private static void FinishSuccess()
        {
            int errorsBefore = SessionState.GetInt(ConsoleErrorsBeforeKey, 0);
            RestoreSavedSceneAfterPlayModeCapture();
            LightsaberSetupTools.InspectLightsaberThrustStartPose();
            LightsaberSetupTools.RequireNoNewUnityConsoleErrors(errorsBefore);
            Action<string> callback = complete;
            CleanupSession();
            callback?.Invoke(
                "Lightsaber_ThrustMode_Enter last hold pose and Lightsaber_Thrust " +
                "first pose compared in natural Play Mode; two-panel direct review " +
                "captured and Edit Mode restored.");
        }

        private static void FinishFailure()
        {
            string error = SessionState.GetString(
                FailureKey,
                "Lightsaber_Thrust start-pose Play Mode inspection failed.");
            Action<Exception> callback = fail;
            RestoreSavedSceneAfterPlayModeCapture();
            CleanupSession();
            callback?.Invoke(new InvalidOperationException(error));
        }

        private static void RestoreSavedSceneAfterPlayModeCapture()
        {
            const string scenePath = "Assets/_Project/Scenes/CargoRunMvp.unity";
            Scene active = SceneManager.GetActiveScene();
            if (active.path != scenePath || active.isDirty)
                EditorSceneManager.OpenScene(scenePath, OpenSceneMode.Single);
        }

        private static float NormalizedFraction(float normalizedTime)
        {
            return normalizedTime - Mathf.Floor(normalizedTime);
        }

        private static void CleanupSession()
        {
            complete = null;
            fail = null;
            SessionState.EraseInt(StateKey);
            SessionState.EraseFloat(WaitStartKey);
            SessionState.EraseInt(ConsoleErrorsBeforeKey);
            SessionState.EraseString(FailureKey);
        }

        private static void TryDelete(string path)
        {
            if (File.Exists(path)) File.Delete(path);
        }

        private static string Absolute(string relativePath)
        {
            return Path.GetFullPath(Path.Combine(
                Path.GetDirectoryName(Application.dataPath) ?? string.Empty,
                relativePath));
        }

        private static string Num(float value)
        {
            return value.ToString("R", CultureInfo.InvariantCulture);
        }

        private readonly struct RuntimeLocalPose
        {
            internal RuntimeLocalPose(
                Vector3 position,
                Quaternion rotation,
                Vector3 scale)
            {
                Position = position;
                Rotation = rotation;
                Scale = scale;
            }

            internal Vector3 Position { get; }
            internal Quaternion Rotation { get; }
            internal Vector3 Scale { get; }
        }
    }

    [InitializeOnLoad]
    internal static class LightsaberThrustMotionPlayModeCapture
    {
        private const string StateKey =
            "Bellerophon.LightsaberThrustMotionCapture.State";
        private const string IndexKey =
            "Bellerophon.LightsaberThrustMotionCapture.Index";
        private const string WaitStartKey =
            "Bellerophon.LightsaberThrustMotionCapture.WaitStart";
        private const string ConsoleErrorsBeforeKey =
            "Bellerophon.LightsaberThrustMotionCapture.ConsoleErrorsBefore";
        private const string FailureKey =
            "Bellerophon.LightsaberThrustMotionCapture.Failure";
        private const int WaitingForPlayMode = 1;
        private const int WaitingForCycleStart = 2;
        private const int Capturing = 3;
        private const int WaitingForEditMode = 4;
        private const int FailedWaitingForEditMode = 5;
        private const int PanelWidth = 360;
        private const int PanelHeight = 480;
        private const string RightArmPath =
            "Armature/Hips/Spine02/Spine01/Spine/RightShoulder/RightArm";
        private const string RightForeArmPath = RightArmPath + "/RightForeArm";
        private const string RightHandPath = RightForeArmPath + "/RightHand";
        private const string LeftArmPath =
            "Armature/Hips/Spine02/Spine01/Spine/LeftShoulder/LeftArm";
        private const string LeftForeArmPath = LeftArmPath + "/LeftForeArm";
        private const string LeftHandPath = LeftForeArmPath + "/LeftHand";
        private const string SpinePath =
            "Armature/Hips/Spine02/Spine01/Spine";
        private const string LeftShoulderPath = SpinePath + "/LeftShoulder";
        private const string RightShoulderPath = SpinePath + "/RightShoulder";
        private const string HipsPath = "Armature/Hips";
        private const string LeftUpLegPath = HipsPath + "/LeftUpLeg";
        private const string LeftLegPath = LeftUpLegPath + "/LeftLeg";
        private const string LeftFootPath = LeftLegPath + "/LeftFoot";
        private const string RightUpLegPath = HipsPath + "/RightUpLeg";
        private const string RightLegPath = RightUpLegPath + "/RightLeg";
        private const string RightFootPath = RightLegPath + "/RightFoot";

        private static readonly float[] ExpectedNormalizedTimes =
        {
            0f, 0.18f, 0.36f, 0.54f,
            0.66f, 0.78f, 0.94f,
            0f
        };

        private static readonly List<Texture2D> Panels = new List<Texture2D>();
        private static readonly List<string> Observations = new List<string>();
        private static Action<string> complete;
        private static Action<Exception> fail;
        private static Vector3 initialRootPosition;
        private static Quaternion initialRootRotation;
        private static Vector3 initialRootScale;
        private static Vector3 initialPropLocalPosition;
        private static Quaternion initialPropLocalRotation;
        private static Vector3 initialPropLocalScale;
        private static Vector3 initialBladeDirectionLocal;
        private static Vector3 initialLeftFootPosition;
        private static Vector3 initialRightFootPosition;
        private static Quaternion initialLeftFootRotation;
        private static Quaternion initialRightFootRotation;
        private static float maximumNormalizedObserved;
        private static float maximumRootPositionDrift;
        private static float maximumRootRotationDrift;
        private static float maximumPropPositionDrift;
        private static float maximumPropRotationDrift;
        private static float maximumPropScaleDrift;
        private static float maximumPropRightHandFollowPositionError;
        private static float maximumPropRightHandFollowRotationError;
        private static float maximumBladeDirectionDelta;
        private static float maximumBladeDirectionDeltaNormalized;
        private static float maximumLeftFootPositionDrift;
        private static float maximumRightFootPositionDrift;
        private static float maximumLeftFootVerticalDrift;
        private static float maximumRightFootVerticalDrift;
        private static float maximumLeftFootRotationDrift;
        private static float maximumRightFootRotationDrift;
        private static float maximumLowerBodyPositionDelta;
        private static float maximumLowerBodyRotationDelta;
        private static float maximumLowerBodyScaleDelta;
        private static float observedTorsoForwardLean;
        private static float maximumTorsoForwardLeanError;
        private static float maximumRightArmForwardAngle;
        private static float maximumLeftArmForwardAngle;
        private static float maximumArmForwardAngleDifference;
        private static float maximumGripOffsetError;
        private static float observedRightElbowBend;
        private static float observedLeftElbowBend;
        private static float maximumRightElbowBendDeviation;
        private static float maximumLeftElbowBendDeviation;
        private static float maximumHandleChestHeightOffset;
        private static float minimumBladeHeadClearance;
        private static float minimumBladeTorsoClearance;
        private static float maximumHoldPositionDelta;
        private static float maximumHoldRotationDelta;
        private static float maximumHoldScaleDelta;
        private static float maximumResetPositionDelta;
        private static float maximumResetRotationDelta;
        private static float maximumResetScaleDelta;
        private static Dictionary<string, RuntimeLocalPose> startReferencePose;
        private static Dictionary<string, RuntimeLocalPose> holdReferencePose;
        private static Dictionary<string, RuntimeLocalPose> lowerBodyReferencePose;

        static LightsaberThrustMotionPlayModeCapture()
        {
            EditorApplication.update -= Tick;
            EditorApplication.update += Tick;
        }

        internal static bool HasPendingCapture =>
            SessionState.GetInt(StateKey, 0) != 0;

        internal static void Start(
            Action<string> completeCallback,
            Action<Exception> failCallback)
        {
            complete = completeCallback;
            fail = failCallback;
            bool alreadyPlaying = EditorApplication.isPlaying;
            if (EditorApplication.isPlayingOrWillChangePlaymode && !alreadyPlaying)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust motion inspection cannot start while " +
                    "Play Mode changes.");
            if (!alreadyPlaying)
                LightsaberSetupTools.InspectLightsaberThrustMotion();
            CleanupPanels();
            Observations.Clear();
            startReferencePose = null;
            holdReferencePose = null;
            ResetMetrics();
            TryDelete(Absolute(
                LightsaberSetupTools.ThrustMotionReviewRelativePath));
            TryDelete(Absolute(
                LightsaberSetupTools.ThrustMotionReportRelativePath));
            SessionState.SetInt(
                ConsoleErrorsBeforeKey, LightsaberSetupTools.ConsoleErrorCount());
            SessionState.SetInt(IndexKey, 0);
            SessionState.SetFloat(
                WaitStartKey, (float)Time.realtimeSinceStartupAsDouble);
            SessionState.SetString(FailureKey, string.Empty);
            SessionState.SetInt(
                StateKey,
                alreadyPlaying ? WaitingForCycleStart : WaitingForPlayMode);
            if (!alreadyPlaying) EditorApplication.EnterPlaymode();
        }

        internal static void Resume(
            Action<string> completeCallback,
            Action<Exception> failCallback)
        {
            int state = SessionState.GetInt(StateKey, 0);
            if ((state == WaitingForPlayMode ||
                 state == WaitingForCycleStart || state == Capturing) &&
                !EditorApplication.isPlayingOrWillChangePlaymode)
            {
                CleanupSession();
                Start(completeCallback, failCallback);
                return;
            }
            complete = completeCallback;
            fail = failCallback;
            Tick();
        }

        private static void Tick()
        {
            if (complete == null && fail == null) return;
            int state = SessionState.GetInt(StateKey, 0);
            try
            {
                if (state == WaitingForPlayMode)
                {
                    if (!EditorApplication.isPlaying) return;
                    SessionState.SetInt(StateKey, WaitingForCycleStart);
                    SessionState.SetFloat(
                        WaitStartKey, (float)Time.realtimeSinceStartupAsDouble);
                    return;
                }
                if (state == WaitingForCycleStart)
                {
                    if (!EditorApplication.isPlaying)
                        throw new InvalidOperationException(
                            "Unity left Play Mode before the thrust cycle began.");
                    WaitForCycleStart();
                    return;
                }
                if (state == Capturing)
                {
                    if (!EditorApplication.isPlaying)
                        throw new InvalidOperationException(
                            "Unity left Play Mode before the thrust cycle completed.");
                    CaptureWhenDue();
                    return;
                }
                if (state == WaitingForEditMode)
                {
                    if (EditorApplication.isPlayingOrWillChangePlaymode) return;
                    FinishSuccess();
                    return;
                }
                if (state == FailedWaitingForEditMode &&
                    !EditorApplication.isPlayingOrWillChangePlaymode)
                    FinishFailure();
            }
            catch (Exception exception)
            {
                SessionState.SetString(FailureKey, exception.ToString());
                SessionState.SetInt(StateKey, FailedWaitingForEditMode);
                CleanupPanels();
                if (EditorApplication.isPlaying) EditorApplication.ExitPlaymode();
                else if (!EditorApplication.isPlayingOrWillChangePlaymode)
                    FinishFailure();
            }
        }

        private static void WaitForCycleStart()
        {
            Animator animator = RequireRuntimeAnimator();
            AnimatorStateInfo info = animator.GetCurrentAnimatorStateInfo(0);
            float normalized = NormalizedFraction(info.normalizedTime);
            if (info.shortNameHash != Animator.StringToHash(
                    LightsaberSetupTools.ThrustMotionStateName) ||
                normalized > 0.08f || animator.IsInTransition(0))
            {
                RequireWithinWaitLimit();
                return;
            }
            Transform root = animator.transform;
            Transform prop = RequireRuntimeProp(root);
            Transform rightHand = RequireRuntimeBone(root, RightHandPath);
            Transform leftHand = RequireRuntimeBone(root, LeftHandPath);
            Transform leftFoot = RequireRuntimeBone(root, LeftFootPath);
            Transform rightFoot = RequireRuntimeBone(root, RightFootPath);
            initialRootPosition = root.position;
            initialRootRotation = root.rotation;
            initialRootScale = root.localScale;
            initialPropLocalPosition = prop.localPosition;
            initialPropLocalRotation = prop.localRotation;
            initialPropLocalScale = prop.localScale;
            initialBladeDirectionLocal = root.InverseTransformDirection(
                prop.TransformDirection(
                    LightsaberSetupTools.DiagonalSlashBladeAxisLocal())).normalized;
            initialLeftFootPosition = leftFoot.position;
            initialRightFootPosition = rightFoot.position;
            initialLeftFootRotation = leftFoot.rotation;
            initialRightFootRotation = rightFoot.rotation;
            startReferencePose = CapturePose(root, prop);
            lowerBodyReferencePose = FilterLowerBodyPose(startReferencePose);
            AccumulateContinuousMetrics(root, prop);
            maximumNormalizedObserved = normalized;
            Panels.Add(CaptureRuntimePanel(root));
            Observations.Add(
                "panel=0|state=" + LightsaberSetupTools.ThrustMotionStateName +
                "|normalized=" + Num(normalized) +
                "|elapsed=" + Num((float)Time.timeAsDouble));
            SessionState.SetInt(IndexKey, 1);
            SessionState.SetInt(StateKey, Capturing);
        }

        private static void CaptureWhenDue()
        {
            Animator animator = RequireRuntimeAnimator();
            Transform root = animator.transform;
            Transform prop = RequireRuntimeProp(root);
            AccumulateContinuousMetrics(root, prop);
            int index = SessionState.GetInt(IndexKey, 0);
            if (index < 0 || index >= ExpectedNormalizedTimes.Length)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust capture index is invalid: " + index + ".");
            if (animator.IsInTransition(0)) return;
            AnimatorStateInfo info = animator.GetCurrentAnimatorStateInfo(0);
            if (info.shortNameHash != Animator.StringToHash(
                    LightsaberSetupTools.ThrustMotionStateName))
                return;
            float normalized = NormalizedFraction(info.normalizedTime);
            if (index == ExpectedNormalizedTimes.Length - 1)
            {
                if (maximumNormalizedObserved < 0.90f || normalized > 0.08f)
                    return;
            }
            else if (normalized < ExpectedNormalizedTimes[index])
                return;
            if (index < ExpectedNormalizedTimes.Length - 1 &&
                normalized > 0.99f && ExpectedNormalizedTimes[index] < 0.95f)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust skipped visual sample " + index + ".");

            maximumNormalizedObserved = Mathf.Max(
                maximumNormalizedObserved, normalized);
            if (index >= 4 && index <= 6)
                AccumulateDestinationAndHoldMetrics(root, prop);
            if (index == ExpectedNormalizedTimes.Length - 1)
                AccumulateResetMetrics(root, prop);
            Panels.Add(CaptureRuntimePanel(root));
            Observations.Add(
                "panel=" + index +
                "|state=" + LightsaberSetupTools.ThrustMotionStateName +
                "|normalized=" + Num(normalized) +
                "|elapsed=" + Num((float)Time.timeAsDouble));
            index++;
            SessionState.SetInt(IndexKey, index);
            if (index < ExpectedNormalizedTimes.Length) return;

            bool exactStart =
                maximumResetPositionDelta <= 0.005f &&
                maximumResetRotationDelta <= 3f &&
                maximumResetScaleDelta <= 0.0001f;
            bool rootStable =
                maximumRootPositionDrift <= 0.0001f &&
                maximumRootRotationDrift <= 0.02f;
            bool propStable =
                maximumPropPositionDrift <= 0.0001f &&
                maximumPropRotationDrift <= 0.02f &&
                maximumPropScaleDrift <= 0.0001f &&
                maximumPropRightHandFollowPositionError <= 0.0001f &&
                maximumPropRightHandFollowRotationError <= 0.02f;
            bool bladeStable =
                maximumBladeDirectionDelta <=
                    LightsaberSetupTools.ThrustMotionBladeToleranceDegrees;
            bool feetPlanted =
                maximumLeftFootPositionDrift <=
                    LightsaberSetupTools.ThrustModeEnterFootPositionToleranceMeters &&
                maximumRightFootPositionDrift <=
                    LightsaberSetupTools.ThrustModeEnterFootPositionToleranceMeters &&
                maximumLeftFootVerticalDrift <=
                    LightsaberSetupTools.ThrustModeEnterFootPositionToleranceMeters &&
                maximumRightFootVerticalDrift <=
                    LightsaberSetupTools.ThrustModeEnterFootPositionToleranceMeters &&
                maximumLeftFootRotationDrift <=
                    LightsaberSetupTools.ThrustModeEnterFootRotationToleranceDegrees &&
                maximumRightFootRotationDrift <=
                    LightsaberSetupTools.ThrustModeEnterFootRotationToleranceDegrees;
            bool lowerBodyUnchanged =
                maximumLowerBodyPositionDelta <=
                    LightsaberSetupTools.ThrustMotionLowerBodyPositionToleranceMeters &&
                maximumLowerBodyRotationDelta <=
                    LightsaberSetupTools.ThrustMotionLowerBodyRotationToleranceDegrees &&
                maximumLowerBodyScaleDelta <=
                    LightsaberSetupTools.ThrustMotionLowerBodyScaleTolerance;
            bool torsoForwardLean =
                maximumTorsoForwardLeanError <=
                    LightsaberSetupTools.ThrustMotionTorsoToleranceDegrees;
            bool armsForward =
                maximumRightArmForwardAngle <=
                    LightsaberSetupTools.ThrustMotionArmForwardToleranceDegrees &&
                maximumLeftArmForwardAngle <=
                    LightsaberSetupTools.ThrustMotionArmForwardToleranceDegrees &&
                maximumArmForwardAngleDifference <=
                    LightsaberSetupTools.
                        ThrustMotionArmForwardSymmetryToleranceDegrees &&
                maximumGripOffsetError <=
                    LightsaberSetupTools.ThrustMotionGripToleranceMeters;
            bool elbowsExtended =
                maximumRightElbowBendDeviation <=
                    LightsaberSetupTools.ThrustMotionElbowToleranceDegrees &&
                maximumLeftElbowBendDeviation <=
                    LightsaberSetupTools.ThrustMotionElbowToleranceDegrees;
            bool handleAtChestHeight =
                maximumHandleChestHeightOffset <=
                    LightsaberSetupTools.ThrustMotionChestHeightToleranceMeters;
            bool clearance =
                minimumBladeHeadClearance >=
                    LightsaberSetupTools.ThrustMotionClearanceMeters &&
                minimumBladeTorsoClearance >=
                    LightsaberSetupTools.ThrustMotionClearanceMeters;
            bool holdStable =
                maximumHoldPositionDelta <= 0.0001f &&
                maximumHoldRotationDelta <= 0.02f &&
                maximumHoldScaleDelta <= 0.0001f;
            bool sequenceObserved =
                Panels.Count == ExpectedNormalizedTimes.Length &&
                maximumNormalizedObserved >= 0.90f;
            bool passed = exactStart && rootStable && propStable && bladeStable &&
                feetPlanted && lowerBodyUnchanged && torsoForwardLean && armsForward &&
                elbowsExtended && handleAtChestHeight && holdStable &&
                sequenceObserved;
            ComposeReview();
            WriteReport(
                passed,
                exactStart,
                torsoForwardLean,
                armsForward,
                elbowsExtended,
                handleAtChestHeight,
                lowerBodyUnchanged,
                feetPlanted,
                bladeStable,
                holdStable,
                propStable);
            if (!passed)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust natural motion review failed. start=" +
                    exactStart + "|root=" + rootStable + "|prop=" + propStable +
                    "|blade=" + bladeStable + "|feet=" + feetPlanted +
                    "|lowerBody=" + lowerBodyUnchanged +
                    "|torsoForwardLean=" + torsoForwardLean +
                    "|arms=" + armsForward +
                    "|elbows=" + elbowsExtended +
                    "|handleAtChestHeight=" + handleAtChestHeight +
                    "|clearanceProxyInformational=" + clearance +
                    "|hold=" + holdStable + "|sequence=" + sequenceObserved +
                    ".");
            SessionState.SetInt(StateKey, WaitingForEditMode);
            EditorApplication.ExitPlaymode();
        }

        private static void ResetMetrics()
        {
            maximumNormalizedObserved = 0f;
            maximumRootPositionDrift = 0f;
            maximumRootRotationDrift = 0f;
            maximumPropPositionDrift = 0f;
            maximumPropRotationDrift = 0f;
            maximumPropScaleDrift = 0f;
            maximumPropRightHandFollowPositionError = 0f;
            maximumPropRightHandFollowRotationError = 0f;
            maximumBladeDirectionDelta = 0f;
            maximumBladeDirectionDeltaNormalized = 0f;
            maximumLeftFootPositionDrift = 0f;
            maximumRightFootPositionDrift = 0f;
            maximumLeftFootVerticalDrift = 0f;
            maximumRightFootVerticalDrift = 0f;
            maximumLeftFootRotationDrift = 0f;
            maximumRightFootRotationDrift = 0f;
            maximumLowerBodyPositionDelta = 0f;
            maximumLowerBodyRotationDelta = 0f;
            maximumLowerBodyScaleDelta = 0f;
            observedTorsoForwardLean = 0f;
            maximumTorsoForwardLeanError = 0f;
            maximumRightArmForwardAngle = 0f;
            maximumLeftArmForwardAngle = 0f;
            maximumArmForwardAngleDifference = 0f;
            maximumGripOffsetError = 0f;
            observedRightElbowBend = 0f;
            observedLeftElbowBend = 0f;
            maximumRightElbowBendDeviation = 0f;
            maximumLeftElbowBendDeviation = 0f;
            maximumHandleChestHeightOffset = 0f;
            minimumBladeHeadClearance = float.PositiveInfinity;
            minimumBladeTorsoClearance = float.PositiveInfinity;
            maximumHoldPositionDelta = 0f;
            maximumHoldRotationDelta = 0f;
            maximumHoldScaleDelta = 0f;
            maximumResetPositionDelta = 0f;
            maximumResetRotationDelta = 0f;
            maximumResetScaleDelta = 0f;
        }

        private static void AccumulateContinuousMetrics(
            Transform root,
            Transform prop)
        {
            maximumRootPositionDrift = Mathf.Max(
                maximumRootPositionDrift,
                Vector3.Distance(initialRootPosition, root.position));
            maximumRootRotationDrift = Mathf.Max(
                maximumRootRotationDrift,
                Quaternion.Angle(initialRootRotation, root.rotation));
            if (Vector3.Distance(initialRootScale, root.localScale) > 0.0001f)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust runtime root scale changed.");
            maximumPropPositionDrift = Mathf.Max(
                maximumPropPositionDrift,
                Vector3.Distance(initialPropLocalPosition, prop.localPosition));
            maximumPropRotationDrift = Mathf.Max(
                maximumPropRotationDrift,
                Quaternion.Angle(initialPropLocalRotation, prop.localRotation));
            maximumPropScaleDrift = Mathf.Max(
                maximumPropScaleDrift,
                Vector3.Distance(initialPropLocalScale, prop.localScale));
            Transform rightHand = RequireRuntimeBone(root, RightHandPath);
            maximumPropRightHandFollowPositionError = Mathf.Max(
                maximumPropRightHandFollowPositionError,
                Vector3.Distance(
                    rightHand.TransformPoint(initialPropLocalPosition),
                    prop.position));
            maximumPropRightHandFollowRotationError = Mathf.Max(
                maximumPropRightHandFollowRotationError,
                Quaternion.Angle(
                    rightHand.rotation * initialPropLocalRotation,
                    prop.rotation));
            Vector3 bladeDirectionLocal = root.InverseTransformDirection(
                prop.TransformDirection(
                    LightsaberSetupTools.DiagonalSlashBladeAxisLocal())).normalized;
            float bladeDelta = Vector3.Angle(
                initialBladeDirectionLocal, bladeDirectionLocal);
            if (bladeDelta > maximumBladeDirectionDelta)
            {
                maximumBladeDirectionDelta = bladeDelta;
                Animator animator = root.GetComponent<Animator>();
                maximumBladeDirectionDeltaNormalized = animator == null
                    ? 0f
                    : NormalizedFraction(
                        animator.GetCurrentAnimatorStateInfo(0).normalizedTime);
            }
            Transform leftFoot = RequireRuntimeBone(root, LeftFootPath);
            Transform rightFoot = RequireRuntimeBone(root, RightFootPath);
            maximumLeftFootPositionDrift = Mathf.Max(
                maximumLeftFootPositionDrift,
                Vector3.Distance(initialLeftFootPosition, leftFoot.position));
            maximumRightFootPositionDrift = Mathf.Max(
                maximumRightFootPositionDrift,
                Vector3.Distance(initialRightFootPosition, rightFoot.position));
            maximumLeftFootVerticalDrift = Mathf.Max(
                maximumLeftFootVerticalDrift,
                Mathf.Abs(initialLeftFootPosition.y - leftFoot.position.y));
            maximumRightFootVerticalDrift = Mathf.Max(
                maximumRightFootVerticalDrift,
                Mathf.Abs(initialRightFootPosition.y - rightFoot.position.y));
            maximumLeftFootRotationDrift = Mathf.Max(
                maximumLeftFootRotationDrift,
                Quaternion.Angle(initialLeftFootRotation, leftFoot.rotation));
            maximumRightFootRotationDrift = Mathf.Max(
                maximumRightFootRotationDrift,
                Quaternion.Angle(initialRightFootRotation, rightFoot.rotation));
            if (lowerBodyReferencePose == null)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust lower-body reference pose is missing.");
            MeasurePoseDelta(
                lowerBodyReferencePose,
                FilterLowerBodyPose(CapturePose(root, prop)),
                out float lowerBodyPosition,
                out float lowerBodyRotation,
                out float lowerBodyScale);
            maximumLowerBodyPositionDelta = Mathf.Max(
                maximumLowerBodyPositionDelta, lowerBodyPosition);
            maximumLowerBodyRotationDelta = Mathf.Max(
                maximumLowerBodyRotationDelta, lowerBodyRotation);
            maximumLowerBodyScaleDelta = Mathf.Max(
                maximumLowerBodyScaleDelta, lowerBodyScale);
        }

        private static void AccumulateDestinationAndHoldMetrics(
            Transform root,
            Transform prop)
        {
            Transform rightArm = RequireRuntimeBone(root, RightArmPath);
            Transform rightForeArm = RequireRuntimeBone(root, RightForeArmPath);
            Transform rightHand = RequireRuntimeBone(root, RightHandPath);
            Transform leftArm = RequireRuntimeBone(root, LeftArmPath);
            Transform leftForeArm = RequireRuntimeBone(root, LeftForeArmPath);
            Transform leftHand = RequireRuntimeBone(root, LeftHandPath);
            Transform leftShoulder = RequireRuntimeBone(root, LeftShoulderPath);
            Transform rightShoulder = RequireRuntimeBone(root, RightShoulderPath);
            Transform spine = RequireRuntimeBone(root, SpinePath);
            Transform hips = RequireRuntimeBone(root, HipsPath);
            Transform leftFoot = RequireRuntimeBone(root, LeftFootPath);
            Transform rightFoot = RequireRuntimeBone(root, RightFootPath);
            Vector3 shoulderCenter =
                (leftShoulder.position + rightShoulder.position) * 0.5f;
            Vector3 torsoDirection =
                (shoulderCenter - spine.position).normalized;
            observedTorsoForwardLean = Vector3.SignedAngle(
                root.up, torsoDirection, root.right);
            maximumTorsoForwardLeanError = Mathf.Max(
                maximumTorsoForwardLeanError,
                Vector3.Angle(
                    torsoDirection,
                    LightsaberSetupTools.LightsaberThrustForwardTorsoDirection(
                        root)));
            maximumRightArmForwardAngle = Mathf.Max(
                maximumRightArmForwardAngle,
                LightsaberSetupTools.MeasureLightsaberThrustForwardAngle(
                    root, rightArm.position, rightHand.position));
            maximumLeftArmForwardAngle = Mathf.Max(
                maximumLeftArmForwardAngle,
                LightsaberSetupTools.MeasureLightsaberThrustForwardAngle(
                    root, leftArm.position, leftHand.position));
            maximumArmForwardAngleDifference = Mathf.Max(
                maximumArmForwardAngleDifference,
                Mathf.Abs(
                    LightsaberSetupTools.MeasureLightsaberThrustForwardAngle(
                        root, rightArm.position, rightHand.position) -
                    LightsaberSetupTools.MeasureLightsaberThrustForwardAngle(
                        root, leftArm.position, leftHand.position)));
            Vector3 bladeDirection = prop.TransformDirection(
                LightsaberSetupTools.DiagonalSlashBladeAxisLocal()).normalized;
            maximumGripOffsetError = Mathf.Max(
                maximumGripOffsetError,
                LightsaberSetupTools.MeasureLightsaberThrustGripAxisError(
                    rightHand, leftHand, bladeDirection));
            observedRightElbowBend = Vector3.Angle(
                rightForeArm.position - rightArm.position,
                rightHand.position - rightForeArm.position);
            observedLeftElbowBend = Vector3.Angle(
                leftForeArm.position - leftArm.position,
                leftHand.position - leftForeArm.position);
            maximumRightElbowBendDeviation = Mathf.Max(
                maximumRightElbowBendDeviation,
                Mathf.Abs(observedRightElbowBend -
                    LightsaberSetupTools.ThrustMotionElbowBendDegrees));
            maximumLeftElbowBendDeviation = Mathf.Max(
                maximumLeftElbowBendDeviation,
                Mathf.Abs(observedLeftElbowBend -
                    LightsaberSetupTools.ThrustMotionElbowBendDegrees));
            Vector3 chestCenter = Vector3.LerpUnclamped(
                hips.position,
                shoulderCenter,
                LightsaberSetupTools.ThrustMotionChestHeightFraction);
            maximumHandleChestHeightOffset = Mathf.Max(
                maximumHandleChestHeightOffset,
                Mathf.Abs(Vector3.Dot(
                    prop.position - chestCenter, root.up)));
            if (maximumRightElbowBendDeviation >
                    LightsaberSetupTools.ThrustMotionElbowToleranceDegrees ||
                maximumLeftElbowBendDeviation >
                    LightsaberSetupTools.ThrustMotionElbowToleranceDegrees)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust runtime elbows are not extended to five degrees. " +
                    "right=" + Num(observedRightElbowBend) +
                    "|left=" + Num(observedLeftElbowBend) + ".");
            if (maximumHandleChestHeightOffset >
                    LightsaberSetupTools.ThrustMotionChestHeightToleranceMeters)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust runtime handle is not centered at chest height. " +
                    "offset=" + Num(maximumHandleChestHeightOffset) + ".");
            RequireRuntimeBladeSegment(
                prop, bladeDirection, out Vector3 bladeStart, out Vector3 bladeEnd);
            Transform head = root.GetComponentsInChildren<Transform>(true)
                .Single(item => item.name == "Head");
            Vector3 middleTorso = Vector3.Lerp(
                hips.position, shoulderCenter, 0.58f);
            minimumBladeHeadClearance = Mathf.Min(
                minimumBladeHeadClearance,
                DistancePointToSegment(head.position, bladeStart, bladeEnd));
            minimumBladeTorsoClearance = Mathf.Min(
                minimumBladeTorsoClearance,
                Mathf.Min(
                    DistancePointToSegment(
                        shoulderCenter, bladeStart, bladeEnd),
                    DistancePointToSegment(
                        middleTorso, bladeStart, bladeEnd)));
            Dictionary<string, RuntimeLocalPose> current = CapturePose(root, prop);
            if (holdReferencePose == null)
            {
                holdReferencePose = current;
                return;
            }
            MeasurePoseDelta(
                holdReferencePose,
                current,
                out float position,
                out float rotation,
                out float scale);
            maximumHoldPositionDelta = Mathf.Max(
                maximumHoldPositionDelta, position);
            maximumHoldRotationDelta = Mathf.Max(
                maximumHoldRotationDelta, rotation);
            maximumHoldScaleDelta = Mathf.Max(maximumHoldScaleDelta, scale);
        }

        private static void AccumulateResetMetrics(
            Transform root,
            Transform prop)
        {
            if (startReferencePose == null)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust start reference pose is missing.");
            MeasurePoseDelta(
                startReferencePose,
                CapturePose(root, prop),
                out maximumResetPositionDelta,
                out maximumResetRotationDelta,
                out maximumResetScaleDelta);
        }

        private static Animator RequireRuntimeAnimator()
        {
            GameObject[] matches = Resources.FindObjectsOfTypeAll<GameObject>()
                .Where(item => item.scene.IsValid() && item.scene.isLoaded &&
                    item.name == LightsaberSetupTools.ThrustTargetName)
                .ToArray();
            if (matches.Length != 1)
                throw new InvalidOperationException(
                    "Expected exactly one runtime Lightsaber_Thrust; found " +
                    matches.Length + ".");
            Animator animator = matches[0].GetComponent<Animator>();
            if (animator == null || animator.runtimeAnimatorController == null ||
                AssetDatabase.GetAssetPath(animator.runtimeAnimatorController) !=
                    LightsaberSetupTools.ThrustMotionControllerPath ||
                !animator.enabled || animator.applyRootMotion)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust runtime Animator settings differ.");
            return animator;
        }

        private static Transform RequireRuntimeProp(Transform root)
        {
            Transform hand = RequireRuntimeBone(root, RightHandPath);
            Transform prop = hand.Find("Lightsaber_Prop") ??
                throw new InvalidOperationException(
                    "Lightsaber_Thrust runtime Lightsaber_Prop is missing.");
            if (prop.parent != hand)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust Lightsaber_Prop stopped following RightHand.");
            return prop;
        }

        private static Transform RequireRuntimeBone(Transform root, string path)
        {
            return root.Find(path) ?? throw new InvalidOperationException(
                "Lightsaber_Thrust runtime bone is missing: " + path);
        }

        private static float DistancePointToSegment(
            Vector3 point,
            Vector3 start,
            Vector3 end)
        {
            Vector3 segment = end - start;
            float denominator = segment.sqrMagnitude;
            if (denominator <= 0.000001f)
                return Vector3.Distance(point, start);
            float distance = Mathf.Clamp01(
                Vector3.Dot(point - start, segment) / denominator);
            return Vector3.Distance(point, start + segment * distance);
        }

        private static void RequireRuntimeBladeSegment(
            Transform prop,
            Vector3 bladeDirection,
            out Vector3 start,
            out Vector3 end)
        {
            Transform bladeRoot = prop.Find("Lightsaber_Blade") ??
                prop.GetComponentsInChildren<Transform>(true)
                    .SingleOrDefault(item => item.name == "Lightsaber_Blade") ??
                throw new InvalidOperationException(
                    "Runtime Lightsaber_Blade is missing during thrust review.");
            start = bladeRoot.position;
            end = start + bladeDirection * 0.9f;
        }

        private static Dictionary<string, RuntimeLocalPose> CapturePose(
            Transform root,
            Transform excludedRoot)
        {
            var result = new Dictionary<string, RuntimeLocalPose>(
                StringComparer.Ordinal);
            foreach (Transform current in root.GetComponentsInChildren<Transform>(true))
            {
                if (current == root || current == excludedRoot ||
                    current.IsChildOf(excludedRoot))
                    continue;
                result[AnimationUtility.CalculateTransformPath(current, root)] =
                    new RuntimeLocalPose(
                        current.localPosition,
                        current.localRotation,
                        current.localScale);
            }
            return result;
        }

        private static Dictionary<string, RuntimeLocalPose> FilterLowerBodyPose(
            IReadOnlyDictionary<string, RuntimeLocalPose> pose)
        {
            return pose
                .Where(item => IsLowerBodyPath(item.Key))
                .ToDictionary(
                    item => item.Key,
                    item => item.Value,
                    StringComparer.Ordinal);
        }

        private static bool IsLowerBodyPath(string path)
        {
            return path == HipsPath ||
                path == LeftUpLegPath ||
                path.StartsWith(LeftUpLegPath + "/", StringComparison.Ordinal) ||
                path == RightUpLegPath ||
                path.StartsWith(RightUpLegPath + "/", StringComparison.Ordinal);
        }

        private static void MeasurePoseDelta(
            IReadOnlyDictionary<string, RuntimeLocalPose> expected,
            IReadOnlyDictionary<string, RuntimeLocalPose> actual,
            out float maximumPositionDelta,
            out float maximumRotationDelta,
            out float maximumScaleDelta)
        {
            if (expected.Count != actual.Count ||
                expected.Keys.Any(path => !actual.ContainsKey(path)))
                throw new InvalidOperationException(
                    "Lightsaber_Thrust runtime pose path set differs.");
            maximumPositionDelta = 0f;
            maximumRotationDelta = 0f;
            maximumScaleDelta = 0f;
            foreach (KeyValuePair<string, RuntimeLocalPose> item in expected)
            {
                RuntimeLocalPose value = actual[item.Key];
                maximumPositionDelta = Mathf.Max(
                    maximumPositionDelta,
                    Vector3.Distance(item.Value.Position, value.Position));
                maximumRotationDelta = Mathf.Max(
                    maximumRotationDelta,
                    Quaternion.Angle(item.Value.Rotation, value.Rotation));
                maximumScaleDelta = Mathf.Max(
                    maximumScaleDelta,
                    Vector3.Distance(item.Value.Scale, value.Scale));
            }
        }

        private static Texture2D CaptureRuntimePanel(Transform target)
        {
            Renderer[] renderers = target.GetComponentsInChildren<Renderer>(true)
                .Where(item => item.enabled && item.gameObject.activeInHierarchy)
                .ToArray();
            if (renderers.Length == 0)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust has no visible runtime renderers.");
            GameObject cameraObject = new GameObject(
                "LightsaberThrustMotionReviewCamera")
            {
                hideFlags = HideFlags.HideAndDontSave
            };
            GameObject lightObject = new GameObject(
                "LightsaberThrustMotionReviewLight")
            {
                hideFlags = HideFlags.HideAndDontSave
            };
            Camera camera = cameraObject.AddComponent<Camera>();
            Light light = lightObject.AddComponent<Light>();
            Transform[] targetNodes = target.GetComponentsInChildren<Transform>(true);
            int[] originalLayers = targetNodes
                .Select(item => item.gameObject.layer).ToArray();
            var occupiedOutsideLayers = new HashSet<int>(
                Resources.FindObjectsOfTypeAll<Renderer>()
                    .Where(item => item != null && item.transform != target &&
                        !item.transform.IsChildOf(target) &&
                        item.gameObject.scene.IsValid() &&
                        item.gameObject.scene.isLoaded)
                    .Select(item => item.gameObject.layer));
            int reviewLayer = Enumerable.Range(0, 32)
                .Reverse()
                .First(layer => !occupiedOutsideLayers.Contains(layer));
            foreach (Transform node in targetNodes)
                node.gameObject.layer = reviewLayer;
            camera.enabled = false;
            camera.cullingMask = 1 << reviewLayer;
            camera.clearFlags = CameraClearFlags.SolidColor;
            camera.backgroundColor = new Color(0.015f, 0.02f, 0.03f, 1f);
            camera.orthographic = true;
            camera.aspect = PanelWidth / (float)PanelHeight;
            camera.orthographicSize = 1.15f;
            Vector3 viewDirection =
                (target.right -
                    target.forward * 0.35f +
                    target.up * 0.35f).normalized;
            const float cameraDistance = 4f;
            Vector3 stableCenter = target.position +
                target.up * 0.98f + target.forward * 0.28f;
            camera.nearClipPlane = 0.01f;
            camera.farClipPlane = 10f;
            camera.transform.SetPositionAndRotation(
                stableCenter + viewDirection * cameraDistance,
                Quaternion.LookRotation(-viewDirection, target.up));
            light.type = LightType.Directional;
            light.intensity = 1.2f;
            light.transform.rotation = Quaternion.LookRotation(
                -viewDirection - target.up * 0.25f, target.up);
            RenderTexture render = RenderTexture.GetTemporary(
                PanelWidth, PanelHeight, 24, RenderTextureFormat.ARGB32);
            RenderTexture previousActive = RenderTexture.active;
            try
            {
                camera.targetTexture = render;
                camera.Render();
                RenderTexture.active = render;
                var panel = new Texture2D(
                    PanelWidth, PanelHeight, TextureFormat.RGB24, false);
                panel.ReadPixels(
                    new Rect(0f, 0f, PanelWidth, PanelHeight), 0, 0, false);
                panel.Apply(false, false);
                return panel;
            }
            finally
            {
                camera.targetTexture = null;
                RenderTexture.active = previousActive;
                RenderTexture.ReleaseTemporary(render);
                for (int index = 0; index < targetNodes.Length; index++)
                    if (targetNodes[index] != null)
                        targetNodes[index].gameObject.layer = originalLayers[index];
                UnityEngine.Object.DestroyImmediate(cameraObject);
                UnityEngine.Object.DestroyImmediate(lightObject);
            }
        }

        private static void ComposeReview()
        {
            if (Panels.Count != ExpectedNormalizedTimes.Length)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust review panel count differs.");
            const int columns = 4;
            const int rows = 2;
            var composite = new Texture2D(
                PanelWidth * columns,
                PanelHeight * rows,
                TextureFormat.RGB24,
                false);
            try
            {
                Color background = new Color(0.015f, 0.02f, 0.03f, 1f);
                composite.SetPixels(Enumerable.Repeat(
                    background, composite.width * composite.height).ToArray());
                for (int index = 0; index < Panels.Count; index++)
                {
                    int x = (index % columns) * PanelWidth;
                    int y = (rows - 1 - index / columns) * PanelHeight;
                    composite.SetPixels(
                        x, y, PanelWidth, PanelHeight, Panels[index].GetPixels());
                }
                composite.Apply(false, false);
                string path = Absolute(
                    LightsaberSetupTools.ThrustMotionReviewRelativePath);
                Directory.CreateDirectory(Path.GetDirectoryName(path) ??
                    throw new InvalidOperationException(
                        "Lightsaber_Thrust review directory is unavailable."));
                File.WriteAllBytes(path, composite.EncodeToPNG());
            }
            finally
            {
                UnityEngine.Object.DestroyImmediate(composite);
            }
        }

        private static void WriteReport(
            bool passed,
            bool exactStart,
            bool torsoForwardLean,
            bool armsForward,
            bool elbowsExtended,
            bool handleAtChestHeight,
            bool lowerBodyUnchanged,
            bool feetPlanted,
            bool bladeStable,
            bool holdStable,
            bool propStable)
        {
            var report = new StringBuilder()
                .AppendLine("Lightsaber_Thrust natural Play Mode motion review")
                .AppendLine("naturalPlayback=True")
                .AppendLine("verificationTargetTransformManipulated=False")
                .AppendLine("animatorPlayCalled=False")
                .AppendLine("animatorRebindCalled=False")
                .AppendLine("exactStartPoseConfirmed=" + exactStart)
                .AppendLine("transitionSeconds=0.9")
                .AppendLine("torsoForwardLeanFifteenDegreesConfirmed=" +
                    torsoForwardLean)
                .AppendLine("bothArmsForwardConfirmed=" + armsForward)
                .AppendLine("bothElbowsFiveDegreesConfirmed=" + elbowsExtended)
                .AppendLine("handleCenteredAtChestHeightConfirmed=" +
                    handleAtChestHeight)
                .AppendLine("lowerBodyUnchangedConfirmed=" + lowerBodyUnchanged)
                .AppendLine("bothFeetPlantedConfirmed=" + feetPlanted)
                .AppendLine("bladeDirectionWithinTwoDegreesConfirmed=" + bladeStable)
                .AppendLine("bladeHeadTorsoClearanceDirectVisualRequired=True")
                .AppendLine("holdPoseConfirmed=" + holdStable)
                .AppendLine("holdSeconds=0.5")
                .AppendLine("immediateRepeatConfirmed=" + exactStart)
                .AppendLine("rightHandFollowPreserved=" + propStable)
                .AppendLine("maximumRootPositionDriftMeters=" +
                    Num(maximumRootPositionDrift))
                .AppendLine("maximumRootRotationDriftDegrees=" +
                    Num(maximumRootRotationDrift))
                .AppendLine("maximumPropLocalPositionDriftMeters=" +
                    Num(maximumPropPositionDrift))
                .AppendLine("maximumPropLocalRotationDriftDegrees=" +
                    Num(maximumPropRotationDrift))
                .AppendLine("maximumPropLocalScaleDrift=" +
                    Num(maximumPropScaleDrift))
                .AppendLine("maximumPropRightHandFollowPositionErrorMeters=" +
                    Num(maximumPropRightHandFollowPositionError))
                .AppendLine("maximumPropRightHandFollowRotationErrorDegrees=" +
                    Num(maximumPropRightHandFollowRotationError))
                .AppendLine("maximumBladeDirectionDeltaDegrees=" +
                    Num(maximumBladeDirectionDelta))
                .AppendLine("maximumBladeDirectionDeltaNormalized=" +
                    Num(maximumBladeDirectionDeltaNormalized))
                .AppendLine("maximumLowerBodyPositionDeltaMeters=" +
                    Num(maximumLowerBodyPositionDelta))
                .AppendLine("maximumLowerBodyRotationDeltaDegrees=" +
                    Num(maximumLowerBodyRotationDelta))
                .AppendLine("maximumLowerBodyScaleDelta=" +
                    Num(maximumLowerBodyScaleDelta))
                .AppendLine("observedTorsoForwardLeanDegrees=" +
                    Num(observedTorsoForwardLean))
                .AppendLine("maximumTorsoForwardLeanErrorDegrees=" +
                    Num(maximumTorsoForwardLeanError))
                .AppendLine("maximumRightArmForwardAngleDegrees=" +
                    Num(maximumRightArmForwardAngle))
                .AppendLine("maximumLeftArmForwardAngleDegrees=" +
                    Num(maximumLeftArmForwardAngle))
                .AppendLine("maximumArmForwardAngleDifferenceDegrees=" +
                    Num(maximumArmForwardAngleDifference))
                .AppendLine("maximumGripOffsetErrorMeters=" +
                    Num(maximumGripOffsetError))
                .AppendLine("observedRightElbowBendDegrees=" +
                    Num(observedRightElbowBend))
                .AppendLine("observedLeftElbowBendDegrees=" +
                    Num(observedLeftElbowBend))
                .AppendLine("maximumRightElbowBendDeviationDegrees=" +
                    Num(maximumRightElbowBendDeviation))
                .AppendLine("maximumLeftElbowBendDeviationDegrees=" +
                    Num(maximumLeftElbowBendDeviation))
                .AppendLine("maximumHandleChestHeightOffsetMeters=" +
                    Num(maximumHandleChestHeightOffset))
                .AppendLine("runtimeBladeHeadClearanceProxyMeters=" +
                    Num(minimumBladeHeadClearance))
                .AppendLine("runtimeBladeTorsoClearanceProxyMeters=" +
                    Num(minimumBladeTorsoClearance))
                .AppendLine("maximumLeftFootPositionDriftMeters=" +
                    Num(maximumLeftFootPositionDrift))
                .AppendLine("maximumRightFootPositionDriftMeters=" +
                    Num(maximumRightFootPositionDrift))
                .AppendLine("maximumLeftFootVerticalDriftMeters=" +
                    Num(maximumLeftFootVerticalDrift))
                .AppendLine("maximumRightFootVerticalDriftMeters=" +
                    Num(maximumRightFootVerticalDrift))
                .AppendLine("maximumLeftFootRotationDriftDegrees=" +
                    Num(maximumLeftFootRotationDrift))
                .AppendLine("maximumRightFootRotationDriftDegrees=" +
                    Num(maximumRightFootRotationDrift))
                .AppendLine("maximumHoldPositionDelta=" +
                    Num(maximumHoldPositionDelta))
                .AppendLine("maximumHoldRotationDelta=" +
                    Num(maximumHoldRotationDelta))
                .AppendLine("maximumHoldScaleDelta=" +
                    Num(maximumHoldScaleDelta))
                .AppendLine("maximumResetPositionDelta=" +
                    Num(maximumResetPositionDelta))
                .AppendLine("maximumResetRotationDelta=" +
                    Num(maximumResetRotationDelta))
                .AppendLine("maximumResetScaleDelta=" +
                    Num(maximumResetScaleDelta))
                .AppendLine("capturedPanelCount=" + Panels.Count)
                .AppendLine("passedNumericChecks=" + passed);
            foreach (string observation in Observations)
                report.AppendLine(observation);
            string path = Absolute(
                LightsaberSetupTools.ThrustMotionReportRelativePath);
            Directory.CreateDirectory(Path.GetDirectoryName(path) ??
                throw new InvalidOperationException(
                    "Lightsaber_Thrust report directory is unavailable."));
            File.WriteAllText(path, report.ToString(), new UTF8Encoding(false));
        }

        private static void FinishSuccess()
        {
            int errorsBefore = SessionState.GetInt(ConsoleErrorsBeforeKey, 0);
            RestoreSavedSceneAfterPlayModeCapture();
            LightsaberSetupTools.InspectLightsaberThrustMotion();
            LightsaberSetupTools.RequireNoNewUnityConsoleErrors(errorsBefore);
            Action<string> callback = complete;
            CleanupSession();
            callback?.Invoke(
                "Lightsaber_Thrust natural 1.4-second cycle inspected in Play Mode; " +
                "eight-panel direct review captured and Edit Mode restored.");
        }

        private static void FinishFailure()
        {
            string error = SessionState.GetString(
                FailureKey,
                "Lightsaber_Thrust Play Mode motion inspection failed.");
            Action<Exception> callback = fail;
            RestoreSavedSceneAfterPlayModeCapture();
            CleanupSession();
            callback?.Invoke(new InvalidOperationException(error));
        }

        private static void RequireWithinWaitLimit()
        {
            float started = SessionState.GetFloat(WaitStartKey, 0f);
            if (Time.realtimeSinceStartupAsDouble - started > 20d)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust did not reach its natural cycle start " +
                    "within twenty seconds.");
        }

        private static void RestoreSavedSceneAfterPlayModeCapture()
        {
            const string scenePath = "Assets/_Project/Scenes/CargoRunMvp.unity";
            Scene active = SceneManager.GetActiveScene();
            if (active.path != scenePath || active.isDirty)
                EditorSceneManager.OpenScene(scenePath, OpenSceneMode.Single);
        }

        private static float NormalizedFraction(float normalizedTime)
        {
            return normalizedTime - Mathf.Floor(normalizedTime);
        }

        private static void CleanupPanels()
        {
            foreach (Texture2D panel in Panels)
                if (panel != null) UnityEngine.Object.DestroyImmediate(panel);
            Panels.Clear();
        }

        private static void CleanupSession()
        {
            CleanupPanels();
            Observations.Clear();
            startReferencePose = null;
            holdReferencePose = null;
            lowerBodyReferencePose = null;
            complete = null;
            fail = null;
            SessionState.EraseInt(StateKey);
            SessionState.EraseInt(IndexKey);
            SessionState.EraseFloat(WaitStartKey);
            SessionState.EraseInt(ConsoleErrorsBeforeKey);
            SessionState.EraseString(FailureKey);
        }

        private static void TryDelete(string path)
        {
            if (File.Exists(path)) File.Delete(path);
        }

        private static string Absolute(string relativePath)
        {
            return Path.GetFullPath(Path.Combine(
                Path.GetDirectoryName(Application.dataPath) ?? string.Empty,
                relativePath));
        }

        private static string Num(float value)
        {
            return value.ToString("R", CultureInfo.InvariantCulture);
        }

        private readonly struct RuntimeLocalPose
        {
            internal RuntimeLocalPose(
                Vector3 position,
                Quaternion rotation,
                Vector3 scale)
            {
                Position = position;
                Rotation = rotation;
                Scale = scale;
            }

            internal Vector3 Position { get; }
            internal Quaternion Rotation { get; }
            internal Vector3 Scale { get; }
        }
    }

    [InitializeOnLoad]
    internal static class LightsaberThrustStabbingPlayModeCapture
    {
        private const string StateKey =
            "Bellerophon.LightsaberThrustStabbingCapture.State";
        private const string IndexKey =
            "Bellerophon.LightsaberThrustStabbingCapture.Index";
        private const string WaitStartKey =
            "Bellerophon.LightsaberThrustStabbingCapture.WaitStart";
        private const string ConsoleErrorsBeforeKey =
            "Bellerophon.LightsaberThrustStabbingCapture.ConsoleErrorsBefore";
        private const string FailureKey =
            "Bellerophon.LightsaberThrustStabbingCapture.Failure";
        private const string ArmPopModeKey =
            "Bellerophon.LightsaberThrustStabbingCapture.ArmPopMode";
        private const string ForearmModeKey =
            "Bellerophon.LightsaberThrustStabbingCapture.ForearmMode";
        private const string DistalForearmModeKey =
            "Bellerophon.LightsaberThrustStabbingCapture.DistalForearmMode";
        private const string WristPanelModeKey =
            "Bellerophon.LightsaberThrustStabbingCapture.WristPanelMode";
        private const string TopGripModeKey =
            "Bellerophon.LightsaberThrustStabbingCapture.TopGripMode";
        private const int WaitingForPlayMode = 1;
        private const int WaitingForSequenceStart = 2;
        private const int Capturing = 3;
        private const int WaitingForEditMode = 4;
        private const int FailedWaitingForEditMode = 5;
        private const int PanelWidth = 480;
        private const int PanelHeight = 540;
        private const string RightHandPath =
            "Armature/Hips/Spine02/Spine01/Spine/RightShoulder/RightArm/" +
            "RightForeArm/RightHand";
        private const string SpinePath =
            "Armature/Hips/Spine02/Spine01/Spine";

        private static readonly List<Texture2D> Panels = new List<Texture2D>();
        private static readonly List<string> Observations = new List<string>();
        private static Action<string> complete;
        private static Action<Exception> fail;
        private static Vector3 initialPropLocalPosition;
        private static Quaternion initialPropLocalRotation;
        private static Vector3 initialPropLocalScale;
        private static Vector3 initialRightHandPosition;
        private static Quaternion initialSpineRotation;
        private static Dictionary<string, RuntimePose> holdReferencePose;
        private static float maximumPropFollowPositionError;
        private static float maximumPropFollowRotationError;
        private static float maximumRightHandTravel;
        private static float maximumSpineMotion;
        private static float maximumHandBackRightAngle;
        private static float maximumBladeForwardAngle;
        private static float maximumWristBend;
        private static float maximumSourcePlaybackSpeedError;
        private static bool sourcePlaybackSpeedObserved;
