        private static Quaternion[] previousRightArmRotations;
        private static int previousStateHash;
        private static float maximumArmPopFrameStep;
        private static float maximumArmPopRawFrameStep;
        private static float loopBoundaryFrameStep;
        private static bool loopBoundaryObserved;
        private static int loopBoundaryCount;
        private static int continuousArmPopSampleCount;
        private static int continuousBridgeSampleCount;
        private static int previousArmPopGameFrame;
        private static double previousArmPopSampleTime;
        private static float minimumRuntimeForearmDiameter;
        private static float maximumRuntimeWristPanelRightAngle;
        private static int runtimeWristPanelRelevantFrameCount;
        private static Vector3 wristPanelNormalLocal;
        private static float maximumRuntimeTopGripHandBackUpAngle;
        private static float maximumRuntimeTopGripHandleAxisError;
        private static float maximumRuntimeTopGripPalmCenterError;
        private static float maximumRuntimeTopGripFingerPoseError;
        private static float maximumRuntimeTopGripFingerContactError;
        private static float maximumRuntimeTopGripWristBend;
        private static int runtimeTopGripFrameCount;

        static LightsaberThrustStabbingPlayModeCapture()
        {
            EditorApplication.update -= Tick;
            EditorApplication.update += Tick;
        }

        internal static bool HasPendingCapture =>
            SessionState.GetInt(StateKey, 0) != 0;

        internal static void Start(
            Action<string> completeCallback,
            Action<Exception> failCallback)
        {
            StartCore(completeCallback, failCallback, false);
        }

        internal static void StartArmPop(
            Action<string> completeCallback,
            Action<Exception> failCallback)
        {
            StartCore(completeCallback, failCallback, true);
        }

        internal static void StartForearmDeformation(
            Action<string> completeCallback,
            Action<Exception> failCallback)
        {
            StartCore(completeCallback, failCallback, true, true);
        }

        internal static void StartDistalForearmSkinning(
            Action<string> completeCallback,
            Action<Exception> failCallback)
        {
            StartCore(completeCallback, failCallback, true, true, true);
        }

        internal static void StartWristPanelOrientation(
            Action<string> completeCallback,
            Action<Exception> failCallback)
        {
            StartCore(
                completeCallback, failCallback, true, false, false, true);
        }

        internal static void StartTopGrip(
            Action<string> completeCallback,
            Action<Exception> failCallback)
        {
            StartCore(
                completeCallback,
                failCallback,
                true,
                false,
                false,
                false,
                true);
        }

        private static void StartCore(
            Action<string> completeCallback,
            Action<Exception> failCallback,
            bool armPopMode,
            bool forearmMode = false,
            bool distalForearmMode = false,
            bool wristPanelMode = false,
            bool topGripMode = false)
        {
            complete = completeCallback;
            fail = failCallback;
            bool alreadyPlaying = EditorApplication.isPlaying;
            if (EditorApplication.isPlayingOrWillChangePlaymode && !alreadyPlaying)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust stabbing inspection cannot start while " +
                    "Play Mode changes.");
            if (!alreadyPlaying)
            {
                if (wristPanelMode)
                    LightsaberSetupTools
                        .InspectLightsaberThrustWristPanelOrientationCorrection();
                else if (topGripMode)
                    LightsaberSetupTools
                        .InspectLightsaberThrustTopGripPose();
                else if (distalForearmMode)
                    LightsaberSetupTools
                        .InspectLightsaberThrustDistalForearmSkinning();
                else if (forearmMode)
                    LightsaberSetupTools
                        .InspectLightsaberThrustForearmDeformationCorrection();
                else if (armPopMode)
                    LightsaberSetupTools
                        .InspectLightsaberThrustArmPopCorrection();
                else
                    LightsaberSetupTools.InspectLightsaberThrustStabbingSequence();
            }
            SessionState.SetBool(ArmPopModeKey, armPopMode);
            SessionState.SetBool(ForearmModeKey, forearmMode);
            SessionState.SetBool(DistalForearmModeKey, distalForearmMode);
            SessionState.SetBool(WristPanelModeKey, wristPanelMode);
            SessionState.SetBool(TopGripModeKey, topGripMode);
            CleanupPanels();
            Observations.Clear();
            holdReferencePose = null;
            maximumPropFollowPositionError = 0f;
            maximumPropFollowRotationError = 0f;
            maximumRightHandTravel = 0f;
            maximumSpineMotion = 0f;
            maximumHandBackRightAngle = 0f;
            maximumBladeForwardAngle = 0f;
            maximumWristBend = 0f;
            maximumSourcePlaybackSpeedError = 0f;
            sourcePlaybackSpeedObserved = false;
            holdObserved = false;
            immediateReturnObserved = false;
            previousRightArmRotations = null;
            previousStateHash = 0;
            maximumArmPopFrameStep = 0f;
            maximumArmPopRawFrameStep = 0f;
            loopBoundaryFrameStep = 0f;
            loopBoundaryObserved = false;
            loopBoundaryCount = 0;
            continuousArmPopSampleCount = 0;
            continuousBridgeSampleCount = 0;
            previousArmPopGameFrame = -1;
            previousArmPopSampleTime = 0d;
            minimumRuntimeForearmDiameter = float.PositiveInfinity;
            maximumRuntimeWristPanelRightAngle = 0f;
            runtimeWristPanelRelevantFrameCount = 0;
            wristPanelNormalLocal = Vector3.zero;
            maximumRuntimeTopGripHandBackUpAngle = 0f;
            maximumRuntimeTopGripHandleAxisError = 0f;
            maximumRuntimeTopGripPalmCenterError = 0f;
            maximumRuntimeTopGripFingerPoseError = 0f;
            maximumRuntimeTopGripFingerContactError = 0f;
            maximumRuntimeTopGripWristBend = 0f;
            runtimeTopGripFrameCount = 0;
            TryDelete(Absolute(ActiveReviewRelativePath()));
            TryDelete(Absolute(ActiveReportRelativePath()));
            SessionState.SetInt(
                ConsoleErrorsBeforeKey,
                LightsaberSetupTools.ConsoleErrorCount());
            SessionState.SetInt(IndexKey, 0);
            SessionState.SetFloat(
                WaitStartKey, (float)Time.realtimeSinceStartupAsDouble);
            SessionState.SetString(FailureKey, string.Empty);
            SessionState.SetInt(
                StateKey,
                alreadyPlaying ? WaitingForSequenceStart : WaitingForPlayMode);
            if (!alreadyPlaying) EditorApplication.EnterPlaymode();
        }

        internal static void Resume(
            Action<string> completeCallback,
            Action<Exception> failCallback)
        {
            ResumeCore(completeCallback, failCallback, false);
        }

        internal static void ResumeArmPop(
            Action<string> completeCallback,
            Action<Exception> failCallback)
        {
            ResumeCore(completeCallback, failCallback, true);
        }

        internal static void ResumeForearmDeformation(
            Action<string> completeCallback,
            Action<Exception> failCallback)
        {
            ResumeCore(completeCallback, failCallback, true, true);
        }

        internal static void ResumeDistalForearmSkinning(
            Action<string> completeCallback,
            Action<Exception> failCallback)
        {
            ResumeCore(completeCallback, failCallback, true, true, true);
        }

        internal static void ResumeWristPanelOrientation(
            Action<string> completeCallback,
            Action<Exception> failCallback)
        {
            ResumeCore(
                completeCallback, failCallback, true, false, false, true);
        }

        internal static void ResumeTopGrip(
            Action<string> completeCallback,
            Action<Exception> failCallback)
        {
            ResumeCore(
                completeCallback,
                failCallback,
                true,
                false,
                false,
                false,
                true);
        }

        private static void ResumeCore(
            Action<string> completeCallback,
            Action<Exception> failCallback,
            bool armPopMode,
            bool forearmMode = false,
            bool distalForearmMode = false,
            bool wristPanelMode = false,
            bool topGripMode = false)
        {
            int state = SessionState.GetInt(StateKey, 0);
            if ((state == WaitingForPlayMode ||
                 state == WaitingForSequenceStart || state == Capturing) &&
                !EditorApplication.isPlayingOrWillChangePlaymode)
            {
                CleanupSession();
                StartCore(
                    completeCallback,
                    failCallback,
                    armPopMode,
                    forearmMode,
                    distalForearmMode,
                    wristPanelMode,
                    topGripMode);
                return;
            }
            SessionState.SetBool(ArmPopModeKey, armPopMode);
            SessionState.SetBool(ForearmModeKey, forearmMode);
            SessionState.SetBool(DistalForearmModeKey, distalForearmMode);
            SessionState.SetBool(WristPanelModeKey, wristPanelMode);
            SessionState.SetBool(TopGripModeKey, topGripMode);
            complete = completeCallback;
            fail = failCallback;
            Tick();
        }

        private static void Tick()
        {
            if (complete == null && fail == null) return;
            int state = SessionState.GetInt(StateKey, 0);
            try
            {
                if (state == WaitingForPlayMode)
                {
                    if (!EditorApplication.isPlaying) return;
                    SessionState.SetInt(StateKey, WaitingForSequenceStart);
                    SessionState.SetFloat(
                        WaitStartKey, (float)Time.realtimeSinceStartupAsDouble);
                    return;
                }
                if (state == WaitingForSequenceStart)
                {
                    if (!EditorApplication.isPlaying)
                        throw new InvalidOperationException(
                            "Unity left Play Mode before the stabbing sequence began.");
                    WaitForSequenceStart();
                    return;
                }
                if (state == Capturing)
                {
                    if (!EditorApplication.isPlaying)
                        throw new InvalidOperationException(
                            "Unity left Play Mode before the stabbing loop completed.");
                    CaptureWhenDue();
                    return;
                }
                if (state == WaitingForEditMode)
                {
                    if (EditorApplication.isPlayingOrWillChangePlaymode) return;
                    FinishSuccess();
                    return;
                }
                if (state == FailedWaitingForEditMode &&
                    !EditorApplication.isPlayingOrWillChangePlaymode)
                    FinishFailure();
            }
            catch (Exception exception)
            {
                SessionState.SetString(FailureKey, exception.ToString());
                SessionState.SetInt(StateKey, FailedWaitingForEditMode);
                CleanupPanels();
                if (EditorApplication.isPlaying) EditorApplication.ExitPlaymode();
                else if (!EditorApplication.isPlayingOrWillChangePlaymode)
                    FinishFailure();
            }
        }

        private static void WaitForSequenceStart()
        {
            Animator animator = RequireRuntimeAnimator();
            string[] expectedStates = BuildExpectedStates();
            AnimatorStateInfo info = animator.GetCurrentAnimatorStateInfo(0);
            float normalized = NormalizedFraction(info.normalizedTime);
            if (info.shortNameHash != Animator.StringToHash(expectedStates[0]) ||
                normalized > 0.20f || animator.IsInTransition(0))
            {
                RequireWithinWaitLimit();
                return;
            }
            Transform root = animator.transform;
            foreach (SkinnedMeshRenderer renderer in
                root.GetComponentsInChildren<SkinnedMeshRenderer>(true))
                renderer.updateWhenOffscreen = true;
            Transform rightHand = RequireBone(root, RightHandPath);
            Transform prop = RequireRuntimeProp(root);
            initialPropLocalPosition = prop.localPosition;
            initialPropLocalRotation = prop.localRotation;
            initialPropLocalScale = prop.localScale;
            initialRightHandPosition = rightHand.position;
            initialSpineRotation = RequireBone(root, SpinePath).localRotation;
            SessionState.SetInt(IndexKey, 0);
            SessionState.SetInt(StateKey, Capturing);
            CaptureWhenDue();
        }

        private static void CaptureWhenDue()
        {
            Animator animator = RequireRuntimeAnimator();
            Transform root = animator.transform;
            Transform prop = RequireRuntimeProp(root);
            AccumulateMotion(root, prop);
            if (SessionState.GetBool(ArmPopModeKey, false))
            {
                if (SessionState.GetBool(ForearmModeKey, false) ||
                    SessionState.GetBool(WristPanelModeKey, false) ||
                    SessionState.GetBool(TopGripModeKey, false))
                    CaptureForearmDeformationFrameWhenDue(
                        animator, root);
                CaptureContinuousArmPopWhenComplete(animator, root, prop);
                return;
            }
            string[] expectedStates = BuildExpectedStates();
            float[] expectedTimes = BuildExpectedNormalizedTimes();
            int index = SessionState.GetInt(IndexKey, 0);
            if (index < 0 || index >= expectedStates.Length)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust stabbing capture index is invalid: " + index);
            if (animator.IsInTransition(0)) return;
            AnimatorStateInfo info = animator.GetCurrentAnimatorStateInfo(0);
            if (info.shortNameHash != Animator.StringToHash(expectedStates[index]))
            {
                RequireWithinCaptureLimit();
                return;
            }
            float normalized = NormalizedFraction(info.normalizedTime);
            if (normalized < expectedTimes[index]) return;

            if (info.shortNameHash == Animator.StringToHash(
                    LightsaberSetupTools.ThrustStabbingSourceStateName))
            {
                sourcePlaybackSpeedObserved = true;
                maximumSourcePlaybackSpeedError = Mathf.Max(
                    maximumSourcePlaybackSpeedError,
                    Mathf.Abs(
                        info.speed -
                        LightsaberSetupTools.ThrustStabbingPlaybackSpeed));
            }

            if (expectedStates[index] ==
                LightsaberSetupTools.ThrustStabbingHoldStateName)
            {
                Dictionary<string, RuntimePose> current = CapturePose(root, prop);
                if (holdReferencePose == null)
                    holdReferencePose = current;
                else
                    RequirePoseNear(
                        holdReferencePose, current,
                        0.0001f, 0.02f, 0.0001f,
                        "stabbing final hold");
                holdObserved = true;
            }
            if (index == expectedStates.Length - 1)
                immediateReturnObserved = true;
            Panels.Add(CaptureRuntimePanel(root));
            Observations.Add(
                "panel=" + index +
                "|state=" + expectedStates[index] +
                "|normalized=" + Num(normalized) +
                "|elapsed=" + Num((float)Time.timeAsDouble));
            index++;
            SessionState.SetInt(IndexKey, index);
            if (index < expectedStates.Length) return;

            bool rightHandFollow =
                maximumPropFollowPositionError <= 0.0001f &&
                maximumPropFollowRotationError <= 0.02f;
            bool sourceMotionObserved =
                maximumRightHandTravel > 0.02f || maximumSpineMotion > 0.2f;
            bool rightHandBackFacesCarrierRight =
                maximumHandBackRightAngle <=
                    LightsaberSetupTools.ThrustStabbingHandBackToleranceDegrees;
            bool bladeCenterAxisAndTipFaceForward =
                maximumBladeForwardAngle <=
                    LightsaberSetupTools.ThrustStabbingBladeForwardToleranceDegrees;
            bool wristBendWithinTolerance =
                maximumWristBend <=
                    LightsaberSetupTools.ThrustStabbingWristBendToleranceDegrees;
            bool armPopMode = SessionState.GetBool(ArmPopModeKey, false);
            bool armPopAbsent = loopBoundaryObserved &&
                maximumArmPopFrameStep <=
                    LightsaberSetupTools.ThrustArmPopFrameStepToleranceDegrees &&
                loopBoundaryFrameStep <=
                    LightsaberSetupTools.ThrustArmPopFrameStepToleranceDegrees;
            bool sourcePlaybackSpeedConfirmed =
                sourcePlaybackSpeedObserved &&
                maximumSourcePlaybackSpeedError <= 0.0001f;
            bool passed = Panels.Count == expectedStates.Length &&
                holdObserved && immediateReturnObserved && rightHandFollow &&
                sourceMotionObserved && sourcePlaybackSpeedConfirmed && (armPopMode
                    ? armPopAbsent
                    : rightHandBackFacesCarrierRight &&
                      bladeCenterAxisAndTipFaceForward &&
                      wristBendWithinTolerance);
            ComposeReview();
            WriteReport(passed, rightHandFollow, sourceMotionObserved);
            if (!passed)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust stabbing natural review failed." +
                    " panels=" + Panels.Count + "/" + expectedStates.Length +
                    "|hold=" + holdObserved +
                    "|immediateReturn=" + immediateReturnObserved +
                    "|rightHandFollow=" + rightHandFollow +
                    "|sourceMotion=" + sourceMotionObserved +
                    "|sourcePlaybackSpeedConfirmed=" +
                        sourcePlaybackSpeedConfirmed +
                    "|maximumSourcePlaybackSpeedError=" +
                        Num(maximumSourcePlaybackSpeedError) +
                    "|armPopMode=" + armPopMode +
                    "|armPopAbsent=" + armPopAbsent +
                    "|maximumArmPopFrameStep=" +
                        Num(maximumArmPopFrameStep) +
                    "|loopBoundaryFrameStep=" +
                        Num(loopBoundaryFrameStep) +
                    "|handBack=" + Num(maximumHandBackRightAngle) +
                    "|blade=" + Num(maximumBladeForwardAngle) +
                    "|wrist=" + Num(maximumWristBend) + ".");
            SessionState.SetInt(StateKey, WaitingForEditMode);
            EditorApplication.ExitPlaymode();
        }

        private static void CaptureContinuousArmPopWhenComplete(
            Animator animator,
            Transform root,
            Transform prop)
        {
            RequireWithinCaptureLimit();
            if (animator.IsInTransition(0) || loopBoundaryCount < 2)
                return;
            AnimatorStateInfo state = animator.GetCurrentAnimatorStateInfo(0);
            int bridgeHash = Animator.StringToHash(
                LightsaberSetupTools.ThrustStabbingBridgeStateName);
            float normalized = NormalizedFraction(state.normalizedTime);
            if (state.shortNameHash != bridgeHash || normalized < 0.85f)
                return;

            bool rightHandFollow =
                maximumPropFollowPositionError <= 0.0001f &&
                maximumPropFollowRotationError <= 0.02f;
            bool sourceMotionObserved =
                maximumRightHandTravel > 0.02f || maximumSpineMotion > 0.2f;
            bool armPopAbsent = loopBoundaryObserved &&
                loopBoundaryCount >= 2 &&
                continuousArmPopSampleCount >= 45 &&
                continuousBridgeSampleCount >= 6 &&
                maximumArmPopFrameStep <=
                    LightsaberSetupTools.ThrustArmPopFrameStepToleranceDegrees &&
                loopBoundaryFrameStep <=
                    LightsaberSetupTools.ThrustArmPopFrameStepToleranceDegrees;
            bool forearmMode = SessionState.GetBool(ForearmModeKey, false);
            bool wristPanelMode = SessionState.GetBool(
                WristPanelModeKey, false);
            bool topGripMode = SessionState.GetBool(
                TopGripModeKey, false);
            bool forearmDeformationAbsent = !forearmMode ||
                (!float.IsPositiveInfinity(minimumRuntimeForearmDiameter) &&
                 minimumRuntimeForearmDiameter >=
                    LightsaberSetupTools
                        .ThrustForearmMinimumRuntimeDiameterMeters);
            bool wristPanelFacesCarrierRight = !wristPanelMode ||
                (runtimeWristPanelRelevantFrameCount > 0 &&
                 maximumRuntimeWristPanelRightAngle <=
                    LightsaberSetupTools
                        .ThrustWristPanelRightToleranceDegrees);
            bool topGripMaintained = !topGripMode ||
                (runtimeTopGripFrameCount > 0 &&
                 maximumRuntimeTopGripPalmCenterError <=
                    LightsaberSetupTools
                        .ThrustTopGripPalmCenterToleranceMeters &&
                 maximumRuntimeTopGripFingerPoseError <=
                    LightsaberSetupTools
                        .ThrustTopGripFingerPoseToleranceDegrees &&
                 maximumRuntimeTopGripFingerContactError <=
                    LightsaberSetupTools
                        .ThrustTopGripFingerContactToleranceMeters &&
                 maximumRuntimeTopGripWristBend <=
                    LightsaberSetupTools
                        .ThrustTopGripWristBendToleranceDegrees);
            bool focusedMode = forearmMode || wristPanelMode || topGripMode;
            bool sourcePlaybackSpeedConfirmed =
                sourcePlaybackSpeedObserved &&
                maximumSourcePlaybackSpeedError <= 0.0001f;
            bool passed = holdObserved && immediateReturnObserved &&
                rightHandFollow && sourceMotionObserved &&
                sourcePlaybackSpeedConfirmed &&
                (wristPanelMode || topGripMode || armPopAbsent) &&
                forearmDeformationAbsent && wristPanelFacesCarrierRight &&
                topGripMaintained &&
                (!focusedMode || Panels.Count == 1);

            // This single still is archival only. Temporal acceptance comes from
            // uninterrupted runtime samples and the separately recorded playback.
            if (!focusedMode)
                Panels.Add(CaptureRuntimePanel(root));
            Observations.Add(
                "continuousReviewComplete=True|state=" +
                LightsaberSetupTools.ThrustStabbingBridgeStateName +
                "|normalized=" + Num(normalized) +
                "|gameFrame=" + Time.frameCount);
            ComposeReview();
            WriteReport(passed, rightHandFollow, sourceMotionObserved);
            if (!passed)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust continuous arm-pop review failed." +
                    " samples=" + continuousArmPopSampleCount +
                    "|bridgeSamples=" + continuousBridgeSampleCount +
                    "|loopBoundaries=" + loopBoundaryCount +
                    "|maximumNormalized60HzStep=" +
                        Num(maximumArmPopFrameStep) +
                    "|maximumRawStep=" + Num(maximumArmPopRawFrameStep) +
                    "|loopBoundaryStep=" + Num(loopBoundaryFrameStep) +
                    "|sourcePlaybackSpeedConfirmed=" +
                        sourcePlaybackSpeedConfirmed +
                    "|maximumSourcePlaybackSpeedError=" +
                        Num(maximumSourcePlaybackSpeedError) +
                    "|forearmMode=" + forearmMode +
                    "|minimumRuntimeForearmDiameterMeters=" +
                        Num(minimumRuntimeForearmDiameter) +
                    "|wristPanelMode=" + wristPanelMode +
                    "|wristPanelRelevantFrames=" +
                        runtimeWristPanelRelevantFrameCount +
                    "|maximumWristPanelRightAngleDegrees=" +
                        Num(maximumRuntimeWristPanelRightAngle) +
                    "|topGripMode=" + topGripMode +
                    "|topGripFrames=" + runtimeTopGripFrameCount +
                    "|maximumTopGripHandBackUpAngleDegrees=" +
                        Num(maximumRuntimeTopGripHandBackUpAngle) +
                    "|maximumTopGripHandleAxisErrorDegrees=" +
                        Num(maximumRuntimeTopGripHandleAxisError) +
                    "|maximumTopGripPalmCenterErrorMeters=" +
                        Num(maximumRuntimeTopGripPalmCenterError) +
                    "|maximumTopGripFingerPoseErrorDegrees=" +
                        Num(maximumRuntimeTopGripFingerPoseError) +
                    "|maximumTopGripFingerContactErrorMeters=" +
                        Num(maximumRuntimeTopGripFingerContactError) +
                    "|maximumTopGripWristBendDegrees=" +
                        Num(maximumRuntimeTopGripWristBend) + ".");
            SessionState.SetInt(StateKey, WaitingForEditMode);
            EditorApplication.ExitPlaymode();
        }

        private static void CaptureForearmDeformationFrameWhenDue(
            Animator animator,
            Transform root)
        {
            if (SessionState.GetInt(IndexKey, 0) > 0 ||
                animator.IsInTransition(0))
                return;
            AnimatorStateInfo state = animator.GetCurrentAnimatorStateInfo(0);
            int sourceHash = Animator.StringToHash(
                LightsaberSetupTools.ThrustStabbingSourceStateName);
            if (state.shortNameHash != sourceHash) return;
            AnimationClip source = AssetDatabase.LoadAssetAtPath<AnimationClip>(
                "Assets/_Project/Art/Player/Animations/LightsaberThrust/" +
                "LightsaberThrust_Stabbing_SourceExact.anim");
            if (source == null || source.length <= 0.0001f)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust corrected source clip is unavailable.");
            bool distalForearmMode = SessionState.GetBool(
                DistalForearmModeKey, false);
            bool wristPanelMode = SessionState.GetBool(
                WristPanelModeKey, false);
            bool topGripMode = SessionState.GetBool(
                TopGripModeKey, false);
            float targetSeconds = distalForearmMode ? 0.416667f : 0.383333f;
            float targetNormalized = Mathf.Clamp01(targetSeconds / source.length);
            float normalized = NormalizedFraction(state.normalizedTime);
            if (normalized < targetNormalized) return;
            minimumRuntimeForearmDiameter =
                LightsaberSetupTools.MeasureRightForearmMinimumDiameter(root);
            Panels.Add(topGripMode
                ? CaptureRuntimeTopGripPanel(root)
                : CaptureRuntimeForearmPanel(root));
            Observations.Add(
                (topGripMode
                    ? "topGripFocusedReview=True|state="
                    : wristPanelMode
                    ? "wristPanelFocusedReview=True|state="
                    : distalForearmMode
                    ? "distalForearmFocusedReview=True|state="
                    : "forearmFocusedReview=True|state=") +
                LightsaberSetupTools.ThrustStabbingSourceStateName +
                "|normalized=" + Num(normalized) +
                "|targetNormalized=" + Num(targetNormalized) +
                "|minimumRuntimeForearmDiameterMeters=" +
                    Num(minimumRuntimeForearmDiameter) +
                "|sameBodyPartViewPoseAndZoom=True");
            SessionState.SetInt(IndexKey, 1);
        }

        private static Animator RequireRuntimeAnimator()
        {
            GameObject[] matches = Resources.FindObjectsOfTypeAll<GameObject>()
                .Where(item => item.scene.IsValid() && item.scene.isLoaded &&
                    item.name == LightsaberSetupTools.ThrustTargetName)
                .ToArray();
            if (matches.Length != 1)
                throw new InvalidOperationException(
                    "Expected exactly one runtime Lightsaber_Thrust; found " +
                    matches.Length + ".");
            Animator animator = matches[0].GetComponent<Animator>();
            if (animator == null || animator.runtimeAnimatorController == null ||
                AssetDatabase.GetAssetPath(animator.runtimeAnimatorController) !=
                    LightsaberSetupTools.ThrustStabbingControllerPath ||
                !animator.enabled || animator.applyRootMotion)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust stabbing runtime Animator settings differ.");
            return animator;
        }

        private static Transform RequireRuntimeProp(Transform root)
        {
            Transform hand = RequireBone(root, RightHandPath);
            Transform prop = hand.Find("Lightsaber_Prop") ??
                throw new InvalidOperationException(
                    "Runtime Lightsaber_Prop is missing from RightHand.");
            if (prop.parent != hand)
                throw new InvalidOperationException(
                    "Runtime Lightsaber_Prop stopped following RightHand.");
            Transform[] props = root.GetComponentsInChildren<Transform>(true)
                .Where(item => item.name == "Lightsaber_Prop").ToArray();
            if (props.Length != 1 || props[0] != prop)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust runtime prop count differs.");
            return prop;
        }

        private static void AccumulateMotion(Transform root, Transform prop)
        {
            Animator animator = root.GetComponent<Animator>();
            if (animator != null && !animator.IsInTransition(0))
            {
                AnimatorStateInfo state = animator.GetCurrentAnimatorStateInfo(0);
                if (state.shortNameHash == Animator.StringToHash(
                        LightsaberSetupTools.ThrustStabbingSourceStateName))
                {
                    sourcePlaybackSpeedObserved = true;
                    maximumSourcePlaybackSpeedError = Mathf.Max(
                        maximumSourcePlaybackSpeedError,
                        Mathf.Abs(
                            state.speed -
                            LightsaberSetupTools.ThrustStabbingPlaybackSpeed));
                }
            }
            Transform hand = RequireBone(root, RightHandPath);
            bool topGripMode = SessionState.GetBool(TopGripModeKey, false);
            if ((!topGripMode &&
                 Vector3.Distance(prop.localPosition, initialPropLocalPosition) >
                    0.0001f) ||
                Vector3.Distance(prop.localScale, initialPropLocalScale) > 0.0001f)
                throw new InvalidOperationException(
                    "Lightsaber_Prop local position or scale changed during " +
                    "stabbing playback.");
            maximumPropFollowPositionError = Mathf.Max(
                maximumPropFollowPositionError,
                Vector3.Distance(
                    hand.TransformPoint(prop.localPosition), prop.position));
            maximumPropFollowRotationError = Mathf.Max(
                maximumPropFollowRotationError,
                Quaternion.Angle(
                    hand.rotation * prop.localRotation, prop.rotation));
            maximumRightHandTravel = Mathf.Max(
                maximumRightHandTravel,
                Vector3.Distance(hand.position, initialRightHandPosition));
            maximumSpineMotion = Mathf.Max(
                maximumSpineMotion,
                Quaternion.Angle(
                    RequireBone(root, SpinePath).localRotation,
                    initialSpineRotation));
            Transform foreArm = hand.parent ?? throw new InvalidOperationException(
                "Lightsaber_Thrust runtime RightForeArm is missing.");
            maximumHandBackRightAngle = Mathf.Max(
                maximumHandBackRightAngle,
                Vector3.Angle(
                    LightsaberSetupTools.RightHandBackDirection(hand),
                    root.right));
            maximumBladeForwardAngle = Mathf.Max(
                maximumBladeForwardAngle,
                Vector3.Angle(
                    prop.TransformDirection(
                        LightsaberSetupTools.DiagonalSlashBladeAxisLocal()),
                    root.forward));
            maximumWristBend = Mathf.Max(
                maximumWristBend,
                Vector3.Angle(
                    LightsaberSetupTools.RightHandFingerDirection(hand),
                    (hand.position - foreArm.position).normalized));
            if (SessionState.GetBool(WristPanelModeKey, false) &&
                Vector3.Angle(
                    LightsaberSetupTools.RightHandBackDirection(hand),
                    root.right) <=
                    LightsaberSetupTools
                        .ThrustWristPanelPalmLeftToleranceDegrees)
            {
                if (wristPanelNormalLocal.sqrMagnitude < 0.5f)
                    wristPanelNormalLocal =
                        LightsaberSetupTools.RightForeArmPanelNormalLocal();
                Vector3 foreArmAxis =
                    (hand.position - foreArm.position).normalized;
                float panelRightAngle = Vector3.Angle(
                    Vector3.ProjectOnPlane(
                        foreArm.TransformDirection(wristPanelNormalLocal),
                        foreArmAxis),
                    Vector3.ProjectOnPlane(root.right, foreArmAxis));
                maximumRuntimeWristPanelRightAngle = Mathf.Max(
                    maximumRuntimeWristPanelRightAngle,
                    panelRightAngle);
                runtimeWristPanelRelevantFrameCount++;
            }
            if (topGripMode)
            {
                LightsaberSetupTools.TopGripFrame frame =
                    LightsaberSetupTools.MeasureRuntimeTopGrip(root, prop);
                maximumRuntimeTopGripHandBackUpAngle = Mathf.Max(
                    maximumRuntimeTopGripHandBackUpAngle,
                    frame.HandBackUpAngleDegrees);
                maximumRuntimeTopGripHandleAxisError = Mathf.Max(
                    maximumRuntimeTopGripHandleAxisError,
                    frame.HandleAxisErrorDegrees);
                maximumRuntimeTopGripPalmCenterError = Mathf.Max(
                    maximumRuntimeTopGripPalmCenterError,
                    frame.PalmCenterErrorMeters);
                maximumRuntimeTopGripFingerPoseError = Mathf.Max(
                    maximumRuntimeTopGripFingerPoseError,
                    frame.FingerPoseErrorDegrees);
                maximumRuntimeTopGripFingerContactError = Mathf.Max(
                    maximumRuntimeTopGripFingerContactError,
                    frame.FingerContactErrorMeters);
                maximumRuntimeTopGripWristBend = Mathf.Max(
                    maximumRuntimeTopGripWristBend,
                    frame.WristBendDegrees);
                runtimeTopGripFrameCount++;
            }
            if (SessionState.GetBool(ArmPopModeKey, false))
                AccumulateArmPopContinuity(root, prop);
        }

        private static void AccumulateArmPopContinuity(
            Transform root,
            Transform prop)
        {
            Animator animator = root.GetComponent<Animator>();
            if (animator == null || animator.IsInTransition(0)) return;
            if (previousArmPopGameFrame == Time.frameCount) return;
            AnimatorStateInfo state = animator.GetCurrentAnimatorStateInfo(0);
            Transform hand = RequireBone(root, RightHandPath);
            Transform foreArm = hand.parent ?? throw new InvalidOperationException(
                "Lightsaber_Thrust runtime RightForeArm is missing.");
            Transform upperArm = foreArm.parent ?? throw new InvalidOperationException(
                "Lightsaber_Thrust runtime RightArm is missing.");
            Quaternion[] current =
            {
                upperArm.localRotation,
                foreArm.localRotation,
                hand.localRotation,
                prop.localRotation
            };
            int bridgeHash = Animator.StringToHash(
                LightsaberSetupTools.ThrustStabbingBridgeStateName);
            int sourceHash = Animator.StringToHash(
                LightsaberSetupTools.ThrustStabbingSourceStateName);
            int holdHash = Animator.StringToHash(
                LightsaberSetupTools.ThrustStabbingHoldStateName);
            double sampleTime = Time.timeAsDouble;
            float normalizedStep = 0f;
            float rawStep = 0f;
            if (previousRightArmRotations != null)
            {
                for (int index = 0; index < current.Length; index++)
                    rawStep = Mathf.Max(
                        rawStep,
                        Quaternion.Angle(
                            previousRightArmRotations[index], current[index]));
                double elapsed = sampleTime - previousArmPopSampleTime;
                normalizedStep = elapsed > 0.00001d
                    ? rawStep * (1f / 60f) / (float)elapsed
                    : rawStep;
                bool correctedMotionRelevant =
                    state.shortNameHash == previousStateHash &&
                    (state.shortNameHash == bridgeHash ||
                     state.shortNameHash == sourceHash);
                if (correctedMotionRelevant)
                {
                    maximumArmPopFrameStep = Mathf.Max(
                        maximumArmPopFrameStep, normalizedStep);
                    maximumArmPopRawFrameStep = Mathf.Max(
                        maximumArmPopRawFrameStep, rawStep);
                    if (state.shortNameHash == bridgeHash)
                        continuousBridgeSampleCount++;
                }
                if (previousStateHash == holdHash &&
                    state.shortNameHash == bridgeHash)
                {
                    loopBoundaryObserved = true;
                    loopBoundaryCount++;
                    loopBoundaryFrameStep = Mathf.Max(
                        loopBoundaryFrameStep, normalizedStep);
                    immediateReturnObserved = true;
                }
            }
            if (state.shortNameHash == holdHash) holdObserved = true;
            continuousArmPopSampleCount++;
            Observations.Add(
                "frame=" + Time.frameCount +
                "|stateHash=" + state.shortNameHash +
                "|normalized=" + Num(NormalizedFraction(state.normalizedTime)) +
                "|rawArmStepDegrees=" + Num(rawStep) +
                "|normalized60HzArmStepDegrees=" + Num(normalizedStep) +
                "|rightHandLocal=" + Vec(root.InverseTransformPoint(hand.position)) +
                "|rightElbowLocal=" + Vec(root.InverseTransformPoint(foreArm.position)));
            previousRightArmRotations = current;
            previousStateHash = state.shortNameHash;
            previousArmPopGameFrame = Time.frameCount;
            previousArmPopSampleTime = sampleTime;
        }

        private static string[] BuildExpectedStates()
        {
            if (SessionState.GetBool(ArmPopModeKey, false))
                return new[]
                {
                    LightsaberSetupTools.ThrustStabbingBridgeStateName,
                    LightsaberSetupTools.ThrustStabbingBridgeStateName,
                    LightsaberSetupTools.ThrustStabbingSourceStateName,
                    LightsaberSetupTools.ThrustStabbingSourceStateName,
                    LightsaberSetupTools.ThrustStabbingSourceStateName,
                    LightsaberSetupTools.ThrustStabbingHoldStateName,
                    LightsaberSetupTools.ThrustStabbingHoldStateName,
                    LightsaberSetupTools.ThrustStabbingHoldStateName,
                    LightsaberSetupTools.ThrustStabbingBridgeStateName,
                    LightsaberSetupTools.ThrustStabbingBridgeStateName
                };
            bool bridge = AssetDatabase.LoadAssetAtPath<AnimationClip>(
                "Assets/_Project/Art/Player/Animations/LightsaberThrust/" +
                "LightsaberThrust_EnterLast_To_StabbingFirst_0_2s.anim") != null;
            if (bridge)
                return new[]
                {
                    LightsaberSetupTools.ThrustStabbingBridgeStateName,
                    LightsaberSetupTools.ThrustStabbingBridgeStateName,
                    LightsaberSetupTools.ThrustStabbingSourceStateName,
                    LightsaberSetupTools.ThrustStabbingSourceStateName,
                    LightsaberSetupTools.ThrustStabbingSourceStateName,
                    LightsaberSetupTools.ThrustStabbingHoldStateName,
                    LightsaberSetupTools.ThrustStabbingHoldStateName,
                    LightsaberSetupTools.ThrustStabbingHoldStateName,
                    LightsaberSetupTools.ThrustStabbingBridgeStateName
                };
            return new[]
            {
                LightsaberSetupTools.ThrustStabbingSourceStateName,
                LightsaberSetupTools.ThrustStabbingSourceStateName,
                LightsaberSetupTools.ThrustStabbingSourceStateName,
                LightsaberSetupTools.ThrustStabbingHoldStateName,
                LightsaberSetupTools.ThrustStabbingHoldStateName,
