        private static float[] BuildExpectedNormalizedTimes()
        {
            if (SessionState.GetBool(ArmPopModeKey, false))
                return new[]
                {
                    0.05f, 0.60f,
                    0.04f, 0.50f, 0.82f,
                    0.04f, 0.50f, 0.82f,
                    0.05f, 0.60f
                };
            return BuildExpectedStates().Length == 9
                ? new[] { 0.00f, 0.50f, 0.04f, 0.50f, 0.82f,
                    0.04f, 0.50f, 0.82f, 0.04f }
                : new[] { 0.04f, 0.50f, 0.82f, 0.04f, 0.50f, 0.82f, 0.04f };
        }

        private static Dictionary<string, RuntimePose> CapturePose(
            Transform root,
            Transform excludedRoot)
        {
            return root.GetComponentsInChildren<Transform>(true)
                .Where(item => item != root && item != excludedRoot &&
                    !item.IsChildOf(excludedRoot))
                .ToDictionary(
                    item => AnimationUtility.CalculateTransformPath(item, root),
                    item => new RuntimePose(
                        item.localPosition, item.localRotation, item.localScale),
                    StringComparer.Ordinal);
        }

        private static void RequirePoseNear(
            IReadOnlyDictionary<string, RuntimePose> expected,
            IReadOnlyDictionary<string, RuntimePose> actual,
            float positionTolerance,
            float rotationTolerance,
            float scaleTolerance,
            string label)
        {
            if (expected.Count != actual.Count ||
                expected.Keys.Any(path => !actual.ContainsKey(path)))
                throw new InvalidOperationException(label + " path set differs.");
            foreach (string path in expected.Keys)
            {
                RuntimePose a = expected[path];
                RuntimePose b = actual[path];
                if (Vector3.Distance(a.Position, b.Position) > positionTolerance ||
                    Quaternion.Angle(a.Rotation, b.Rotation) > rotationTolerance ||
                    Vector3.Distance(a.Scale, b.Scale) > scaleTolerance)
                    throw new InvalidOperationException(
                        label + " changed at " + path + ".");
            }
        }

        private static Texture2D CaptureRuntimeTopGripPanel(Transform target)
        {
            Transform foreArm = RequireBone(
                target,
                "Armature/Hips/Spine02/Spine01/Spine/RightShoulder/" +
                "RightArm/RightForeArm");
            Transform hand = RequireBone(target, RightHandPath);
            Transform prop = RequireRuntimeProp(target);
            Bounds bounds = new Bounds(foreArm.position, Vector3.zero);
            bounds.Encapsulate(hand.position);
            bounds.Encapsulate(prop.position);
            foreach (Transform finger in hand.GetComponentsInChildren<Transform>(true))
                if (finger != prop && !finger.IsChildOf(prop))
                    bounds.Encapsulate(finger.position);
            bounds.Expand(0.20f);

            GameObject cameraObject = new GameObject(
                "LightsaberThrustTopGripReviewCamera")
            {
                hideFlags = HideFlags.HideAndDontSave
            };
            GameObject lightObject = new GameObject(
                "LightsaberThrustTopGripReviewLight")
            {
                hideFlags = HideFlags.HideAndDontSave
            };
            Camera camera = cameraObject.AddComponent<Camera>();
            Light light = lightObject.AddComponent<Light>();
            Transform[] targetNodes =
                target.GetComponentsInChildren<Transform>(true);
            int[] originalLayers = targetNodes
                .Select(item => item.gameObject.layer).ToArray();
            var occupiedOutsideLayers = new HashSet<int>(
                Resources.FindObjectsOfTypeAll<Renderer>()
                    .Where(item => item != null && item.transform != target &&
                        !item.transform.IsChildOf(target) &&
                        item.gameObject.scene.IsValid() &&
                        item.gameObject.scene.isLoaded)
                    .Select(item => item.gameObject.layer));
            int reviewLayer = Enumerable.Range(0, 32)
                .Reverse().First(layer => !occupiedOutsideLayers.Contains(layer));
            foreach (Transform node in targetNodes)
                node.gameObject.layer = reviewLayer;
            camera.enabled = false;
            camera.cullingMask = 1 << reviewLayer;
            camera.clearFlags = CameraClearFlags.SolidColor;
            camera.backgroundColor = new Color(0.015f, 0.02f, 0.03f, 1f);
            camera.orthographic = true;
            camera.aspect = PanelWidth / (float)PanelHeight;
            camera.orthographicSize = Mathf.Max(
                bounds.extents.y,
                bounds.extents.x / camera.aspect) * 1.08f;
            Vector3 viewDirection = (
                target.forward + target.right * 1.0f + target.up * 0.10f)
                .normalized;
            camera.nearClipPlane = 0.01f;
            camera.farClipPlane = 12f;
            camera.transform.SetPositionAndRotation(
                bounds.center + viewDirection * 3f,
                Quaternion.LookRotation(-viewDirection, target.up));
            light.type = LightType.Directional;
            light.intensity = 1.2f;
            light.transform.rotation = Quaternion.LookRotation(
                -viewDirection - target.up * 0.25f, target.up);
            RenderTexture render = RenderTexture.GetTemporary(
                PanelWidth, PanelHeight, 24, RenderTextureFormat.ARGB32);
            RenderTexture previousActive = RenderTexture.active;
            try
            {
                camera.targetTexture = render;
                camera.Render();
                RenderTexture.active = render;
                var panel = new Texture2D(
                    PanelWidth, PanelHeight, TextureFormat.RGB24, false);
                panel.ReadPixels(
                    new Rect(0f, 0f, PanelWidth, PanelHeight), 0, 0, false);
                panel.Apply(false, false);
                if (!PanelContainsRenderedCharacter(panel))
                {
                    UnityEngine.Object.DestroyImmediate(panel);
                    throw new InvalidOperationException(
                        "Lightsaber_Thrust focused top-grip review was blank.");
                }
                return panel;
            }
            finally
            {
                camera.targetTexture = null;
                RenderTexture.active = previousActive;
                RenderTexture.ReleaseTemporary(render);
                for (int index = 0; index < targetNodes.Length; index++)
                    if (targetNodes[index] != null)
                        targetNodes[index].gameObject.layer = originalLayers[index];
                UnityEngine.Object.DestroyImmediate(cameraObject);
                UnityEngine.Object.DestroyImmediate(lightObject);
            }
        }

