            var report = new StringBuilder()
                .AppendLine("Lightsaber_Thrust exact stabbing Play Mode review")
                .AppendLine("naturalPlayback=True")
                .AppendLine("verificationTargetTransformManipulated=False")
                .AppendLine("directVisualInspected=" +
                    (SessionState.GetBool(WristPanelModeKey, false) ||
                     SessionState.GetBool(TopGripModeKey, false)))
                .AppendLine("directVisualUserConfirmed=" +
                    SessionState.GetBool(DistalForearmModeKey, false))
                .AppendLine("animationMotionModified=False")
                .AppendLine("animatorPlayCalled=False")
                .AppendLine("animatorRebindCalled=False")
                .AppendLine("exactMixamoSourcePreserved=True")
                .AppendLine("unapprovedSourceMotionGenerated=False")
                .AppendLine("sourceMotionObserved=" + sourceMotionObserved)
                .AppendLine("sourceSeconds=" +
                    (source == null ? "missing" : Num(source.length)))
                .AppendLine("sourcePlaybackSpeed=" +
                    Num(LightsaberSetupTools.ThrustStabbingPlaybackSpeed))
                .AppendLine("sourcePlaybackSpeedConfirmed=" +
                    (sourcePlaybackSpeedObserved &&
                     maximumSourcePlaybackSpeedError <= 0.0001f))
                .AppendLine("maximumSourcePlaybackSpeedError=" +
                    Num(maximumSourcePlaybackSpeedError))
                .AppendLine("enterLastStartPoseConfirmed=True")
                .AppendLine("bridgeRequired=" + bridgeRequired)
                .AppendLine("bridgeDurationConfirmed=True")
                .AppendLine("bridgeSeconds=" +
                    (bridgeRequired
                        ? Num(LightsaberSetupTools.ThrustStabbingBridgeSeconds)
                        : "0"))
                .AppendLine("holdDurationConfirmed=True")
                .AppendLine("holdSeconds=" +
                    Num(LightsaberSetupTools.ThrustStabbingHoldSeconds))
                .AppendLine("holdPoseConfirmed=" + holdObserved)
                .AppendLine("immediateReturnConfirmed=" +
                    immediateReturnObserved)
                .AppendLine("rightHandFollowPreserved=" + rightHandFollow)
                .AppendLine("rightHandBackFacesCarrierRight=" +
                    (maximumHandBackRightAngle <=
                        LightsaberSetupTools
                            .ThrustStabbingHandBackToleranceDegrees))
                .AppendLine("bladeCenterAxisAndTipFaceForward=" +
                    (maximumBladeForwardAngle <=
                        LightsaberSetupTools
                            .ThrustStabbingBladeForwardToleranceDegrees))
                .AppendLine("wristBendWithinTolerance=" +
                    (maximumWristBend <=
                        LightsaberSetupTools
                            .ThrustStabbingWristBendToleranceDegrees))
                .AppendLine("maximumHandBackRightAngleDegrees=" +
                    Num(maximumHandBackRightAngle))
                .AppendLine("maximumBladeForwardAngleDegrees=" +
                    Num(maximumBladeForwardAngle))
                .AppendLine("maximumWristBendDegrees=" +
                    Num(maximumWristBend))
                .AppendLine("maximumPropFollowPositionErrorMeters=" +
                    Num(maximumPropFollowPositionError))
                .AppendLine("maximumPropFollowRotationErrorDegrees=" +
                    Num(maximumPropFollowRotationError))
                .AppendLine("maximumRightHandTravelMeters=" +
                    Num(maximumRightHandTravel))
                .AppendLine("maximumSpineMotionDegrees=" +
                    Num(maximumSpineMotion))
                .AppendLine("armPopAbsent=" +
                    (loopBoundaryObserved &&
                     maximumArmPopFrameStep <=
                        LightsaberSetupTools
                            .ThrustArmPopFrameStepToleranceDegrees &&
                     loopBoundaryFrameStep <=
                        LightsaberSetupTools
                            .ThrustArmPopFrameStepToleranceDegrees))
                .AppendLine("forearmDeformationAbsent=" +
                    (!SessionState.GetBool(ForearmModeKey, false) ||
                     (!float.IsPositiveInfinity(
                        minimumRuntimeForearmDiameter) &&
                      minimumRuntimeForearmDiameter >=
                        LightsaberSetupTools
                            .ThrustForearmMinimumRuntimeDiameterMeters)))
                .AppendLine("distalForearmSkinningCorrected=" +
                    SessionState.GetBool(DistalForearmModeKey, false))
                .AppendLine("wristPanelOrientationMode=" +
                    SessionState.GetBool(WristPanelModeKey, false))
                .AppendLine("wristPanelFacesCarrierRight=" +
                    (!SessionState.GetBool(WristPanelModeKey, false) ||
                     (runtimeWristPanelRelevantFrameCount > 0 &&
                      maximumRuntimeWristPanelRightAngle <=
                        LightsaberSetupTools
                            .ThrustWristPanelRightToleranceDegrees)))
                .AppendLine("runtimeWristPanelRelevantFrameCount=" +
                    runtimeWristPanelRelevantFrameCount)
                .AppendLine("maximumRuntimeWristPanelRightAngleDegrees=" +
                    Num(maximumRuntimeWristPanelRightAngle))
                .AppendLine("topGripMode=" +
                    SessionState.GetBool(TopGripModeKey, false))
                .AppendLine("rightHandGripsHandleFromAbove=" +
                    (!SessionState.GetBool(TopGripModeKey, false) ||
                     (runtimeTopGripFrameCount > 0 &&
                      maximumRuntimeTopGripPalmCenterError <=
                        LightsaberSetupTools
                            .ThrustTopGripPalmCenterToleranceMeters &&
                      maximumRuntimeTopGripWristBend <=
                        LightsaberSetupTools
                            .ThrustTopGripWristBendToleranceDegrees)))
                .AppendLine("fingerGripMaintained=" +
                    (!SessionState.GetBool(TopGripModeKey, false) ||
                     (runtimeTopGripFrameCount > 0 &&
                      maximumRuntimeTopGripFingerPoseError <=
                        LightsaberSetupTools
                            .ThrustTopGripFingerPoseToleranceDegrees &&
                      maximumRuntimeTopGripFingerContactError <=
                        LightsaberSetupTools
                            .ThrustTopGripFingerContactToleranceMeters)))
                .AppendLine("runtimeTopGripFrameCount=" +
                    runtimeTopGripFrameCount)
                .AppendLine("maximumRuntimeTopGripHandBackUpAngleDegrees=" +
                    Num(maximumRuntimeTopGripHandBackUpAngle))
                .AppendLine("maximumRuntimeTopGripHandleAxisErrorDegrees=" +
                    Num(maximumRuntimeTopGripHandleAxisError))
                .AppendLine("maximumRuntimeTopGripPalmCenterErrorMeters=" +
                    Num(maximumRuntimeTopGripPalmCenterError))
                .AppendLine("maximumRuntimeTopGripFingerPoseErrorDegrees=" +
                    Num(maximumRuntimeTopGripFingerPoseError))
                .AppendLine("maximumRuntimeTopGripFingerContactErrorMeters=" +
                    Num(maximumRuntimeTopGripFingerContactError))
                .AppendLine("maximumRuntimeTopGripWristBendDegrees=" +
                    Num(maximumRuntimeTopGripWristBend))
                .AppendLine("protectedMotionPreserved=" + rightHandFollow)
                .AppendLine("minimumRuntimeForearmDiameterMeters=" +
                    Num(minimumRuntimeForearmDiameter))
                .AppendLine("maximumArmPopFrameStepDegrees=" +
                    Num(maximumArmPopFrameStep))
                .AppendLine("maximumArmPopRawFrameStepDegrees=" +
                    Num(maximumArmPopRawFrameStep))
                .AppendLine("loopBoundaryFrameStepDegrees=" +
                    Num(loopBoundaryFrameStep))
                .AppendLine("loopBoundaryObserved=" + loopBoundaryObserved)
                .AppendLine("loopBoundaryCount=" + loopBoundaryCount)
                .AppendLine("continuousPlayback=" +
                    SessionState.GetBool(ArmPopModeKey, false))
                .AppendLine("continuousFrameSampleCount=" +
                    continuousArmPopSampleCount)
                .AppendLine("continuousBridgeSampleCount=" +
                    continuousBridgeSampleCount)
                .AppendLine("timingPreserved=" +
                    (Mathf.Abs(
                        LightsaberSetupTools.ThrustStabbingBridgeSeconds - 0.2f) <
                            0.0001f &&
                     Mathf.Abs(
                        LightsaberSetupTools.ThrustStabbingHoldSeconds - 0.5f) <
                            0.0001f))
                .AppendLine("capturedPanelCount=" + Panels.Count)
                .AppendLine("passedNumericChecks=" + passed);
            foreach (string observation in Observations)
                report.AppendLine(observation);
            string path = Absolute(ActiveReportRelativePath());
            Directory.CreateDirectory(Path.GetDirectoryName(path) ??
                throw new InvalidOperationException(
                    "Stabbing report directory is unavailable."));
            File.WriteAllText(path, report.ToString(), Encoding.UTF8);
        }

        private static void FinishSuccess()
        {
            Action<string> callback = complete;
            int errorsBefore = SessionState.GetInt(ConsoleErrorsBeforeKey, 0);
            try
            {
                RestoreSavedSceneAfterPlayModeCapture();
                if (SessionState.GetBool(TopGripModeKey, false))
                    LightsaberSetupTools
                        .InspectLightsaberThrustTopGripPoseCorrection();
                else if (SessionState.GetBool(WristPanelModeKey, false))
                    LightsaberSetupTools
                        .InspectLightsaberThrustWristPanelOrientationCorrection();
                else if (SessionState.GetBool(DistalForearmModeKey, false))
                    LightsaberSetupTools
                        .InspectLightsaberThrustDistalForearmSkinning();
                else if (SessionState.GetBool(ForearmModeKey, false))
                    LightsaberSetupTools
                        .InspectLightsaberThrustForearmDeformationCorrection();
                else if (SessionState.GetBool(ArmPopModeKey, false))
                    LightsaberSetupTools
                        .InspectLightsaberThrustArmPopCorrection();
                int errorsAfter = LightsaberSetupTools.ConsoleErrorCount();
                if (errorsAfter > errorsBefore)
                    throw new InvalidOperationException(
                        "Unity console gained errors during stabbing review. before=" +
                        errorsBefore + "|after=" + errorsAfter + ".");
                CleanupPanels();
                CleanupSession();
                callback?.Invoke(
                    "Lightsaber_Thrust stabbing loop inspected in Play Mode; " +
                    "direct review captured and Edit Mode restored.");
            }
            catch (Exception exception)
            {
                CleanupSession();
                fail?.Invoke(exception);
            }
        }

        private static void FinishFailure()
        {
            string failureText = SessionState.GetString(
                FailureKey, "Unknown stabbing review failure.");
            Action<Exception> callback = fail;
            try
            {
                RestoreSavedSceneAfterPlayModeCapture();
            }
            finally
            {
                CleanupSession();
            }
            callback?.Invoke(new InvalidOperationException(failureText));
        }

        private static Transform RequireBone(Transform root, string path)
        {
            return root.Find(path) ?? throw new InvalidOperationException(
                "Lightsaber_Thrust stabbing bone is missing: " + path);
        }

        private static void RequireWithinWaitLimit()
        {
            float started = SessionState.GetFloat(WaitStartKey, 0f);
            if (Time.realtimeSinceStartupAsDouble - started > 20d)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust did not reach its stabbing sequence start " +
                    "within twenty seconds.");
        }

        private static void RequireWithinCaptureLimit()
        {
            float started = SessionState.GetFloat(WaitStartKey, 0f);
            if (Time.realtimeSinceStartupAsDouble - started > 30d)
                throw new InvalidOperationException(
                    "Lightsaber_Thrust stabbing sequence did not complete within " +
                    "thirty seconds.");
        }

        private static void RestoreSavedSceneAfterPlayModeCapture()
        {
            const string scenePath = "Assets/_Project/Scenes/CargoRunMvp.unity";
            Scene active = SceneManager.GetActiveScene();
            if (active.path != scenePath || active.isDirty)
                EditorSceneManager.OpenScene(scenePath, OpenSceneMode.Single);
        }

        private static float NormalizedFraction(float normalizedTime)
        {
            return normalizedTime - Mathf.Floor(normalizedTime);
        }

        private static string ActiveReviewRelativePath()
        {
            if (SessionState.GetBool(TopGripModeKey, false))
                return LightsaberSetupTools.ThrustTopGripReviewRelativePath;
            if (SessionState.GetBool(WristPanelModeKey, false))
                return LightsaberSetupTools
                    .ThrustWristPanelReviewRelativePath;
            if (SessionState.GetBool(DistalForearmModeKey, false))
                return LightsaberSetupTools
                    .ThrustDistalForearmReviewRelativePath;
            if (SessionState.GetBool(ForearmModeKey, false))
                return LightsaberSetupTools
                    .ThrustForearmDeformationReviewRelativePath;
            return SessionState.GetBool(ArmPopModeKey, false)
                ? LightsaberSetupTools.ThrustArmPopReviewRelativePath
                : LightsaberSetupTools.ThrustStabbingReviewRelativePath;
        }

        private static string ActiveReportRelativePath()
        {
            if (SessionState.GetBool(TopGripModeKey, false))
                return LightsaberSetupTools.ThrustTopGripReportRelativePath;
            if (SessionState.GetBool(WristPanelModeKey, false))
                return LightsaberSetupTools
                    .ThrustWristPanelReportRelativePath;
            if (SessionState.GetBool(DistalForearmModeKey, false))
                return LightsaberSetupTools
                    .ThrustDistalForearmReportRelativePath;
            if (SessionState.GetBool(ForearmModeKey, false))
                return LightsaberSetupTools
                    .ThrustForearmDeformationReportRelativePath;
            return SessionState.GetBool(ArmPopModeKey, false)
                ? LightsaberSetupTools.ThrustArmPopReportRelativePath
                : LightsaberSetupTools.ThrustStabbingReportRelativePath;
        }

        private static void CleanupPanels()
        {
            foreach (Texture2D panel in Panels)
                if (panel != null) UnityEngine.Object.DestroyImmediate(panel);
            Panels.Clear();
        }

        private static void CleanupSession()
        {
            CleanupPanels();
            Observations.Clear();
            holdReferencePose = null;
            previousRightArmRotations = null;
            previousStateHash = 0;
            complete = null;
            fail = null;
            SessionState.EraseInt(StateKey);
            SessionState.EraseInt(IndexKey);
            SessionState.EraseFloat(WaitStartKey);
            SessionState.EraseInt(ConsoleErrorsBeforeKey);
            SessionState.EraseString(FailureKey);
            SessionState.EraseBool(ArmPopModeKey);
            SessionState.EraseBool(ForearmModeKey);
            SessionState.EraseBool(DistalForearmModeKey);
            SessionState.EraseBool(WristPanelModeKey);
            SessionState.EraseBool(TopGripModeKey);
        }

        private static void TryDelete(string path)
        {
            if (File.Exists(path)) File.Delete(path);
        }

        private static string Absolute(string relativePath)
        {
            return Path.GetFullPath(Path.Combine(
                Path.GetDirectoryName(Application.dataPath) ?? string.Empty,
                relativePath));
        }

        private static string Num(float value)
        {
            return value.ToString("R", CultureInfo.InvariantCulture);
        }

        private static string Vec(Vector3 value)
        {
            return Num(value.x) + "," + Num(value.y) + "," + Num(value.z);
        }

        private readonly struct RuntimePose
        {
            internal RuntimePose(
                Vector3 position,
                Quaternion rotation,
                Vector3 scale)
            {
                Position = position;
                Rotation = rotation;
                Scale = scale;
            }

            internal Vector3 Position { get; }
            internal Quaternion Rotation { get; }
            internal Vector3 Scale { get; }
        }
    }
}
